/* ===== POPUP REKOMENDASI ZOOM MOBILE 80% ===== */
.zoomSuggestOverlay{
  display:none;
  position:fixed;
  inset:0;
  z-index:10000;
  align-items:center;
  justify-content:center;
  padding:20px;
  background:rgba(7,29,43,.68);
  backdrop-filter:blur(2px);
}
.zoomSuggestOverlay.on{display:flex}
.zoomSuggestCard{
  width:min(430px,100%);
  background:#fff;
  border-radius:16px;
  box-shadow:0 20px 60px rgba(0,0,0,.28);
  padding:24px;
  color:var(--ink);
}
.zoomSuggestIcon{
  width:46px;
  height:46px;
  border-radius:13px;
  display:grid;
  place-items:center;
  margin-bottom:14px;
  background:#eaf4fb;
  color:var(--petrol);
  font-size:22px;
  font-weight:800;
}
.zoomSuggestCard h3{
  margin:0 0 10px;
  color:var(--petrol);
  font-size:18px;
}
.zoomSuggestCard p{
  margin:0;
  color:var(--ink2);
  font-size:13px;
  line-height:1.65;
}
.zoomSuggestInstruction{
  margin-top:16px;
  padding:12px 14px;
  border:1px solid var(--line);
  border-radius:10px;
  background:#f7f9fb;
  color:var(--ink2);
  font-size:13px;
  line-height:1.6;
}
.zoomSuggestCheck{
  display:flex;
  align-items:flex-start;
  gap:9px;
  margin-top:17px;
  color:var(--ink2);
  font-size:12px;
  line-height:1.5;
  cursor:pointer;
}
.zoomSuggestCheck input{
  width:17px;
  height:17px;
  margin-top:1px;
  flex:0 0 auto;
}
.zoomSuggestButton{
  width:100%;
  min-height:44px;
  margin-top:20px;
  border:0;
  border-radius:9px;
  background:var(--petrol);
  color:#fff;
  font-weight:700;
  cursor:pointer;
}
.zoomSuggestButton:hover{background:#0c2c3d}
@media(max-width:760px){
  .zoomSuggestOverlay{padding:18px}
  .zoomSuggestCard{border-radius:18px;padding:23px 20px}
  .zoomSuggestCard h3{font-size:19px}
  .zoomSuggestCard p,.zoomSuggestInstruction{font-size:13px}
  .zoomSuggestButton{min-height:48px;font-size:14px}
}

