/* ===== AI ASSISTANT v1 ===== */
.aiShell{display:grid;grid-template-columns:minmax(0,1fr);gap:12px;align-items:start}.aiChat{background:#fff;border:1px solid var(--line);border-radius:12px;overflow:hidden}.aiHead{padding:12px 14px;background:linear-gradient(120deg,#10394E,#176786);color:#fff;display:flex;align-items:center;gap:10px}.aiHead b{font-size:13px}.aiHead small{display:block;color:#d6e6ee;margin-top:2px}.aiDot{width:10px;height:10px;border-radius:50%;background:#54d6a8;box-shadow:0 0 0 4px #54d6a833}.aiMessages{min-height:360px;max-height:58vh;overflow:auto;padding:14px;background:#f7f9fb}.aiMsg{display:flex;margin:8px 0}.aiMsg.user{justify-content:flex-end}.aiBubble{max-width:82%;padding:10px 12px;border-radius:13px;line-height:1.55;white-space:pre-wrap;font-size:11.5px}.aiMsg.user .aiBubble{background:#10394E;color:#fff;border-bottom-right-radius:4px}.aiMsg.assistant .aiBubble{background:#fff;border:1px solid #dbe3ea;color:#263443;border-bottom-left-radius:4px}.aiMeta{font-size:9px;color:#7a8794;margin-top:5px}.aiComposer{border-top:1px solid var(--line);padding:10px;display:flex;gap:8px;background:#fff}.aiComposer textarea{flex:1;resize:vertical;min-height:46px;max-height:130px;border:1px solid var(--line);border-radius:8px;padding:10px;font:12px inherit}.aiComposer button{align-self:flex-end;border-radius:8px}.aiSide .panel{border-radius:12px}.aiQuick{display:flex;flex-direction:column;gap:7px}.aiQuick button{text-align:left;border:1px solid #d9e1e8;background:#fff;border-radius:8px;padding:9px;color:#274357;cursor:pointer;font-size:11px}.aiQuick button:hover{border-color:#176786;background:#f2f8fb}.aiReadonly{background:#eaf7f3;border-left:3px solid var(--green);padding:9px 10px;border-radius:6px;font-size:10.5px;color:#31594d}.aiThinking{opacity:.7;font-style:italic}.aiEmpty{text-align:center;color:#7a8794;padding:65px 20px}.aiEmpty b{display:block;color:#274357;font-size:15px;margin-bottom:5px}@media(max-width:900px){.aiShell{grid-template-columns:1fr}.aiSide{order:-1}.aiMessages{max-height:52vh}.aiBubble{max-width:94%}}

.weeklyTable .table-scroll thead th:last-child{background:#e2f2f8!important;color:#10394e!important}.weeklyTable .table-scroll thead th:last-child *{color:#10394e!important}

/* Brand · Pergerakan gabungan SELL THRU + SELL OUT */
.typeMovement table.stSoCombined{min-width:1180px;table-layout:fixed}
.stSoCombined th,.stSoCombined td{white-space:nowrap}
.stSoCombined th:first-child,.stSoCombined td:first-child{position:-webkit-sticky;position:sticky;left:0;z-index:2;width:190px;min-width:190px;background:#f6f9fb}
.stSoCombined thead th:first-child{z-index:7;background:#e8f0f5}
.stSoCombined .stBand{background:#cfeaf6!important;color:#10445d!important;border-left:2px solid #9ccfe2}
.stSoCombined .soBand{background:#f9ddcc!important;color:#6f3c21!important;border-left:2px solid #e9b896}
.stSoCombined .bandStart{border-left:2px solid #cbdbe4}
.stSoCombined .contribCell{font-weight:750;color:#10394e}
.stSoCombined .topStRow td{background:#fff6d9!important}
.stSoCombined .topStRow td:first-child{background:#fff0b8!important;border-left:4px solid #e5a900}
.stSoCombined .topStTotal{font-weight:850;color:#8b5b00}
.topStBadge{display:inline-flex;align-items:center;margin-left:7px;padding:2px 6px;border-radius:999px;background:#f0a400;color:#10394e;font-size:8px;font-weight:850;letter-spacing:.45px;vertical-align:middle}
@media(max-width:760px){.typeMovement table.stSoCombined{min-width:1080px}.stSoCombined th:first-child,.stSoCombined td:first-child{width:145px;min-width:145px}.topStBadge{display:block;width:max-content;margin:4px 0 0}}

/* v5.2: total row stays visible at the bottom of every scrollable table. */
.table-scroll tbody tr.totalRow>td,.weeklyTable .table-scroll tbody tr:last-child>td{position:-webkit-sticky;position:sticky;bottom:0;z-index:5}
.table-scroll tbody tr.totalRow>td:first-child,.weeklyTable .table-scroll tbody tr:last-child>td:first-child{z-index:8}

/* v5.1: first-column readability across every menu/table. */
#view .table-scroll table th:first-child,#view .table-scroll table td:first-child{min-width:190px;max-width:none;white-space:normal;overflow-wrap:anywhere}
#view .grouped th:first-child,#view .grouped td:first-child{min-width:210px}
.typeMovement th:first-child,.typeMovement td:first-child{width:280px;min-width:280px;max-width:none}
.stSoCombined th:first-child,.stSoCombined td:first-child{width:300px;min-width:300px;max-width:none}
@media(max-width:760px){#view .table-scroll table th:first-child,#view .table-scroll table td:first-child{min-width:170px;max-width:none}.typeMovement th:first-child,.typeMovement td:first-child{width:220px;min-width:220px}.stSoCombined th:first-child,.stSoCombined td:first-child{width:230px;min-width:230px}}


/* ===== v5.3 UI CONSISTENCY + DEALER FILTERS ===== */
:root{--control-h:40px;--filter-bg:#f7fafc;--filter-border:#d8e5ec}
.kpis{align-items:stretch}.kpis .kpi{height:100%;min-height:106px;display:flex;flex-direction:column;justify-content:center}.kpis .ksub{min-height:28px;display:flex;align-items:center}
.filterCard{margin:10px 0 14px;padding:13px;border:1px solid var(--filter-border);border-radius:12px;background:linear-gradient(180deg,#fbfdff,#f6fafc);box-shadow:0 3px 10px rgba(16,57,78,.055)}
.filterCardHead,.filterCardFoot{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.filterCardHead{margin-bottom:11px}.filterCardHead b{display:block;color:#10394e;font-size:12px}.filterCardHead small,.filterSectionTitle small{display:block;color:#6d8190;font-size:10px;margin-top:2px;font-weight:400}
.filterGrid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:10px 12px;align-items:end}.filterGrid>label,.filterField{grid-column:span 2;min-width:0}.filterGrid>.filterWide{grid-column:span 3}
.filterGrid label,.filterField{display:flex;flex-direction:column;gap:5px;font-size:10px;font-weight:650;color:#35556a}.filterLabel{min-height:14px;font-size:10px;font-weight:650;color:#35556a}
.filterGrid .fi,.filterGrid select.fi,.filterGrid input.fi:not([type=file]),.filterField>details>summary{width:100%;height:var(--control-h);min-height:var(--control-h);padding:0 11px;border-radius:9px;border:1px solid #cbd8e0;background:#fff;font-size:11px;color:#203f52}
.filterGrid input.fi{line-height:var(--control-h)}.filterField>details{width:100%;min-width:0}.filterField>details>summary{display:flex;align-items:center;cursor:pointer;list-style:none}.filterField>details>summary::-webkit-details-marker{display:none}
.filterSection+.filterSection{margin-top:12px;padding-top:12px;border-top:1px solid #e2ebf0}.filterSectionTitle{margin:0 0 8px;color:#16445e}
.filterCardFoot{margin-top:12px;padding-top:11px;border-top:1px solid #e2ebf0}.filterActions{display:flex;align-items:center;justify-content:flex-end;gap:7px;flex-wrap:wrap}.filterActions .chip{min-height:var(--control-h);padding:0 13px;border-radius:9px}
.filterSummary{display:flex;align-items:center;gap:7px;flex-wrap:wrap;min-width:0;flex:1}.filterSummaryMain{display:flex;gap:5px;flex-wrap:wrap}.filterPill{display:inline-flex;align-items:center;gap:5px;padding:5px 8px;border:1px solid #d7e4eb;border-radius:999px;background:#fff;color:#5d7382;font-size:9px;line-height:1.2}.filterPill b{color:#143f58}.filterPill.muted{color:#788997}.filterResultCount{margin-left:auto;color:#10394e;font-size:10px;white-space:nowrap}
.filterAdvanced{margin-top:12px;border:1px dashed #cbdbe4;border-radius:10px;background:#fff}.filterAdvanced>summary{display:flex;align-items:center;gap:8px;padding:10px 12px;cursor:pointer;font-size:10.5px;font-weight:750;color:#17475f;list-style:none}.filterAdvanced>summary::-webkit-details-marker{display:none}.filterAdvanced>summary:before{content:'+';display:grid;place-items:center;width:18px;height:18px;border-radius:50%;background:#dceef6;color:#126282}.filterAdvanced[open]>summary:before{content:'−'}.filterAdvanced>summary small{margin-left:auto;color:#7a8c99;font-weight:400}.filterAdvanced .filterGrid{padding:0 12px 12px}
.historyInfo,.historyTableNote{display:flex;align-items:center;gap:9px;flex-wrap:wrap;padding:8px 10px;border:1px solid #d6e7ef;border-radius:8px;background:#edf6fa;color:#476678;font-size:10px;margin:9px 0}.historyInfo:empty{display:none}.historyInfo b{color:#0f5876}.historyTableNote{margin-bottom:7px}
.historyTotalValue{display:block;font-weight:850;color:#10394e;white-space:nowrap}.historyGrowth{display:block;margin-top:3px;font-size:8.5px;font-weight:750;white-space:nowrap}.historyGrowth.up{color:#147157}.historyGrowth.dn{color:#b0443e}.historyGrowth.flat,.historyGrowth.neutral{color:#71838f}
.filterEmpty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;min-height:130px;padding:24px;text-align:center;border:1px dashed #cbdbe4;border-radius:10px;background:#f8fbfd;color:#6a7e8c}.filterEmpty b{color:#24495e}
.mobileDealerArea{display:block;margin-top:-3px;color:#627a89;font-size:10px}
.toolbar.filterToolbar{padding:9px 10px;border:1px solid #e0e9ef;border-radius:10px;background:#f8fbfd;align-items:end}
.toolbar.filterToolbar>label{gap:5px}.toolbar.filterToolbar select.fi,.toolbar.filterToolbar input.fi:not([type=file]),.toolbar.filterToolbar>select.fi,.toolbar.filterToolbar>input.fi:not([type=file]),.toolbar.filterToolbar>button.chip,.toolbar.filterToolbar>details>summary{min-height:var(--control-h);height:var(--control-h);border-radius:8px}
.toolbar.filterToolbar>button.chip{display:inline-flex;align-items:center;justify-content:center;padding-top:0;padding-bottom:0}.toolbar.filterToolbar .brandPicker>summary,.toolbar.filterToolbar .historyMultiDesktop>summary,.toolbar.filterToolbar .customerStatusMulti>summary{height:var(--control-h);min-height:var(--control-h);border-radius:8px}
