 .filterCardFoot{align-items:stretch}.filterSummary{width:100%;flex-basis:100%}.filterResultCount{width:100%;margin-left:0}.filterActions{width:100%;display:grid;grid-template-columns:1fr 1fr}.filterActions .chip{width:100%}.filterActions .primary,.filterActions .ioAction{grid-column:auto}
 .filterAdvanced .historyMultiDesktop{display:block!important;width:100%;min-width:0}.filterAdvanced .historyBrandChoices{position:static;width:100%;min-width:0;box-shadow:none;margin-top:5px}.filterAdvanced .filterGrid{padding:0 10px 10px}
 .historyInfo,.historyTableNote{font-size:11px}.historyGrowth{font-size:9px}.toolbar.filterToolbar{padding:9px}
}


/* ===== v5.6 FILTER VISUAL HIGHLIGHT — #d5d4fc ===== */
:root{
 --filter-shell:#d5d4fc;
 --filter-shell-soft:rgba(213,212,252,.58);
 --filter-shell-lighter:rgba(213,212,252,.36);
 --filter-border-strong:#aaa8ef;
 --filter-field:#ffffff;
 --filter-footer:rgba(255,255,255,.45);
 --filter-title:#343278;
 --filter-accent:#7774d4
}
.filterCard{
 border-color:var(--filter-border-strong);
 background:var(--filter-shell);
 box-shadow:0 6px 18px rgba(68,65,145,.10),inset 0 1px 0 rgba(255,255,255,.62)
}
.filterCardHead{padding:2px 2px 0}
.filterCardHead b{color:var(--filter-title);font-weight:850;letter-spacing:.15px}
.filterCardHead small{color:#514f88}
.filterSection{
 padding:11px 12px;
 border:1px solid rgba(81,78,164,.23);
 border-radius:10px;
 background:rgba(255,255,255,.52)
}
.filterSection+.filterSection{
 margin-top:10px;
 padding-top:11px;
 border-top:1px solid rgba(81,78,164,.23)
}
.historyFilterCard>.filterSection:first-child,
.historyFilterCard>.filterSection+.filterSection{
 background:rgba(255,255,255,.52);
 border-color:rgba(81,78,164,.23)
}
.filterSectionTitle{
 padding-left:9px;
 border-left:4px solid var(--filter-accent);
 color:var(--filter-title)
}
.historyFilterCard>.filterSection+.filterSection .filterSectionTitle{border-left-color:var(--filter-accent)}
.filterSectionTitle b{font-weight:850}
.filterSectionTitle small{color:#5f5d91}
.filterGrid .fi,
.filterGrid select.fi,
.filterGrid input.fi:not([type=file]),
.filterField>details>summary{
 background:var(--filter-field);
 border-color:#aaa8e7;
 box-shadow:0 1px 0 rgba(255,255,255,.85),inset 0 1px 2px rgba(50,46,114,.035)
}
.filterGrid .fi:hover,
.filterField>details>summary:hover{
 border-color:#8683d7;
 background:#fff
}
.filterGrid .fi:focus,
.filterGrid select.fi:focus,
.filterGrid input.fi:not([type=file]):focus{
 border-color:#706dcc;
 box-shadow:0 0 0 3px rgba(112,109,204,.15);
 outline:none
}
.filterAdvanced{
 border-color:#9b98e4;
 background:rgba(255,255,255,.42);
 box-shadow:inset 0 1px 0 rgba(255,255,255,.6)
}
.filterAdvanced>summary{color:#39367d}
.filterAdvanced>summary:before{background:#e8e7ff;color:#514eac}
.filterAdvanced[open]>summary{
 background:rgba(255,255,255,.45);
 border-radius:10px 10px 0 0
}
.filterAdvanced .filterGrid{
 border-top:1px solid rgba(81,78,164,.22);
 padding-top:10px
}
.filterCardFoot{
 margin-top:11px;
 padding:10px 11px;
 border:1px solid rgba(81,78,164,.25);
 border-radius:9px;
 background:var(--filter-footer)
}
.filterPill{
 background:rgba(255,255,255,.76);
 border-color:#aaa8e7;
 color:#57558a
}
.filterPill b{color:#302e72}
.filterPill:first-child{
 background:#e8e7ff;
 border-color:#9b98e4;
 color:#3e3b86
}
.filterResultCount{font-weight:850;color:#302e72}
.filterActions .chip:not(.primary):not(.ioAction){
 background:#fff;
 border-color:#9694d9
}
.filterActions .chip:not(.primary):not(.ioAction):hover{
 background:#fafaff;
 border-color:#7774cd
}
.toolbar.filterToolbar{
 background:var(--filter-shell);
 border-color:var(--filter-border-strong);
 box-shadow:0 4px 12px rgba(55,52,128,.09)
}
.toolbar.filterToolbar select.fi,
.toolbar.filterToolbar input.fi:not([type=file]),
.toolbar.filterToolbar>select.fi,
.toolbar.filterToolbar>input.fi:not([type=file]),
.toolbar.filterToolbar>details>summary{
 background:#fff;
 border-color:#9896d9
}
.customerFilterCard .filterGrid{
 padding:10px 11px;
 border:1px solid rgba(81,78,164,.23);
 border-radius:10px;
 background:rgba(255,255,255,.52)
}
.customerFilterCard .filterCardFoot{margin-top:10px}
@media(max-width:760px){
 .filterSection{padding:10px}
 .filterCardFoot{padding:10px}
 .customerFilterCard .filterGrid{padding:10px}
}


.customerFilterGrid{grid-template-columns:repeat(4,minmax(0,1fr))}.customerFilterGrid>label,.customerFilterGrid>.filterField{grid-column:span 1}.customerFilterGrid>.filterWide{grid-column:span 2}
.historyMainGrid>label{grid-column:span 3}.historyAreaGrid>label{grid-column:span 3}.historyAreaGrid>.filterWide{grid-column:span 6}.advancedFilterGrid>label,.advancedFilterGrid>.filterField{grid-column:span 3}
