@media(max-width:760px){.customerFilterGrid{grid-template-columns:repeat(2,minmax(0,1fr))}.customerFilterGrid>.filterWide{grid-column:1/-1}.historyMainGrid>label,.historyAreaGrid>label,.advancedFilterGrid>label,.advancedFilterGrid>.filterField{grid-column:span 1}.historyAreaGrid>.filterWide{grid-column:1/-1}}


/* ===== v5.6 HISTORY DISPLAY MULTI + DESKTOP TABLE LEGIBILITY ===== */
.historyDisplayMulti{position:relative;width:100%;min-width:0}
.historyDisplayMulti>summary{width:100%;height:var(--control-h);min-height:var(--control-h);display:flex;align-items:center;padding:0 11px;border:1px solid #aaa8e7;border-radius:9px;background:#fff;color:#203f52;font-size:11px;cursor:pointer;list-style:none}
.historyDisplayMulti>summary::-webkit-details-marker{display:none}
.historyDisplayMulti>summary:after{content:'▾';margin-left:auto;color:#6663a8}
.historyDisplayMulti[open]>summary:after{content:'▴'}
.historyDisplayMulti .historyBrandChoices{left:0;top:100%;width:max-content;min-width:300px;max-width:min(520px,70vw)}
.historyIndicatorChoices{grid-template-columns:1fr!important;min-width:220px!important}
.historyIndicatorChoices label{font-weight:700}
