 table td,table td.n{font-size:12.5px!important;line-height:1.45;padding:9px 8px}
 table td.k{font-size:11.5px!important}
 .cellsub{font-size:10.5px!important;line-height:1.35;margin-top:2px}
 .grouped .metricHead{font-size:12px!important}
