 .textlink{font-size:12.5px}
 .statusBadge,.pill{font-size:10px}
}


/* ===== HISTORY DEALER: BRAND > INDIKATOR > BULAN ===== */
#dealerHistoryRows .historyBrandMatrix{min-width:max-content;border-collapse:separate;border-spacing:0}
#dealerHistoryRows .historyBrandMatrix th,#dealerHistoryRows .historyBrandMatrix td{white-space:nowrap}
#dealerHistoryRows .historyBrandBand{background:#d5d4fc!important;color:#2f2d72!important;font-weight:900!important;font-size:12px!important;border-left:3px solid #7774cd!important;text-align:left!important}
#dealerHistoryRows .historyMetricBand{font-weight:850!important;font-size:11px!important;text-align:left!important;border-left:2px solid #d7e2e9!important}
#dealerHistoryRows .historyMetricBand.metricST{background:#d6edf6!important;color:#144b62!important}
#dealerHistoryRows .historyMetricBand.metricSO{background:#efd8ee!important;color:#693c6b!important}
#dealerHistoryRows .historyMetricBand.metricOMZET{background:#fff0c7!important;color:#705600!important}
