/* ===== v5.7 HISTORY SUMMARY: BIG REGION / REGION / ASM / SALES ===== */
.historySummaryPanel{margin:13px 0 0;border:1px solid #aaa8e7;border-radius:12px;background:#fff;overflow:hidden;box-shadow:0 3px 12px rgba(55,52,128,.07)}
.historySummaryPanel>summary{display:flex;align-items:center;gap:12px;padding:13px 15px;background:#d5d4fc;color:#302e72;cursor:pointer;list-style:none;border-left:5px solid #6663c4}
.historySummaryPanel>summary::-webkit-details-marker{display:none}
.historySummaryPanel>summary:before{content:'›';display:grid;place-items:center;width:21px;height:21px;border-radius:50%;background:#6663c4;color:#fff;font-size:18px;line-height:1;transition:transform .15s ease;flex:0 0 auto}
.historySummaryPanel[open]>summary:before{transform:rotate(90deg)}
.historySummaryPanel>summary span:first-of-type{display:flex;flex-direction:column;gap:3px}
.historySummaryPanel>summary b{font-size:12px;letter-spacing:.2px}
.historySummaryPanel>summary small{font-size:10px;font-weight:500;color:#5d5a91}
.historySummaryBadge{margin-left:auto;padding:5px 9px;border:1px solid #9694d9;border-radius:999px;background:#fff;font-size:9px;font-weight:750;white-space:nowrap}
.historySummaryBody{padding:13px;background:#f8f8ff}
.historySummaryToolbar{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin-bottom:10px}
.historySummaryToolbar label{display:flex;flex-direction:column;gap:5px;font-size:10px;font-weight:750;color:#39367d;min-width:200px}
.historySummaryMeta{font-size:10.5px;color:#5c6880;padding-bottom:8px}
.historySummaryMeta b{color:#302e72}
.historySummaryMatrix{min-width:max-content;border-collapse:separate!important;border-spacing:0!important}
.historySummaryMatrix .summaryName{font-weight:800}
.historySummaryMatrix .summaryDealerCount{font-weight:800;text-align:right!important;background:#eef1ff!important}
@media(min-width:761px){
