 .historySummaryMatrix.summaryThreeCols .summaryContext{position:-webkit-sticky;position:sticky;left:190px;z-index:5;width:180px;min-width:180px;max-width:180px;background:#f5f7fb;box-shadow:1px 0 0 #d8dfeb}
 .historySummaryMatrix.summaryThreeCols .summaryDealerCount{position:-webkit-sticky;position:sticky;left:370px;z-index:5;width:95px;min-width:95px;max-width:95px;box-shadow:3px 0 5px rgba(21,61,80,.08)}
 .historySummaryMatrix.summaryTwoCols .summaryDealerCount{position:-webkit-sticky;position:sticky;left:190px;z-index:5;width:95px;min-width:95px;max-width:95px;box-shadow:3px 0 5px rgba(21,61,80,.08)}
 .historySummaryMatrix thead .summaryName,.historySummaryMatrix thead .summaryContext,.historySummaryMatrix thead .summaryDealerCount{z-index:11;background:#dde7f0!important}
 .historySummaryMatrix tbody tr:nth-child(even) .summaryName,.historySummaryMatrix tbody tr:nth-child(even) .summaryContext{background:#f8fafc}
 .historySummaryMatrix tbody tr:hover .summaryName,.historySummaryMatrix tbody tr:hover .summaryContext{background:#fff9e9}
 .historySummaryMatrix tbody .totalRow .summaryName,.historySummaryMatrix tbody .totalRow .summaryContext,.historySummaryMatrix tbody .totalRow .summaryDealerCount{z-index:10;background:#d7eaf2!important}
}
@media(max-width:760px){.historySummaryPanel>summary{align-items:flex-start}.historySummaryBadge{display:none}.historySummaryBody{padding:10px}.historySummaryToolbar label{width:100%;min-width:0}.historySummaryToolbar .fi{width:100%}}


/* ===== v5.8 HIGHLIGHT KOLOM TOTAL HISTORY + SUMMARY =====
   Berlaku untuk tabel utama History Dealer dan tabel Summary bawah. */
#dealerHistoryRows .historyBrandMatrix .historyBrandTotal,
#historySummaryRows .historyBrandMatrix .historyBrandTotal{
  background:#fff4c7!important;
  color:#5d4900!important;
  font-weight:900!important;
  border-left:2px solid #dfbd3e!important;
  border-right:1px solid #ead990!important;
}

/* Header TOTAL dibuat lebih tegas supaya mudah discan horizontal. */
#dealerHistoryRows .historyBrandMatrix thead .historyBrandTotal,
#historySummaryRows .historyBrandMatrix thead .historyBrandTotal{
  background:#f4dc7a!important;
  color:#493800!important;
  box-shadow:inset 0 -2px 0 #c9a72c;
}

/* Zebra row tetap terbaca tetapi kolom total tidak kehilangan highlight. */
#dealerHistoryRows .historyBrandMatrix tbody tr:nth-child(even) .historyBrandTotal,
#historySummaryRows .historyBrandMatrix tbody tr:nth-child(even) .historyBrandTotal{
  background:#ffefad!important;
}

/* Hover row. */
#dealerHistoryRows .historyBrandMatrix tbody tr:hover .historyBrandTotal,
#historySummaryRows .historyBrandMatrix tbody tr:hover .historyBrandTotal{
  background:#ffe58b!important;
}

/* Perpotongan baris TOTAL bawah + kolom TOTAL samping dibuat paling tegas. */
#dealerHistoryRows .historyBrandMatrix tbody .totalRow .historyBrandTotal,
#historySummaryRows .historyBrandMatrix tbody .totalRow .historyBrandTotal{
  background:#f3d45f!important;
  color:#3f3100!important;
  border-top:2px solid #b99620!important;
}

