/* ===== GLOBAL APP LOADING FEEDBACK ===== */
.appLoading{position:fixed;inset:0;z-index:95;display:grid;place-items:center;padding:22px;background:rgba(230,238,249,.58);-webkit-backdrop-filter:blur(5px) saturate(.8);backdrop-filter:blur(5px) saturate(.8);opacity:0;visibility:hidden;pointer-events:none;transition:opacity .18s ease,visibility .18s ease}
.appLoading.on{opacity:1;visibility:visible;pointer-events:auto}
.appLoading[hidden]{display:none!important}


.appLoadingCard{width:min(360px,calc(100vw - 36px));padding:26px 25px 22px;border:1px solid rgba(255,255,255,.9);border-radius:20px;background:rgba(255,255,255,.96);box-shadow:0 24px 65px rgba(10,37,79,.2);text-align:center;color:#132442}
.appLoadingMark{position:relative;width:64px;height:64px;margin:0 auto 17px;display:grid;place-items:center}
.appLoadingMark:before,.appLoadingMark:after{content:"";position:absolute;border-radius:50%;border:3px solid transparent}
.appLoadingMark:before{inset:0;border-top-color:#1968df;border-right-color:#1cb7d5;animation:appLoadingSpin 1s linear infinite}
.appLoadingMark:after{inset:9px;border-bottom-color:#7257dc;border-left-color:#e69a25;animation:appLoadingSpin .78s linear infinite reverse}
.appLoadingMark i{width:13px;height:13px;border-radius:50%;background:linear-gradient(135deg,#1968df,#1cb7d5);box-shadow:0 0 0 7px #1968df12}
.appLoadingCard h3{margin:0 0 7px;font-size:18px;letter-spacing:-.2px;color:#102753}
.appLoadingCard p{min-height:19px;margin:0;color:#61718b;font-size:12px;line-height:1.55}
.appLoadingTrack{height:4px;margin-top:17px;overflow:hidden;border-radius:99px;background:#e7edf6}
.appLoadingTrack i{display:block;width:42%;height:100%;border-radius:inherit;background:linear-gradient(90deg,#1968df,#1cb7d5,#7257dc);animation:appLoadingSlide 1.25s ease-in-out infinite}
.appLoadingDismiss{margin-top:15px;padding:7px 12px;border:1px solid #d8e1ed;border-radius:9px;background:#f7f9fc;color:#41536f;font-size:11px;font-weight:700;cursor:pointer}
.appLoadingDismiss:hover{background:#edf3fa;border-color:#bfcddd}
.errorRetry{display:inline-flex;margin-top:9px;padding:6px 10px;border:1px solid currentColor;border-radius:8px;background:#fff;color:#8b2925;font-size:11px;font-weight:750;cursor:pointer}
@keyframes appLoadingSpin{to{transform:rotate(360deg)}}
@keyframes appLoadingSlide{0%{transform:translateX(-115%)}55%,100%{transform:translateX(245%)}}
@media(min-width:761px){.appLoading{left:var(--v2side,238px);z-index:59;transition:left .22s ease,opacity .18s ease,visibility .18s ease}}
@media(max-width:760px){.appLoadingCard{padding:23px 20px 20px;border-radius:17px}.appLoadingMark{width:56px;height:56px}.appLoadingCard h3{font-size:17px}}
/* Spinner tetap berputar walau OS mematikan animasi (kalau tidak, terlihat macet/hang). */
@media(prefers-reduced-motion:reduce){.appLoading{transition:none!important}.appLoadingMark:before,.appLoadingMark:after{animation-duration:1.4s!important}.appLoadingTrack i{animation:none!important;width:100%;opacity:.35}}

