#view .v6ewTable th:nth-child(6),#view .v6ewTable td:nth-child(6),#view .v6ewTable th:nth-child(7),#view .v6ewTable td:nth-child(7),#view .v6ewTable th:nth-child(n+10),#view .v6ewTable td:nth-child(n+10){text-align:center!important}
