.v12Sc .gB0{background:#2b7be0!important}.v12Sc .gB1{background:#0e9f6e!important}.v12Sc .gB2{background:#7c4ddb!important}.v12Sc .gB3{background:#e59a2f!important}.v12Sc .gB4{background:#d63a55!important}.v12Sc .gB5{background:#0b8a60!important}.v12Sc td.cB0{background:#e8f0fd}.v12Sc td.cB1{background:#e3f6ee}.v12Sc td.cB2{background:#efe9fd}.v12Sc td.cB3{background:#fdf1dd}.v12Sc td.cB4{background:#fde8ec}.v12Sc td.cB5{background:#e0f3ec}
.v12Sc .v7delta,.v7delta{display:inline-flex;flex-direction:column;align-items:flex-end;gap:2px;text-align:right}.v12Sc .v7delta .cmp{font-size:10px;color:#7C8899;white-space:nowrap;text-align:right}.v12Sc .v7delta .dlt{white-space:nowrap}.v12Sc .targetActual{white-space:nowrap}
.alBars,.alPct,.alSteps{display:none}
@media(max-width:760px){
.appLoading{padding:0;background:radial-gradient(280px 280px at 0 0,#7fb6f5cc,transparent 70%),radial-gradient(260px 260px at 100% 38%,#ffd08acc,transparent 70%),radial-gradient(300px 300px at 25% 100%,#b7a6f2cc,transparent 70%),#eef3fb;-webkit-backdrop-filter:none;backdrop-filter:none}
.appLoadingCard{width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px;border:0;border-radius:0;background:transparent;box-shadow:none}
.appLoadingMark{display:none}
.alBars{display:flex;gap:9px;align-items:flex-end;justify-content:center;height:64px;margin-bottom:14px}
.alBars i{width:14px;border-radius:7px 7px 3px 3px;animation:alBar 1.2s ease-in-out infinite}
.alBars i:nth-child(1){background:linear-gradient(#2b7be0,#2b5fb8);--h:70%}.alBars i:nth-child(2){background:linear-gradient(#0e9f6e,#0b8a60);--h:95%;animation-delay:.14s}.alBars i:nth-child(3){background:linear-gradient(#f07a0c,#ffb020);--h:60%;animation-delay:.28s}.alBars i:nth-child(4){background:linear-gradient(#6d3fd8,#9a72f0);--h:100%;animation-delay:.42s}.alBars i:nth-child(5){background:linear-gradient(#2b7be0,#2b5fb8);--h:80%;animation-delay:.56s}
@keyframes alBar{0%,100%{height:22%}50%{height:var(--h)}}
.alPct{display:block;margin:8px 0 10px;font-size:34px;font-weight:900;color:#16202e;font-variant-numeric:tabular-nums}
.appLoadingTrack{display:block;width:180px;height:6px;margin:0 0 18px}
.appLoadingTrack i{width:var(--alp,0%);animation:none;transition:width .35s ease;background:linear-gradient(90deg,#ffb020,#f07a0c)}
.alSteps{display:inline-grid;gap:10px;text-align:left}
.alSteps em{display:flex;align-items:center;gap:10px;font-style:normal;font-size:13px;font-weight:700;color:#7c8899}
.alSteps em:before{content:"";width:20px;height:20px;box-sizing:border-box;border-radius:50%;border:2px solid #c9d3e3;display:grid;place-items:center;font-size:11px;color:#fff;font-weight:800}
.alSteps em.on{color:#16202e}.alSteps em.on:before{border-color:#f07a0c;border-top-color:transparent;animation:appLoadingSpin .8s linear infinite}
.alSteps em.ok{color:#0e9f6e}.alSteps em.ok:before{content:"✓";background:#0e9f6e;border-color:#0e9f6e}
.appLoadingCard p{margin-bottom:6px}
}
