  .insightLead>div:before{content:"";position:absolute;inset:0 auto 0 0;width:4px;background:#2479df}
  .insightLead>div:nth-child(2){background:linear-gradient(145deg,#fffaf1,#fff3df);border-color:#f0dfbd}
  .insightLead>div:nth-child(2):before{background:#e69a25}
