  .insightLead>div:nth-child(3):before{background:#12a676}
  .insightLead small,.insightStats small{display:block!important;margin:0 0 4px;color:#657892;font-size:9px!important;font-weight:750;line-height:1.35;text-transform:uppercase;letter-spacing:.4px}
  .insightLead b{display:block!important;margin:0;color:#162a43;font-size:12.5px!important;font-weight:700;line-height:1.5;overflow-wrap:anywhere}
  .insightStats{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px!important;margin-top:9px!important}
  .insightStats span{display:block;min-width:0!important;padding:9px 8px;border:1px solid #dfe8f1;border-left:3px solid #2479df;border-radius:9px;background:#f7f9fc}
  .insightStats small{min-height:24px;margin-bottom:3px;font-size:8px!important}
