}
@media(max-width:350px){.insightStats{grid-template-columns:1fr!important}.insightStats small{min-height:0}}
/* One growth language everywhere: overview, brand, team, desktop, and mobile. */
.cmp{display:flex!important;align-items:baseline!important;gap:5px!important;margin:0 0 5px!important;font-family:inherit!important;font-size:10px!important;font-weight:500!important;line-height:1.25!important;color:#26364d!important;white-space:nowrap!important}
.cmpLabel{font-size:9px!important;font-weight:600!important;text-transform:none!important;letter-spacing:0!important;color:#5d6f88!important}
.cmp b{font-size:11px!important;font-weight:600!important;color:#17263c!important}
.dlt{display:inline-flex!important;align-items:center!important;flex-wrap:nowrap!important;gap:3px!important;width:max-content!important;max-width:none!important;margin:0!important;padding:4px 6px!important;border-radius:6px!important;font-family:inherit!important;font-size:10.5px!important;font-weight:500!important;line-height:1.15!important;white-space:nowrap!important}
.dlt.up{background:#e7f7f0!important;color:#087451!important}.dlt.dn{background:#fff0f0!important;color:#b4232d!important}.dlt.fl{background:#edf2f7!important;color:#526176!important}
.growthArrow{font-size:9px!important;line-height:1!important}.growthValue,.growthUnit,.growthSep{font-weight:500!important}.growthUnit{font-size:9px!important}.growthSep{margin:0 1px;opacity:.65}.growthPct{font-size:10.5px!important;font-weight:750!important}
@media(max-width:760px){.table-scroll td .cmp{min-width:118px}}
.demoBanner{display:flex;align-items:center;gap:12px;padding:10px 18px;background:linear-gradient(90deg,#fff3c4,#ffe49a);color:#604500;border-bottom:1px solid #e9c95c;box-shadow:0 4px 14px #73550015;position:-webkit-sticky;position:sticky;top:46px;z-index:45}.demoBanner strong{font-size:12px;letter-spacing:.35px}.demoBanner span{font-size:12px}.demoBanner .chip{margin-left:auto;min-height:34px;background:#fff;border-color:#c9a52c;color:#684b00}.demoEntry{grid-column:1/-1!important;background:#f7b618!important;border-color:#ffd66b!important;color:#15213c!important;font-weight:800!important}.demoModalNote{padding:11px 13px;margin-bottom:12px;border-radius:10px;background:#fff6d9;border:1px solid #ecd271;color:#654b00;font-size:12px}.demoFilters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.demoFilters label,.demoTargetLabel{display:flex;flex-direction:column;gap:5px;font-size:11px;font-weight:750;color:#52647f}.demoTargetLabel{margin-top:10px}.demoTargetLabel select{min-height:120px}.demoMeta{display:block;margin-top:8px;color:#75839a;font-size:11px}.demoActions{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}@media(max-width:760px){.demoBanner{top:var(--mobile-header-height,110px);padding:10px 12px;flex-wrap:wrap}.demoBanner span{width:100%;font-size:11px}.demoBanner .chip{margin-left:0}.demoFilters{grid-template-columns:1fr}.demoEntry{grid-column:auto!important}}


/* ===================================================================
   v6 CLEAN THEME — tampilan terang & bersih (desktop + mobile).
   Hanya lapisan tampilan: semua logika, ID, dan fungsi tetap.
   =================================================================== */
:root{--c6-blue:#0B5CAD;--c6-blue-d:#0A2E57;--c6-blue-s:#EAF3FC;--c6-cyan:#00A5D9;--c6-red:#E5484D;--c6-red-s:#FFF0F1;--c6-green:#12A86B;--c6-green-s:#E8F7F0;--c6-amber:#E7A51A;--c6-amber-s:#FFF6DF;--c6-bg:#F4F7FB;--c6-card:#fff;--c6-text:#152238;--c6-muted:#728098;--c6-line:#E5EBF3;--c6-line2:#EFF3F8;--c6-shadow:0 10px 30px rgba(9,46,92,.07);--c6-r:16px}
html,body{background:var(--c6-bg)!important;color:var(--c6-text)}
body,button,input,select,textarea{font-family:Inter,"Segoe UI",system-ui,-apple-system,Roboto,sans-serif!important}
/* ---------- LOGIN ---------- */
#login,#changePin{background:radial-gradient(circle at 15% 10%,#DCEBFA 0,transparent 45%),radial-gradient(circle at 90% 90%,#E3F6FC 0,transparent 40%),var(--c6-bg)!important}
.lcard{border:1px solid var(--c6-line)!important;box-shadow:0 20px 60px rgba(9,46,92,.12)!important;border-radius:20px!important}
.lcard .llogo{color:var(--c6-blue-d)!important}.lcard .llogo span{color:var(--c6-cyan)!important}
.lfield input{border-radius:10px!important;font-family:inherit!important}
.lbtn{background:var(--c6-blue)!important;border-radius:10px!important;box-shadow:0 8px 18px rgba(11,92,173,.25)!important}
#changePin .llogo{color:var(--c6-blue-d)!important}
/* ---------- KOMPONEN UMUM (semua ukuran) ---------- */
.panel{background:#fff!important;border:1px solid #EBF0F6!important;border-radius:var(--c6-r)!important;box-shadow:var(--c6-shadow)!important}
.panel>.ph,.panel>summary.ph,.foldPanel>summary{background:#fff!important;color:var(--c6-text)!important;border-bottom:1px solid var(--c6-line2)!important;border-left:0!important}
.foldPanel.stTone>summary,.foldPanel.soTone>summary,.foldPanel.ratioTone>summary{background:#fff!important;box-shadow:inset 4px 0 var(--c6-blue)!important}
.foldPanel.soTone>summary{box-shadow:inset 4px 0 var(--c6-red)!important}.foldPanel.ratioTone>summary{box-shadow:inset 4px 0 #7A5AF8!important}
.ph h3{color:var(--c6-text)!important;text-transform:none!important;letter-spacing:0!important;font-size:14px!important;font-weight:750!important}
.ph .hint{font-family:inherit!important;color:var(--c6-muted)!important}
.ptitle{text-transform:none!important;letter-spacing:-.3px!important;color:var(--c6-text)!important;font-weight:800!important}
.psub{color:var(--c6-muted)!important}
.chip{border-radius:10px!important;border-color:var(--c6-line)!important;color:#3D4A5C!important;background:#fff!important;font-weight:650!important}
.chip:hover{border-color:var(--c6-blue)!important}
.chip.on,.chip.primary,.primary{background:var(--c6-blue)!important;border-color:var(--c6-blue)!important;color:#fff!important;box-shadow:0 6px 14px rgba(11,92,173,.22)!important}
.ioAction{background:#fff!important;color:var(--c6-blue)!important;border:1px solid #BFD6EE!important;box-shadow:none!important}
.ioAction:hover{background:var(--c6-blue-s)!important}
input[type=file]::file-selector-button{background:var(--c6-blue-s)!important;color:var(--c6-blue)!important;border:1px solid #BFD6EE!important}
input.fi,select.fi,.fi{font-family:inherit!important;border-radius:10px!important;border-color:var(--c6-line)!important;background:#fff!important}
select.fi.hl{border-color:#BFD6EE!important;background:#F7FBFF!important}
.info{background:var(--c6-blue-s)!important;border-left:3px solid var(--c6-blue)!important;border-radius:10px!important;color:#284766!important}
.banner{border-radius:10px!important}
.statusBadge{border-radius:999px!important;font-family:inherit!important}
.status-active{background:var(--c6-green-s)!important;color:#0B8156!important}
.status-passive{background:var(--c6-red-s)!important;color:#B8232D!important}
.status-idle{background:var(--c6-amber-s)!important;color:#8A5E00!important}
.status-new{background:var(--c6-blue-s)!important;color:var(--c6-blue-d)!important}
.textlink{color:var(--c6-blue)!important}
.table-scroll{border:1px solid var(--c6-line)!important;border-radius:12px!important;background:#fff!important}
table thead th,.table-scroll th,.table-scroll thead th{background:#F7F9FC!important;color:#66758A!important;border-bottom:1px solid var(--c6-line)!important;font-family:inherit!important}
table tbody tr:nth-child(even) td{background:#FCFDFE!important}
.table-scroll tbody tr:hover td,table tbody tr:hover td{background:#F2F7FD!important;box-shadow:none!important}
.table-scroll tbody tr:hover td:first-child{box-shadow:inset 3px 0 var(--c6-blue)!important}
.totalRow td,.table-scroll .totalRow td,tr.tot td{background:#EEF4FB!important;color:var(--c6-blue-d)!important;border-top:1px solid #C9DBEE!important;font-weight:800!important}
.weeklyTable .table-scroll thead th{background:#F7F9FC!important;color:#66758A!important;border-right:1px solid var(--c6-line2)!important}
.weeklyTable .table-scroll thead th:last-child,.weeklyTable .table-scroll thead th.totalGeneric{background:var(--c6-blue-s)!important;color:var(--c6-blue-d)!important}
.weeklyTable tbody tr:last-child td{background:#EEF4FB!important;color:var(--c6-blue-d)!important;border-top:1px solid #C9DBEE!important}
.grouped .metricHead{color:var(--c6-blue-d)!important;text-shadow:none!important}
.grouped .metricHead.metric0{background:#DDEBFA!important}.grouped .metricHead.metric1{background:#DDF4E9!important;color:#0B5E45!important}
.grouped .metricHead.metric2{background:#EBE5FD!important;color:#4A33A8!important}.grouped .metricHead.metric3{background:#FFEFD0!important;color:#7A5200!important}
.grouped .metricHead.metric4{background:#E3E9F2!important}.grouped .metricHead.metric5{background:#D9F2F8!important;color:#086477!important}.grouped .metricHead.metric6{background:#EAF2D8!important;color:#4F6512!important}
.progress>div{background:#EEF2F7!important;border-radius:99px!important}.progress i{border-radius:99px!important}
.dlt.up{background:var(--c6-green-s)!important;color:#0B8156!important}.dlt.dn{background:var(--c6-red-s)!important;color:#B8232D!important}
.insightLead>div{border:1px solid var(--c6-line)!important;background:#fff!important;border-radius:12px!important;box-shadow:inset 0 3px var(--c6-blue)}
.insightLead>div:nth-child(2){box-shadow:inset 0 3px var(--c6-amber)}.insightLead>div:nth-child(3){box-shadow:inset 0 3px var(--c6-green)}
.insightStats span{background:#F7F9FC!important;border-left-color:var(--c6-blue)!important;border-radius:10px!important}
.kpiCompareLevel>summary{background:#fff!important;color:var(--c6-text)!important;border-left:4px solid var(--c6-blue)!important;border-bottom:1px solid var(--c6-line2)!important}
.kpiCompareLevel>summary:before{background:var(--c6-blue)!important}
.kpiCompareLevel>summary .kpiCompareScore{background:var(--c6-blue)!important}
.kpiCompareGroup>h4{background:#F7F9FC!important;color:var(--c6-text)!important;border-bottom:1px solid var(--c6-line)!important;border-left:4px solid var(--c6-blue)!important}
.kpiSummaryGroup>h4{background:var(--c6-blue-s)!important;color:var(--c6-blue-d)!important}
.kpiCompareTable .finalScore,.kpiFinalSummary tbody td:last-child{background:var(--c6-blue-d)!important;border-left-color:var(--c6-cyan)!important}
.kpiCompareTable thead .finalScore{background:var(--c6-blue)!important}
.kpiCompareTable .indicatorScore{background:#FFF6DF!important}
.kpiFinalSummary thead th{background:#F7F9FC!important}
.analysisSummary{background:linear-gradient(155deg,var(--c6-blue-d),var(--c6-blue))!important}
.mhead{background:#fff!important;color:var(--c6-text)!important;border-bottom:1px solid var(--c6-line)!important}
.mhead h3{color:var(--c6-text)!important;text-transform:none!important;letter-spacing:0!important;font-size:15px!important}
.mhead .x{color:var(--c6-muted)!important;background:#F4F7FB!important;border-radius:10px!important}
.modal{border-radius:18px!important}
.tabs button.on{color:var(--c6-blue)!important;border-bottom-color:var(--c6-blue)!important}
.adminFeature>summary{background:#fff!important;color:var(--c6-text)!important}
.adminFeature>summary svg{color:var(--c6-blue)!important}
.infoCard{border:1px solid #EBF0F6!important;border-radius:var(--c6-r)!important;box-shadow:var(--c6-shadow)!important}
.axisLabel{fill:#8A96A7!important}
/* ---------- Tambahan v6: hero, mini bar, tabel proyeksi ---------- */
.v6hero{display:grid;grid-template-columns:auto minmax(0,1fr) minmax(260px,auto);gap:22px;align-items:center;padding:20px 22px;margin-bottom:14px;background:#fff;border:1px solid #EBF0F6;border-radius:var(--c6-r);box-shadow:var(--c6-shadow);position:relative;overflow:hidden}
.v6hero:after{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:linear-gradient(var(--c6-blue) 0 60%,var(--c6-cyan) 60%)}
.v6ring{position:relative;width:128px;height:128px}.v6ring .c{position:absolute;inset:0;display:grid;place-items:center;text-align:center}
.v6ring b{display:block;font-size:22px;line-height:1;color:var(--c6-text)}.v6ring small{font-size:10px;color:var(--c6-muted);line-height:1.35;display:block;margin-top:3px}
.v6hero h2{margin:0;font-size:21px;color:var(--c6-blue-d);letter-spacing:-.3px}
.v6hero .meta{color:var(--c6-muted);font-size:12px;margin-top:4px}
.v6tags{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}
.v6pill{display:inline-flex;align-items:center;padding:3px 9px;border-radius:999px;font-size:10.5px;font-weight:800;white-space:nowrap}
.v6good{background:var(--c6-green-s);color:#0B8156}.v6warn{background:var(--c6-amber-s);color:#8A5E00}.v6bad{background:var(--c6-red-s);color:#B8232D}.v6info{background:var(--c6-blue-s);color:var(--c6-blue-d)}
.v6tl{margin-top:14px;max-width:620px}.v6tl .row6{display:flex;justify-content:space-between;gap:8px;font-size:11px;color:var(--c6-muted);margin-bottom:5px}
.v6bar{height:10px;border-radius:99px;background:#EEF2F7;position:relative}
.v6bar .a{position:absolute;left:0;top:0;bottom:0;border-radius:99px;background:linear-gradient(90deg,var(--c6-blue),#2B8AE0)}
.v6bar .p{position:absolute;left:0;top:0;bottom:0;border-radius:99px;background:repeating-linear-gradient(45deg,#BFD6EE 0 4px,#E3EDF8 4px 8px)}
.v6bar .tg{position:absolute;top:-4px;bottom:-4px;width:2px;background:var(--c6-red)}
.v6stats{display:grid;grid-template-columns:repeat(2,minmax(120px,1fr));gap:10px}
.v6stat{background:#F7F9FC;border:1px solid var(--c6-line);border-radius:12px;padding:10px 12px}
.v6stat .l{font-size:10px;color:var(--c6-muted)}.v6stat .v{font-size:18px;font-weight:800;margin-top:3px;color:var(--c6-text)}.v6stat .s{font-size:10px;color:var(--c6-muted);margin-top:2px}
.v6mb{height:6px;background:#EEF2F7;border-radius:99px;position:relative;margin-top:9px}
.v6mb i{position:absolute;left:0;top:0;bottom:0;border-radius:99px}.v6mb em{position:absolute;top:-3px;bottom:-3px;width:2px;background:var(--c6-blue-d);opacity:.55}
.v6achc{display:flex;align-items:center;gap:8px;min-width:120px}.v6achc .v6mb{flex:1;margin:0;min-width:60px}.v6achc b{font-size:12px;min-width:44px;text-align:right}
.v6legend{display:flex;gap:12px;flex-wrap:wrap;font-size:11px;color:var(--c6-muted);margin-bottom:8px}.v6legend i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:4px;vertical-align:-1px}
.v6cum svg{display:block;width:100%;height:auto}
.v6note{font-size:11px;color:var(--c6-muted);margin-top:8px;line-height:1.5}
.kpi .v6kbadge{position:absolute;top:12px;right:12px;font-size:10px;font-weight:800;padding:2px 7px;border-radius:999px}
@media(max-width:1100px){.v6hero{grid-template-columns:auto minmax(0,1fr)}.v6hero .v6stats{grid-column:1/-1;grid-template-columns:repeat(4,minmax(0,1fr))}}

/* ---------- DESKTOP (≥761px): sidebar putih ---------- */
@media(min-width:761px){
 .topbar{background:#fff!important;color:var(--c6-text)!important;border-right:1px solid var(--c6-line)!important;box-shadow:none!important}
 .topbar .brand,.topbar .logo{padding:6px 4px 14px!important;border-bottom:1px solid var(--c6-line)!important}
 .navBrand,.brand img{background:transparent!important}
 .desktopCollapse{background:#F4F7FB!important;border:1px solid var(--c6-line)!important;color:#4A5870!important}
 .desktopCollapse:hover{background:#EAF3FC!important}
 .nav button{color:#4A5870!important;font-weight:600!important;border-radius:10px!important}
 .nav button:hover{background:#F3F6FA!important;color:var(--c6-text)!important;transform:none!important}
 .nav button.on{background:var(--c6-blue)!important;color:#fff!important;border-color:var(--c6-blue)!important;box-shadow:0 6px 14px rgba(11,92,173,.25)!important}
 .who{border-top:1px solid var(--c6-line)!important}
 .who #namaTop{color:var(--c6-text)!important;font-weight:700}
 .who .rolechip{background:var(--c6-blue-s)!important;color:var(--c6-blue-d)!important;border:0!important}
 .who .out{background:#fff!important;color:#4A5870!important;border:1px solid var(--c6-line)!important}
 .who .out:hover{background:#F3F6FA!important}
 .demoEntry{background:var(--c6-blue-s)!important;color:var(--c6-blue-d)!important}
 .updbar{background:#fff!important;border-bottom:1px solid var(--c6-line)!important;box-shadow:none!important}
 .subbar{background:rgba(244,247,251,.94)!important;border-bottom:1px solid var(--c6-line)!important}
 .subbar #crumb{color:var(--c6-text)!important}
 .kpi{background:#fff!important;border:1px solid #EBF0F6!important;border-radius:14px!important;box-shadow:var(--c6-shadow)!important;min-height:112px}
 .kpi:before{height:0!important}.kpi:after{display:none!important}
 .kpis .kpi{background:#fff!important;color:var(--c6-text)!important}
 .kpis .kpi .klab{color:var(--c6-muted)!important}.kpis .kpi .kval{color:var(--c6-text)!important}.kpis .kpi .ksub{color:var(--c6-muted)!important;font-family:inherit!important}
 .klab{text-transform:uppercase}
 .kval{font-size:23px!important}
 .toolbar{background:#F7F9FC!important;border-color:var(--c6-line)!important}
 .mask{background:rgba(10,25,45,.45)!important}
}

/* ---------- MOBILE (≤760px): putih bersih ---------- */
@media(max-width:760px){
 html,body{background:var(--c6-bg)!important}
 #app{background:var(--c6-bg)!important}
 .topbar{background:#fff!important;color:var(--c6-text)!important;border-bottom:1px solid var(--c6-line)!important}
 .navBrand{background:transparent!important;padding:0!important}
 .who{color:var(--c6-text)!important}
 .who .out{color:#4A5870!important;background:#fff!important;border:1px solid var(--c6-line)!important}
 .rolechip{background:var(--c6-blue-s)!important;color:var(--c6-blue-d)!important}
 .updbar{background:#F7F9FC!important;color:#5A6B82!important;border-radius:0!important;border-bottom:1px solid var(--c6-line)!important}
 .subbar{background:var(--c6-bg)!important}
 .ptitle{font-size:22px!important}
 .kpis .kpi,.kpi{background:#fff!important;color:var(--c6-text)!important;border:1px solid #EBF0F6!important;border-radius:14px!important;box-shadow:var(--c6-shadow)!important}
 .kpi .klab{color:var(--c6-muted)!important}.kpi .kval{color:var(--c6-text)!important;font-size:22px!important}.kpi .ksub{color:var(--c6-muted)!important}
 .kpi::before{display:none!important}
 .panel,.infoCard,.mobileCard{border-radius:14px!important}
 .mBottom{background:#fff!important;border-top:1px solid var(--c6-line)!important;box-shadow:0 -4px 16px rgba(9,46,92,.06)!important}
 .mBottom button{color:#7B889B!important}
 .mBottom button.on{color:var(--c6-blue)!important;font-weight:800!important}
 .mBottom button.on svg{filter:none!important}
 .mBottom [data-mobile-page="ai"] span{color:#7B889B!important}
 .mBottom [data-mobile-page="ai"].on span{color:var(--c6-blue)!important}
 .mBottom [data-mobile-page="ai"] .oceanLogoCrop{border-color:#fff!important}
 .mobileMore{background:var(--c6-bg)!important}
 .mobileMore header{background:#fff!important;color:var(--c6-text)!important;border-bottom:1px solid var(--c6-line)}
 .mobileMore header small,.mobileMore header p{color:var(--c6-muted)!important}
 .mobileMore h2{color:var(--c6-blue-d)!important}
 .moreBack{color:var(--c6-blue)!important}
 .heroOrbit{border-color:var(--c6-line)!important;background:var(--c6-blue-s)!important}.heroOrbit svg{color:var(--c6-blue)!important}
 .moreCard{border-color:var(--c6-line)!important}.moreCard.selected{border:2px solid var(--c6-blue)!important}
 .menuArt{background:var(--c6-blue-s)!important;color:var(--c6-blue)!important}
 .v6hero{grid-template-columns:1fr;justify-items:center;text-align:center;padding:18px 14px}
 .v6hero .v6tags{justify-content:center}.v6tl{width:100%}
 .v6hero .v6stats{grid-template-columns:1fr 1fr;width:100%}
 .v6hero h2{font-size:18px}
}
/* v6: netralkan warna pastel panel yang dipaksa lewat #view */
#view .panel>.ph,#view .panel>summary,#view .panel.stTone>summary,#view .panel.soTone>summary,#view .panel.ratioTone>summary{background:#fff!important;color:var(--c6-text)!important;border-bottom:1px solid var(--c6-line2)!important}
#view .panel.stTone>summary{box-shadow:inset 4px 0 var(--c6-blue)!important}#view .panel.soTone>summary{box-shadow:inset 4px 0 var(--c6-red)!important}#view .panel.ratioTone>summary{box-shadow:inset 4px 0 #7A5AF8!important}
#view .dailySummaryPanel{border-color:#EBF0F6!important;border-radius:var(--c6-r)!important;box-shadow:var(--c6-shadow)!important}
#view .dailySummaryPanel>summary{background:#fff!important;color:var(--c6-text)!important;text-transform:none!important;letter-spacing:0!important;font-size:13px!important}
#view .dailySummaryPanel>summary:before,.brandAnalysisFold>summary:before{background:var(--c6-blue)!important}
#view .dailySummaryPanel[open]>summary{border-bottom:1px solid var(--c6-line2)!important}
details.panel.v2AutoFold>summary.ph:before{background:var(--c6-blue-s)!important;color:var(--c6-blue)!important}
@media(min-width:761px){.moneyLong{display:none!important}.moneyShort{display:inline!important;font-size:inherit!important}}
.trendPoint .plotBar{fill:#8DB6E0}.trendPoint[aria-pressed="true"] .plotBar{fill:var(--c6-blue)}.growthLabel{fill:#C2410C!important}
.ksub,.kpi .ksub{font-family:inherit!important}
.nav button{text-transform:none!important;letter-spacing:0!important}

/* ===================== v6.1 COLORFUL + INTERAKTIF ===================== */
:root{--k1:#0B5CAD;--k1s:#E6F0FB;--k2:#7A5AF8;--k2s:#F0ECFF;--k3:#0E9F8E;--k3s:#E3F7F4;--k4:#E08A00;--k4s:#FFF3DC;--k5:#E0457B;--k5s:#FDE8F0;--k6:#00A5D9;--k6s:#E0F5FC}
/* Kartu KPI berwarna */
.kpis .kpi,.kpi{--kc:var(--k1);--ks:var(--k1s);background:linear-gradient(140deg,var(--ks) 0%,#fff 62%)!important;border:1px solid color-mix(in srgb,var(--kc) 22%,#fff)!important;border-left:4px solid var(--kc)!important;transition:transform .18s ease,box-shadow .18s ease!important;position:relative;overflow:hidden}
.kpis .kpi:nth-child(6n+2){--kc:var(--k2);--ks:var(--k2s)}.kpis .kpi:nth-child(6n+3){--kc:var(--k3);--ks:var(--k3s)}.kpis .kpi:nth-child(6n+4){--kc:var(--k4);--ks:var(--k4s)}.kpis .kpi:nth-child(6n+5){--kc:var(--k5);--ks:var(--k5s)}.kpis .kpi:nth-child(6n){--kc:var(--k6);--ks:var(--k6s)}
.kpis .kpi .klab{color:var(--kc)!important;font-weight:800!important}
.kpis .kpi:after{content:""!important;display:block!important;position:absolute;right:-26px;top:-26px;width:86px;height:86px;border-radius:50%;background:var(--kc);opacity:.08;z-index:0}
.kpis .kpi:hover{transform:translateY(-3px)!important;box-shadow:0 16px 32px color-mix(in srgb,var(--kc) 22%,transparent)!important}
.kpis .kpi[data-jump]:hover .klab:after{content:" →"}
/* Header panel dengan aksen warna bergilir */
#view .panel{--pc:var(--k1)}#view .panel:nth-of-type(5n+2){--pc:var(--k2)}#view .panel:nth-of-type(5n+3){--pc:var(--k3)}#view .panel:nth-of-type(5n+4){--pc:var(--k4)}#view .panel:nth-of-type(5n){--pc:var(--k5)}
#view .panel>.ph,#view .panel>summary.ph{background:linear-gradient(90deg,color-mix(in srgb,var(--pc) 9%,#fff),#fff 55%)!important}
#view .panel>.ph h3:before,#view .panel>summary.ph h3:before{content:"";display:inline-block;width:8px;height:8px;border-radius:3px;background:var(--pc);margin-right:8px;vertical-align:1px}
#view .panel{transition:box-shadow .2s ease}#view .panel:hover{box-shadow:0 14px 34px rgba(9,46,92,.1)!important}
/* Hero lebih hidup */
.v6hero{background:radial-gradient(circle at 96% 8%,#DDF3FB 0,transparent 30%),radial-gradient(circle at 60% 120%,#EEE9FF 0,transparent 35%),linear-gradient(120deg,#F3F8FE,#fff 55%)!important}
.v6stat{background:#fff!important;transition:transform .15s ease}.v6stat:hover{transform:translateY(-2px)}
.v6stat:nth-child(1){border-top:3px solid var(--k1)!important}.v6stat:nth-child(2){border-top:3px solid var(--k5)!important}.v6stat:nth-child(3){border-top:3px solid var(--k3)!important}.v6stat:nth-child(4){border-top:3px solid var(--k4)!important}
/* Tabel: baris interaktif */
.table-scroll tbody tr{transition:background .12s ease}
/* Sel heatmap (sebaran minggu & harian per brand) */
.v6heat{display:inline-flex;align-items:center;justify-content:center;min-width:46px;padding:5px 8px;border-radius:8px;font-weight:800;font-size:12px;font-variant-numeric:tabular-nums;transition:transform .12s ease,box-shadow .12s ease;cursor:default}
.v6heat:hover{transform:scale(1.12);box-shadow:0 4px 10px rgba(11,92,173,.3)}
.v6heat.v6zero{background:#F4F6F9;color:#B0B9C6}
.weeklyTable td,.v6dailyTable td{text-align:center!important}.weeklyTable td:first-child,.v6dailyTable td:first-child{text-align:left!important}
/* Kalender harian */
.v6cal{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:7px}
.v6calh{font-size:11px;font-weight:700;color:var(--c6-muted);text-align:center;padding-bottom:2px}.v6calh.v6sun{color:var(--c6-red)}
.v6day{position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:1px;min-height:66px;padding:7px 8px;border-radius:11px;border:1px solid transparent;background:#F4F6F9;font:inherit;text-align:left;color:var(--c6-text);overflow:hidden;cursor:pointer;transition:transform .14s ease,box-shadow .14s ease}
.v6day b{font-size:13px}.v6day span{font-size:11px;font-weight:700}.v6day small{font-size:10px;opacity:.8}
.v6day i{position:absolute;left:0;bottom:0;height:3px;background:currentColor;opacity:.55}
.v6day:hover{transform:translateY(-2px);box-shadow:0 8px 18px rgba(9,46,92,.14)}
.v6day.v6ok{background:#DDF4E9;color:#0B6A46}.v6day.v6mid{background:#FFF1CC;color:#7A5200}.v6day.v6low{background:#FFE1E4;color:#A61B2B}
.v6day.v6sunday b{color:var(--c6-red)}
.v6day.v6today{outline:2px solid var(--c6-blue);outline-offset:1px}
.v6day.v6future{background:#F9FAFC;border:1px dashed #D3DCE7;color:#8A96A7;cursor:default}.v6day.v6future:hover{transform:none;box-shadow:none}
/* Medali peringkat */
.v6medal{display:inline-flex;align-items:center;gap:4px;font-size:18px;line-height:1}.v6medal b{font-size:12px;padding:2px 7px;border-radius:999px}
.v6gold b{background:#FFE7A3;color:#7A5300}.v6silver b{background:#E4E9F0;color:#44536A}.v6bronze b{background:#F6D8C2;color:#7A3E12}
.rankNumber:has(.v6medal){background:transparent!important;padding:0!important}
tr:has(.v6gold) td{background:#FFFAEB!important}tr:has(.v6gold) td:first-child{box-shadow:inset 4px 0 #E8B21A!important}
tr:has(.v6silver) td{background:#F6F8FB!important}tr:has(.v6silver) td:first-child{box-shadow:inset 4px 0 #9AA6B6!important}
tr:has(.v6bronze) td{background:#FDF5EF!important}tr:has(.v6bronze) td:first-child{box-shadow:inset 4px 0 #C87F4A!important}
.mobileCard:has(.v6gold){border-left:4px solid #E8B21A!important;background:#FFFAEB!important}.mobileCard:has(.v6silver){border-left:4px solid #9AA6B6!important}.mobileCard:has(.v6bronze){border-left:4px solid #C87F4A!important;background:#FDF5EF!important}
@media(max-width:760px){.v6cal{gap:4px}.v6day{min-height:54px;padding:5px}.v6day small{display:none}.v6day span{font-size:10px}.kpis .kpi{border-left-width:4px!important}}
@media(prefers-reduced-motion:reduce){.v6heat,.v6day,.kpis .kpi,.v6stat{transition:none!important}}

/* ===================== v6.2 SIDEBAR & NAV BAWAH BIRU ===================== */
@media(min-width:761px){
 .topbar{background:linear-gradient(170deg,#0B5CAD 0%,#0A4A8F 55%,#0A2E57 100%)!important;color:#fff!important;border-right:0!important;box-shadow:6px 0 24px rgba(10,46,87,.18)!important}
 .topbar .brand,.topbar .logo{border-bottom:1px solid rgba(255,255,255,.14)!important}
 .navBrand,.brand img{background:#fff!important;border-radius:12px!important;padding:6px 10px!important}
 .desktopCollapse{background:rgba(255,255,255,.1)!important;border:1px solid rgba(255,255,255,.2)!important;color:#E3EEFA!important}
 .desktopCollapse:hover{background:rgba(255,255,255,.18)!important}
 .nav button{color:#CFE0F3!important}
 .nav button:hover{background:rgba(255,255,255,.1)!important;color:#fff!important}
 .nav button.on{background:#fff!important;color:#0B5CAD!important;border-color:#fff!important;box-shadow:0 8px 18px rgba(3,20,45,.28)!important;font-weight:800!important}
 .who{border-top:1px solid rgba(255,255,255,.16)!important}
 .who #namaTop{color:#fff!important}
 .who .rolechip{background:rgba(255,255,255,.16)!important;color:#fff!important}
 .who .out{background:rgba(255,255,255,.08)!important;color:#E3EEFA!important;border:1px solid rgba(255,255,255,.22)!important}
 .who .out:hover{background:rgba(255,255,255,.18)!important}
 .demoEntry{background:rgba(255,255,255,.16)!important;color:#fff!important}
}
@media(max-width:760px){
 .mBottom{background:linear-gradient(180deg,#0B5CAD,#0A4A8F)!important;border-top:0!important;box-shadow:0 -6px 18px rgba(10,46,87,.22)!important}
 .mBottom button{color:#BFD6EE!important}
 .mBottom button.on{color:#fff!important;font-weight:800!important}
 .mBottom button.on svg{filter:drop-shadow(0 0 5px rgba(255,255,255,.55))!important}
 .mBottom [data-mobile-page="ai"] span{color:#BFD6EE!important}
 .mBottom [data-mobile-page="ai"].on span{color:#fff!important}
 .mBottom [data-mobile-page="ai"] .oceanLogoCrop{border-color:#0B5CAD!important}
}

/* ===================== v6.3 HEADER TABEL LEBIH TEGAS ===================== */
#view table thead th,#view .table-scroll thead th,.modal table thead th,#view .weeklyTable .table-scroll thead th,
#view .grouped thead tr:nth-child(2) th,#view .kpiCompareTable thead tr:nth-child(2) th,#view .kpiFinalSummary thead th,
#teamRows .grouped thead th.lc,#brandIndicatorRows .grouped thead th:first-child,#view .kpiCompareTable thead .identityName,#view .kpiCompareTable thead .identityRegion,#dealerHistoryRows thead th[rowspan]{
 background:#0B5CAD!important;color:#fff!important;border-bottom:0!important;border-right:1px solid rgba(255,255,255,.14)!important;font-weight:800!important;letter-spacing:.35px!important}
#view .weeklyTable .table-scroll thead th:last-child,#view .weeklyTable .table-scroll thead th.totalGeneric,#view .kpiCompareTable thead .finalScore{background:#0A2E57!important;color:#fff!important}
#view table thead th *,.modal table thead th *{color:inherit!important}
#view .sortableHeader::after,.modal .sortableHeader::after{color:#fff!important;opacity:.7}
#view .sortableHeader[aria-sort]::after{color:#FFD54A!important;opacity:1}
#view table thead th:hover{background:#0A4A8F!important}
/* Header grup (baris atas tabel bertingkat) — warna tegas per kelompok */
#view .grouped .metricHead,#view .kpiCompareTable thead tr:first-child .metricHead{color:#fff!important;border-left:2px solid #fff!important}
#view .grouped .metricHead.metric0,#view .kpiCompareTable thead tr:first-child .metric0{background:#0A2E57!important}
#view .grouped .metricHead.metric1,#view .kpiCompareTable thead tr:first-child .metric1{background:#0E9F8E!important}
#view .grouped .metricHead.metric2,#view .kpiCompareTable thead tr:first-child .metric2{background:#7A5AF8!important}
#view .grouped .metricHead.metric3,#view .kpiCompareTable thead tr:first-child .metric3{background:#E08A00!important}
#view .grouped .metricHead.metric4{background:#E0457B!important}#view .grouped .metricHead.metric5{background:#00A5D9!important}#view .grouped .metricHead.metric6{background:#5C7C12!important}
.table-scroll{border-color:#C9DBEE!important}

/* ===================== v6.4 ADMIN: panel biru + pemisah jelas ===================== */
.adminFeature .desktopChartExpand{display:none!important}
#view .adminFeature{margin:0 0 14px!important;border:1px solid #BFD6EE!important;border-radius:14px!important;overflow:hidden;box-shadow:0 8px 22px rgba(11,92,173,.10)!important}
#view .adminFeature>summary,#view details.panel.adminFeature>summary.ph{background:linear-gradient(100deg,#0B5CAD,#0A4A8F)!important;color:#fff!important;border-bottom:0!important;padding:15px 18px!important}
#view .adminFeature:nth-of-type(even)>summary,#view details.panel.adminFeature:nth-of-type(even)>summary.ph{background:linear-gradient(100deg,#0A4A8F,#0A2E57)!important}
#view .adminFeature>summary *,#view .adminFeature>summary h3{color:#fff!important}
#view .adminFeature>summary h3:before{display:none!important}
#view .adminFeature>summary small{color:#CFE0F3!important}
#view .adminFeature>summary svg{color:#fff!important;background:rgba(255,255,255,.14);border-radius:9px;padding:4px;width:30px!important;height:30px!important}
#view .adminFeature>summary:after{color:#fff!important}
#view .adminFeature>summary:hover{filter:brightness(1.08)}
#view .adminFeature[open]{border-color:#0B5CAD!important}
#view .adminFeature[open]>summary{box-shadow:inset 0 -3px #00A5D9!important}
#view .adminFeature>.pb,#view .adminFeature>.adminFeatureContent{background:#F7FAFE!important}
#view .adminFeature .adminFeatureContent>.ph,#view .adminFeature .panel>.ph,#view .adminFeature .panel>summary{background:#EAF3FC!important;color:#0A2E57!important;border-bottom:1px solid #C9DBEE!important}
#view .adminFeature .panel>.ph h3:before{background:#0B5CAD!important}
#view .adminFeature .toolbar{background:#fff!important;border:1px solid #D6E4F3!important}
.adminFinder .fi{border-color:#BFD6EE!important}

/* ===================== v6.5 ===================== */
/* 1) History dealer: warna header dibedakan per lapisan & metrik */
#view .historyBrandMatrix thead th[rowspan]{background:#0A2E57!important;color:#fff!important}
#view .historyBrandMatrix .historyBrandBand{background:#5B3FD6!important;color:#fff!important;border-left:3px solid #fff!important;font-size:12.5px!important}
#view .historyBrandMatrix .historyMetricBand.metricST{background:#0B5CAD!important;color:#fff!important}
#view .historyBrandMatrix .historyMetricBand.metricSO{background:#B0357E!important;color:#fff!important}
#view .historyBrandMatrix .historyMetricBand.metricOMZET{background:#C77700!important;color:#fff!important}
#view .historyBrandMatrix .historyMonthHead.metricST{background:#DCEBFA!important;color:#0A2E57!important}
#view .historyBrandMatrix .historyMonthHead.metricSO{background:#F8E1EE!important;color:#7E1F5A!important}
#view .historyBrandMatrix .historyMonthHead.metricOMZET{background:#FFF0D2!important;color:#6B4500!important}
#view .historyBrandMatrix .historyMonthHead .cellsub{color:inherit!important;opacity:.8}
#view .historyBrandMatrix .historyBrandTotal.metricST{background:#0A2E57!important;color:#fff!important}
#view .historyBrandMatrix .historyBrandTotal.metricSO{background:#7E1F5A!important;color:#fff!important}
#view .historyBrandMatrix .historyBrandTotal.metricOMZET{background:#8A5200!important;color:#fff!important}
#view .historyBrandMatrix .historyMonthHead .sortableHeader::after,#view .historyBrandMatrix .historyMonthHead.sortableHeader::after{color:inherit!important}
/* 3) Tombol kontak: tanpa garis bawah, WhatsApp hijau menarik */
a.chip,.contactLinks a{text-decoration:none!important}
.contactLinks .contactWhatsApp,a.contactWhatsApp{display:inline-flex!important;align-items:center;justify-content:center;gap:8px;min-height:46px;padding:10px 18px!important;border:0!important;border-radius:999px!important;background:linear-gradient(135deg,#25D366,#128C7E)!important;color:#fff!important;font-weight:800!important;font-size:13px!important;box-shadow:0 8px 18px rgba(18,140,126,.3)!important;transition:transform .15s ease,box-shadow .15s ease}
.contactLinks .contactWhatsApp:hover{transform:translateY(-2px);box-shadow:0 12px 22px rgba(18,140,126,.38)!important}
.contactLinks .contactPhone,a.contactPhone{display:inline-flex!important;align-items:center;gap:6px;border:1px solid #BFD6EE!important;background:#EAF3FC!important;color:#0B5CAD!important;border-radius:999px!important;padding:9px 16px!important;font-weight:700!important}
.contactLinks .contactPhone:before{content:"☎"}
/* 5) Header sticky atas: biru */
.updbar{background:#0A2E57!important;color:#CFE0F3!important;border-bottom:0!important}
.updbar b{color:#fff!important}.updbar .sep{color:rgba(255,255,255,.3)!important}
.updbar .dot{background:#3DDC97!important;box-shadow:0 0 0 4px rgba(61,220,151,.2)!important}
.updbar .chip.refresh{background:rgba(255,255,255,.12)!important;color:#fff!important;border:1px solid rgba(255,255,255,.3)!important}
.subbar{background:#0B5CAD!important;border-bottom:0!important;box-shadow:0 6px 16px rgba(10,46,87,.15)!important}
.subbar #crumb{color:#fff!important}
.periodControls label{color:#CFE0F3!important}
.subbar select.fi,.subbar select.fi.hl{background:#fff!important;border-color:#fff!important;color:#0A2E57!important}
.subbar .chip{background:rgba(255,255,255,.14)!important;color:#fff!important;border-color:rgba(255,255,255,.3)!important}
@media(max-width:760px){
 .topbar{background:linear-gradient(135deg,#0B5CAD,#0A2E57)!important;border-bottom:0!important}
 .topbar .navBrand{background:#fff!important;border-radius:10px!important;padding:4px 8px!important}
 .who,.who #namaTop{color:#fff!important}
 .who .out{background:rgba(255,255,255,.12)!important;color:#fff!important;border:1px solid rgba(255,255,255,.3)!important}
 .rolechip{background:rgba(255,255,255,.18)!important;color:#fff!important}
 .subbar.filtersOpen .periodControls{background:#0A4A8F!important}
 /* 2) Kartu menu rincian dealer (mobile): biru */
 .dealerTabs .modalTab{background:#0B5CAD!important;color:#fff!important;border:1px solid #0B5CAD!important;box-shadow:0 4px 10px rgba(11,92,173,.2)}
 .dealerTabs .modalTab svg{color:#fff!important}
 .dealerTabs .modalTab.active{background:#0A2E57!important;border-color:#00A5D9!important;box-shadow:inset 0 -3px #00A5D9,0 6px 14px rgba(10,46,87,.3)!important}
 .contactLinks .contactWhatsApp{width:100%}
}
.v6tlfoot{position:relative;margin-top:5px;padding-top:17px;font-size:11px;min-height:17px}
.v6tgl{position:absolute;top:0;transform:translateX(-50%);color:var(--c6-red);font-weight:700;white-space:nowrap}
.v6tt{display:block;text-align:right;margin-top:3px;color:var(--c6-muted)}

/* v6.7 popup kalender */
.v6popHead{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-bottom:14px}
.v6seg{display:inline-flex;flex-wrap:wrap;gap:4px;padding:4px;border-radius:12px;background:#EAF3FC;margin-bottom:12px}
.v6segBtn{border:0;background:transparent;color:#0A4A8F;font-weight:700;font-size:12px;padding:8px 14px;border-radius:9px;cursor:pointer}
@media(hover:hover){.v6segBtn:hover{background:#fff}}.v6segBtn.on{background:#0B5CAD;color:#fff;box-shadow:0 4px 10px rgba(11,92,173,.25)}
@media(max-width:760px){.v6popHead{grid-template-columns:1fr 1fr}.v6seg{display:flex}.v6segBtn{flex:1 1 30%;padding:10px 6px}}
/* v6.8 pola hari */
.v6dowGrid{display:grid;grid-template-columns:1fr 1.2fr;gap:18px;align-items:start}.v6dowGrid>*{min-width:0}
.v6dow{display:grid;grid-template-columns:repeat(7,1fr);gap:8px;align-items:end;height:230px;padding-top:10px}
.v6dowb{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;gap:5px}
.v6dowb i{display:block;width:72%;border-radius:8px 8px 3px 3px;background:linear-gradient(180deg,#2B8AE0,#0B5CAD);transition:filter .15s}.v6dowb:hover i{filter:brightness(1.15)}
.v6dowb i.low{background:linear-gradient(180deg,#F59CA6,#E5484D)}.v6dowb b{font-size:12px}.v6dowb small{color:var(--c6-muted);font-weight:700}.v6dowb .v6pill{font-size:9.5px;padding:2px 6px}
.v6insight{margin-top:12px;background:linear-gradient(135deg,#0A2E57,#0B5CAD);color:#fff;border-radius:12px;padding:12px 14px;line-height:1.6;font-size:12px}.v6insight b{color:#FFD54A}
@media(max-width:900px){.v6dowGrid{grid-template-columns:1fr}}
.v6dowGrid .v6heat{min-width:36px;padding:4px 5px;font-size:11px}.v6dowGrid .table-scroll td,.v6dowGrid .table-scroll th{padding:8px 6px!important}
/* v6.9 Early Warning & Analisa */
.v6ctrl{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-bottom:14px}.v6ctrl .hint{margin-left:auto}
.v6inline{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:700;color:var(--c6-blue-d)}.v6inline select{min-width:150px}
.v6kpis{margin-bottom:14px}.v6kpis .kpi{cursor:default}
.v6who{display:flex;gap:9px;align-items:center;min-width:180px}.v6av{width:30px;height:30px;border-radius:50%;display:inline-grid;place-items:center;font-weight:800;font-size:11px;background:var(--c6-blue-s);color:var(--c6-blue);flex:0 0 auto}.v6av.hot{background:#FFF3DC;color:#8A5E00}
.v6spark{display:block}
.v6wa{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:7px 13px;background:linear-gradient(135deg,#25D366,#128C7E);color:#fff!important;font-weight:800;font-size:11.5px;text-decoration:none!important;box-shadow:0 5px 12px rgba(18,140,126,.25);white-space:nowrap;transition:transform .15s}.v6wa:hover{transform:translateY(-1px)}
.v6anaHead{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between;margin-bottom:14px}
.v6anaHead .v6segBtn{font-size:13px;padding:10px 16px}
.v6ws{display:inline-grid;place-items:center;min-width:36px;height:28px;padding:0 6px;border-radius:8px;font-weight:800;font-size:11px;border:0;font-family:inherit}
.v6ws.has{background:#DDEBFA;color:#0A2E57}.v6ws.opp{background:#FFF3DC;color:#8A5E00;border:1.5px dashed #E0A93A;cursor:pointer}.v6ws.opp:hover{background:#FFE7B0;transform:scale(1.08)}.v6ws.none{background:#F4F6F9;color:#C3CAD4}
.v6opp{display:flex;gap:10px;align-items:center;padding:10px 0;border-bottom:1px dashed var(--c6-line)}.v6opp:last-child{border:0}.v6oppR{margin-left:auto;text-align:right;display:flex;flex-direction:column;align-items:flex-end;gap:4px}
.v6rk{width:26px;height:26px;border-radius:8px;display:grid;place-items:center;font-weight:800;background:#FFF3DC;color:#8A5E00;flex:0 0 auto}
.v6dcard{border:1px solid var(--c6-line);border-radius:14px;padding:12px 14px;background:#fff;display:grid;grid-template-columns:minmax(0,1.3fr) auto auto;gap:14px;align-items:center;margin-bottom:10px;transition:box-shadow .15s}.v6dcard:hover{box-shadow:0 10px 24px rgba(9,46,92,.1)}
.v6dmid{display:flex;gap:18px;align-items:center}.v6pot{font-size:10.5px;color:var(--c6-muted)}.v6pot b{display:block;font-size:17px;color:var(--c6-text)}.v6pot small{display:block;font-size:9px;margin-top:2px}
.v6dact{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}
.v6vio{background:#F0ECFF;color:#4A33A8}
.v6funnel{display:flex;flex-direction:column;gap:9px}.v6fr{display:grid;grid-template-columns:190px 1fr 56px;gap:12px;align-items:center}
.v6fb{height:30px;border-radius:9px;background:#EEF2F7;position:relative;overflow:hidden}.v6fb i{position:absolute;left:0;top:0;bottom:0;border-radius:9px}.v6fb span{position:absolute;left:10px;top:7px;font-weight:800;color:#fff;font-size:12px;text-shadow:0 1px 2px rgba(0,0,0,.25)}
@media(max-width:760px){.v6dcard{grid-template-columns:1fr}.v6dact{justify-content:flex-start}.v6fr{grid-template-columns:110px 1fr 44px}.v6ctrl .hint{margin-left:0}.v6anaHead .v6seg{display:flex;width:100%}.v6anaHead .v6segBtn{flex:1;padding:10px 6px;font-size:12px}}
/* v6.10 filter bertingkat & komparasi */
.v6fbar{display:grid;grid-template-columns:repeat(5,minmax(0,1fr)) auto;gap:10px;align-items:end;background:#EAF3FC;border:1px solid #C9DBEE;border-radius:14px;padding:12px 14px;margin-bottom:14px}
.v6fbar label{display:flex;flex-direction:column;gap:5px;font-size:11px;font-weight:800;color:#0A2E57;text-transform:uppercase;letter-spacing:.3px}
.v6fbar .fi{width:100%}
.v6stack{display:grid;grid-template-columns:minmax(0,1fr);gap:0}
.v6csTable th{white-space:nowrap}
.v6cmp2{display:grid;grid-template-columns:1fr 1fr;gap:16px}.v6cmpBox{border:1px solid var(--c6-line);border-radius:14px;padding:14px;background:#F7FAFE}.v6cmpBox.cur{background:#F2FBF7;border-color:#BFE8D5}
.v6funHead{font-weight:800;color:var(--c6-blue-d);margin-bottom:10px}.v6cmpBox.cur .v6funHead{color:#0B6A46}
.v6cmpBox .v6fr{grid-template-columns:150px 1fr 50px}
@media(max-width:1000px){.v6fbar{grid-template-columns:1fr 1fr}.v6cmp2{grid-template-columns:1fr}}
@media(max-width:760px){.v6fbar{grid-template-columns:1fr 1fr}.v6fbar .chip{grid-column:1/-1}.v6cmpBox .v6fr{grid-template-columns:100px 1fr 44px}}
/* 4) Rincian Transaksi: judul tidak tertutup ikon */
#view details.panel.v2AutoFold>summary.ph{padding-left:48px!important}
#view details.panel.v2AutoFold>summary.ph:before{left:14px!important}
#view .transactionDetailPanel>summary.ph{padding-left:48px!important;border-left:0!important}
#view .transactionDetailPanel>summary.ph h3{margin-left:0!important}
/* 5) Admin: biru lembut (tidak gelap, tidak putih) */
#view .adminFeature>summary,#view details.panel.adminFeature>summary.ph{background:linear-gradient(100deg,#D6E7FA,#E6F0FC)!important;color:#0A2E57!important}
#view .adminFeature:nth-of-type(even)>summary,#view details.panel.adminFeature:nth-of-type(even)>summary.ph{background:linear-gradient(100deg,#CFE3F7,#E0ECFA)!important}
#view .adminFeature>summary *,#view .adminFeature>summary h3{color:#0A2E57!important}
#view .adminFeature>summary small{color:#4A6A8C!important}
#view .adminFeature>summary svg{color:#0B5CAD!important;background:#fff!important}
#view .adminFeature>summary:after{color:#0B5CAD!important}
#view .adminFeature{border-color:#AFCBEA!important}
#view .adminFeature[open]>summary{box-shadow:inset 0 -3px #0B5CAD!important}
.v6frBtn{width:100%;border:0;background:transparent;font:inherit;color:inherit;text-align:left;padding:4px 6px;margin:-4px -6px;border-radius:10px;cursor:pointer;transition:background .15s}
.v6frBtn:hover{background:rgba(11,92,173,.08)}.v6frBtn:hover .v6fb{box-shadow:0 0 0 2px #0B5CAD33}
.v6bchip{display:inline-block;padding:2px 7px;margin:1px 0;border-radius:999px;background:#EEF2F7;color:#4A5870;font-size:10.5px;font-weight:700}.v6bchip.on{background:#0B5CAD;color:#fff}

/* ===================== v6.11 HISTORY DEALER ===================== */
/* Kolom TOTAL: header tetap tegas, isi tabel satu warna terang & terbaca */
#view .historyBrandMatrix tbody td.historyBrandTotal,#view .historyBrandMatrix tbody tr:nth-child(n) td.historyBrandTotal{color:#0A2E57!important;font-weight:800!important;box-shadow:none!important}
#view .historyBrandMatrix tbody tr:nth-child(n) td.historyBrandTotal.metricST{background:#DCEBFA!important}
#view .historyBrandMatrix tbody tr:nth-child(n) td.historyBrandTotal.metricSO{background:#F8E1EE!important;color:#7E1F5A!important}
#view .historyBrandMatrix tbody tr:nth-child(n) td.historyBrandTotal.metricOMZET{background:#FFF0D2!important;color:#6B4500!important}
#view .historyBrandMatrix tbody tr.totalRow td.historyBrandTotal.metricST{background:#BFD8F3!important}
#view .historyBrandMatrix tbody tr.totalRow td.historyBrandTotal.metricSO{background:#EFC6DD!important}
#view .historyBrandMatrix tbody tr.totalRow td.historyBrandTotal.metricOMZET{background:#F6DDA6!important}
/* Filter History: ringkas, 1–2 baris */
#view .historyFilterCard{display:flex!important;flex-wrap:wrap;align-items:flex-end;gap:8px 10px!important;padding:10px 12px!important;background:#EAF3FC!important;border:1px solid #C9DBEE!important;border-radius:12px!important}
#view .historyFilterCard>.filterSection,#view .historyFilterCard .filterGrid{display:contents!important}
#view .historyFilterCard .filterSectionTitle{display:none!important}
#view .historyFilterCard .filterGrid>label,#view .historyFilterCard .filterGrid>.filterField{flex:1 1 140px;min-width:130px;max-width:230px;display:flex;flex-direction:column;gap:3px;margin:0!important;padding:0!important;font-size:10.5px!important;font-weight:800!important;color:#0A2E57!important;text-transform:uppercase;letter-spacing:.3px}
#view .historyFilterCard .filterGrid>label.filterWide{flex:2 1 220px;max-width:340px}
#view .historyFilterCard .filterLabel{font-size:10.5px!important;font-weight:800!important;color:#0A2E57!important;margin:0!important}
#view .historyFilterCard .fi,#view .historyFilterCard .historyDisplayMulti>summary,#view .historyFilterCard .historyMultiDesktop>summary{min-height:34px!important;height:34px;padding:4px 10px!important;font-size:12px!important;border-radius:9px!important;text-transform:none;letter-spacing:0;font-weight:500}
#view .historyFilterCard .filterAdvanced{flex:1 1 100%;margin:0!important;padding:0!important;border:0!important;background:transparent!important}
#view .historyFilterCard .filterAdvanced>summary{display:inline-flex!important;align-items:center;gap:6px;padding:5px 10px!important;min-height:0!important;border:1px dashed #9CC0E6!important;border-radius:9px!important;background:#fff!important;font-size:11.5px!important;color:#0B5CAD!important}
#view .historyFilterCard .filterAdvanced>summary small{display:none}
#view .historyFilterCard .filterAdvanced[open]>.filterGrid{display:flex!important;flex-wrap:wrap;gap:8px 10px;margin-top:8px}
#view .historyFilterCard .filterCardFoot{flex:1 1 100%;display:flex!important;align-items:center;gap:8px;margin:0!important;padding:6px 0 0!important;border-top:1px solid #C9DBEE!important;background:transparent!important}
#view .historyFilterCard .filterCardFoot .chip{min-height:32px!important;padding:5px 12px!important}
#view .historyFilterCard .filterSummary{flex:1;min-width:0}
@media(max-width:760px){#view .historyFilterCard .filterGrid>label,#view .historyFilterCard .filterGrid>.filterField{flex:1 1 44%;max-width:none}#view .historyFilterCard .filterGrid>label.filterWide{flex:1 1 100%;max-width:none}#view .historyFilterCard .fi{height:40px;min-height:40px!important}}
/* v6.12 warna header brand di History (tiap brand beda) */
#view .historyBrandMatrix th.historyBrandBand{color:#fff!important;border-left:3px solid #fff!important}
#view .historyBrandMatrix th.historyBrandBand.v6b0{background:#5B3FD6!important}
#view .historyBrandMatrix th.historyBrandBand.v6b1{background:#0E8C7E!important}
#view .historyBrandMatrix th.historyBrandBand.v6b2{background:#C2410C!important}
#view .historyBrandMatrix th.historyBrandBand.v6b3{background:#1E6FD9!important}
#view .historyBrandMatrix th.historyBrandBand.v6b4{background:#2E7D32!important}
#view .historyBrandMatrix th.historyBrandBand.v6b5{background:#C2185B!important}
#view .historyBrandMatrix th.historyBrandBand.v6b6{background:#455A64!important}
#view .historyBrandMatrix th.historyBrandBand.v6b7{background:#00838F!important}

/* ===================== v6.13 FILTER DAFTAR DEALER: 1 baris ===================== */
#view .customerFilterCard{display:flex!important;flex-wrap:wrap;align-items:flex-end;gap:8px 10px!important;padding:10px 12px!important;background:#EAF3FC!important;border:1px solid #C9DBEE!important;border-radius:12px!important;box-shadow:none!important}
#view .customerFilterCard>.filterCardHead{display:none!important}
#view .customerFilterCard>.filterGrid{display:contents!important}
#view .customerFilterCard .filterGrid>label,#view .customerFilterCard .filterGrid>.filterField{flex:1 1 112px;min-width:105px;display:flex;flex-direction:column;gap:3px;margin:0!important;padding:0!important;font-size:10.5px!important;font-weight:800!important;color:#0A2E57!important;text-transform:uppercase;letter-spacing:.3px}
#view .customerFilterCard .filterGrid>label.filterWide{flex:.9 1 120px}
#view .customerFilterCard .filterLabel{font-size:10.5px!important;font-weight:800!important;color:#0A2E57!important;margin:0!important}
#view .customerFilterCard .fi,#view .customerFilterCard .customerStatusMulti>summary{min-height:34px!important;height:34px;padding:4px 10px!important;font-size:12px!important;border-radius:9px!important;text-transform:none;letter-spacing:0;font-weight:500;width:100%}
#view .customerFilterCard>.filterCardFoot{flex:0 0 auto;display:flex!important;align-items:center;gap:8px;margin:0!important;padding:0!important;border:0!important;background:transparent!important}
#view .customerFilterCard .filterSummaryMain{display:none!important}
#view .customerFilterCard .filterResultCount{white-space:nowrap;font-size:12px;color:#0A2E57}
#view .customerFilterCard .filterActions{display:flex;gap:6px;flex-wrap:nowrap}
#view .customerFilterCard .filterActions .chip{min-height:34px!important;padding:5px 10px!important;white-space:nowrap;font-size:11px!important}

@media(max-width:760px){#view .customerFilterCard .filterGrid>label,#view .customerFilterCard .filterGrid>.filterField{flex:1 1 44%}#view .customerFilterCard .filterGrid>label.filterWide{flex:1 1 100%}#view .customerFilterCard>.filterCardFoot{flex:1 1 100%;justify-content:space-between}#view .customerFilterCard .fi{height:40px;min-height:40px!important}}
#view .customerFilterCard .customerStatusMulti>summary{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:flex;align-items:center}
#view .customerFilterCard select.fi{padding:4px 24px 4px 9px!important;font-size:12px!important}
/* v6.14 Brand detail: panel biru + tombol brand */
#view .toolbar.v6brandBar{display:flex!important;flex-wrap:wrap;align-items:center;gap:10px 14px!important;background:linear-gradient(100deg,#0B5CAD,#0A4A8F)!important;border:0!important;border-radius:14px!important;padding:12px 16px!important;box-shadow:0 8px 20px rgba(11,92,173,.2)}
#view .v6brandBar>label{flex-direction:row!important;align-items:center;gap:8px!important;color:#fff!important;font-size:12px!important;font-weight:800!important;text-transform:uppercase;letter-spacing:.4px}
#view .v6brandBar select.fi{background:#fff!important;border-color:#fff!important;color:#0A2E57!important;font-weight:700;min-width:140px;height:34px}
.v6bpicks{display:flex;flex-wrap:wrap;gap:6px}
.v6bpick{border:1px solid rgba(255,255,255,.35);background:rgba(255,255,255,.12);color:#fff;border-radius:999px;padding:6px 12px;font:inherit;font-size:12px;font-weight:800;cursor:pointer;display:inline-flex;align-items:center;gap:6px;transition:background .15s,transform .15s}
.v6bpick small{font-size:10px;font-weight:700;opacity:.8;background:rgba(255,255,255,.18);padding:1px 6px;border-radius:999px}
.v6bpick:hover{background:rgba(255,255,255,.24);transform:translateY(-1px)}
.v6bpick.on{background:#fff;color:#0B5CAD;border-color:#fff;box-shadow:0 4px 12px rgba(3,20,45,.25)}.v6bpick.on small{background:#EAF3FC;color:#0B5CAD;opacity:1}
@media(max-width:760px){.v6bpicks{overflow-x:auto;flex-wrap:nowrap;width:100%;padding-bottom:4px}.v6bpick{flex:0 0 auto}}
/* v6.15 kolom nomor/peringkat ramping + header summary history tidak terpotong */
#view table.v6numcol th:first-child,#view table.v6numcol td:first-child,.modal table.v6numcol th:first-child,.modal table.v6numcol td:first-child{min-width:0!important;max-width:none!important;width:1%!important;white-space:nowrap!important;padding-left:12px!important;padding-right:10px!important}
#view .historySummaryMatrix thead th[rowspan]{white-space:normal!important;line-height:1.3!important;vertical-align:middle!important;overflow:visible!important}
#view .historySummaryMatrix thead th[rowspan]:nth-child(2),#view .historySummaryMatrix tbody td:nth-child(2){min-width:120px!important}
/* v6.16 Summary History Dealer disembunyikan di HP */
@media(max-width:760px){
 #view .historySummaryPanel>*{display:none!important}
 #view .historySummaryPanel{border:1px dashed #9CC0E6!important;background:#EAF3FC!important;box-shadow:none!important}
 #view .historySummaryPanel::before{content:"📊  Summary History Dealer tersedia di tampilan desktop (laptop/PC).";display:block;padding:12px 14px;font-size:12px;font-weight:700;color:#0A2E57;line-height:1.5}
}

/* v6.17 Pager rapi + di HP pindah ke atas tabel */
#view .pager{display:flex!important;align-items:center;justify-content:flex-end;gap:8px 10px;flex-wrap:wrap;background:#EAF3FC;border:1px solid #C9DBEE;border-radius:12px;padding:8px 12px!important;margin:10px 0!important;font-size:12px!important;color:#0A2E57}
#view .pager>span{font-weight:700;margin-right:auto;order:0}
#view .pager label{display:inline-flex!important;align-items:center;gap:6px;font-weight:700;order:-1}
#view .pager select{min-height:32px!important;height:32px;border-radius:9px!important;border:1px solid #BFD6EE!important;padding:2px 26px 2px 10px!important;background:#fff!important;color:#0A2E57!important;font-weight:700}
#view .pager .chip{min-height:32px!important;padding:4px 12px!important;background:#fff!important;border:1px solid #BFD6EE!important;color:#0B5CAD!important;font-weight:800!important}
#view .pager .chip:disabled{opacity:.45!important;cursor:not-allowed}
@media(max-width:760px){
 #view div:has(> .pager){display:flex!important;flex-direction:column}
 #view div:has(> .pager)>.pager{order:-1}
 #view .pager{display:grid!important;grid-template-columns:auto 1fr 1fr;gap:8px;margin:0 0 10px!important}
 #view .pager>span{grid-column:1/-1;margin:0;text-align:center;font-size:12.5px}
 #view .pager label{order:0}
 #view .pager .chip{width:100%;min-height:38px!important}
 #view .pager:not(:has(label)){grid-template-columns:1fr 1fr}
 #view .pager:not(:has(label))>span{order:-1}
}
@media(max-width:760px){#view .pager>span{order:-2!important}#view .pager label{font-size:0!important;gap:0!important}#view .pager label select{font-size:13px!important}}

/* ===================== v6.18 SEMUA TOOLBAR FILTER: gaya seragam ===================== */
#view .toolbar:not(.v6brandBar):has(select,input:not([type=file])){display:flex!important;flex-wrap:wrap;align-items:flex-end;gap:8px 10px!important;background:#EAF3FC!important;border:1px solid #C9DBEE!important;border-radius:12px!important;padding:10px 12px!important;box-shadow:none!important}
#view .toolbar:not(.v6brandBar) label{display:flex!important;flex-direction:column;gap:3px!important;font-size:10.5px!important;font-weight:800!important;color:#0A2E57!important;text-transform:uppercase;letter-spacing:.3px;margin:0!important}
#view .toolbar:not(.v6brandBar) label>.fi,#view .toolbar:not(.v6brandBar) label>select,#view .toolbar:not(.v6brandBar) label>input:not([type=checkbox]):not([type=file]),#view .toolbar:not(.v6brandBar)>.fi{min-height:34px!important;height:34px;padding:4px 26px 4px 10px!important;font-size:12px!important;font-weight:600;text-transform:none;letter-spacing:0;border-radius:9px!important;border:1px solid #BFD6EE!important;background:#fff!important;color:#0A2E57!important;min-width:110px}
#view .toolbar:not(.v6brandBar) label>input[type=text],#view .toolbar:not(.v6brandBar) label>input:not([type]),#view .toolbar:not(.v6brandBar) label>input[type=month],#view .toolbar:not(.v6brandBar) label>input[type=date]{padding-right:10px!important}
#view .toolbar:not(.v6brandBar) select.fi.hl{border-color:#0B5CAD!important;box-shadow:0 0 0 2px rgba(11,92,173,.12)!important}
