#view .analysisFilterMore>summary{color:#0B5CAD!important;font-size:12px!important;font-weight:800!important;cursor:pointer}
#view .analysisFilterMore .toolbar{background:transparent!important;border:0!important;padding:8px 0 0!important}
#view .dosFilters{background:#EAF3FC!important;border:1px solid #C9DBEE!important;border-radius:12px!important;padding:10px 12px!important}
@media(max-width:760px){#view .toolbar:not(.v6brandBar) label{flex:1 1 44%!important}#view .toolbar:not(.v6brandBar) label>.fi,#view .toolbar:not(.v6brandBar) label>select{height:40px;min-height:40px!important;width:100%}}

/* ===== v6.19: hari kerja, tooltip, DOS terapkan, potensi dealer ===== */
.v6tipbox{position:fixed;z-index:9999;display:none;max-width:280px;min-width:190px;background:#10243B;color:#fff;border-radius:10px;padding:9px 11px;font-size:11.5px;line-height:1.45;box-shadow:0 10px 26px rgba(0,0,0,.28);pointer-events:none}
.v6tipbox:after{content:"";position:absolute;left:var(--ax,20px);top:-6px;border:6px solid transparent;border-top:0;border-bottom-color:#10243B}
.v6tipbox.up:after{top:auto;bottom:-6px;border:6px solid transparent;border-bottom:0;border-top-color:#10243B}
.v6tipbox .v6tt-t{font-weight:800;color:#FFD76A;margin-bottom:1px}.v6tipbox .v6tt-sub{opacity:.75;font-size:10.5px;margin-bottom:5px}
.v6tipbox .v6tt-rows div{display:flex;justify-content:space-between;gap:12px}.v6tipbox .v6tt-rows span{opacity:.8}.v6tipbox .v6tt-rows b{font-weight:700;text-align:right}
.v6tipbox .v6tt-v{margin-top:5px;font-weight:700}.v6tipbox .v6tt-gd{color:#6EE7A8}.v6tipbox .v6tt-md{color:#FFD76A}.v6tipbox .v6tt-bd{color:#FF9A9A}.v6tipbox .v6tt-op{color:#C9B2FF}
.v6sheetWrap .v6shade{position:fixed;inset:0;background:rgba(10,20,35,.38);opacity:0;pointer-events:none;transition:opacity .2s;z-index:9998}
.v6sheetWrap .v6sheet{position:fixed;left:0;right:0;bottom:0;z-index:9999;background:#fff;border-radius:18px 18px 0 0;padding:8px 18px calc(18px + env(safe-area-inset-bottom));max-height:78vh;overflow:auto;transform:translateY(105%);transition:transform .25s ease;box-shadow:0 -10px 28px rgba(0,0,0,.18);color:#10243B}
.v6sheetWrap.on .v6shade{opacity:1;pointer-events:auto}.v6sheetWrap.on .v6sheet{transform:none}
.v6grab{width:42px;height:4px;border-radius:3px;background:#D5DCE5;margin:0 auto 12px}
.v6sheet .v6tt-t{font-size:15px;font-weight:800}.v6sheet .v6tt-sub{color:#6B7A8C;font-size:12px;margin:2px 0 10px}
.v6sheet .v6tt-rows div{display:flex;justify-content:space-between;gap:14px;padding:8px 0;border-top:1px solid #E3E9F1;font-size:13px}.v6sheet .v6tt-rows div:first-child{border-top:0}.v6sheet .v6tt-rows span{color:#6B7A8C}
.v6sheet .v6tt-v{margin-top:10px;border-radius:10px;padding:9px 11px;font-size:13px;font-weight:700}
.v6sheet .v6tt-gd{background:#DDF4E8;color:#0E6B40}.v6sheet .v6tt-md{background:#FFF1D2;color:#7A5200}.v6sheet .v6tt-bd{background:#FBE1E1;color:#9B1F1F}.v6sheet .v6tt-op{background:#EEE6FD;color:#4B2AA3}
.v6sheet .v6tt-s{font-size:14px}
.v6tt-mini{display:flex;gap:5px;align-items:flex-end;height:46px;margin:6px 0 2px}.v6tt-mini i{flex:1;background:#9CC0E6;border-radius:3px}.v6tt-mini i.now{background:#0B5CAD}
.v6tt-ml{display:flex;justify-content:space-between;font-size:10.5px;color:#6B7A8C;margin-bottom:6px}.v6tt-ml span{flex:1;text-align:center}
.v6sheetClose{margin-top:14px;width:100%;height:42px;border:0;border-radius:10px;background:#EAF3FC;color:#0B5CAD;font:inherit;font-weight:800}
[data-v6tip]{cursor:help}.v6tap,.v6pc,.v6gap{border-bottom:1.5px dotted #8FB2D8}
.v6day[data-v6tip]{cursor:pointer}
.kpis .kpi{position:relative}.v6ki{position:absolute;top:9px;right:10px;z-index:2;width:17px;height:17px;border-radius:50%;background:#E3EEF9;color:#0B5CAD;font:800 10px/17px system-ui,sans-serif;text-align:center;font-style:normal}
.v6tipnote{margin-top:8px;font-size:12px;background:#EAF3FC;color:#0A2E57;border-radius:8px;padding:7px 10px}
.v6tipSel{outline:2px solid #FFB020;outline-offset:2px;border-radius:6px}
/* hari libur */
.v6day.v6off{background:repeating-linear-gradient(45deg,#EEF1F5 0 6px,#F6F8FA 6px 12px)!important;color:#8A96A7!important;border:1px solid #E3E9F1}
.v6day.v6off.v6hol{background:repeating-linear-gradient(45deg,#FCE8D4 0 6px,#FFF4E8 6px 12px)!important;color:#9A5A12!important}
.v6day.v6off:hover{transform:none;box-shadow:none}.v6day.v6off b{color:inherit}
.v6lgOff{background:repeating-linear-gradient(45deg,#D5DCE5 0 3px,#EEF1F5 3px 6px)!important}
.v6dowOff i{background:repeating-linear-gradient(45deg,#D5DCE5 0 4px,#EEF1F5 4px 8px)!important}.v6dowOff b{color:#8A96A7}
.v6pill.v6off{background:#EEF1F5;color:#6B7A8C}
.v6heat.v6heatOff{background:#EEF1F5!important;color:#8A96A7!important}
.v6dowTable thead th:last-child{background:#8A97A8!important}
/* DOS */
#view select.v6chg,#view input.v6chg{border-color:#F0A500!important;box-shadow:0 0 0 3px #FFE7AE!important}
#dosApply.v6pulse{background:#F08C00!important;border-color:#F08C00!important;color:#fff!important;animation:v6pl 1.4s infinite}
@keyframes v6pl{0%{box-shadow:0 0 0 0 rgba(240,140,0,.55)}70%{box-shadow:0 0 0 10px rgba(240,140,0,0)}100%{box-shadow:0 0 0 0 rgba(240,140,0,0)}}
.v6pend{margin:8px 0 4px;font-size:12px;color:#8A5A00;background:#FFF4DA;border:1px solid #F5D995;border-radius:8px;padding:7px 10px}
