/* potensi dealer */
.v6pc{display:inline-block;line-height:1.2;border-bottom:0}.v6pc b{font-size:13px;border-bottom:1.5px dotted #8FB2D8}.v6pc small{display:block;font-size:10px;color:#6B7A8C;font-weight:600}
.v6pc-gd b{color:#15945A}.v6pc-md b{color:#C98A0B}.v6pc-bd b{color:#D23B3B}.v6pc-op b,.v6pc-op small{color:#6D3FD6}.v6pc-na b{border-bottom:0}
.v6gap{font-weight:800;color:#D23B3B}.v6gap.ok{color:#15945A;border-bottom:0}
