/* v6.20 #11 proyeksi */
.v6pj{display:inline-flex;flex-direction:column;align-items:flex-start;gap:2px;line-height:1.15}
.v6pjp{display:inline-block;font-size:10px;font-weight:800;border-radius:9px;padding:1px 7px;white-space:nowrap}
td b + .v6pjp{display:block;width:max-content;margin-top:2px}
.v6pj-bd{background:#FBE1E1;color:#C62F2F}.v6pj-md{background:#FFF1D2;color:#8A5D00}.v6pj-gd{background:#DDF4E8;color:#15945A}
/* #16 brand bar */
#view .toolbar.v6brandBar>label:has(#detailBrand){display:block!important;position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
#view .toolbar.v6brandBar::before{content:"BRAND DETAIL";color:#fff;font-weight:800;font-size:11px;letter-spacing:.5px;white-space:nowrap;align-self:center}
@media(max-width:760px){.v6brandBar{flex-wrap:nowrap!important;overflow-x:auto}.v6brandBar .v6bpicks{flex-wrap:nowrap!important}.v6brandBar .v6bpick{flex:0 0 auto}}
/* v6.20 #17 loading */
#v6topbar{position:fixed;top:0;left:0;right:0;height:3px;z-index:10000;overflow:hidden;opacity:0;transition:opacity .2s;pointer-events:none}
#v6topbar.on{opacity:1}#v6topbar i{position:absolute;top:0;bottom:0;width:35%;background:linear-gradient(90deg,#5FB0FF,#FFD76A);border-radius:3px;animation:v6run 1.1s infinite ease-in-out}
@keyframes v6run{0%{left:-35%}100%{left:100%}}
.v6loading{display:flex!important;align-items:center;gap:10px;flex-wrap:wrap;font-weight:700;color:#0A2E57}
.v6loading::before,.v6spin{content:"";display:inline-block;width:16px;height:16px;flex:0 0 16px;border-radius:50%;border:3px solid #CFE0F3;border-top-color:#0B5CAD;animation:v6rot .8s linear infinite}
@keyframes v6rot{to{transform:rotate(360deg)}}
.v6skel{margin:6px 0 10px}.v6skel i{display:block;height:14px;border-radius:6px;margin:10px 0;background:linear-gradient(90deg,#EDF1F6 25%,#F7F9FC 50%,#EDF1F6 75%);background-size:200% 100%;animation:v6sh 1.3s infinite linear}
.v6skel i:nth-child(2){width:92%}.v6skel i:nth-child(3){width:84%}.v6skel i:nth-child(4){width:70%}
@keyframes v6sh{0%{background-position:200% 0}100%{background-position:-200% 0}}
.v6slow{flex-basis:100%;font-size:12px;font-weight:600;color:#8A5D00;background:#FFF4DA;border-radius:8px;padding:6px 10px;margin-top:4px}
@media(prefers-reduced-motion:reduce){#v6topbar i,.v6skel i{animation:none}}
/* v6.20 #15 dealer tutup */
.v6bdg{display:inline-block;font-size:10px;font-weight:800;border-radius:10px;padding:2px 8px;margin-left:6px;white-space:nowrap;vertical-align:1px}
.v6b-tutup{background:#E4E8EE;color:#4D5A6B}.v6b-ajuan{background:#FFF1C7;color:#8A5D00}.v6b-info{background:#EAF3FC;color:#0B5CAD}.v6b-err{background:#FBE1E1;color:#C62F2F;margin:0}.v6b-ok{background:#DDF4E8;color:#15945A;margin:0}
.statusBadge.v6st-tutup{background:#E4E8EE!important;color:#4D5A6B!important}
.v6tban{border-radius:10px;padding:10px 12px;font-size:12.5px;margin:0 0 12px;line-height:1.5}
.v6tban.grey{background:#EEF1F5;border:1px solid #D8DEE6;color:#3C4858}.v6tban.yel{background:#FFF7DD;border:1px solid #F2DDA4;color:#6D4F00}.v6tban.plain{padding:0;background:none}
.v6tban .chip{margin-left:6px}.v6tact{display:inline-flex;gap:6px;flex-wrap:wrap}
.v6tf{display:grid;grid-template-columns:200px 1fr;gap:10px;margin-top:10px;background:#F7F9FC;border:1px solid #E3E9F1;border-radius:10px;padding:12px}
.v6tf label{display:flex;flex-direction:column;gap:4px;font-size:10.5px;font-weight:800;color:#0A2E57;text-transform:uppercase}.v6tf .full{grid-column:1/-1}.v6tf textarea{min-height:60px;resize:vertical;font:inherit;padding:8px}
@media(max-width:760px){.v6tf{grid-template-columns:1fr}}
.v6ttabs{display:flex;gap:4px;border-bottom:1px solid #E3E9F1;margin-bottom:12px;flex-wrap:wrap}
.v6ttabs button{border:0;background:none;padding:9px 12px;font:inherit;font-weight:700;font-size:12.5px;color:#6B7A8C;border-bottom:3px solid transparent;cursor:pointer}
.v6ttabs button.on{color:#0B5CAD;border-bottom-color:#0B5CAD}.v6ttabs .n{background:#D23B3B;color:#fff;border-radius:9px;padding:0 6px;font-size:10px;margin-left:5px}
.v6file{cursor:pointer}
#view td.v6hoff{background:repeating-linear-gradient(45deg,#EEF1F5 0 5px,#F6F8FA 5px 10px)!important;color:#8A96A7!important;font-size:10.5px}
.adminFeature .v6tph{display:none!important}
#view .v6ttabs button{border:0!important;border-bottom:3px solid transparent!important;border-radius:0!important;background:none!important;box-shadow:none!important;outline:none}
