.v6tnote{margin:0 0 12px;font-size:12.5px;background:#EEF1F5;border:1px solid #D8DEE6;color:#3C4858;border-radius:10px;padding:9px 12px}
/* v6.20 #18 AI chips */
.v6aiChips{margin-top:14px;text-align:left;max-width:860px;margin-left:auto;margin-right:auto}
.v6aicat{font-size:10.5px;font-weight:800;color:#6B7A8C;letter-spacing:.5px;text-transform:uppercase;margin:12px 0 6px}
.v6aichips{display:flex;flex-wrap:wrap;gap:6px}
.v6aichip{border:1px solid #CFE0F3;background:#F4F8FD;color:#0A2E57;border-radius:16px;padding:6px 12px;font:inherit;font-size:12.5px;cursor:pointer;text-align:left}
.v6aichip:hover{background:#E3EEF9;border-color:#9CC0E6}
.v6aiFollow{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:4px 0 10px}.v6aiFollow>span{font-size:11px;font-weight:700;color:#6B7A8C;margin-right:2px}
.v6jump{display:flex;flex-wrap:wrap;align-items:center;gap:10px;background:#fff;border:1px solid #E3E9F1;border-radius:14px;padding:14px 16px;margin:12px 0}
.v6hlform{display:flex;flex-wrap:wrap;gap:10px;align-items:flex-end;background:#EAF3FC;border:1px solid #CFE0F3;border-radius:12px;padding:10px 12px;margin-bottom:8px}
.v6hlform label{display:flex;flex-direction:column;gap:4px;font-size:10.5px;font-weight:800;color:#0A2E57;text-transform:uppercase}.v6hlform .grow{flex:1;min-width:200px}
/* v6.21 growth type per sales */
.v6gtctrl{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-bottom:12px}
.v6gtctrl label{display:flex;align-items:center;gap:6px;font-size:10.5px;font-weight:800;color:#0A2E57;text-transform:uppercase}.v6gtctrl select{height:32px;min-width:150px}
.v6gtcharts{display:grid;grid-template-columns:1.1fr 1fr;gap:18px;margin:12px 0 14px}@media(max-width:900px){.v6gtcharts{grid-template-columns:1fr}}
.v6gtcl{font-size:11px;font-weight:800;color:#6B7A8C;letter-spacing:.4px;text-transform:uppercase;margin-bottom:8px}
.v6gtpair{display:grid;grid-template-columns:minmax(90px,170px) 1fr 70px;gap:8px;align-items:center;margin:7px 0;font-size:12px}
.v6gtpair .n,.v6gtdiv .n{font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.v6gtpair .v6gtb{display:flex;flex-direction:column;gap:3px}
.v6gtpair .v6gtb i{display:block;height:10px;border-radius:4px;min-width:1px}.v6gtpair .v6gtb i.lm{background:#C9D5E3}.v6gtpair .v6gtb i.mt{background:#0B5CAD}.v6gtpair .d,.v6gtdiv .d{text-align:right;font-weight:800}
.v6gtdiv{display:grid;grid-template-columns:minmax(90px,160px) 1fr 1fr 64px;gap:0 6px;align-items:center;margin:6px 0;font-size:12px}
.v6gtdiv .L{display:flex;justify-content:flex-end;border-right:2px solid #10243B;min-height:14px}.v6gtdiv .R{display:flex}.v6gtdiv i{height:14px;border-radius:3px}.v6gtdiv .L i{background:#E06565}.v6gtdiv .R i{background:#1FA86B}
.v6gttable{overflow:auto;max-height:640px;border:1px solid #E3E9F1;border-radius:10px}
.v6gttable table{border-collapse:separate;border-spacing:0;width:100%}
.v6gttable th{background:#0B5CAD;color:#fff;font-size:11px;padding:7px 9px;white-space:nowrap;text-align:right;position:-webkit-sticky;position:sticky;top:0;z-index:2}
.v6gttable tr:nth-child(2) th{top:31px}
.v6gttable th.l{text-align:left}.v6gttable th.v6gth{background:#6D3FD6;text-align:center;border-left:2px solid #fff}.v6gttable th.v6gth.tot{background:#0A2E57}.v6gttable th.v6gsub{background:#1E6FD9;font-size:10px}
.v6gttable td{padding:7px 9px;border-top:1px solid #E3E9F1;white-space:nowrap;text-align:right;font-variant-numeric:tabular-nums}.v6gttable td.l{text-align:left}.v6gttable td.v6gs{border-left:2px solid #E3E9F1}
.v6gttable tr.v6gtasm td{background:#EAF3FC;font-weight:800;cursor:pointer}.v6gttable tr.v6gttot td{background:#0A2E57;color:#fff;font-weight:800}
.v6gp{display:inline-block;min-width:56px;text-align:center;font-size:10.5px;font-weight:800;border-radius:9px;padding:2px 6px}
.v6gp.up{background:#DDF4E8;color:#15945A}.v6gp.dn{background:#FBE1E1;color:#D23B3B}.v6gp.fl{background:#EEF1F5;color:#6B7A8C}.v6gp.nw{background:#EEE6FD;color:#6D3FD6}.v6gp.gone{background:#FFE7D6;color:#B45309}
.v6gself{color:#D23B3B!important;font-style:italic}.v6mut{color:#A8B3C1}
.v6gtcard{border:1px solid #E3E9F1;border-radius:12px;padding:10px 12px;margin-bottom:8px;background:#fff}
.v6gtcard .h{display:flex;justify-content:space-between;gap:8px;font-weight:800}.v6gtcard .h small{font-weight:400;color:#6B7A8C;text-align:right}
.v6gtcard .r{display:grid;grid-template-columns:1fr auto auto auto;gap:8px;padding:5px 0;border-top:1px solid #E3E9F1;font-size:12px;align-items:center}.v6gtcard .r.b{font-weight:800}
.v6gtctrl .v6seg{display:inline-flex;background:#EAF3FC;border-radius:10px;padding:3px;gap:2px}
.v6gtctrl .v6seg button{border:0!important;background:none!important;padding:6px 12px;border-radius:8px;font:inherit;font-size:12px;font-weight:700;color:#6B7A8C;cursor:pointer;box-shadow:none}
.v6gtctrl .v6seg button.on{background:#fff!important;color:#0B5CAD;box-shadow:0 1px 3px rgba(0,0,0,.1)}
