#v6splash{position:fixed;inset:0;z-index:99999;overflow:hidden;background:linear-gradient(170deg,#061C38,#0A2E57 55%,#0B5CAD);display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;transition:opacity .45s ease}
#v6splash.out{opacity:0;pointer-events:none}
#v6splash .sk{position:absolute;right:18px;top:16px;font-size:12px;color:rgba(255,255,255,.7);z-index:2}
#v6splash .wv{position:absolute;left:0;bottom:0;width:200%;height:46%;transform:translateY(100%)}
#v6splash .wv1{animation:v6sRise 1.4s ease-out forwards,v6sDrift 5s linear infinite}
#v6splash .wv2{animation:v6sRise 1.6s ease-out forwards,v6sDrift 7s linear infinite reverse}
#v6splash .pl{position:relative;z-index:1;background:#fff;border-radius:16px;padding:12px 18px;box-shadow:0 10px 30px rgba(0,0,0,.25);opacity:0;transform:scale(.7);animation:v6sPop .7s cubic-bezier(.2,1.4,.3,1) forwards .6s}
#v6splash .pl img{display:block;height:40px}
#v6splash .tg{position:relative;z-index:1;margin-top:16px;font-size:12px;letter-spacing:3px;font-weight:700;color:#9CC4F0;opacity:0;animation:v6sFade .5s forwards 1.2s}
@keyframes v6sRise{to{transform:translateY(0)}}@keyframes v6sDrift{from{margin-left:0}to{margin-left:-100%}}
@keyframes v6sPop{to{opacity:1;transform:scale(1)}}@keyframes v6sFade{to{opacity:1}}
