select.fi,select.fi option,.v6seg button,#view .tabs>button{text-transform:uppercase}

/* v10: panel KPI RGM */
.rgPanel>summary{cursor:pointer}
.rgT{width:100%;border-collapse:collapse;font-size:13px}
