.rgT th.n,.rgT td.n{text-align:right}
.rgT td{padding:8px;border-bottom:1px solid #EAF0F8;vertical-align:middle}
.rgT tfoot td{background:#F0F6FF;border-top:2px solid #CFE0F5}
.rgT td.rgNa{background:#F1F4F8;color:#9AA6B6}
.rgT tr.rgMe td{background:#F0F6FF}
#view .rgT td.rgHi,.rgT td.rgHi{background:#D7F7D1!important;color:#1E6B2E!important;font-weight:800!important}
.rgT tr.rgOff td{color:#8A96A7}
.rgBadge{display:inline-grid;place-items:center;min-width:28px;height:28px;border-radius:99px;background:#E6EEF8;color:#0B4A8A;font-weight:900;font-size:12px;padding:0 6px}
.rgBadge.r1{background:linear-gradient(135deg,#FFE08A,#F5B301);font-size:16px}.rgBadge.r2{background:linear-gradient(135deg,#F1F4F8,#C9D2DE);font-size:16px}.rgBadge.r3{background:linear-gradient(135deg,#FFD9B3,#E39A52);font-size:16px}.rgBadge.no{background:#F1F4F8;color:#9AA6B6}
.rgH4{margin:16px 0 8px;font-size:13px;color:#33465c}
