.rgCard>summary::-webkit-details-marker{display:none}
.rgCard .rgN{flex:1;min-width:0}.rgCard .rgN b{display:block}.rgCard .rgN small{color:#5B6B80;font-size:11.5px}
.rgCard .rgS{font-size:16px;color:#0B5CAD}
