.rgRb{font-weight:600;font-size:10.5px;color:#7A5A12}
.rgAuto{color:#0B7A3B!important}
.rgTot{margin-top:10px;font-size:13px;text-align:right}
.rgHead{font-size:12px;margin-bottom:8px}
/* v10: Atur KPI RGM */
.v6kBlk td{background:#FFF1C9!important;color:#5A3E00;font-weight:900;font-size:12px;padding:8px 10px!important}
.v6kBlk td span{font-weight:600;color:#7A5A12;margin-left:8px;font-size:11px}
