.v6kTg input.fi{min-width:104px}
.v6kRev{display:block;margin:4px 0 0 auto;border:0;background:none;color:#0B5CAD;font-weight:800;font-size:10.5px;cursor:pointer;padding:0}
.v6kMt{display:inline-flex;align-items:center;gap:8px;margin-right:14px}
