.v6kBar u{display:block;height:100%;background:linear-gradient(90deg,#12A150,#38C172)}.v6kMt.bad .v6kBar u{background:linear-gradient(90deg,#E5484D,#F08A8D)}
.v6kPrev{margin-top:12px;border:1px dashed #9CC4F2;border-radius:14px;padding:10px 12px;background:#F7FAFF}
