.v6kPv{display:flex;gap:8px;flex-wrap:wrap}.v6kPv span{background:#fff;border:1px solid #D5E3F5;border-radius:10px;padding:5px 9px;font-size:12px}.v6kPv b{color:#0B5CAD}
/* ===== v10: region per brand ===== */
/* v10: grafik mingguan lebih rapat, dua grafik dipisah jelas */
.v6gtcharts:not(.v6one){grid-template-columns:minmax(0,500px) minmax(0,500px)!important;justify-content:start;column-gap:0!important}
