@media(max-width:900px){.v6gtcharts:not(.v6one){grid-template-columns:1fr!important}.v6gtcharts:not(.v6one)>div:first-child{padding-right:0}.v6gtcharts:not(.v6one)>div+div{border-left:0;padding-left:0;border-top:1.5px solid #D5E3F5;padding-top:12px;margin-top:6px}}
#view tr.rbCh td{background:#FFFBEA}
.v6xnos{font-style:normal;font-size:10px;font-weight:800;background:#FFF1CC;color:#7A5200;border-radius:99px;padding:2px 8px;margin-left:4px;white-space:nowrap}
.v6xheat .hc.na{opacity:1}.v6xheat .hc.na .hp{color:#A3AFBC}.v6xheat .hc.na .hu{color:#60758B;font-weight:800}

/* ===== v11: Beranda Nasional/RGM/ASM — hierarchy + heatmap ===== */
.v6xheroNat .v6xhr{justify-content:center;min-height:105px}.v6xheroNat h4{font-size:17px}.v6xheroNat .v6xring{width:112px!important;height:112px!important;flex-basis:112px!important}.v6xheroNat .v6xring b{font-size:18px}.v6xheroNat .v6xring small{font-size:9px!important}.v6xheroNat .v6xprow:first-of-type{justify-content:flex-end}.v6xheroNat .v6xprow:first-of-type>span:first-child{display:none}
.v6xsummary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.v6xsum{border:1px solid #D7E4F1;background:#FBFDFF;border-radius:10px;padding:10px;min-height:72px}.v6xsum small{display:block;color:#58708A;font-size:9px;font-weight:850;letter-spacing:.35px;text-transform:uppercase}.v6xsum b{display:block;color:#123B60;font-size:20px;line-height:1.05;margin:5px 0 2px}.v6xsum span{font-size:9.5px;color:#657D94}.v6xsum .up{color:#15945A;font-weight:850}.v6xsum .dn{color:#D23B3B;font-weight:850}
.v6xheat .rn.total{background:#EAF4FD;border:1px solid #C7DDF2;border-radius:6px;padding:6px;color:#154F83!important;font-weight:900}.v6xheat .hsep{grid-column:1/-1!important;height:3px!important;min-height:3px!important;padding:0!important;border-radius:99px!important;background:#8FB7DA!important;margin:1px 0 3px}.v6xheat .hc .hu{font-size:9.5px!important;font-weight:800!important;color:#3F5873!important}
.v6xhmbar{display:flex;gap:5px;margin-left:auto;align-items:center}.v6xhmbar small{font-size:8.5px;color:#788CA1;font-weight:850;margin-right:2px}.v6xhmbar button{white-space:nowrap;border:1.5px solid #CFE0F3;border-radius:16px;padding:4px 10px;font:inherit;font-size:10px;font-weight:800;color:#0B5CAD;background:#fff;cursor:pointer}.v6xhmbar button.on{background:#0B5CAD;color:#fff;border-color:#0B5CAD}.v6xhmbar.purple button{color:#6D3FD6;border-color:#E3D6FB}.v6xhmbar.purple button.on{background:#6D3FD6;color:#fff;border-color:#6D3FD6}
/* v12 hierarchy cards: Big/Sub Region vs Sales */
.v6xhierGrid,.v6xregionGrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:8px}.v6xregionMobile{display:none}
.v6xhierCard{position:relative;border-radius:11px;padding:9px 10px;min-width:0}.v6xhierCard.region{background:#EEF7FF;border:1px solid #C9DDF0}.v6xhierCard.sales{background:#FFF;border:1px solid #DFE8F1}.v6xhierCard.me{border:2px solid #0B5CAD}.v6xhierCard.clickable{cursor:pointer}.v6xhierCard.clickable:hover{box-shadow:0 4px 12px #0B5CAD12;transform:translateY(-1px)}
.v6xhierBadge{display:inline-flex;align-items:center;border-radius:99px;padding:3px 8px;margin-bottom:6px;font-size:7px;font-weight:900;letter-spacing:.35px;text-transform:uppercase}.v6xhierBadge.region{background:#DDF5E8;border:1px solid #A8DEC0;color:#087451}.v6xhierBadge.sales{background:#FFF0D8;border:1px solid #F2CB90;color:#A45B00}.v6xhierBadge i{width:6px;height:6px;border-radius:50%;background:currentColor;margin-right:4px}
.v6xhierHead{display:flex;justify-content:space-between;gap:7px;align-items:flex-start}.v6xhierHead .nm{font-size:11px;font-weight:900;line-height:1.15;color:#113B60;overflow-wrap:anywhere}.v6xhierHead .lead{font-size:7.5px;color:#667C91;margin-top:2px;font-weight:750;text-transform:uppercase;letter-spacing:.15px;overflow-wrap:anywhere}.v6xhierHead .scores{text-align:right;min-width:90px;white-space:nowrap}.v6xhierHead .scores b{display:block;font-size:9px;font-weight:900}.v6xhierHead .scores .proj{color:#D23B3B}.v6xhierHead .scores .actual{color:#35516E;margin-top:2px}
.v6xhierProg{position:relative;margin:6px 0 8px}.v6xhierTrack{height:6px;background:#E2EAF1;border-radius:99px;position:relative;overflow:hidden}.v6xhierTrack .actual{position:absolute;inset:0 auto 0 0;border-radius:99px;background:#E5484D;z-index:2}.v6xhierTrack .forecast{position:absolute;top:0;bottom:0;background:repeating-linear-gradient(135deg,#BCD3EA 0 5px,#E8F1F8 5px 10px);z-index:1}.v6xhierTrack .actual.w{background:#E0A21B}.v6xhierTrack .actual.g{background:#15945A}.v6xhierMark{position:absolute;top:-2px;width:2px;height:10px;background:#D23B3B;border-radius:2px;z-index:4}.v6xhierTG{text-align:right;margin-top:2px;color:#C83A43;font-size:7.5px;font-weight:900;white-space:nowrap}
.v6xhierMetrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:3px;text-align:center}.v6xhierMetrics small{display:block;font-size:6.8px;color:#7F91A3;text-transform:uppercase;white-space:nowrap}.v6xhierMetrics b{font-size:9.5px;color:#123B60;white-space:nowrap}.v6xhierMetrics .growth{font-size:8.3px}.v6xhierMetrics .v6up{color:#15945A}.v6xhierMetrics .v6dn{color:#D23B3B}.v6xhierNote{font-size:7px;color:#8A6A00;margin-top:5px;font-weight:700}
.v6xchartlab{font-size:6.2px;font-weight:850}.v6xchartsub{font-size:5.1px}.v6xcall{fill:#fff;stroke-width:.65}
/* v13: wider desktop, centered hero metrics, clearer hierarchy + fullscreen */
.v6xheroNat .v6xring{width:144px!important;height:144px!important;flex-basis:144px!important}.v6xheroNat .v6xring b{font-size:22px!important}.v6xheroNat .v6xring small{font-size:10px!important}
.v6xhero .v6xtv{max-width:840px;margin-left:auto;margin-right:auto}.v6xhero .v6xkg{max-width:840px;width:100%;margin:12px auto 0;border:1px solid #E8EDF3;border-radius:0 0 12px 12px}
.v6xhero .v6xkg>div:nth-last-child(-n+2){border-bottom:0}
.v6xhierCard.me{border:2px solid #0B5CAD!important;background:#E4F2FF!important;box-shadow:0 0 0 3px #0B5CAD14,0 6px 16px #0B5CAD12}
.v6xfsPanel{position:relative}.v6xfsBtn{margin-left:auto;border:1px solid #C8DAED;background:#fff;color:#0B5CAD;border-radius:8px;padding:5px 9px;font:inherit;font-size:9px;font-weight:900;cursor:pointer;white-space:nowrap}.v6xfsBtn:hover{background:#EFF6FD}.v6xfsPanel:fullscreen{background:#EEF5FC;padding:18px;overflow:auto}.v6xfsPanel:fullscreen .v6xbox{min-height:calc(100vh - 70px)}.v6xfsPanel:fullscreen .v6xsec{position:sticky;top:0;z-index:5;background:#EEF5FC;padding:8px 4px}
@media(max-width:760px){.v6xsummary{grid-template-columns:1fr 1fr}.v6xhierGrid,.v6xregionGrid{grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.v6xhierCard{padding:6px 7px}.v6xhierBadge{font-size:6px;padding:2px 6px;margin-bottom:4px}.v6xhierHead .nm{font-size:9.2px}.v6xhierHead .lead{font-size:6.1px}.v6xhierHead .scores{min-width:68px}.v6xhierHead .scores b{font-size:7.4px}.v6xhierProg{margin:4px 0 5px}.v6xhierTrack{height:5px}.v6xhierTrack .forecast{background:repeating-linear-gradient(135deg,#BCD3EA 0 4px,#E8F1F8 4px 8px)}.v6xhierTG{font-size:6.2px;margin-top:1px}.v6xhierMetrics{grid-template-columns:repeat(4,minmax(0,1fr));gap:2px}.v6xhierMetrics>div{background:#FFF;border:1px solid #DCE6EF;border-radius:6px;padding:3px 2px}.v6xhierMetrics>div:last-child{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;background:transparent;border:0;padding:2px 0 0}.v6xhierMetrics small{font-size:5.4px}.v6xhierMetrics b{font-size:8px}.v6xhierMetrics .growth{font-size:7px}.v6xheroNat .v6xhr{justify-content:flex-start}.v6xheroNat .v6xring{width:100px!important;height:100px!important;flex-basis:100px!important}}


