.v6projFs:fullscreen>.panel>.ph{position:sticky;top:0;z-index:8;background:#fff!important}
.v6projFs:fullscreen>.panel>.pb{flex:1;padding:18px!important;background:#fff}
.v6projFs:fullscreen .v6projChart{min-height:calc(100vh - 145px);display:flex;flex-direction:column;justify-content:center;padding:14px 16px}
.v6projFs:fullscreen .v6projChart svg{max-height:calc(100vh - 205px)}
.v6projFs:fullscreen .v6projAxis{font-size:9.8px}
.v6projFs:fullscreen .v6projAnn{font-size:10.2px}
.v6projFs:fullscreen .v6projSub{font-size:7.8px}
.v6projFs:fullscreen .v6projLegend{font-size:14px;gap:22px}
.v6projFs:fullscreen .v6xfsBtn{font-size:12px;padding:7px 12px}
@media(max-width:760px){
 .v6projAxis{font-size:9px}
 .v6projAnn{font-size:9px}.v6projSub{font-size:7px}
 .v6projLegend{font-size:10.5px;gap:10px}
 .v6projLegend i{width:18px}
}


/* ===== v16: heatmap metric + fullscreen detail ===== */
.v6xheat .ht,.v6xheat .hg{display:none}.v6xheat .hc{overflow:hidden}
.v6xheat .hempty{font-size:18px!important;color:#91A1B0!important;align-items:center!important;justify-content:center!important}
.v6xheat .hg.up{color:#087A48!important}.v6xheat .hg.dn{color:#B42318!important}.v6xheat .hg.flat{color:#6F8498!important}
.v6xmetricbar button{min-width:88px}
.v6xCtrlSep{display:inline-block;width:1px;height:24px;background:#C7D4E0;margin:0 3px;align-self:center;flex:0 0 1px}
.v6xmetricbar button{border-color:#BDD6EE!important;color:#0B5CAD!important;background:#F7FBFF!important}.v6xmetricbar button.on{background:#0B5CAD!important;color:#fff!important;border-color:#0B5CAD!important}
.v6xmodebar button{border-color:#B9DDD7!important;color:#0F766E!important;background:#F6FCFB!important}.v6xmodebar button.on{background:#0F766E!important;color:#fff!important;border-color:#0F766E!important}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat>div:first-child{position:sticky;top:0;left:0;z-index:12;background:#fff;min-height:34px}
.v6xHeaderControls{flex-wrap:wrap;justify-content:flex-end}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat{--hm-label-min:190px!important;--hm-cell-min:132px!important;--hm-head-h:40px;--hm-total-h:112px;gap:6px!important;overflow:auto!important;max-height:calc(100vh - 168px);padding-bottom:6px;align-content:start}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat .hd{font-size:13px!important;min-height:34px;align-items:center;position:sticky;top:0;z-index:9;background:#fff;box-shadow:0 2px 0 rgba(143,183,218,.35)}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat .rn{font-size:14px!important;position:sticky;left:0;z-index:5;background:#fff;padding:10px 8px!important;display:flex;align-items:center;box-shadow:5px 0 9px rgba(28,67,103,.05)}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat .rn.total{background:#EAF4FD!important}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat .hc{min-height:112px!important;padding:10px 8px!important;border-radius:9px!important;justify-content:flex-start!important;overflow:hidden}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat .hc .hp{font-size:16px!important;line-height:1!important;font-weight:900!important}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat .hc .hu{font-size:22px!important;margin-top:5px!important;color:#173F61!important;font-weight:900!important;line-height:1.05!important}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat .ht{display:inline-flex;margin-top:8px;padding:3px 8px;border-radius:99px;background:rgba(255,255,255,.58);font-size:11px;font-weight:850;color:#526B82;white-space:nowrap}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat .hg{display:flex;align-items:center;justify-content:center;width:calc(100% + 16px);max-width:none;margin:auto -8px -10px;padding:8px 10px!important;border-radius:0 0 9px 9px!important;background:#E9EEF2!important;border-top:1px solid #C9D3DC;border-left:0;border-right:0;border-bottom:0;font-size:11.5px;font-weight:500;line-height:1.15;white-space:nowrap}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat .hempty{font-size:24px!important}
#view.v6xPresent:fullscreen .v6xFocus .v6legend{font-size:12px!important;margin-top:10px}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat .rn.total,#view.v6xPresent:fullscreen .v6xFocus .v6xheat .hc.hctotal{position:sticky;top:var(--hm-head-h);z-index:8;box-shadow:none}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat .rn.total{left:0;z-index:10;background:#EAF4FD!important}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat .hc.hctotal{z-index:7}
#view.v6xPresent:fullscreen .v6xFocus .v6xheat .hsep{display:block!important}#view.v6xPresent:fullscreen .v6xFocus .v6xheat .hsep.hseptotal{position:sticky;top:calc(var(--hm-head-h) + var(--hm-total-h) + 6px);z-index:9;height:3px!important;min-height:3px!important;background:#78AADB!important;box-shadow:0 1px 0 rgba(255,255,255,.8)}
@media(max-width:900px){
 .v6xHeaderControls{width:100%;margin-top:7px;gap:5px}
 .v6xHeaderControls .v6xhmbar,.v6xHeaderControls .v6xheatmode{flex-wrap:nowrap}
 .v6xmetricbar button{min-width:84px}
}
@media(max-width:900px) and (orientation:landscape){
 #view.v6xPresent:fullscreen{padding:8px!important}
 #view.v6xPresent:fullscreen .v6xFocus>.v6xsec{padding:8px 4px 10px!important;font-size:14px!important;flex-wrap:wrap}
 #view.v6xPresent:fullscreen .v6xFocus>.v6xbox{padding:10px!important;min-height:calc(100vh - 70px)!important}
 #view.v6xPresent:fullscreen .v6xFocus .v6xheat{--hm-label-min:170px!important;--hm-cell-min:158px!important;--hm-head-h:41px;--hm-total-h:124px;gap:5px!important;max-height:calc(100vh - 150px)!important}
 #view.v6xPresent:fullscreen .v6xFocus .v6xheat .hd{font-size:13px!important;min-height:36px!important;position:sticky;top:0;z-index:9;background:#fff;box-shadow:0 2px 0 rgba(143,183,218,.35)}
 #view.v6xPresent:fullscreen .v6xFocus .v6xheat .rn{font-size:14.5px!important;padding:10px 9px!important}
 #view.v6xPresent:fullscreen .v6xFocus .v6xheat .hc{min-height:124px!important;padding:10px 9px!important;justify-content:flex-start!important;overflow:hidden}
 #view.v6xPresent:fullscreen .v6xFocus .v6xheat .hc .hp{font-size:17.5px!important}
 #view.v6xPresent:fullscreen .v6xFocus .v6xheat .hc .hu{font-size:24px!important;margin-top:5px!important;font-weight:900!important}
 #view.v6xPresent:fullscreen .v6xFocus .v6xheat .ht{font-size:12.5px!important;margin-top:8px}
 #view.v6xPresent:fullscreen .v6xFocus .v6xheat .hg{font-size:12px!important;font-weight:500!important;margin:auto -9px -10px!important;padding:9px 10px!important;width:calc(100% + 18px)!important;max-width:none!important;border-radius:0 0 9px 9px!important;background:#E9EEF2!important;border-top:1px solid #C9D3DC!important;border-left:0!important;border-right:0!important;border-bottom:0!important}
 #view.v6xPresent:fullscreen .v6xFocus .v6xheat .hempty{font-size:27px!important}
 #view.v6xPresent:fullscreen .v6xFocus .v6legend{font-size:11.5px!important}
 #view.v6xPresent:fullscreen .v6xchips button,#view.v6xPresent:fullscreen .v6xhmbar button,#view.v6xPresent:fullscreen .v6xheatmode button{font-size:11.5px!important;padding:7px 11px!important}
}

/* ===== v9: verifikasi 2 langkah + panel keamanan ===== */
#tfa{min-height:100vh;min-height:100dvh;display:none;align-items:center;justify-content:center;padding:24px 18px;background:radial-gradient(circle at 15% 10%,#DCEBFA 0,transparent 45%),radial-gradient(circle at 90% 90%,#E3F6FC 0,transparent 40%),var(--c6-bg,#EEF5FF)}
#tfa:not([hidden]){display:flex}
#tfa .llogo{color:var(--c6-blue-d,#084A87)}
.tfaCard{max-height:calc(100dvh - 32px);overflow:auto}
.tfaCard .lfield{margin-top:12px}
.tfaP{font-size:13px;color:#33465c;line-height:1.5;margin:0 0 12px}
.tfaOtp{text-align:center;letter-spacing:6px;font-size:22px!important;font-weight:800}
.tfaLink{display:block;width:100%;background:none;border:0;color:var(--c6-blue,#0B5CAD);font-weight:700;font-size:12.5px;padding:10px 0 0;cursor:pointer}
.tfaStep{display:flex;gap:10px;align-items:flex-start;margin:8px 0;font-size:12.5px;color:#0F1B2D}
.tfaStep>b{flex:0 0 22px;height:22px;border-radius:50%;background:var(--c6-blue,#0B5CAD);color:#fff;display:grid;place-items:center;font-size:11px}
.tfaQr{width:176px;height:176px;margin:8px auto 4px;padding:6px;background:#fff;border:1px solid #D5E3F5;border-radius:12px}
.tfaQr svg{width:100%;height:100%;display:block}
.tfaCap{text-align:center;font-size:11.5px;color:#5B6B80;margin:4px 0}
.tfaA{display:flex;align-items:center;justify-content:center;text-decoration:none;margin-top:8px}
.tfaKey{background:#F0F6FF;border:1px dashed #9CC4F2;border-radius:10px;padding:10px;text-align:center;font-family:ui-monospace,Consolas,monospace;font-weight:800;letter-spacing:1.5px;font-size:14px;color:var(--c6-blue,#0B5CAD);word-break:normal;user-select:all}
.tfaGhost{width:100%;margin-top:8px;padding:11px;border-radius:10px;border:1.5px solid #CFE0F5;background:#fff;color:var(--c6-blue,#0B5CAD);font-weight:800;font-size:13px;cursor:pointer}
.tfaRow{display:flex;gap:8px}.tfaRow .tfaGhost{margin-top:10px}
.tfaNote{font-size:11.5px;border-radius:10px;padding:10px;margin:10px 0;line-height:1.45;background:#E6F2FF;color:#0B4A8A}
.tfaNote.warn{background:#FFF4D6;color:#6B4A00}
.tfaCodes{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0}
.tfaCodes div{background:#fff;border:1px solid #D5E3F5;border-radius:10px;padding:9px;text-align:center;font-family:ui-monospace,Consolas,monospace;font-weight:800;font-size:13px;user-select:all}
.tfaAck{display:flex;gap:8px;align-items:center;font-size:12.5px;margin:12px 0 4px;cursor:pointer}
.tfaCard .lbtn:disabled{opacity:.45;cursor:not-allowed}
.sxKp{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:6px 0 12px}
.sxKp div{border-radius:14px;padding:12px;background:linear-gradient(135deg,#F0F6FF,#fff);border:1px solid #D5E3F5}
.sxKp b{font-size:22px;display:block;color:#0F1B2D}.sxKp small{color:#5B6B80;font-size:11.5px}
.sxKp .bad b{color:#B3262B}
.sxp{padding:3px 9px;border-radius:99px;font-size:11px;font-weight:800;display:inline-block;white-space:nowrap}
.sxp.ok{background:#DDF6E8;color:#0B7A3B}.sxp.no{background:#FFE6E6;color:#B3262B}.sxp.lock{background:#FFF1BF;color:#7A5200}.sxp.na{background:#EDF1F6;color:#5B6B80}
@media(max-width:640px){.sxKp{grid-template-columns:1fr}}
/* ===== LOGIN DSM (v11) ===== */
#login.dlPage{--dlb:#1677b8;--dlt:#173f60;--dlm:#708897;--dll:#dceaf3;--dlcard:rgba(255,255,255,.90);--dlsh:0 20px 60px rgba(21,88,128,.14);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--dlt);display:grid;min-height:100vh;min-height:100dvh;padding:30px;align-items:normal}
#login.dlPage,#login.dlPage *{box-sizing:border-box}
#login.dlPage .dl-shell h2,#login.dlPage .dl-shell p{font-family:inherit}
#login .dl-card .lerr{display:none;margin:0 0 14px;border-radius:12px;font-size:12.5px}
#login .dl-field input{font-family:inherit;margin:0}
#login .dl-btn:disabled{opacity:.7;cursor:wait;transform:none}
#login .dl-eye{background:none;border:0;padding:6px 0 6px 6px}
#login.dlPage {
  position:relative;
  min-height:100dvh;
  display:grid;
  place-items:center;
  padding:30px;
  overflow:hidden;
  background:
    radial-gradient(circle at 18% 18%, rgba(255,255,255,.98) 0 18%, transparent 44%),
    linear-gradient(135deg,#fff 0%,#f6fbff 48%,#eaf6fd 100%) !important;
}
#login.dlPage::before {
  content:"";
  position:absolute;
  width:440px;height:440px;
  left:-120px;top:-100px;
  border-radius:50%;
  background:radial-gradient(circle,rgba(22,119,184,.16),rgba(22,119,184,0) 68%);
  opacity:.5;
}
#login.dlPage::after {
  content:"";
  position:absolute;
  width:380px;height:380px;
  right:-120px;bottom:-120px;
  border-radius:50%;
  background:radial-gradient(circle,rgba(255,154,26,.14),rgba(255,154,26,0) 68%);
  opacity:.45;
}

.dl-wave {
  position:absolute;
  left:-8vw;right:-8vw;bottom:-170px;
  height:450px;
  pointer-events:none;
  opacity:.8;
}
.dl-wave::before,.dl-wave::after {
  content:"";
  position:absolute;left:0;right:0;
  border-radius:50% 50% 0 0 / 100% 100% 0 0;
}
.dl-wave::before {
  bottom:55px;height:220px;
  background:linear-gradient(90deg,rgba(22,119,184,.08),rgba(22,119,184,.15),rgba(255,154,26,.07));
  transform:rotate(-2deg) scaleX(1.05);
}
.dl-wave::after {
  bottom:0;height:260px;
  background:linear-gradient(90deg,rgba(22,119,184,.08),rgba(63,160,220,.11),rgba(255,154,26,.05));
  transform:rotate(3deg) scaleX(1.08);
}

.dl-shell {
  position:relative;
  z-index:2;
  width:min(1120px,96vw);
  min-height:650px;
  display:grid;
  grid-template-columns:1.08fr .92fr;
  border:1px solid rgba(255,255,255,.86);
  background:rgba(255,255,255,.60);
  backdrop-filter:blur(18px);
  -webkit-backdrop-filter:blur(18px);
  border-radius:30px;
  box-shadow:var(--dlsh);
  overflow:hidden;
}

.dl-brand {
  position:relative;
  padding:56px 52px;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  border-right:1px solid rgba(22,119,184,.08);
}

.dl-brand-wrap { margin-top:8px; max-width:610px; }
.dl-logo {
  width:min(560px,100%);
  display:block;
  mix-blend-mode:multiply;
  opacity:0;
  transform:translateY(12px) scale(.985);
  animation:dlrise 1s .22s cubic-bezier(.2,.8,.2,1) forwards;
}
.dl-headline {
  margin:20px 0 0;
  font-size:clamp(28px,3vw,44px);
  line-height:1.08;
  letter-spacing:-.03em;
  font-weight:850;
  opacity:0;transform:translateY(14px);
  animation:dlrise .85s .55s ease forwards;
}
.dl-headline span { color:var(--dlb); }
.dl-copy {
  margin:14px 0 0;
  max-width:560px;
  font-size:15px;
  line-height:1.7;
  color:var(--dlm);
  opacity:0;transform:translateY(12px);
  animation:dlrise .85s .7s ease forwards;
}
.dl-metrics {
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:12px;
  margin-top:32px;
}
.dl-metric {
  padding:15px 14px;
  border-radius:16px;
  background:rgba(255,255,255,.68);
  border:1px solid rgba(22,119,184,.08);
}
.dl-metric strong { display:block;font-size:14px;color:#204b6a; }
.dl-metric span { display:block;margin-top:4px;font-size:12px;color:#7990a0; }
.dl-brand-foot {
  display:flex;align-items:center;gap:9px;
  margin-top:34px;
  font-size:12px;color:#8297a6;
}
.dl-brand-foot::before {content:"";width:28px;height:1px;background:rgba(22,119,184,.3)}

.dl-login-side {
  display:flex;
  align-items:center;
  justify-content:center;
  padding:48px;
  background:linear-gradient(180deg,rgba(255,255,255,.55),rgba(245,251,255,.72));
}
.dl-card {
  width:min(390px,100%);
  padding:34px 32px 30px;
  border-radius:24px;
  background:var(--dlcard);
  border:1px solid rgba(255,255,255,.98);
  box-shadow:0 18px 50px rgba(34,91,128,.12);
  opacity:0;transform:translateY(22px);
  animation:dlrise .95s .9s cubic-bezier(.2,.8,.2,1) forwards;
}
.dl-card h2 {
  margin:8px 0 6px;
  font-size:28px;
  line-height:1.2;
  letter-spacing:-.02em;
}
.dl-card p {
  margin:0 0 24px;
  font-size:13px;
  line-height:1.6;
  color:#7b91a0;
}
.dl-field { position:relative; margin:14px 0; }
.dl-field input {
  width:100%;
  height:52px;
  border-radius:14px;
  border:1px solid var(--dll);
  background:#fbfdff;
  padding:0 46px 0 46px;
  outline:none;
  font-size:14px;
  color:#24475f;
  transition:.2s ease;
}
.dl-field input:focus {
  border-color:rgba(22,119,184,.55);
  box-shadow:0 0 0 4px rgba(22,119,184,.08);
  background:#fff;
}
.dl-icon {
  position:absolute;left:15px;top:50%;
  width:18px;height:18px;
  transform:translateY(-50%);
  opacity:.58;
}
.dl-eye {
  position:absolute;right:15px;top:50%;
  transform:translateY(-50%);
  font-size:12px;color:#7b91a0;
  cursor:pointer;user-select:none;
  font-weight:700;
}
.dl-btn {
  width:100%;height:52px;border:0;border-radius:14px;
  font-size:14px;font-weight:850;color:#fff;
  background:linear-gradient(135deg,var(--dlb),#2496d0);
  box-shadow:0 10px 24px rgba(22,119,184,.25);
  cursor:pointer;
  transition:.18s ease;
}
.dl-btn:hover { transform:translateY(-1px);box-shadow:0 14px 30px rgba(22,119,184,.30); }
.dl-help-text {
  margin-top:14px;
  text-align:center;
  font-size:12px;
  line-height:1.5;
  color:#7b91a0;
}

.dl-pixels {
  position:absolute;top:38px;right:40px;width:98px;height:98px;pointer-events:none;
}
.dl-px {
  position:absolute;border-radius:2px;background:rgba(22,119,184,.26);
  animation:dlfloat 4s ease-in-out infinite;
}
.dl-px:nth-child(1){left:5px;top:44px;width:10px;height:10px}
.dl-px:nth-child(2){left:34px;top:10px;width:15px;height:15px;animation-delay:.5s}
.dl-px:nth-child(3){right:8px;top:32px;width:8px;height:8px;animation-delay:.9s}
.dl-px:nth-child(4){left:44px;bottom:8px;width:13px;height:13px;animation-delay:1.3s}
.dl-px:nth-child(5){right:20px;bottom:25px;width:7px;height:7px;animation-delay:1.7s}

.dl-splash {
  position:fixed;inset:0;z-index:20;
  display:grid;place-items:center;
  background:#fff;
  animation:dlSplashOut .6s 1.75s forwards;
  pointer-events:none;
}
.dl-splash-box {
  position:relative;
  width:min(560px,78vw);
}
.dl-splash img {
  width:100%;
  mix-blend-mode:multiply;
  opacity:0;transform:scale(.97);
  animation:dlSplashLogo 1s .15s cubic-bezier(.2,.8,.2,1) forwards;
}
.dl-sweep {
  position:absolute;left:-35%;top:0;width:34%;height:100%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.92),transparent);
  transform:skewX(-16deg);
  animation:dlsweep 1.05s .42s ease forwards;
}

@keyframes dlrise { to {opacity:1;transform:none} }
@keyframes dlfloat {0%,100%{transform:translateY(0);opacity:.35}50%{transform:translateY(-7px);opacity:.75}}
@keyframes dlSplashLogo {to{opacity:1;transform:scale(1)}}
@keyframes dlsweep {to{left:110%}}
@keyframes dlSplashOut {to{opacity:0;visibility:hidden}}

/* Tablet */
@media (max-width: 900px) {
  #login.dlPage { padding:18px; place-items:stretch center; }
  .dl-shell {
    width:min(680px,96vw);
    min-height:auto;
    grid-template-columns:1fr;
    border-radius:24px;
  }
  .dl-brand {
    padding:34px 30px 24px;
    border-right:0;
    border-bottom:1px solid rgba(22,119,184,.08);
  }
  .dl-brand-wrap { margin-top:8px; }
  .dl-logo { width:min(460px,100%); }
  .dl-headline { font-size:31px; }
  .dl-copy { font-size:14px; }
  .dl-metrics { margin-top:24px; }
  .dl-brand-foot { display:none; }
  .dl-login-side { padding:28px; }
  .dl-card { width:min(430px,100%); }
  .dl-pixels { right:18px;top:18px;transform:scale(.85); }
}

/* Mobile */
@media (max-width: 560px) {
  
  #login.dlPage {
    padding:0;
    display:block!important;
    min-height:100dvh;
  }
  .dl-shell {
    width:100%;
    min-height:100dvh;
    border-radius:0;
    box-shadow:none;
    background:rgba(255,255,255,.72);
    border:0;
  }
  .dl-brand {
    padding:max(18px,env(safe-area-inset-top)) 20px 18px;
    text-align:center;
    align-items:center;
    border-bottom:1px solid rgba(22,119,184,.08);
  }
  .dl-brand-wrap {
    margin-top:0;
    width:100%;
  }
  .dl-logo {
    width:min(330px,88vw);
    max-height:135px;
    object-fit:contain;
    margin:0 auto;
  }
  .dl-headline {
    margin-top:6px;
    font-size:24px;
    line-height:1.08;
  }
  .dl-copy {
    margin:8px auto 0;
    max-width:330px;
    font-size:12.5px;
    line-height:1.55;
  }
  .dl-metrics { display:none; }
  .dl-login-side {
    padding:16px 16px calc(22px + env(safe-area-inset-bottom));
    align-items:flex-start;
  }
  .dl-card {
    max-width:420px;
    padding:24px 20px 20px;
    border-radius:22px;
  }
    .dl-card h2 { font-size:24px; }
  .dl-card p { margin-bottom:18px; font-size:12px; }
  .dl-field input { height:52px; }
  .dl-help-text { font-size:11px; margin-top:12px; }
        .dl-pixels {
    right:8px;top:8px;transform:scale(.7);opacity:.55;
  }
  .dl-wave { bottom:-215px;opacity:.6; }
  .dl-splash-box { width:min(340px,82vw); }
}

/* Short mobile screens */
@media (max-width:560px) and (max-height:740px) {
  .dl-brand { padding-bottom:12px; }
  .dl-brand-wrap { margin-top:8px; }
  .dl-logo { width:min(285px,80vw);max-height:110px; }
  .dl-headline { font-size:21px;margin-top:0; }
  .dl-copy { font-size:11.5px;margin-top:5px; }
  .dl-login-side { padding-top:10px; }
  .dl-card { padding-top:20px; }
}

/* --- Mobile compact spacing override --- */
@media (max-width: 560px) {
  .dl-shell {
    display:flex;
    flex-direction:column;
  }

  .dl-brand {
    justify-content:flex-start !important;
    min-height:auto !important;
    flex:0 0 auto;
    padding-top:max(14px, env(safe-area-inset-top)) !important;
    padding-bottom:8px !important;
  }

  .dl-brand-wrap {
    margin-top:0 !important;
    margin-bottom:0 !important;
  }

  .dl-logo {
    width:min(315px, 84vw) !important;
    max-height:118px !important;
  }

  .dl-headline {
    margin-top:0 !important;
    font-size:22px !important;
    line-height:1.08 !important;
  }

  .dl-copy {
    margin-top:6px !important;
    font-size:12px !important;
    line-height:1.48 !important;
  }

  .dl-login-side {
    flex:1 0 auto;
    align-items:flex-start !important;
    padding-top:10px !important;
  }

  .dl-card {
    margin-top:0 !important;
  }
}

@media (max-width:560px) and (max-height:740px) {
