  #app .topbar .who .rolechip{grid-column:1!important;grid-row:2!important;width:auto!important;max-width:100%!important;padding:0!important;background:transparent!important;border:0!important;color:#166e9d!important;font-size:11px!important;font-weight:700!important;letter-spacing:.2px!important;line-height:1.2!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important}
  #app .topbar .who .avatar{grid-column:2!important;grid-row:1/3!important;display:flex!important;width:39px!important;height:39px!important;border-radius:50%!important;background:#e4f2f8!important;color:#137caf!important;font-size:13px!important;font-weight:800!important}
  #app .topbar .who .out,#app .topbar .who #demoEntry,#app .topbar #menuToggle{display:none!important}
  #app .updbar{display:flex!important;flex-wrap:nowrap!important;align-items:center!important;gap:8px!important;min-height:54px!important;padding:5px 12px 5px 15px!important;background:#fff!important;color:#244861!important;border-radius:0!important;border-bottom:1px solid #bfd2df!important;box-shadow:0 7px 17px rgba(20,73,108,.20)!important}
  #app .updbar .mobileDataStatus{display:flex;align-items:center;gap:8px;flex:1 1 auto;min-width:0;min-height:44px;padding:5px 0;border:0;background:transparent;color:#244861;text-align:left;font:inherit;font-size:12px;cursor:pointer}
  #app .updbar .mobileDataStatus .dot{width:8px;height:8px;background:#23bb8a!important;box-shadow:0 0 0 3px #23bb8a22!important}
  #app .updbar .mobileDataStatus b{color:#153d57!important;font-size:13px!important;font-weight:700!important;white-space:nowrap}
  #app .updbar .mobileDataStatus .mobileChevron{margin-left:2px;color:#54748a;font-size:16px;line-height:1;transition:transform .15s}
  #app .updbar .mobileDataStatus[aria-expanded="true"] .mobileChevron{transform:rotate(180deg)}
  #app .updbar .processDetail{display:none!important}
