  #app .updbar.processOpen .processDetail b{color:#244861!important}
  #app .updbar .sep{display:none!important}
  #app .updbar .chip.refresh{flex:0 0 42px!important;width:42px!important;height:42px!important;min-height:42px!important;margin:0!important;padding:0!important;display:grid!important;place-items:center!important;background:#e8f4fa!important;color:#2076a1!important;border:0!important;border-radius:10px!important;font-size:20px!important;font-weight:500!important;line-height:1!important}
  #app .updbar .chip.refresh .refreshLabel{display:none!important}
