@media(max-width:350px){#app .topbar{padding-inline:10px!important}#app .topbar .navBrand{width:112px!important;height:43px!important}#app .topbar .who #namaTop{font-size:14px!important}#app .topbar .who{grid-template-columns:minmax(0,1fr) 35px!important}#app .topbar .who .avatar{width:35px!important;height:35px!important}}
