/* Detail customer desktop: histori bulanan menggantikan ringkasan brand periode. */
.cmhPanel{margin:22px 0 18px;border:1px solid #d9e6ee;border-radius:14px;overflow:hidden;box-shadow:0 5px 16px #1c49600c}.cmhHeader{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:16px 18px;background:#f7fafc;border-bottom:1px solid #e2eaf0}.cmhHeader h4{margin:0 0 4px;font-size:15px}.cmhHeader p{margin:0;color:#6e8195;font-size:12px}.cmhActions{display:flex;align-items:center;gap:8px}.cmhSwitch{display:flex;gap:3px;padding:3px;border:1px solid #dce5ed;background:#eef3f7;border-radius:9px}.cmhSwitch button{border:0;background:transparent;color:#50647a;border-radius:7px;padding:8px 11px;font-size:11px;font-weight:800;cursor:pointer}.cmhSwitch button.active{background:#fff;color:#176fbd;box-shadow:0 1px 5px #21415b1b}.cmhTable .table-scroll{max-height:440px}.cmhTable table{min-width:680px}.cmhTable th,.cmhTable td{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.cmhTable th:first-child,.cmhTable td:first-child{text-align:left}.cmhTable td:first-child small{display:block;color:#74899c;font-size:10px;font-weight:500}.cmhTable tr.cmhCurrent td{background:#eef7ff}.cmhTable .cmhTotal{font-weight:800!important;color:#165b92!important;background:#f1f8fc!important}.cmhTable .hint{padding:10px 18px;margin:0;border-top:1px solid #e5ecf2;background:#fbfdff;font-size:11px}

/* Jarak vertikal kartu region yang disepakati: desktop 19px, mobile 16px. */
.v6xhierGrid,.v6xregionGrid{row-gap:19px}
@media(max-width:760px){.v6xhierGrid,.v6xregionGrid{row-gap:16px}}

/*V7UX-CSS-START*/
/* =====================================================================
   v7 UX — FASE 1 (revisi UX 2026-10)
   Lapisan override global: judul kapital, header tabel, kartu netral,
   section, sidebar terang + tree, header konteks, filter, tabel lebar.
   Chart Proyeksi SELL THRU sengaja TIDAK disentuh.
   ===================================================================== */
:root{--v7-blue:#0B5CAD;--v7-blue2:#1F7FC2;--v7-blue3:#3B9BE0;--v7-ink:#16202E;--v7-ink2:#3D4A5C;--v7-muted:#7C8899;--v7-line:#EAEEF3;--v7-line2:#D6DCE4;--v7-bg:#F2F5F9;
 --v7-g:#0E6E48;--v7-gs:#E2F5EA;--v7-r:#A3201B;--v7-rs:#FBE3E1;--v7-y:#8A5A00;--v7-ys:#FFF4D6;--v7-n:#5B6778;--v7-ns:#EEF1F5;
 --v7-th:linear-gradient(180deg,#F2F7FD,#DCEAF8);--v7-thc:#0B4C8F;--v7-div:#B9CDE3;--v7-shadow:0 3px 12px rgba(16,40,80,.06)}

/* ---------- 1. Font seragam (M10) ---------- */
html body :is(#app,.modal) :is(#main,#view,#mbody) :is(.tag,.ksub,.ph .hint,th.n,td.n,td.k,.chip .c,.bar .cp,.bar .bv,input.fi,select.fi,.sval,.trend,.ratio,.dlt,.cmp,.lhint code){font-family:inherit!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) :is(td,th,.kval,.n){font-variant-numeric:tabular-nums}

/* ---------- 2. Judul selalu KAPITAL ---------- */
html body :is(#app,.modal) :is(#main,#view,#mbody) :is(.ptitle,.panel .ph h3,summary.ph h3,.v6xsec,h3,h4,.foldPanel>summary,.kpiTreeContent h4){text-transform:uppercase!important;letter-spacing:.02em}
html body :is(#app,.modal) :is(#main,#view,#mbody) .foldPanel>summary small,html body :is(#app,.modal) :is(#main,#view,#mbody) .ph .hint,html body :is(#app,.modal) :is(#main,#view,#mbody) .v6xsec .v6xHeaderControls{text-transform:none!important;letter-spacing:0}
html body :is(#app,.modal) :is(#main,#view,#mbody) .ptitle{font-weight:800!important;letter-spacing:.01em}

/* ---------- 3. Header tabel: gradient biru lembut + garis bawah biru tebal ---------- */
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead th,html body .modal table thead th{background:var(--v7-th)!important;color:var(--v7-thc)!important;font-weight:800!important;text-transform:uppercase;letter-spacing:.03em;border-color:#D4E3F3!important;box-shadow:none!important;text-shadow:none!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead tr:last-child th,html body :is(#app,.modal) :is(#main,#view,#mbody) table thead th[rowspan],html body .modal table thead tr:last-child th{border-bottom:3px solid var(--v7-blue)!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead th *,html body .modal table thead th *{color:inherit}
/* header grup (kategori / brand) → label pastel, tetap beda warna */
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead :is(.metricHead,.historyBrandBand,.historyMetricBand){background:#fff!important;border-bottom:0!important;padding-bottom:3px!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead :is(.metricHead,.historyBrandBand,.historyMetricBand)>*{color:inherit}
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .metric0,html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .metricST{color:#0B5CAD!important;box-shadow:inset 0 -26px 0 -2px #E6F0FB!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .metric1{color:#0E6E48!important;box-shadow:inset 0 -26px 0 -2px #E2F5EA!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .metric2{color:#6D3FD8!important;box-shadow:inset 0 -26px 0 -2px #F0EBFD!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .metric3,html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .metricOMZET{color:#B35F00!important;box-shadow:inset 0 -26px 0 -2px #FFF0DD!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .metric4,html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .metricSO{color:#B4204F!important;box-shadow:inset 0 -26px 0 -2px #FDE8EE!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .historyBrandBand{color:var(--v7-ink)!important;box-shadow:inset 0 -26px 0 -2px #EEF3F9!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .v6b0{color:#5B3FD6!important}html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .v6b1{color:#0E8C7E!important}html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .v6b2{color:#C2410C!important}html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .v6b3{color:#1E6FD9!important}html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .v6b4{color:#2E7D32!important}html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .v6b5{color:#C2185B!important}html body :is(#app,.modal) :is(#main,#view,#mbody) table thead .v6b6{color:#455A64!important}
/* ikon sort: cuma muncul saat hover / kolom aktif */
html body :is(#app,.modal) :is(#main,#view,#mbody) .sortableHeader::after,html body .modal .sortableHeader::after{content:" ↕"!important;opacity:0!important;color:var(--v7-blue)!important;transition:opacity .15s}
html body :is(#app,.modal) :is(#main,#view,#mbody) .sortableHeader:hover::after,html body .modal .sortableHeader:hover::after{opacity:.55!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) .sortableHeader[aria-sort="ascending"]::after,html body .modal .sortableHeader[aria-sort="ascending"]::after{content:" ▲"!important;opacity:1!important;color:var(--v7-blue)!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) .sortableHeader[aria-sort="descending"]::after,html body .modal .sortableHeader[aria-sort="descending"]::after{content:" ▼"!important;opacity:1!important;color:var(--v7-blue)!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) .sortableHeader:hover{filter:none!important;background:linear-gradient(180deg,#E9F2FC,#D2E4F7)!important}
/* angka rata kanan */
html body :is(#app,.modal) :is(#main,#view,#mbody) :is(th.n,td.n){text-align:right!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) :is(th,td).v7txt{text-align:left!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) th.v7num,html body :is(#app,.modal) :is(#main,#view,#mbody) td.v7numc{text-align:right!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) td.v7txt>*{text-align:left!important;justify-content:flex-start!important;margin-left:0!important}
/* garis pemisah antar grup kategori / brand (poin 20) */
html body :is(#app,.modal) :is(#main,#view,#mbody) table :is(th,td):is(.groupStart,.brandDivider,.metricDivider){border-left:2px solid var(--v7-div)!important}
