/* ===== v7.1 Filter Pertumbuhan/Perbandingan: 1 panel, 3 kelompok warna ===== */
.v6gtgrp{display:grid!important;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:12px!important;align-items:start!important}
.v6gtg{border:1px solid #E3EBF5;border-radius:14px;background:#fff;position:relative}
.v6gtg:has(.ss-list:not([hidden])){z-index:6}
.v6gtgh{padding:8px 13px;font:800 11px Inter,system-ui,sans-serif;letter-spacing:.07em;text-transform:uppercase;border-radius:13px 13px 0 0}
.v6gtg.g1 .v6gtgh{background:#EAF2FE;color:#1E5FB8}.v6gtg.g2 .v6gtgh{background:#E6F7F1;color:#0E7C6B}.v6gtg.g3 .v6gtgh{background:#EFE9FD;color:#6D3FD8}
.v6gtgb{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:12px 13px 13px}
.v6gtgb>:is(.v6seg,.v6chk),.v6gtgb>label:has(select[data-k=cmp],select[data-k=metric],select[data-k=sort]),.v6gtgb>label:last-child:nth-child(odd){grid-column:1/-1}
