 html body #app .who>*:not(.v7acct):not(.v7menu){display:none!important}
 .v7acct{display:flex;align-items:center;gap:9px;width:100%;background:none;border:0;border-radius:11px;padding:6px;cursor:pointer;text-align:left;font:inherit;color:var(--v7-ink)}
 .v7acct:hover,.v7acct[aria-expanded="true"]{background:#F2F6FB}
