 html body #app #view .v6xhierCard.v7open .v6xhierTG{display:block!important}
 html body #app #view .v6xhierCard.v7open .v7mg{display:none}
 html body #app #view .v6xhierCard.v7open .v6xhierMetrics{display:grid!important;grid-template-columns:repeat(4,1fr)!important;gap:4px!important;text-align:center}
 html body #app #view .v6xhierCard.v7open .v6xhierMetrics>div{background:#ffffffcc;border-radius:8px;padding:4px 2px}
 html body #app #view .v6xhierCard.v7open .v6xhierMetrics>div:last-child{display:none}
 html body #app #view .v6xhierCard.v7open .v7ext{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin-top:5px;text-align:center}
 .v7ext>div{background:#ffffffcc;border-radius:8px;padding:4px 2px}
 .v7ext span{display:block;font:700 7.5px Inter,sans-serif;letter-spacing:.04em;color:var(--v7-muted)}
 .v7ext b{font-size:12px}
}

/* FASE 2 · DEALER: histori per brand */
.v7gone{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:10px 0 0;background:#FFF8E6;border:1px solid #F6DFA3;border-radius:10px;padding:8px 12px;font:500 12px Inter,system-ui,sans-serif;color:#5A4500}
.v7gone b{font-weight:800}
.v7peluang{margin-left:auto;background:var(--v7-gs);color:var(--v7-g);border-radius:999px;padding:2px 9px;font:800 10.5px Inter,sans-serif}
html body .modal #mbody .cmhTable tr.totalRow td{background:#EAF2FB!important;font-weight:800;border-top:2px solid var(--v7-blue)!important}
html body .modal #mbody .cmhTable tr.totalRow td small{display:block;font-weight:500;color:var(--v7-muted);font-size:10.5px}

/* FASE 2 · DOS HP: kelompok per dealer (M5) */
.v7dosList{display:grid;gap:8px;margin:10px 0}
.v7dosDealer{background:#fff;border:1px solid var(--v7-line);border-radius:12px;box-shadow:var(--v7-shadow);overflow:hidden}
.v7dosDealer>summary{list-style:none;display:flex;align-items:flex-start;gap:8px;padding:10px 12px;cursor:pointer;position:relative;padding-right:30px}
.v7dosDealer>summary::-webkit-details-marker{display:none}
.v7dosDealer>summary::after{content:"";position:absolute;right:13px;top:16px;width:7px;height:7px;border-right:2px solid var(--v7-muted);border-bottom:2px solid var(--v7-muted);transform:rotate(45deg);transition:transform .15s}
.v7dosDealer[open]>summary::after{transform:rotate(225deg);top:19px}
.v7dn{flex:1;min-width:0}
.v7dn>b{display:block;font:800 12.5px Inter,sans-serif;color:var(--v7-ink);text-transform:uppercase}
.v7dn>small{display:block;font-size:10px;color:var(--v7-muted);margin-top:1px}
.v7ds{display:flex;flex-wrap:wrap;gap:4px 12px;margin-top:5px;font:600 9.5px Inter,sans-serif;color:var(--v7-muted);font-variant-numeric:tabular-nums}
.v7ds b{color:var(--v7-ink);font-size:11.5px;margin-left:2px}
.v7ds b.neg,.v7db td.neg{color:var(--v7-r)!important;font-weight:800}
.v7dosDealer>summary .statusBadge{flex:none;font-size:9px!important;margin-top:1px}
.v7db{padding:0 12px 10px;border-top:1px solid var(--v7-line)}
.v7db table{width:100%;border-collapse:collapse;font-size:11px;margin-top:6px}
.v7db th{background:var(--v7-th);color:var(--v7-thc);font:800 9px Inter,sans-serif;letter-spacing:.04em;padding:6px;text-align:left;border-bottom:2px solid var(--v7-blue)}
.v7db th.n,.v7db td.n{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
.v7db td{padding:6px;border-bottom:1px solid #EEF1F5;vertical-align:top}
.v7db td .statusBadge{font-size:8.5px!important;margin-top:2px;display:inline-block}
.v7dopen{margin-top:8px;font-size:11.5px}

/* FASE 2 · TIM: Early Warning (poin 12) */
.v7rit{display:inline-block;margin-left:4px;padding:1px 7px;border-radius:999px;font:800 10px Inter,sans-serif;white-space:nowrap;vertical-align:1px}
.v7rit.dn{background:var(--v7-rs);color:var(--v7-r)}.v7rit.md{background:var(--v7-ys);color:var(--v7-y)}.v7rit.up{background:var(--v7-gs);color:var(--v7-g)}
html body #app #view .v6who{justify-content:flex-start!important;text-align:left!important}
html body #app #view .v6who>div{text-align:left!important}
html body #app #view td.v7txt{white-space:normal}
html body #app #view table td:has(>.v6who)+td{white-space:nowrap;text-align:left!important}
/* catatan kolom seragam (poin 13) */
.v7uni{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0 0 8px;font:600 11.5px Inter,system-ui,sans-serif;color:var(--v7-muted)}
.v7uni b{background:var(--v7-ys);color:var(--v7-y);border-radius:999px;padding:2px 9px;font-weight:800;font-size:10.5px;text-transform:uppercase}
html body :is(#app,.modal) :is(#main,#view,#mbody) table .v7hidecol{display:none!important}

.v7st{display:inline-block;background:var(--v7-ns);color:var(--v7-n);border-radius:999px;padding:2px 8px;font:800 10px Inter,sans-serif;text-transform:uppercase;white-space:nowrap}

/* FASE 2 · bug: header tabel sticky nembus menu Lainnya (thead z-index 50 > menu 45) */
html body #app #main table thead{z-index:20!important}
html body #app #mobileMore{z-index:48!important}

/* FASE 2 · LOGIN (poin 19) */
#lerr.v7lerr{background:#FFF8E6!important;border:1px solid #F6DFA3!important;color:#5A4500!important;text-align:left;font-size:12.5px;line-height:1.5}
#lerr.v7lerr ol{margin:6px 0 4px;padding-left:18px}
#lerr.v7lerr small{display:block;color:#7C6A2E;font-size:11px}

/* FASE 2 · PERINGKAT HP (M4) */
@media(max-width:760px){
 html body #app #view article.mobileCard.v7rank{padding:8px 12px!important;margin:6px 0!important;border-radius:12px!important;display:grid;grid-template-columns:1fr;gap:2px}
 html body #app #view article.mobileCard.v7rank>small{font-size:10px!important;color:var(--v7-muted)!important;margin:0!important}
 html body #app #view article.mobileCard.v7rank .mobilePair{margin:4px 0 0!important;gap:4px!important;display:grid!important;grid-template-columns:repeat(3,1fr)!important}
 html body #app #view article.mobileCard.v7rank .mobilePair>div{padding:3px 6px!important;font-size:8.5px!important;border-radius:6px!important;line-height:1.2}
 html body #app #view article.mobileCard.v7rank .mobilePair b{font-size:12.5px!important;margin-top:0!important}
 .v7nopol{margin:10px 0;background:#F5F7FA;border-radius:12px;padding:0 10px}
 .v7nopol>summary{padding:11px 2px;font:800 11.5px Inter,sans-serif;letter-spacing:.03em;color:var(--v7-ink2);cursor:pointer}
}
/* FASE 2 · BRAND HP (M6) */
.v7search{margin:8px 0}
.v7search input{width:100%;border:1px solid var(--v7-line2);border-radius:10px;padding:9px 12px;font:500 13px Inter,sans-serif;background:#fff}
.v7search input:focus{outline:2px solid var(--v7-blue);outline-offset:0;border-color:transparent}
