.v7cnt{display:none}
@media(max-width:760px){
 html body #app #view .v6gtcard{cursor:pointer;position:relative}
 html body #app #view .v6gtcard .h{padding-right:22px}
 html body #app #view .v6gtcard::after{content:"";position:absolute;right:12px;top:16px;width:7px;height:7px;border-right:2px solid var(--v7-muted);border-bottom:2px solid var(--v7-muted);transform:rotate(225deg)}
 html body #app #view .v6gtcard.v7fold::after{transform:rotate(45deg)}
 html body #app #view .v6gtcard.v7fold .r:not(.b){display:none!important}
 .v7cnt{display:inline;margin-left:6px;font:700 10px Inter,sans-serif;color:var(--v7-muted)}
}
/* FASE 2 · TRANSAKSI HP (M8) */
@media(max-width:760px){
 .v7trxDay{position:sticky;top:56px;z-index:4;display:flex;justify-content:space-between;align-items:center;background:#E6F0FB;color:var(--v7-blue);border-radius:9px;padding:7px 10px;margin:12px 0 4px;font:800 11px Inter,sans-serif;text-transform:uppercase}
 .v7trxDay em{font-style:normal;font-weight:600;text-transform:none;color:#3D6FA3}
 html body #app #view button.mobileTransaction.v7trx{display:grid!important;grid-template-columns:1fr auto;align-items:center;gap:0 8px;padding:8px 12px!important;margin:0!important;border-radius:0!important;border:0!important;border-bottom:1px solid var(--v7-line)!important;background:#fff!important;box-shadow:none!important;min-height:0!important;text-align:left}
 html body #app #view button.mobileTransaction.v7trx b{font-size:12px!important;grid-column:1;grid-row:1}
 html body #app #view button.mobileTransaction.v7trx small{grid-column:1;grid-row:2;font-size:10px!important;margin:0!important}
 html body #app #view button.mobileTransaction.v7trx span{grid-column:2;grid-row:1/3;color:var(--v7-muted)}
}
/* FASE 2 · ANALISA HP: top peluang ringkas (M12) */
@media(max-width:760px){
 html body #app #view .v6opp{padding:8px 0!important;gap:8px!important;align-items:center!important}
 html body #app #view .v6opp .hint{font-size:10.5px!important;line-height:1.35!important;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
 html body #app #view .v6opp .v6oppR{display:flex!important;flex-direction:column;align-items:flex-end;gap:4px}
 html body #app #view .v6opp .v6wa{font-size:0!important;width:32px;height:32px;border-radius:50%!important;padding:0!important;display:grid!important;place-items:center}
 html body #app #view .v6opp .v6wa::before{content:"✆";font-size:15px}
}
@media(max-width:760px){
 html body #app #view article.mobileCard.v7rank>div:not(.mobilePair){margin:0!important;min-height:0!important;padding:0!important;gap:6px!important;font-size:12px!important}
 html body #app #view article.mobileCard.v7rank .textlink{font-size:12px!important}
 html body #app #view .v6opp .v6oppR b{white-space:nowrap!important;font-size:12px!important}
}

/* REVISI #13 · Brand: Tren SELL THRU dan Proyeksi 1:1 (wadah saja, isi chart tidak diubah) */
@media(min-width:900px){
 html body #app #view .row:has(> .v6projFs){display:grid!important;grid-template-columns:minmax(0,1fr) minmax(0,1fr)!important;gap:14px!important;align-items:stretch}
 html body #app #view .row:has(> .v6projFs)>*{min-width:0!important;width:auto!important;max-width:none!important;flex:none!important;margin:0!important}
}
html body #app #view .ph:has(.v6xfsBtn) .desktopChartExpand{display:none!important} /* satu tombol layar penuh saja */

/* REVISI #2 · donut hero diperbesar & di tengah, tanpa tulisan "capai" */
html body #app #view .v6xhero .v6xhr{display:flex!important;flex-direction:column!important;align-items:center!important;text-align:center!important;gap:8px!important}
html body #app #view .v6xhero .v6xhr>div:last-child{flex:none!important;display:flex;flex-direction:column;align-items:center}
html body #app #view .v6xhero .v6xring{width:140px!important;height:140px!important;position:relative}
html body #app #view .v6xhero .v6xring svg{width:140px!important;height:140px!important}
html body #app #view .v6xhero .v6xring>div{position:absolute;inset:0;display:grid!important;place-items:center;align-content:center}
html body #app #view .v6xhero .v6xring>div b{font-size:30px!important;line-height:1}
html body #app #view .v6xhero .v6xring>div small{display:none!important}
html body #app #view .v6xhero h4{font-size:17px!important;margin:0!important}
html body #app #view .v6xhero .v6tags{justify-content:center!important}
html body #app #view .v6xhero .v6tags .v6pill{font-size:11.5px!important}
@media(max-width:760px){
 html body #app #view .v6xhero .v6xring,html body #app #view .v6xhero .v6xring svg{width:120px!important;height:120px!important}
 html body #app #view .v6xhero .v6xring>div b{font-size:26px!important}
}
/* Brand page hero (v6 lama) ikut: donut lebih besar tanpa "capai" tidak diubah layout-nya */

/* REVISI #3 · heatmap: garis per baris, kotak abu muda untuk sel tanpa target, sejajar tengah */
html body #app #view .v6xheat{row-gap:0!important}
html body #app #view .v6xheat>.rn,html body #app #view .v6xheat>.hc{border-bottom:1px solid #E6ECF3!important;margin-top:0!important;margin-bottom:0!important}
html body #app #view .v6xheat>.rn{display:flex!important;align-items:center!important}
html body #app #view .v6xheat>.hc{display:flex!important;flex-direction:column!important;justify-content:center!important}
html body #app #view .v6xheat>.hc.na:not(.hempty){background:#F4F6F9!important;color:#16202E!important;box-shadow:inset 0 0 0 3px #fff!important;border-radius:9px!important}
html body #app #view .v6xheat>.hc.na:not(.hempty) .hu{color:#16202E!important;font-weight:800!important}
html body #app #view .v6xheat>.hc.hempty{background:transparent!important}
html body #app #view .v6xheat>.hc[class*="v7t"]{box-shadow:inset 0 0 0 3px #fff!important;border-radius:9px!important}
html body #app #view .v6xheat>.hsep{border-bottom:2px solid #9DBEE3!important}
html body #app #view .v6xheat>.v7hcol.v7hcol{display:none!important}

/* REVISI #4 · warna header per brand */
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead th.v7bh{background:var(--v7bb)!important;color:var(--v7bc)!important;box-shadow:none!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead th.v7bh *{color:inherit!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead th.v7bs{border-left:3px solid #fff!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table tbody td.v7bs{border-left:3px solid var(--v7bd)!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table thead tr:last-child th.v7bh{border-bottom:3px solid var(--v7bc)!important}

/* REVISI #6 · SELL THRU biru, SELL OUT orange */
html body :is(#app,.modal) :is(#main,#view,#mbody) table th.v7cST{background:#E3EEFB!important;color:#1E5FB8!important;box-shadow:inset 0 -3px 0 #1E5FB8}
html body :is(#app,.modal) :is(#main,#view,#mbody) table th.v7cSO{background:#FDEDE3!important;color:#B4530B!important;box-shadow:inset 0 -3px 0 #E07A1F}
