html body :is(#app,.modal) :is(#main,#view,#mbody) table td.v7cSO{background-color:#FFF8F2!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table tr.totalRow td.v7cST{background-color:#E3EEFB!important;color:#1E5FB8!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table tr.totalRow td.v7cSO{background-color:#FDEDE3!important;color:#B4530B!important}
/* ===== REVISI #9/#11 · Perbandingan KPI ASM / Sales ===== */
html body #app .kpiCompareGroup{border:1px solid #E3EAF3!important;border-radius:14px!important;background:#fff;box-shadow:0 3px 12px rgba(16,40,80,.06)}
html body #app .kpiCompareGroup>h4{background:#fff!important;color:#3D4A5C!important;border:0!important;border-bottom:1px solid #EEF1F5!important;font:800 12px/1.3 Inter,system-ui,sans-serif!important;letter-spacing:.04em;text-transform:uppercase;padding:12px 16px!important}
html body #app table.v7kc{border-collapse:separate!important;border-spacing:0;min-width:max-content;width:100%}
html body #app table.v7kc th{font:800 9.5px/1.3 Inter,system-ui,sans-serif!important;text-transform:uppercase;letter-spacing:.03em;padding:7px 10px!important;text-align:right!important;color:#0B4C8F!important;background:linear-gradient(180deg,#F2F7FD,#DCEAF8)!important;border-bottom:3px solid #0B5CAD!important;white-space:nowrap;position:static!important}
html body #app table.v7kc th.l,html body #app table.v7kc td.l{text-align:left!important}
html body #app table.v7kc th.grp{background:var(--gb)!important;color:var(--gt)!important;text-align:left!important;border-bottom:0!important;border-left:2px solid #fff!important}
html body #app table.v7kc th.grp small{display:inline-block;margin-left:6px;background:#ffffffb0;color:var(--gt);border-radius:999px;padding:1px 7px;font-size:9px;text-transform:none}
html body #app table.v7kc th.res{background:#0B5CAD!important;color:#fff!important;text-align:center!important;border-left:2px solid #fff!important}
html body #app table.v7kc :is(th,td).gs{border-left:2px solid #B9CDE3!important}
html body #app table.v7kc td{padding:8px 10px!important;text-align:right!important;border-bottom:1px solid #EEF1F5!important;font-variant-numeric:tabular-nums;font-size:12px!important;white-space:nowrap;background:#fff;color:#16202E}
html body #app table.v7kc td.v7kWho{position:sticky;left:0;z-index:2;background:#fff;box-shadow:1px 0 0 #E3EAF3;min-width:170px;white-space:normal}
html body #app table.v7kc thead th.l{position:sticky!important;left:0;z-index:3}
html body #app table.v7kc td.v7kWho b{display:block;font-size:12px;text-transform:uppercase}
html body #app table.v7kc td.v7kWho small{color:#7C8899;font-size:10.5px}
html body #app table.v7kc .v7kTa{color:#7C8899}html body #app table.v7kc .v7kTa b{color:#16202E}
html body #app table.v7kc td.pt{font-weight:800;color:#0B4C8F}
html body #app table.v7kc td.res{border-left:2px solid #B9CDE3!important;text-align:center!important;background:#F4F8FD!important}
html body #app table.v7kc tr.v7kT td{background:#EAF2FB!important;color:#16202E!important;font-weight:800;border-top:2px solid #0B5CAD!important;border-bottom:0!important}
html body #app table.v7kc tr.v7kT td small{display:block;font-weight:500;color:#5B6778}
.v7rgChip{display:inline-block;padding:2px 8px;border-radius:999px;font:800 10.5px/1.4 Inter,system-ui,sans-serif;background:#EEF1F5;color:#5B6778;white-space:nowrap}
.v7rgChip.r{background:#FBE3E1;color:#A3201B}.v7rgChip.y{background:#FFF4D6;color:#8A5A00}.v7rgChip.gr{background:#E2F5EA;color:#0E6E48}
