/* ===== REVISI #12 · tabel KPI RGM ===== */
.v7rgNote{display:flex;align-items:center;gap:6px;padding:4px 2px 10px;font:600 11px Inter,system-ui,sans-serif;color:#7C8899}
.v7rgSt{background:#FFF4D6;color:#8A5A00;border-radius:999px;padding:2px 9px;font:800 10px Inter,system-ui,sans-serif}
html body #app table.rgT.v7rgSum{border-collapse:separate;border-spacing:0}
html body #app table.rgT.v7rgSum th,html body #app table.rgT.v7rgNt th{font:800 9.5px/1.3 Inter,system-ui,sans-serif!important;text-transform:uppercase;letter-spacing:.03em;padding:9px 12px!important;text-align:right!important;color:#0B4C8F!important;background:linear-gradient(180deg,#F2F7FD,#DCEAF8)!important;border-bottom:3px solid #0B5CAD!important}
html body #app table.rgT :is(th,td).l{text-align:left!important}
