/* ===== REVISI #10 · Rincian per RGM ===== */
html body #app .rgH4{font:800 11px Inter,system-ui,sans-serif!important;letter-spacing:.06em;color:#3D4A5C!important;margin:18px 0 8px!important;text-transform:uppercase}
.v7rgGrid{display:grid;grid-template-columns:1fr 1fr;gap:14px;align-items:start}
