/* ===== v7: chart Tren bulanan Beranda ===== */
.v7trend{--m:#7C8899}
.v7tleg{display:flex;flex-wrap:wrap;gap:6px 18px;padding:2px 2px 6px;font:600 11.5px Inter,system-ui,sans-serif;color:#3D4A5C}
.v7tleg span{display:inline-flex;align-items:center;gap:6px}.v7tleg .tot{margin-right:auto;font-weight:700;color:#16202E}
.v7tleg .k{display:inline-block;width:12px;height:12px;border-radius:3px}
.v7tleg .k.bar{background:#8FB6E0}.v7tleg .k.est{background:#fff;border:1.5px dashed #0B5CAD}
.v7tleg .k.ln{width:16px;height:0;border-top:2px dashed #D07345;border-radius:0}.v7tleg .k.tg{width:16px;height:0;border-top:2px solid #C2362F;border-radius:0}
.v7tscroll{overflow-x:auto;scrollbar-width:thin}
.v7tscroll svg{display:block;width:100%;height:auto}
.v7trend .ax{font:500 10px Inter,system-ui,sans-serif;fill:#8A94A6}
.v7trend .ql{font:800 11px Inter,system-ui,sans-serif;fill:#16202E}
.v7trend .qi{font:800 10px Inter,system-ui,sans-serif;fill:#fff}
.v7trend .ml{font:600 11px Inter,system-ui,sans-serif;fill:#3D4A5C}
.v7trend .mtd{font:800 9px Inter,system-ui,sans-serif;fill:#B26A00}
.v7trend .gl{font:800 10.5px Inter,system-ui,sans-serif}.v7trend .gl.up{fill:#0E8A55}.v7trend .gl.dn{fill:#C2362F}
.v7trend .cp{font:800 10.5px Inter,system-ui,sans-serif}
.v7trend .v7tp{cursor:pointer;outline:none}
.v7trend .v7tp:hover rect.b{filter:brightness(.94)}
.v7trend .v7tp.on rect.b{stroke:#0B2C55;stroke-width:1}.v7trend .v7tp.on .ml{font-weight:800;fill:#0B5CAD}
.v7trend .v7tp:focus-visible rect.b{stroke:#16202E;stroke-width:2}
.v7tdet{margin:6px 0 4px;padding:12px 14px;background:#F5F8FC;border:1px solid #E3EAF3;border-radius:10px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.v7tdet .t{grid-column:1/-1;font:800 12px Inter,system-ui,sans-serif;letter-spacing:.03em;color:#16202E}
.v7tdet small{display:block;font:700 10px Inter,system-ui,sans-serif;letter-spacing:.04em;color:#7C8899;text-transform:uppercase}
.v7tdet b{font:800 15px "Plus Jakarta Sans",Inter,sans-serif}
.v7tdet i{font-style:normal;font-size:11px;color:#5B6778;display:block}
.v7tfn{font-size:10px;color:#8A94A6;padding:2px 2px 0}
@media (max-width:899px){.v7tdet{grid-template-columns:1fr 1fr}.v7tleg{font-size:10.5px;gap:4px 12px}.v7tleg .tot{flex-basis:100%}}
