html body :is(#app,.modal) :is(#main,#view,#mbody) table.rgT.v7rgSum thead th.res{background:#0B5CAD!important;color:#fff!important;border-left:3px solid #fff!important;text-align:center!important}
html body :is(#app,.modal) :is(#main,#view,#mbody) table.rgT.v7rgSum thead th.l{background:#F4F7FB!important;color:#0B4C8F!important;border-bottom:3px solid #0B5CAD!important}
