/* KPI settings: approved preview, scoped to editor and target only. */
#v6kBox.v6kWrap{display:block;min-width:0}
#v6kBox .v6kScope{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:14px;background:#fff;border:1px solid #d7e4f1;border-radius:10px;margin-bottom:16px}
#v6kBox .v6kScope label{font-size:12px;color:#617287}
