#view #v6kBox .v6kTable th,#view #v6kBox .v6kDemoTable th{background:#f8fafd!important;color:#617287!important;font-size:12px!important;letter-spacing:0;text-transform:none;padding:11px 9px;border-bottom:1px solid #d7e4f1}
#view #v6kBox .v6kTable td{padding:12px 9px;font-size:13px!important;vertical-align:top;border-bottom:1px solid #d7e4f1}
#v6kBox .v6kTable th:first-child,#v6kBox .v6kTable td:first-child{padding-left:18px}
#v6kBox .v6kTable .fi{background:#fff;border:1px solid #d7e4f1;border-radius:7px;padding:8px;min-height:38px;font-size:13px;text-transform:none}
#v6kBox .v6kTable select[data-k=metric]{min-width:140px}
#v6kBox .v6kTable input[data-k=group]{width:118px}
#v6kBox .v6kTable input[data-k=label]{width:125px}
#v6kBox .v6kTable select[data-k=brand]{min-width:90px}
#v6kBox .v6kTpBtn{border-color:#d7e4f1;min-height:38px;min-width:116px;background:#fff;border-radius:7px}
#v6kBox .v6kRowNote{display:block;color:#0b5cad;font-size:11px;margin-top:6px}
#view #v6kBox .v6kIddleRow td,#view #v6kBox .v6kIddleRow:hover td{background:#f0f6fe!important}
#v6kBox .v6kIddleRow td:first-child{box-shadow:inset 3px 0 #0b5cad}
#v6kBox .v6kLocked{display:block;padding:10px 6px;background:#f5f8fc;border-radius:7px;color:#617287;font-size:11px;white-space:nowrap}
#v6kBox .v6kSums{padding:14px 18px;margin:0;background:#fbfcfe;border-bottom:1px solid #d7e4f1;gap:18px;min-height:45px}
#v6kBox .v6kMt{display:flex;flex-direction:column;gap:6px;margin:0;min-width:165px;max-width:320px;flex:1;border-radius:0;padding:0;background:transparent;color:#16734a}
#v6kBox .v6kMt>span{display:flex;justify-content:space-between;gap:12px;padding:0;border-radius:0;background:transparent;color:inherit}
#v6kBox .v6kMt.bad{color:#b33036}
#v6kBox .v6kBar{width:100%;height:5px;background:#d7e4f1;border-radius:3px}
#v6kBox .v6kBar u{background:#16734a}#v6kBox .v6kMt.bad .v6kBar u{background:#b33036}
#v6kBox .v6kEditorActions{padding:14px 18px;margin:0}
#v6kBox .v6kRuleHelp{padding:14px 18px;background:#e6f0fb;color:#10243b;font-size:12px}
#v6kBox .v6kRuleHelp>b{color:#0b5cad}#v6kBox .v6kRuleHelp p{margin:6px 0 0}
#v6kBox .v6kSaveArea{padding:16px 18px;align-items:flex-end;gap:10px;margin:0;border-bottom:1px solid #d7e4f1}
#v6kBox .v6kSaveArea label{display:flex;flex:1;min-width:200px;flex-direction:column;gap:5px;font-size:12px;color:#617287}
#v6kBox .v6kSaveArea .fi{width:100%;min-height:40px}
#v6kBox .v6kSaveArea #v6kSMsg{flex-basis:100%;font-size:12px}
#v6kBox .v6kSaveArea #v6kSMsg:empty{display:none}
