#v6kBox .v6kDemo{margin:16px 18px;border:1px solid #d7e4f1;border-radius:10px;overflow:hidden;background:#fff}
#v6kBox .v6kDemoHead{padding:15px;display:flex;justify-content:space-between;gap:12px;align-items:start}
#v6kBox .v6kDemoHead h4{margin:0 0 5px;font-size:15px}
#v6kBox .v6kDemoHead p{font-size:12px;margin:0;color:#617287}
#v6kBox .v6kDemoTable{min-width:660px;width:100%}
#view #v6kBox .v6kDemoTable td{padding:10px 9px;font-size:12px!important;vertical-align:middle}
