#v6kBox .v6kDemoTotals .v6kdComplete{flex-direction:row;align-items:center;grid-column:1/-1}
#v6kBox #v6kdStatus{grid-column:1/-1}
#view #v6tBox .v6tTable th{background:#f8fafd!important;color:#617287!important;border-bottom:1px solid #d7e4f1}
