@media(max-width:650px){#v6kBox .v6kScope select{width:100%;flex-basis:100%;min-width:0}#v6kBox .v6kEditorHead>p{padding-right:0}#v6kBox .v6kDemo{margin:14px}#v6kBox .v6kDemoTotals{grid-template-columns:1fr 1fr}#v6kBox .v6kDemoTotals>div:nth-child(3){grid-column:1/-1}#v6kBox .v6kSaveArea label{min-width:0;width:100%;flex-basis:100%}#v6kBox #v6kSave{width:100%}#v6kBox .v6kEditorHead h4{padding-right:0}#v6kBox .v6kEditorHead>.v6kTag{position:static;margin-top:8px}}
