<script>
'use strict';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>n==null?'—':new Intl.NumberFormat('id-ID',{maximumFractionDigits:0}).format(n),decimal=n=>n==null?'—':new Intl.NumberFormat('id-ID',{maximumFractionDigits:1}).format(n),rupiah=n=>'Rp '+num(n),pct=n=>n==null?'—':new Intl.NumberFormat('id-ID',{minimumFractionDigits:1,maximumFractionDigits:1}).format(n)+'%',pctLegacy=n=>n==null?'—':decimal(n)+'%',tgl=s=>s?new Date(s+'T00:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}):'—',bulan=s=>new Date(s+'-01T00:00:00').toLocaleDateString('id-ID',{month:'long',year:'numeric'});

const zoomPreferenceStorage={
  getItem(key){try{return window.localStorage.getItem(key);}catch(error){return null;}},
  setItem(key,value){try{window.localStorage.setItem(key,value);}catch(error){}}
};
function showZoomRecommendation(){
  if(!window.matchMedia('(max-width: 760px)').matches)return;
  if(zoomPreferenceStorage.getItem('sp-hide-zoom-80')==='true')return;
  const overlay=$('zoomSuggestOverlay');
  if(!overlay)return;
  overlay.hidden=false;
  overlay.classList.add('on');
  requestAnimationFrame(()=>$('zoomSuggestContinue')?.focus());
}
function closeZoomRecommendation(){
  const overlay=$('zoomSuggestOverlay');
  if(!overlay)return;
  if($('dontShowZoomAgain')?.checked)zoomPreferenceStorage.setItem('sp-hide-zoom-80','true');
  overlay.classList.remove('on');
  overlay.hidden=true;
}
$('zoomSuggestContinue').onclick=closeZoomRecommendation;

// Storage can be denied in embedded/private browser contexts. Keep the live
// token in memory; persistent tab storage is only an optional convenience.
// localStorage (bukan sessionStorage) dipakai supaya token dipakai bersama oleh semua tab
// browser yang sama (satu kali login dipakai di semua tab), dan supaya logout di satu tab
// langsung kedeteksi tab lain lewat event 'storage'.
const portalStorage={
  getItem(key){try{return window.localStorage.getItem(key);}catch(error){return null;}},
  setItem(key,value){try{window.localStorage.setItem(key,value);}catch(error){}},
  removeItem(key){try{window.localStorage.removeItem(key);}catch(error){}}
};
function deviceId_(){let id='';try{id=window.localStorage.getItem('sp-device-id')||'';}catch(error){}if(!id){id=(crypto.randomUUID?crypto.randomUUID():'dsm-'+Date.now()+'-'+Math.random().toString(16).slice(2)).replace(/[^a-zA-Z0-9_-]/g,'');try{window.localStorage.setItem('sp-device-id',id);}catch(error){}}return id;}
const DEVICE_ID=deviceId_();
let TOKEN=portalStorage.getItem('sp-token')||'',BOOT=null,REPORT=null,PAGE='beranda',SEQUENCE=0,AI_HISTORY=[],AI_OPTIONS=null,customerFilter={query:'',statuses:[],order:'ALL',brand:'ALL',city:'ALL',region:'ALL',subRegion:'ALL'},customerPage=0,customerPageSize=10,brandChoice='',teamLevel='SALES',teamScope={big:'ALL',region:'ALL',sub:'ALL'},teamBrandChoice='',brandTeamRegion='ALL',brandTeamSubRegion='ALL',brandIndicatorMetric='ST',brandIndicatorLevel='SALES',brandIndicatorRegion='ALL',brandIndicatorSubRegion='ALL',brandIndicatorBrands=[],rankNational=false,transactionPage=0,transactionPageSize=100,stage=null,lastFocus=null;
let weeklyAnalysis={mode:'WOW',metric:'ST',type:'ALL',weekA:1,weekB:2,periodA:'',periodB:'',big:'ALL',region:'ALL',sub:'ALL',rgm:'',asm:'',sales:''},teamCompare={mode:'WOW',metric:'ST',level:'SALES',weekA:1,weekB:2,brand:'ALL',big:'ALL',region:'ALL',sub:'ALL',rgm:'',asm:'',sales:''};
const brandTeamCache=new Map();let brandTeamRequest=0,brandIndicatorRequest=0,kpiBigRegion='ALL';
const titles={beranda:'Beranda',analisa:'Analisa',transaksi:'Transaksi',customer:'Dealer',brand:'Brand',tim:'Tim',kpi:'KPI',peringkat:'Peringkat',dos:'DOS',ai:'AI Assistant',informasi:'Informasi',panduan:'Panduan',perangkat:'Perangkat Saya',admin:'Admin',tmfu:'FOLLOW UP',tmorder:'FORM ORDER',tmactivity:'AKTIVITAS TELEMARKETING'};
let appLoadingTicket=0,appLoadingStarted=0,appLoadingSlowTimer=0,appLoadingDismissTimer=0;
const waitForPaint=()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
function ensureAppLoading(){let overlay=$('appLoading');if(overlay)return overlay;overlay=document.createElement('div');overlay.id='appLoading';overlay.className='appLoading';overlay.hidden=true;overlay.setAttribute('role','status');overlay.setAttribute('aria-live','polite');overlay.setAttribute('aria-busy','true');overlay.innerHTML='<section class="appLoadingCard"><span class="appLoadingMark" aria-hidden="true"><i></i></span><span class="alBars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span><h3 id="appLoadingTitle">Memuat data…</h3><p id="appLoadingDetail">Menyiapkan tampilan terbaru.</p><b class="alPct" id="alPct" aria-hidden="true">0%</b><span class="appLoadingTrack" aria-hidden="true"><i></i></span><span class="alSteps" id="alSteps" aria-hidden="true"><em>Mengambil data</em><em>Menghitung angka</em><em>Menyiapkan tampilan</em></span><button type="button" class="appLoadingDismiss" id="appLoadingDismiss" hidden>Tutup tampilan loading</button></section>';$('app').append(overlay);$('appLoadingDismiss').onclick=()=>finishAppLoading(appLoadingTicket,true);return overlay;}
function markActivePage(page){document.querySelectorAll('#navigation button').forEach(button=>button.classList.toggle('on',button.dataset.page===page));syncMobileNav();}
function lockNavigation(locked){document.querySelectorAll('#navigation button,#mBottom button').forEach(button=>{button.disabled=locked;button.setAttribute('aria-disabled',String(locked));});}
var alTimer=0,alP=0;function alSet(p,done){alP=p;const o=$('appLoading');if(!o)return;o.style.setProperty('--alp',p+'%');const pc=$('alPct');if(pc)pc.textContent=Math.round(p)+'%';const st=done?3:(p<30?0:p<65?1:2);document.querySelectorAll('#alSteps em').forEach((e,i)=>{e.className=i<st?'ok':i===st?'on':'';});}
function alStart(){clearInterval(alTimer);alSet(4,false);alTimer=setInterval(()=>{alSet(alP+(92-alP)*.09,false);},160);}
function alStop(){clearInterval(alTimer);alSet(100,true);}
function showAppLoading(title='Memuat data…',detail='Menyiapkan tampilan terbaru.'){const app=$('app');if(!app||app.hidden)return 0;const ticket=++appLoadingTicket,overlay=ensureAppLoading();clearTimeout(appLoadingSlowTimer);clearTimeout(appLoadingDismissTimer);appLoadingStarted=performance.now();$('appLoadingTitle').textContent=title;$('appLoadingDetail').textContent=detail;$('appLoadingDismiss').hidden=true;overlay.hidden=false;overlay.classList.remove('on');void overlay.offsetWidth;overlay.classList.toggle('v12c',!!window.v12L);window.v12L=0;overlay.classList.add('on');alStart();$('main')?.setAttribute('aria-busy','true');lockNavigation(true);appLoadingSlowTimer=setTimeout(()=>{if(ticket===appLoadingTicket&&!overlay.hidden)$('appLoadingDetail').textContent='Datanya cukup banyak, proses masih berjalan…';},9000);appLoadingDismissTimer=setTimeout(()=>{if(ticket===appLoadingTicket&&!overlay.hidden){$('appLoadingDetail').textContent='Proses lebih lama dari biasanya. Lu bisa tetap menunggu atau menutup tampilan loading.';$('appLoadingDismiss').hidden=false;}},25000);return ticket;}
function finishAppLoading(ticket=appLoadingTicket,immediate=false){if(ticket&&ticket!==appLoadingTicket)return;clearTimeout(appLoadingSlowTimer);clearTimeout(appLoadingDismissTimer);const overlay=$('appLoading');if(!overlay)return;alStop();const close=()=>{if(ticket&&ticket!==appLoadingTicket)return;overlay.classList.remove('on');$('main')?.removeAttribute('aria-busy');lockNavigation(false);setTimeout(()=>{if(!overlay.classList.contains('on'))overlay.hidden=true;},190);};const delay=immediate?0:Math.max(0,320-(performance.now()-appLoadingStarted));setTimeout(close,delay);}
async function navigateTo(page){if(page==='tmfu')page='tmactivity';if(!REPORT||!titles[page])return;PAGE=page;if(window.location.hash.slice(1)!==page){try{history.replaceState(null,'','#'+page);}catch(error){window.location.hash=page;}}markActivePage(page);$('navigation').classList.remove('open');$('menuToggle').setAttribute('aria-expanded','false');closeMobileMore();const ticket=(window.v12L=isMobile()&&!['dos','brand','analisa','kpi'].includes(page),showAppLoading('Memuat '+titles[page]+'…','Menyiapkan data dan tampilan '+titles[page]+'.'));await waitForPaint();try{await render();}finally{finishAppLoading(ticket);}}
window.addEventListener('hashchange',()=>{const page=window.location.hash.slice(1);if(page&&titles[page]&&page!==PAGE&&REPORT)navigateTo(page);});
function rpcBody(name,args){const forms=args.map(a=>a instanceof HTMLFormElement);if(!forms.some(Boolean))return {headers:{'Content-Type':'application/json'},body:JSON.stringify({fn:name,args})};const fd=new FormData(),plain=args.map((a,i)=>{if(!(a instanceof HTMLFormElement))return a;const o={};new FormData(a).forEach((v,k)=>{if(v instanceof File){fd.append('__f'+i+'__'+k,v,v.name||'');o[k]={__file:'__f'+i+'__'+k};}else if(k in o){o[k]=[].concat(o[k],v);}else o[k]=v;});return {__form:o};});fd.append('__payload',JSON.stringify({fn:name,args:plain}));return {body:fd};}
function rpc(name,...args){v6Busy(1);let tries=0;return new Promise((resolve,reject)=>{const go=()=>{const req=rpcBody(name,args);fetch('api.php',{method:'POST',headers:req.headers,body:req.body}).then(r=>r.text()).then(t=>{let j;try{j=JSON.parse(t);}catch(e){throw Error(t&&t.length<400?t.replace(/<[^>]+>/g,' ').trim():'Jawaban server tidak valid (cek ukuran file / log PHP).');}return j;}).then(j=>{if(j&&j.ok){v6Busy(-1);resolve(j.result);}else{const m=String((j&&j.message)||'Gagal memanggil server.');if(tries<3&&V6RETRY.test(m)&&!/SESI:/.test(m)){const wait=[1200,2500,5000][tries++]+Math.random()*800;v6RetryNote(tries);setTimeout(go,wait);return;}v6Busy(-1);const er=Error(m);er.data=j&&j.data;reject(er);}}).catch(err=>{const m=String(err&&err.message||err);if(tries<3&&/Failed to fetch|NetworkError/i.test(m)&&!/SESI:/.test(m)){const wait=[1200,2500,5000][tries++]+Math.random()*800;v6RetryNote(tries);setTimeout(go,wait);return;}v6Busy(-1);reject(Error(m));});};go();});}
function fail(e,retry){const msg=e?.message||String(e);if(msg.includes('SESI:')){logout(false);$('lerr').style.display='block';$('lerr').textContent=msg;return;}const box=$('error');box.hidden=false;box.textContent=msg;if(typeof retry==='function'){const button=document.createElement('button');button.type='button';button.className='errorRetry';button.textContent='Coba lagi';button.onclick=()=>retry();box.append(document.createElement('br'),button);}}
function storeToken(t){TOKEN=t;portalStorage.setItem('sp-token',t);}
function hideLoginScreen(){const el=$('login');if(!el)return;document.body.classList.add('loginDismissed');el.hidden=true;el.style.setProperty('display','none','important');try{window.scrollTo({top:0,left:0,behavior:'instant'});}catch(error){window.scrollTo(0,0);}document.documentElement.scrollTop=0;document.body.scrollTop=0;}
function showLoginScreen(){const el=$('login');if(!el)return;document.body.classList.remove('loginDismissed');el.hidden=false;el.style.removeProperty('display');try{window.scrollTo({top:0,left:0,behavior:'instant'});}catch(error){window.scrollTo(0,0);}document.documentElement.scrollTop=0;document.body.scrollTop=0;}
(function(){const eye=$('inPinEye'),pin=$('inPin');const t=()=>{const show=pin.type==='password';pin.type=show?'text':'password';eye.textContent=show?'Sembunyikan':'Lihat';};eye.onclick=t;eye.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();t();}};})();
$('loginForm').onsubmit=async e=>{e.preventDefault();$('loginBtn').disabled=true;$('loginBtn').textContent='Memuat dashboard…';$('lerr').style.display='none';try{const r=await rpc('apiLogin',$('inNik').value.trim(),$('inPin').value,DEVICE_ID);$('inPin').value='';if(r.need2fa){await tfaStart(r);return;}storeToken(r.token);if(r.mustChange)showPin();else await start();}catch(e){$('lerr').style.display='block';$('lerr').textContent=e.message;}finally{$('loginBtn').disabled=false;$('loginBtn').textContent='Masuk →';}};

// Sinkronisasi antar tab: tab lain yang logout/login akan kedeteksi lewat event 'storage'
// (hanya terpicu di tab LAIN, bukan tab yang melakukan perubahan).
window.addEventListener('storage',e=>{
  if(e.key!=='sp-token')return;
  const now=e.newValue||'';
  if(now===TOKEN)return;
  if(!now){TOKEN='';BOOT=null;REPORT=null;$('app').hidden=true;$('changePin').hidden=true;$('tfa').hidden=true;removeDemoUi();showLoginScreen();return;}
  // Token berubah (login baru / ganti PIN di tab lain) — muat ulang supaya konsisten.
  window.location.reload();
});

/* ===== Verifikasi 2 langkah (Authenticator) ===== */
let TFA=null;
function tfaShow(sec){['tfaVerify','tfaS1','tfaS2','tfaCodes'].forEach(id=>{$(id).hidden=id!==sec;});hideLoginScreen();$('changePin').hidden=true;$('tfa').hidden=false;$('tfaErr').style.display='none';$('tfaErr').textContent='';$('tfaTag').textContent=sec==='tfaVerify'?'Verifikasi 2 langkah':'Aktifkan Authenticator';}
function tfaErr(msg){const b=$('tfaErr');b.textContent=msg;b.style.display='block';}
function tfaBack(msg){TFA=null;$('tfa').hidden=true;showLoginScreen();['tfaCode','tfaSetCode'].forEach(i=>$(i).value='');if(msg){$('lerr').style.display='block';$('lerr').textContent=msg;}}
function tfaCatch(e){const m=e?.message||String(e);if(m.includes('Sesi verifikasi habis')||m.includes('dikunci')||m.includes('Terlalu banyak')){tfaBack(m);return;}tfaErr(m);}
function tfaCopy(text,btn){const done=()=>{if(btn){const o=btn.textContent;btn.textContent='Tersalin ✓';setTimeout(()=>btn.textContent=o,1500);}};
 if(navigator.clipboard&&window.isSecureContext)navigator.clipboard.writeText(text).then(done,()=>tfaCopyOld(text,done));else tfaCopyOld(text,done);}
function tfaCopyOld(text,done){const t=document.createElement('textarea');t.value=text;t.style.cssText='position:fixed;opacity:0';document.body.append(t);t.select();try{document.execCommand('copy');done();}catch(e){}t.remove();}
async function tfaStart(r){TFA={ticket:r.ticket,mode:r.mode,backup:false};
 if(r.mode==='verify'){tfaShow('tfaVerify');tfaMode(false);$('tfaCode').value='';$('tfaCode').focus();return;}
 tfaShow('tfaS1');$('tfaKey').textContent='Memuat…';$('tfaQr').innerHTML='';
 try{const s=await rpc('apiTotpSetup',TFA.ticket);TFA.uri=s.uri;TFA.secret=s.secret;
  const q=qrcode(0,'M');q.addData(s.uri);q.make();$('tfaQr').innerHTML=q.createSvgTag({cellSize:4,margin:2,scalable:true});
  $('tfaKey').textContent=s.secret.replace(/(.{4})/g,'$1 ').trim();$('tfaOpen').href=s.uri;}catch(e){tfaCatch(e);}}
function tfaMode(backup){TFA.backup=backup;const c=$('tfaCode');c.value='';c.placeholder=backup?'XXXX-XXXX':'000000';c.inputMode=backup?'text':'numeric';c.maxLength=backup?12:6;$('tfaCodeL').textContent=backup?'Kode cadangan':'Kode 6 digit';$('tfaToggle').textContent=backup?'Pakai kode dari aplikasi':'Pakai kode cadangan';$('tfaVerifyP').innerHTML=backup?'Ketik salah satu <b>kode cadangan</b> yang kamu simpan. Tiap kode hanya sekali pakai.':'Buka aplikasi Authenticator di HP dan ketik kode 6 digit untuk <b>DSM</b>.';}
function tfaDone(r){storeToken(r.token);$('tfa').hidden=true;TFA=null;
 if(r.mustChange){showPin();return;}
 start().then(()=>{if(r.usedBackup)alert('Kode cadangan terpakai. Sisa '+r.backupLeft+' kode.'+(r.backupLeft<=2?'\nKode cadangan hampir habis. Minta admin reset Authenticator lalu daftar ulang untuk mendapat kode baru.':''));});}
$('tfaToggle').onclick=()=>tfaMode(!TFA.backup);
document.querySelectorAll('[data-tfa-back]').forEach(b=>b.onclick=()=>tfaBack());
$('tfaVerify').onsubmit=async e=>{e.preventDefault();const btn=$('tfaVerifyBtn');btn.disabled=true;btn.textContent='Memeriksa…';try{tfaDone(await rpc('apiLogin2fa',TFA.ticket,$('tfaCode').value.trim()));}catch(err){tfaCatch(err);}finally{btn.disabled=false;btn.textContent='Masuk';}};
$('tfaNext').onclick=()=>{if(!TFA?.secret)return;tfaShow('tfaS2');$('tfaSetCode').value='';$('tfaSetCode').focus();};
$('tfaPrev').onclick=()=>{tfaShow('tfaS1');};
$('tfaCopyKey').onclick=e=>{if(TFA?.secret)tfaCopy(TFA.secret,e.target);};
$('tfaS2').onsubmit=async e=>{e.preventDefault();const btn=$('tfaEnableBtn');btn.disabled=true;btn.textContent='Memeriksa…';try{const r=await rpc('apiTotpEnable',TFA.ticket,$('tfaSetCode').value.trim());TFA.done=r;TFA.codes=r.backupCodes;$('tfaCodeList').innerHTML=r.backupCodes.map(c=>`<div>${esc(c)}</div>`).join('');$('tfaAck').checked=false;$('tfaGo').disabled=true;tfaShow('tfaCodes');}catch(err){tfaCatch(err);}finally{btn.disabled=false;btn.innerHTML='Verifikasi &amp; aktifkan';}};
$('tfaCopyCodes').onclick=e=>tfaCopy((TFA?.codes||[]).join('\n'),e.target);
$('tfaDl').onclick=()=>{const nik=($('inNik').value||'akun').trim();const b=new Blob(['Kode cadangan DSM ('+nik+')\nTiap kode hanya sekali pakai. Simpan di tempat aman, jangan di HP yang sama.\n\n'+(TFA?.codes||[]).join('\n')+'\n'],{type:'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='kode-cadangan-dsm.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),2000);};
