function showPin(){if(BOOT?.demo?.active){fail(Error('Mode Demo hanya-baca. Kembali ke akun Super Admin untuk mengganti PIN.'));return;}hideLoginScreen();$('app').hidden=true;$('changePin').hidden=false;$('pinErr').textContent='';$('newPin').focus();}
$('pinForm').onsubmit=async e=>{e.preventDefault();if($('newPin').value!==$('confirmPin').value){$('pinErr').textContent='Kedua PIN harus sama.';return;}const btn=e.target.querySelector('button');btn.disabled=true;try{const r=await rpc('apiChangePin',TOKEN,$('newPin').value);storeToken(r.token);$('pinForm').reset();await start();}catch(err){$('pinErr').textContent=err.message;}finally{btn.disabled=false;}};
function resetViewForIdentity(){tmResetIdentity();PAGE='beranda';REPORT=null;SEQUENCE++;AI_HISTORY=[];AI_OPTIONS=null;customerPage=0;transactionPage=0;brandTeamCache.clear();
 /* v7: buang semua data yang tersimpan di memori milik akun sebelumnya (mis. Analisa Super Admin terbawa ke akun ASM setelah logout) */
 for(const f of [()=>{v6ANA=null;},()=>v6DayCache.clear(),()=>v6OrgCache.clear(),()=>{brandDealerContext='';},()=>{V6X.key=null;V6X.data=null;V6X.drill=null;},()=>{V6K=null;V6KSEL=null;V6KROWS=[];},()=>{V6T=null;},()=>{V6DE=null;},()=>{V6PM=null;},()=>{V6DR=null;},()=>{V6RM=null;},()=>{V6H=null;}])try{f();}catch(e){}}
function removeDemoUi(){$('demoBanner')?.remove();$('demoEntry')?.remove();$('presentationEntry')?.remove();const pinButton=document.querySelector('.who button[onclick="showPin()"]');if(pinButton)pinButton.hidden=false;}
function syncDemoUi(){
  removeDemoUi();const demo=BOOT?.demo,who=document.querySelector('.who'),topbar=document.querySelector('.topbar');if(!demo||!who||!topbar)return;
  if(demo.active){const pinButton=who.querySelector('button[onclick="showPin()"]');if(pinButton)pinButton.hidden=true;const back=document.createElement('button');back.type='button';back.id='demoEntry';back.className='out demoEntry';back.textContent='Kembali Super Admin';back.onclick=stopDemoMode;who.insertBefore(back,who.querySelector('button[onclick="logout()"]'));const banner=document.createElement('div');banner.id='demoBanner';banner.className='demoBanner';banner.setAttribute('role','status');banner.innerHTML=`<strong>MODE DEMO</strong><span>Sebagai ${esc(demo.target?.nama||BOOT.user.nama)} · ${esc(demo.target?.role||BOOT.user.role)} · hanya-baca</span><button type="button" class="chip">Kembali ke Super Admin</button>`;banner.querySelector('button').onclick=stopDemoMode;topbar.insertAdjacentElement('afterend',banner);
  }else if(demo.canStart){const button=document.createElement('button');button.type='button';button.id='demoEntry';button.className='out demoEntry';button.textContent='Demo · Lihat sebagai';button.onclick=openDemoChooser;who.insertBefore(button,who.querySelector('button[onclick="showPin()"]'));}
  if(demo.active||demo.canStart){const present=document.createElement('button');present.type='button';present.id='presentationEntry';present.className='out';present.textContent='Presentasi';present.title='Buka simulasi desktop dan mobile';present.onclick=()=>window.open(new URL('demo-presentasi.html',window.location.href).href,'_blank','noopener');$('demoEntry')?.insertAdjacentElement('afterend',present);}
}
async function openDemoChooser(){
  const button=$('demoEntry');if(button)button.disabled=true;try{const users=await rpc('apiDemoOptions',TOKEN);if(!users.length){fail(Error('Belum ada akun aktif yang dapat dipakai untuk Demo.'));return;}modal('Demo · Lihat sebagai pengguna',`<div class="demoModalNote"><b>Mode presentasi aman.</b> Menu dan data mengikuti pengguna yang dipilih. Export, perubahan data, dan aksi administrasi otomatis dikunci.</div><form id="demoForm"><div class="demoFilters"><label>Big Region<select class="fi" id="demoBig"></select></label><label>Region / Sub Region<select class="fi" id="demoRegion"></select></label><label>Role<select class="fi" id="demoRole"></select></label><label>Cari nama / NIK<input class="fi" id="demoSearch" autocomplete="off" placeholder="Ketik nama atau NIK"></label></div><label class="demoTargetLabel">Sebagai siapa?<select class="fi" id="demoTarget" size="6" required></select></label><small class="demoMeta" id="demoMeta"></small><div class="demoActions"><button type="button" class="chip" onclick="closeModal()">Batal</button><button class="chip primary" id="demoSubmit">Mulai Demo</button></div></form>`);
    const uniq=a=>[...new Set(a.filter(Boolean))].sort((x,y)=>x.localeCompare(y,'id')),option=(value,label=value)=>`<option value="${esc(value)}">${esc(label)}</option>`,big=$('demoBig'),region=$('demoRegion'),role=$('demoRole'),search=$('demoSearch'),target=$('demoTarget');big.innerHTML=option('ALL','Semua Big Region')+uniq(users.map(x=>x.bigRegion)).map(x=>option(x)).join('');
    const refreshRegions=()=>{const rows=users.filter(x=>big.value==='ALL'||x.bigRegion===big.value),old=region.value;region.innerHTML=option('ALL','Semua Region / Sub Region')+uniq(rows.map(x=>x.region)).map(x=>option(x)).join('');if([...region.options].some(x=>x.value===old))region.value=old;refreshRoles();},refreshRoles=()=>{const rows=users.filter(x=>(big.value==='ALL'||x.bigRegion===big.value)&&(region.value==='ALL'||x.region===region.value)),old=role.value;role.innerHTML=option('ALL','Semua Role')+uniq(rows.map(x=>x.role)).map(x=>option(x)).join('');if([...role.options].some(x=>x.value===old))role.value=old;refreshTargets();},refreshTargets=()=>{const q=search.value.trim().toLowerCase(),rows=users.filter(x=>(big.value==='ALL'||x.bigRegion===big.value)&&(region.value==='ALL'||x.region===region.value)&&(role.value==='ALL'||x.role===role.value)&&(!q||(x.nama+' '+x.nik).toLowerCase().includes(q)));target.innerHTML=rows.map(x=>option(x.nik,`${x.nama} · ${x.role} · ${x.region}`)).join('');$('demoMeta').textContent=rows.length?rows.length+' akun aktif tersedia':'Tidak ada akun sesuai filter.';};
    big.onchange=refreshRegions;region.onchange=refreshRoles;role.onchange=refreshTargets;search.oninput=refreshTargets;refreshRegions();$('demoForm').onsubmit=async e=>{e.preventDefault();if(!target.value)return;const submit=$('demoSubmit');submit.disabled=true;submit.textContent='Mengaktifkan…';try{await rpc('apiStartDemo',TOKEN,target.value);portalStorage.setItem('sp-demo-active','1');closeModal();resetViewForIdentity();try{V6X.key=null;V6X.data=null;}catch(e){}await start();}catch(error){fail(error);submit.disabled=false;submit.textContent='Mulai Demo';}};
  }catch(error){fail(error);}finally{if(button?.isConnected)button.disabled=false;}
}
async function stopDemoMode(){const buttons=[...document.querySelectorAll('#demoEntry,#demoBanner button')];buttons.forEach(x=>x.disabled=true);const ticket=showAppLoading('Mengembalikan akun…','Memulihkan akses Super Admin.');try{await rpc('apiStopDemo',TOKEN);portalStorage.removeItem('sp-demo-active');resetViewForIdentity();try{V6X.key=null;V6X.data=null;}catch(e){}await start();}catch(error){fail(error);buttons.forEach(x=>x.disabled=false);}finally{finishAppLoading(ticket);}}
async function start(){const initialToken=TOKEN;const [result,v6b]=await Promise.all([rpc('apiBootstrap',TOKEN),rpc('apiV6Boot',TOKEN).catch(()=>({hol:[],tutup:null}))]);if(initialToken!==TOKEN)return;BOOT=result;try{const nt=new URLSearchParams(location.search).get('nt');if(nt){rpc('apiNotifOpened',TOKEN,+nt).catch(()=>{});history.replaceState(null,'',location.pathname+location.hash)}}catch(e){}BOOT.v6hol=(v6b&&v6b.hol)||[];v6TutupSet(v6b&&v6b.tutup);hideLoginScreen();$('changePin').hidden=true;$('tfa').hidden=true;$('app').hidden=false;const u=BOOT.user;$('roleChip').textContent=({'CHIEF OPERATING OFFICER':'COO','CHIEF COMMERCIAL OFFICER':'CCO','BOARD OF DIRECTOR':'BOD'})[u.role]||u.role;$('namaTop').textContent=u.nama;$('avatarTop').textContent=u.nama.split(' ').slice(0,2).map(x=>x[0]).join('');$('navigation').innerHTML=Object.keys(titles).filter(k=>tmMenuAllowed(k,u.role)).filter(k=>(k!=='admin'||['ADMIN','SUPER ADMIN'].includes(u.role))).map(k=>`<button data-page="${k}">${titles[k]}</button>`).join('');$('periodSelect').innerHTML=BOOT.periods.map(p=>`<option value="${p}">${bulan(p)}</option>`).join('');$('scopeSelect').innerHTML=scopeOptions();$('scopeSelect').disabled=['SALES','TELEMARKETING'].includes(u.role);{let hashPage=window.location.hash.slice(1);if(hashPage==='tmfu')hashPage='tmactivity';PAGE=(hashPage&&titles[hashPage]&&tmMenuAllowed(hashPage,u.role)&&(hashPage!=='admin'||['ADMIN','SUPER ADMIN'].includes(u.role)))?hashPage:'beranda';try{history.replaceState(null,'','#'+PAGE);}catch(error){}}syncDemoUi();await refresh();showZoomRecommendation();}
function logout(remote=true){closeMobileMore();const old=TOKEN;TOKEN='';try{resetViewForIdentity();}catch(e){}BOOT=null;REPORT=null;SEQUENCE++;portalStorage.removeItem('sp-token');portalStorage.removeItem('sp-demo-active');removeDemoUi();$('main').innerHTML='';$('mbody').innerHTML='';closeModal();$('app').hidden=true;$('changePin').hidden=true;$('tfa').hidden=true;showLoginScreen();try{history.replaceState(null,'',window.location.pathname+window.location.search);}catch(error){}if(remote&&old)rpc('apiLogout',old).catch(()=>{});}
$('navigation').onclick=e=>{const button=e.target.closest('[data-page]');if(button)navigateTo(button.dataset.page);};
$('menuToggle').onclick=()=>{const on=$('navigation').classList.toggle('open');$('menuToggle').setAttribute('aria-expanded',String(on));};
$('mobileDataStatus').onclick=()=>{const bar=document.querySelector('#app .updbar');const open=bar.classList.toggle('processOpen');$('mobileDataStatus').setAttribute('aria-expanded',String(open));};
['periodSelect','scopeSelect'].forEach(id=>$(id).onchange=()=>{customerPage=0;transactionPage=0;refresh();});
async function refresh(){if(!BOOT)return;const ticket=showAppLoading('Memuat data…','Memperbarui periode, cakupan, dan seluruh ringkasan.');if(ticket)await waitForPaint();const seq=++SEQUENCE;$('busy').hidden=false;$('error').hidden=true;try{const r=await rpc('apiDashboard',TOKEN,$('periodSelect').value,$('scopeSelect').value);if(seq!==SEQUENCE)return;REPORT=r;v6ApplyTutup(REPORT);brandTeamCache.clear();$('updData').textContent=tgl(r.coverage.cutoff);$('updProses').textContent=new Date(r.processed).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})+' WIB';$('crumb').textContent=(BOOT.user.wilayah||'Nasional')+' / '+r.scopeCount+(uRoleIsTelemarketing()?' dealer penugasan':' data Sales');$('busy').hidden=true;await render();}catch(e){if(seq===SEQUENCE)fail(e,refresh);}finally{if(seq===SEQUENCE)$('busy').hidden=true;finishAppLoading(ticket);}}
function panel(title,content,hint='',action=''){return `<section class="panel"><div class="ph"><h3>${title}</h3><span class="hint">${hint}</span>${action}</div><div class="pb">${content}</div></section>`;}
function analysisSummaryPanel(title,happening,cause,action,stats=[]){if(typeof PAGE==='string'&&PAGE!=='beranda')return '';return panel(title,`<div class="insightLead"><div><small>Apa yang terjadi</small><b>${esc(happening)}</b></div><div><small>Penyebab utama</small><b>${esc(cause)}</b></div><div><small>Tindakan disarankan</small><b>${esc(action)}</b></div></div>${stats.length?'<div class="insightStats">'+stats.map(x=>`<span><small>${esc(x[0])}</small><b>${esc(x[1])}</b></span>`).join('')+'</div>':''}`,'Ringkasan otomatis mengikuti periode, cakupan, dan filter aktif');}
function table(head,rows){return `<div class="table-scroll"><table><thead><tr>${head.map((h,i)=>`<th class="${i?'n':'ns'}">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr class="${row[0]==='Total'?'totalRow':''}">${row.map((v,i)=>`<td class="${i?'n':''}">${v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${head.length}"><div class="empty">Tidak ada data untuk pilihan ini.</div></td></tr>`}</tbody></table></div>`;}
function moneyCard(n){/* v7: format singkat seragam (rb/jt/M) */return '<span class="moneyLong">'+rupiah(n)+'</span><span class="moneyShort" title="'+rupiah(n)+'">'+moneyShort(n)+'</span>';}
function kGlyph(l){l=String(l||'').toUpperCase();const M=[[/IDLE|IDDLE/,'◐'],[/PASIF/,'‖'],[/NOO/,'★'],[/^DA|DEALER AKTIF/,'↺'],[/AKTIF/,'✓'],[/SELL ?OUT|^SO\b/,'↑'],[/SELL ?THRU|^ST\b/,'→'],[/OMZET|OMSET|RP/,'Rp'],[/TARGET/,'◎'],[/ACH|CAPAI|SKOR|SCORE/,'%'],[/GROWTH|NAIK|TUMBUH/,'↗'],[/STOK|STOCK|DOS/,'▦'],[/DEALER|TOKO|OUTLET/,'◉']];for(const [r,g] of M)if(r.test(l))return g;return '●';}
function kBody(it){return `<i class="kic" aria-hidden="true">${kGlyph(it[0])}</i><div class="ktx"><div class="klab">${it[0]}</div><div class="kval">${it[1]}</div><div class="ksub">${it[2]}</div>${it[4]!=null?v6Mini(it[4],it[5]??100):''}</div>${it[6]?'<span class="v6ki"'+it[6]+'>i</span>':''}`;}
function cards(items){return '<div class="kpis">'+items.map((it,i)=>`<button class="kpi ${['g','a','c',''][i%4]}" ${it[3]?`data-jump="${it[3]}"`:''}>${kBody(it)}</button>`).join('')+'</div>';}
function ach(a,t){return t&&t.value>0?a/t.value*100:null;}
function targetText(t){if(!t||!(t.value>0))return !t||!t.exists?'0':num(t.value||0);return num(t.value);}
function bar(value){if(value==null)return '<span class="v7dash">-</span>';/* v7: pencapaian jadi chip warna (tanpa bar) */const tone=value>=100?'up':value>=80?'md':'dn';return `<span class="v7ach ${tone}">${pct(value)}</span>`;}
function delta(now,old,unit='unit'){if(!REPORT.previousAvailable)return '<span class="hint">Pembanding belum tersedia</span>';/* v7: chip % di atas, selisih + bulan lalu di bawah (data sama, lebih ringkas) */if(!now&&!old)return '<span class="v7dash">-</span>';const d=now-old,p=old===0?'basis 0':pct(Math.abs(d/old*100)),state=d>0?'up':d<0?'dn':'fl',arrow=d>0?'▲':d<0?'▼':'•';return `<span class="v7delta"><span class="dlt ${state}" title="${esc(unit)}"><span class="growthArrow">${arrow}</span> <span class="growthPct">${p}</span></span><span class="cmp"><span class="growthValue">${d>0?'+':''}${num(d)}</span> · dari <b>${num(old)}</b></span></span>`;}
function compareHtml(){const c=REPORT.coverage;if(c.closed)return `<span class="v6cmp"><span class="v6c a"><b>${esc(bulan(REPORT.period))}</b></span><em>vs</em><span class="v6c b"><b>${esc(bulan(REPORT.previousPeriod))}</b></span><span class="v6c k">bulan penuh</span></span>`;return `<span class="v6cmp"><span class="v6c a"><i>MTD</i> 1–${+c.cutoff.slice(8)} ${esc(bulan(REPORT.period))}</span><em>vs</em><span class="v6c b"><i>LMTD</i> 1–${+REPORT.previousCutoff.slice(8)} ${esc(bulan(REPORT.previousPeriod))}</span></span>`;}
function compareLabel(){return REPORT.coverage.closed?`${bulan(REPORT.period)} vs ${bulan(REPORT.previousPeriod)} · bulan penuh`:`1–${+REPORT.coverage.cutoff.slice(8)} ${bulan(REPORT.period)} vs 1–${+REPORT.previousCutoff.slice(8)} ${bulan(REPORT.previousPeriod)}`;}
function customerButton(c){return `<button class="textlink" data-customer="${esc(c.id)}">${esc(c.nama)}</button>${v6TutupTag(c.id)}<small class="cellsub">${esc(c.id)} · ${esc(c.kota||'—')}</small>`;}
function canExport(type){return !!BOOT?.exportAccess?.[type];}
function canExportSummary(){return canExport('SUMMARY');}
function canExportDealer(){return canExport('DEALER');}
function canExportKPI(){return canExport('KPI');}
function canExportBrand(){return canExport('BRAND');}
function bind(){document.querySelectorAll('[data-rank-person]').forEach(b=>b.onclick=()=>rankPerson(b.dataset.rankPerson));document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>navigateTo(b.dataset.jump));document.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>detail(b.dataset.customer));document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>person(b.dataset.person));}
async function render(){if(!REPORT)return;v6ExecFab();closeMobileMore();syncMobileNav();$('periodSelect').disabled=PAGE==='informasi'||PAGE==='perangkat'||PAGE==='panduan';$('scopeSelect').disabled=PAGE==='informasi'||PAGE==='perangkat'||PAGE==='panduan'||['SALES','TELEMARKETING'].includes(BOOT.user.role);const seq=++SEQUENCE,token=TOKEN;$('error').hidden=true;document.querySelectorAll('#navigation button').forEach(b=>b.classList.toggle('on',b.dataset.page===PAGE));$('main').innerHTML=`<h2 class="ptitle">${titles[PAGE]}</h2><div class="psub">${['informasi','dos','ai','tim','perangkat','panduan'].includes(PAGE)?esc(PAGE==='panduan'?'Cara membaca setiap menu · sesuai jabatan Anda':PAGE==='informasi'?'Informasi sesuai hak akses · tidak mengikuti periode penjualan':PAGE==='dos'?'Estimasi stok suplai kita · monitoring di luar KPI':PAGE==='ai'?'AI read-only · jawaban mengikuti periode dan cakupan yang sedang dipilih':PAGE==='perangkat'?'Perangkat yang sedang masuk ke akun ini · maksimal 5 perangkat':PAGE==='tim'?'Pencapaian tim dan perbandingan periode · sesuai hak akses':compareLabel()):compareHtml()}</div><div id="view"></div>`;const view=$('view');if(REPORT.regionStatus?.length&&!['admin','perangkat','panduan'].includes(PAGE))view.insertAdjacentHTML('beforebegin',freshnessPanel());try{if(await tmRenderPage(view,seq)){if(token===TOKEN)bind();return;}if(REPORT.noData&&!['admin','informasi','customer','ai','perangkat','panduan'].includes(PAGE)){view.innerHTML='<div class="info">Belum ada data ST untuk cakupan dan periode ini. Admin dapat mengunggah data dari menu Admin.</div>';tmAttachTabs(view);return;}if(PAGE==='beranda')await v6ExecView(view,seq);else if(PAGE==='analisa')await v6AnalisaView(view,seq);else if(PAGE==='brand')await brands(view,seq);else if(PAGE==='tim')await team(view,seq);else if(PAGE==='customer'){customers(view);dealerHistoryPanel(view);}else if(PAGE==='kpi'){kpis(view);kpiOwnValidationPanel(view);kpiExportButton(view);}else if(PAGE==='transaksi')await transactions(view,seq);else if(PAGE==='peringkat')await ranks(view,seq);else if(PAGE==='admin')await admin(view,seq);else if(PAGE==='informasi')await information(view,seq);else if(PAGE==='panduan')await window.panduanView(view);else if(PAGE==='dos')await dosView(view,seq);else if(PAGE==='ai')await aiView(view,seq);else if(PAGE==='perangkat')await perangkatView(view,seq);if(token===TOKEN){tmAttachTabs(view);bind();}}catch(e){if(seq===SEQUENCE)fail(e,()=>navigateTo(PAGE));}}

function sortedUnique(values){return [...new Set((values||[]).map(v=>String(v||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'id'));}
function dealerOwnersForBrand(c,brand){
 const fallback={nik:c.nik||'',nama:c.sales||'',bigRegion:c.bigRegion||'',subRegion:c.subRegion||c.region||'',asm:c.asm||'',source:'MASTER_CUSTOMER'};
 const m=c.brandOwners||{};
 if(brand&&brand!=='ALL')return [m[brand]||fallback];
 const brands=(REPORT?.deviceBrands||[]).length?REPORT.deviceBrands:(c.brands||[]).map(x=>x.brand);const seen=new Set(),out=[];
 (brands.length?brands:['ALL']).forEach(b=>{const o=b==='ALL'?fallback:(m[b]||fallback),k=[o.nik,o.bigRegion,o.subRegion].join('|');if(!seen.has(k)){seen.add(k);out.push(o);}});return out.length?out:[fallback];
}
function dealerOwnerValues(c,brand,key){return sortedUnique(dealerOwnersForBrand(c,brand).map(o=>o?.[key]||''));}
function dealerOwnerText(c,brand,key,fallback='—'){const a=dealerOwnerValues(c,brand,key);return a.length?a.join(' / '):fallback;}
function dealerOwnerMatch(c,brand,region,sub){return dealerOwnersForBrand(c,brand).some(o=>(!region||region==='ALL'||o.bigRegion===region)&&(!sub||sub==='ALL'||o.subRegion===sub));}
function dealerRegions(customers,brand='ALL'){return sortedUnique(customers.flatMap(c=>dealerOwnersForBrand(c,brand).map(o=>o.bigRegion||'')));}
function dealerSubRegions(customers,region,brand='ALL'){return sortedUnique(customers.flatMap(c=>dealerOwnersForBrand(c,brand).filter(o=>!region||region==='ALL'||o.bigRegion===region).map(o=>o.subRegion||'')));}
function filterOptions(values,current,allLabel){return `<option value="ALL">${esc(allLabel)}</option>`+values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('');}
function filterSummaryHtml(items,count,label='hasil'){const active=items.filter(x=>x&&x[1]&&x[1]!=='ALL'&&x[1]!=='');return `<div class="filterSummaryMain">${active.length?active.map(x=>`<span class="filterPill"><b>${esc(x[0])}</b>${esc(x[1])}</span>`).join(''):'<span class="filterPill muted">Tanpa filter khusus</span>'}</div>${count==null?'':`<strong class="filterResultCount">${num(count)} ${esc(label)}</strong>`}`;}
function customers(v){
 const cs=REPORT.customers,statuses=['AKTIF','BELUM MINIMUM DA','DA BULAN LALU','IDLE','PASIF','NOO','BELUM ORDER','TUTUP'],count=s=>cs.filter(c=>c.status===s).length,regions=dealerRegions(cs,customerFilter.brand);
 if(customerFilter.region!=='ALL'&&!regions.includes(customerFilter.region)){customerFilter.region='ALL';customerFilter.subRegion='ALL';}
 let subRegions=dealerSubRegions(cs,customerFilter.region,customerFilter.brand);if(customerFilter.subRegion!=='ALL'&&!subRegions.includes(customerFilter.subRegion))customerFilter.subRegion='ALL';
 v.innerHTML=cards([['Aktif',num(count('AKTIF')),'Minimal 2 unit bulan ini'],['DA Bulan Lalu',num(count('DA BULAN LALU')),'Order bulan lalu, belum order bulan ini'],['Idle',num(count('IDLE')),'Terakhir order dua bulan lalu'],['Pasif',num(count('PASIF')),'Tiga bulan tanpa order'],['NOO per brand',num(REPORT.total.noo),'Bukan sekadar outlet baru terdaftar'],['SELL OUT',soNum(REPORT.total.sellout),soNote()]])+(REPORT.v6tutupNow?`<div class="v6tnote">🚫 <b>${num(REPORT.v6tutupNow)} dealer tutup</b> bulan ini · tidak dihitung Idle / Pasif / Belum order. Centang status TUTUP di filter Daftar dealer untuk melihatnya.</div>`:'')+('');
