function pageSizeOptions(size){return [10,50,100,200].map(n=>`<option value="${n}" ${n===size?'selected':''}>${n}</option>`).join('');}
function pager(p,total,size,fixedSize=false,opts=null){return `<div class="pager">${fixedSize?`<span>Maks. ${size} dealer per halaman</span>`:`<label>Tampilkan <select id="pageSizeSelect" aria-label="Jumlah data per halaman">${opts?opts.map(n=>`<option value="${n}" ${n===size?'selected':''}>${n}</option>`).join(''):pageSizeOptions(size)}</select></label>`}<span>${total?p*size+1:0}–${Math.min((p+1)*size,total)} dari ${num(total)}</span><button class="chip" id="prevPage" ${p===0?'disabled':''}>Sebelumnya</button><button class="chip" id="nextPage" ${(p+1)*size>=total?'disabled':''}>Berikutnya</button></div>`;}
function bindPager(prev,next,resize){$('prevPage').onclick=prev;$('nextPage').onclick=next;if($('pageSizeSelect')&&resize)$('pageSizeSelect').onchange=e=>resize(Number(e.target.value));}
function contactLinks(hp){const raw=String(hp||'').trim();if(!raw)return '<p class="hint">Nomor kontak belum tersedia.</p>';let n=raw.replace(/[\s()+.-]/g,'');if(!/^\d{8,15}$/.test(n))return '<p>Kontak: '+esc(raw)+'</p>';if(n.startsWith('0'))n='62'+n.slice(1);else if(n.startsWith('8'))n='62'+n;return '<div class="toolbar contactLinks"><a class="chip contactPhone" href="tel:+'+n+'">Telepon '+esc(raw)+'</a><a class="chip primary contactWhatsApp" href="https:&#47;&#47;wa.me/'+n+'" target="_blank" rel="noopener noreferrer">☏ Hubungi via WhatsApp</a></div>';}
function kpiHtml(k,limited=false){return kpiGridHtml(k,{limited,title:'KPI AKHIR'});}
function fullRankKpiDetailAccess(){
 return ['ADMIN','SUPER ADMIN','HEAD OF SALES','CHIEF OPERATING OFFICER','CHIEF COMMERCIAL OFFICER','BOARD OF DIRECTOR'].includes(BOOT?.user?.role);
