 v.innerHTML=exportBar+(REPORT.regionalKpi.map(k=>'<section class="kpiRegion" style="--region-color:'+kpiRegionColor(k.region)+'">'+panel(esc(k.region),kpiHtml(k),'Target bulan penuh · SALES')+'</section>').join('')||'<div class="empty">Tidak ada wilayah KPI dalam pilihan.</div>');
 const admin=['ADMIN','SUPER ADMIN'].includes(BOOT.user.role),chosen=BOOT.people.find(p=>p.nik===$('scopeSelect').value);
 const top=['HEAD OF SALES','CHIEF OPERATING OFFICER','CHIEF COMMERCIAL OFFICER','BOARD OF DIRECTOR'].includes(BOOT.user.role);
 if(!top&&!admin&&!['ASM','RGM','SALES'].includes(BOOT.user.role)){if($('kpiExportBtn'))$('kpiExportBtn').onclick=openKPIExport;return;}
 v.innerHTML=exportBar;if($('kpiExportBtn'))$('kpiExportBtn').onclick=openKPIExport;
