 v.insertAdjacentHTML('beforeend',`<details class="panel foldPanel" id="teamKpiPanel"><summary>Rincian KPI ${top?'ASM per Region Induk':'Tim · RGM / ASM / Sales'}<small>Klik untuk membuka rincian target dan aktual</small></summary><div class="pb" id="teamKpiBody"></div></details>`);
 v6RgmKpiPanel(v);
 const fold=$('teamKpiPanel'),body=$('teamKpiBody'),token=TOKEN,period=REPORT.period,selection=$('scopeSelect').value;let loaded=false,loading=false;
 fold.ontoggle=async()=>{if(!fold.open||loaded||loading)return;loading=true;body.innerHTML='<div class="empty v6load">Memuat rincian KPI tim…</div>';try{
