 if(selection==='ALL'&&['ASM','RGM'].includes(BOOT.user.role)){
  const peers=BOOT.people.filter(p=>p.role===BOOT.user.role&&p.nik!==BOOT.user.nik);
  if(peers.length){
   const peerResults=await Promise.allSettled(peers.map(p=>rpc('apiKpiTree',token,period,p.nik)));
   if(token!==TOKEN||!body.isConnected)return;
   const existing=new Set(flattenKpiTree(rows).filter(p=>p.role===BOOT.user.role).map(p=>p.nik));
   peerResults.forEach((result,index)=>{if(result.status!=='fulfilled')return;const flat=flattenKpiTree(result.value),peer=flat.find(p=>p.role===BOOT.user.role&&p.nik===peers[index].nik)||flat.find(p=>p.role===BOOT.user.role);if(peer&&!existing.has(peer.nik)){rows.push({...peer,children:[]});existing.add(peer.nik);}});
  }
 }
 const draw=p=>`<details class="kgroup kpiTreeNode level-${p.role==='RGM'?'rgm':p.role==='ASM'?'asm':'sales'}"><summary><span class="kpiLevel">${esc(p.role)}</span> ${esc(p.nama)}${p.acting?' · Portofolio rangkap':''} <b>${p.noData?'—':pct(p.kpi.score)}</b><small class="cellsub">${esc(p.area||'')} · ${p.partial?'Data sementara · ':''}ST s.d. ${esc(p.cutoff||'belum tersedia')}</small></summary><div class="kpiTreeContent">${p.noData?'<div class="empty">Data ST belum tersedia.</div>':kpiHtml(p.kpi)}${p.children?.length?'<h4>Rincian KPI Tim</h4>'+p.children.map(draw).join(''):''}</div></details>`;
 const canBigRegion=top||admin,regionValues=[...new Set(regionKpis.map(k=>k.region).concat(rows.map(p=>p.region)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'id'));
 const regionFilter=canBigRegion?`<div class="toolbar kpiRegionFilter"><label>Big Region<select class="fi hl" id="kpiBigRegionFilter"><option value="ALL">Semua Big Region</option>${regionValues.map(r=>`<option value="${esc(r)}" ${r===kpiBigRegion?'selected':''}>${esc(r)}</option>`).join('')}</select></label></div>`:'';
 body.innerHTML=regionFilter+'<div id="kpiTreeRender"></div>';
 const drawKpiTree=()=>{const selected=canBigRegion?kpiBigRegion:'ALL',scopedRows=selected==='ALL'?rows:rows.filter(p=>p.region===selected);$('kpiTreeRender').innerHTML=isMobile()?mobileKpiComparison(scopedRows):desktopKpiComparison(scopedRows);bindCollapses($('kpiTreeRender'));addTopTableScroll($('kpiTreeRender'));};
 if(canBigRegion){$('kpiBigRegionFilter').onchange=e=>{kpiBigRegion=e.target.value;drawKpiTree();};if(!regionValues.includes(kpiBigRegion))kpiBigRegion='ALL';}
 drawKpiTree();loaded=true;
 }catch(e){if(body.isConnected)body.textContent='Gagal memuat: '+e.message+'. Tutup lalu buka panel untuk mencoba lagi.';}finally{loading=false;}};
}
