async function person(nik){const token=TOKEN;try{const r=await rpc('apiPersonKpi',token,REPORT.period,nik);if(token!==TOKEN)return;modal('Rincian KPI',kpiHtml(r));}catch(e){if(token===TOKEN)fail(e);}}
function modal(title,html){lastFocus=document.activeElement;$('mtitle').textContent=title;$('mbody').innerHTML=html;if(!$('mask').classList.contains('on')){modalScroll=window.scrollY;try{history.pushState({portalModal:true},'');modalHistory=true;}catch(e){}}$('mask').classList.add('on');$('mask').querySelector('.x').focus();}
function closeModal(fromBack=false){$('mask').classList.remove('on');if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});window.scrollTo(0,modalScroll);lastFocus=null;if(modalHistory&&!fromBack){modalHistory=false;history.back();}else modalHistory=false;}
$('mask').onclick=e=>{if(e.target===$('mask'))closeModal();};document.onkeydown=e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('mask').classList.contains('on')){const els=[...$('mask').querySelectorAll('button,a,input,select,textarea')].filter(x=>!x.disabled),first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}};

async function openKPIExport(){
