 try{
  let opt=await rpc('apiKPIExportOptions',TOKEN,REPORT.period);if(!$('mask').classList.contains('on'))return;
  const form=()=>{const periods=(opt.periods||[]).length?opt.periods:[REPORT.period],period=opt.period||REPORT.period,rank=opt.ranking?`<label>Dasar Ranking Nasional<select class="fi hl" id="kpiExportRank"><option value="">Pilih kelompok KPI…</option>${(opt.groups||[]).map(g=>`<option value="${esc(g)}">${esc(g)}</option>`).join('')}<option value="FINAL">KPI Akhir</option></select></label>`:'';$('mbody').innerHTML=`<form id="kpiExportForm"><div class="userForm"><label>Periode KPI<select class="fi hl" id="kpiExportPeriod">${periods.map(p=>`<option value="${esc(p)}" ${p===period?'selected':''}>${esc(bulan(p))}</option>`).join('')}</select></label>${rank}</div><p class="hint">${opt.rankingOnly?'Top Tier: export hanya Ranking Sales & Ranking ASM nasional.':'ASM: detail KPI Sales area sendiri. RGM: detail KPI Sales + ASM area sendiri. Admin: detail sesuai region akses. Super Admin: detail semua Big Region. RGM/Admin/Super Admin juga mendapat Ranking Sales & Ranking ASM nasional.'}</p><p id="kpiExportStatus" role="status"></p><button class="chip ioAction" id="kpiExportRun">Export Excel KPI</button></form>`;const ps=$('kpiExportPeriod');ps.onchange=async()=>{const status=$('kpiExportStatus');status.textContent='Memuat konfigurasi KPI periode…';try{opt=await rpc('apiKPIExportOptions',TOKEN,ps.value);form();}catch(err){status.textContent=err.message;}};$('kpiExportForm').onsubmit=async e=>{e.preventDefault();const btn=$('kpiExportRun'),status=$('kpiExportStatus'),period=$('kpiExportPeriod').value,rankEl=$('kpiExportRank'),rankGroup=rankEl?rankEl.value:'FINAL';if(opt.ranking&&!rankGroup){status.textContent='Pilih kelompok KPI atau KPI Akhir sebagai dasar ranking.';return;}btn.disabled=true;status.textContent='Menyiapkan workbook KPI…';try{const data=await rpc('apiKPIExportData',TOKEN,period,{rankGroup});downloadKPIReportXlsx(data);status.textContent='Export KPI siap.';}catch(err){status.textContent=err.message;}finally{btn.disabled=false;}};};form();
 }catch(err){$('mbody').innerHTML='<p>'+esc(err.message)+'</p>';}
}
function downloadKPIReportXlsx(data){
 const xml=v=>String(v??'').replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'),
  col=n=>{let s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26);}return s;},
  cell=(ref,v,style)=>v===null||v===undefined||v===''?`<c r="${ref}" s="${style}"/>`:typeof v==='number'&&Number.isFinite(v)?`<c r="${ref}" s="${style}"><v>${v}</v></c>`:`<c r="${ref}" s="${style}" t="inlineStr"><is><t xml:space="preserve">${xml(v)}</t></is></c>`,
  fullDate=d=>d?new Date(d+'T00:00:00Z').toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}):'belum tersedia',
  safeName=(name,used)=>{let n=String(name||'SHEET').replace(/[\\\/?*\[\]:]/g,' ').trim().slice(0,31)||'SHEET',base=n,i=2;while(used.has(n))n=(base.slice(0,27)+' '+i++).slice(0,31);used.add(n);return n;},
  frac=v=>v==null?null:Number(v)/100,
