  groupShort=name=>String(name||'').trim().toUpperCase();

 const styles=`<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts count="2"><numFmt numFmtId="164" formatCode="#,##0"/><numFmt numFmtId="165" formatCode="0.0%"/></numFmts><fonts count="10"><font><sz val="11"/><name val="Calibri"/><family val="2"/></font><font><b/><sz val="11"/><name val="Calibri"/><family val="2"/></font><font><b/><sz val="14"/><name val="Calibri"/><family val="2"/></font><font><b/><sz val="10"/><name val="Calibri"/><family val="2"/></font><font><i/><sz val="10"/><name val="Calibri"/><family val="2"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Calibri"/><family val="2"/></font><font><b/><color rgb="FFC00000"/><sz val="11"/><name val="Calibri"/><family val="2"/></font><font><color rgb="FFC00000"/><sz val="11"/><name val="Calibri"/><family val="2"/></font><font><color rgb="FF008000"/><sz val="11"/><name val="Calibri"/><family val="2"/></font><font><b/><color rgb="FF008000"/><sz val="11"/><name val="Calibri"/><family val="2"/></font></fonts><fills count="17"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFFFFF00"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FF92D050"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FF83C9E5"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFC9B2D9"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFC6E0F5"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFC6E0B4"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFF8CBAD"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFF4CCCC"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FF1F4E78"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFE4A3D7"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFC6E0B4"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFF4B183"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FF5B9BD5"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFFFE699"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFF2F2F2"/></patternFill></fill></fills><borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border><border><left style="thin"><color rgb="FFB7B7B7"/></left><right style="thin"><color rgb="FFB7B7B7"/></right><top style="thin"><color rgb="FFB7B7B7"/></top><bottom style="thin"><color rgb="FFB7B7B7"/></bottom><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="41"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="2" fillId="0" borderId="0" xfId="0" applyFont="1"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/><xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="centerContinuous" vertical="center"/></xf><xf numFmtId="0" fontId="1" fillId="3" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="centerContinuous" vertical="center"/></xf><xf numFmtId="0" fontId="1" fillId="4" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="centerContinuous" vertical="center"/></xf><xf numFmtId="0" fontId="1" fillId="5" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="centerContinuous" vertical="center"/></xf><xf numFmtId="0" fontId="5" fillId="4" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="0" fontId="1" fillId="6" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1"/><xf numFmtId="164" fontId="0" fillId="8" borderId="1" xfId="0" applyNumberFormat="1" applyFill="1" applyBorder="1"/><xf numFmtId="165" fontId="0" fillId="6" borderId="1" xfId="0" applyNumberFormat="1" applyFill="1" applyBorder="1"/><xf numFmtId="165" fontId="1" fillId="7" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="165" fontId="0" fillId="7" borderId="1" xfId="0" applyNumberFormat="1" applyFill="1" applyBorder="1"/><xf numFmtId="165" fontId="1" fillId="2" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="0" fontId="1" fillId="11" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="centerContinuous" vertical="center"/></xf><xf numFmtId="0" fontId="5" fillId="14" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="164" fontId="5" fillId="14" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="165" fontId="5" fillId="14" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="centerContinuous" vertical="center"/></xf><xf numFmtId="0" fontId="5" fillId="10" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="165" fontId="6" fillId="9" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="165" fontId="1" fillId="2" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="165" fontId="5" fillId="10" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="165" fontId="1" fillId="2" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="0" fontId="1" fillId="4" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1"/><xf numFmtId="165" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1"/><xf numFmtId="0" fontId="1" fillId="12" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="165" fontId="1" fillId="12" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="0" fontId="1" fillId="13" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="165" fontId="1" fillId="13" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="0" fontId="4" fillId="0" borderId="0" xfId="0" applyFont="1"/><xf numFmtId="0" fontId="3" fillId="0" borderId="0" xfId="0" applyFont="1"/><xf numFmtId="165" fontId="1" fillId="7" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="0" fontId="1" fillId="7" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="165" fontId="7" fillId="6" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="165" fontId="8" fillId="6" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="165" fontId="1" fillId="2" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles><dxfs count="0"/><tableStyles count="0" defaultTableStyle="TableStyleMedium2" defaultPivotStyle="PivotStyleLight16"/></styleSheet>`;

 const groupStyles=[3,4,5,6],achStyle=v=>v==null?11:v>=100?38:37;
 const used=new Set(),defs=[];
 const buildLayout=groups=>{let c=6;const gs=groups.map((g,gi)=>{const start=c,inds=(g.indicators||[]).map(ind=>{const x={start:c,target:c,actual:c+1,ach:c+2,weighted:c+3,sep:c+4,def:ind};c+=5;return x;}),total=c++;const end=total,sep=c++;return {name:g.name,start,end,sep,total,inds,index:gi};});const finalStart=c,finalCols=groups.map(()=>c++),final=c++,last=c-1;return {groups:gs,finalStart,finalCols,final,last};};

 const detailSheet=sheet=>{
  const layout=buildLayout(sheet.groups||[]),r=[],cols=[`<col min="1" max="1" width="2.5" customWidth="1"/>`,`<col min="2" max="2" width="28" customWidth="1"/>`,`<col min="3" max="3" width="26" customWidth="1"/>`,`<col min="4" max="4" width="18" customWidth="1"/>`,`<col min="5" max="5" width="2.5" customWidth="1"/>`];
  layout.groups.forEach(g=>{g.inds.forEach(i=>{cols.push(`<col min="${i.target}" max="${i.actual}" width="10" customWidth="1"/>`,`<col min="${i.ach}" max="${i.ach}" width="9" customWidth="1"/>`,`<col min="${i.weighted}" max="${i.weighted}" width="11.5" customWidth="1"/>`,`<col min="${i.sep}" max="${i.sep}" width="1.8" customWidth="1"/>`);});cols.push(`<col min="${g.total}" max="${g.total}" width="12" customWidth="1"/>`,`<col min="${g.sep}" max="${g.sep}" width="2.5" customWidth="1"/>`);});
  for(let c=layout.finalStart;c<=layout.final;c++)cols.push(`<col min="${c}" max="${c}" width="14" customWidth="1"/>`);
  const groupAt=(row,name)=>row?.kpi?.groups?.find(g=>g.name===name);
  const section=(title,personHead,bossHead,rows,total,start)=>{
   r.push(`<row r="${start}" ht="19">${cell('B'+start,title,1)}</row>`,`<row r="${start+1}">${cell('B'+(start+1),'PERIODE : '+fullDate(sheet.cutoff),2)}</row>`);
   let top='';
   layout.groups.forEach(g=>{for(let c=g.start;c<=g.end;c++)top+=cell(col(c)+(start+2),c===g.start?groupLabel(g.name,g.index):'',groupStyles[g.index%groupStyles.length]);});
   for(let c=layout.finalStart;c<=layout.final;c++)top+=cell(col(c)+(start+2),c===layout.finalStart?'KPI AKHIR':'',19);
   r.push(`<row r="${start+2}" ht="18">${top}</row>`,`<row r="${start+3}" ht="5"></row>`);

   let names=cell('B'+(start+4),personHead,7)+cell('C'+(start+4),bossHead,7)+cell('D'+(start+4),'SUB REGION',7);
   layout.groups.forEach(g=>{g.inds.forEach(ind=>{for(let q=0;q<3;q++)names+=cell(col(ind.start+q)+(start+4),q===0?(ind.def.label||ind.def.metric+' '+ind.def.brand):'',15);names+=cell(col(ind.weighted)+(start+4),Number(ind.def.weight||0)/100,12);});names+=cell(col(g.total)+(start+4),'100%',35);});
   (sheet.groups||[]).forEach((g,i)=>names+=cell(col(layout.finalCols[i])+(start+4),groupShort(g.name),20));
   names+=cell(col(layout.final)+(start+4),'KPI AKHIR',40);
   r.push(`<row r="${start+4}" ht="18">${names}</row>`);

   let subs='';['B','C','D'].forEach(c=>subs+=cell(c+(start+5),'',7));
   layout.groups.forEach((g,gi)=>{g.inds.forEach(ind=>{subs+=cell(col(ind.target)+(start+5),'TARGET',8)+cell(col(ind.actual)+(start+5),'ACTUAL',8)+cell(col(ind.ach)+(start+5),'%',8)+cell(col(ind.weighted)+(start+5),'BOBOT KPI',36);});subs+=cell(col(g.total)+(start+5),'TOTAL KPI '+(gi+1),35);});
   (sheet.groups||[]).forEach((g,i)=>subs+=cell(col(layout.finalCols[i])+(start+5),'%',20));
   subs+=cell(col(layout.final)+(start+5),'KPI AKHIR',40);
   r.push(`<row r="${start+5}" ht="18">${subs}</row>`);

   const body=start+6;
   rows.forEach((row,i)=>{const rr=body+i;let z=cell('B'+rr,row.nama,9)+cell('C'+rr,row.atasan||'—',9)+cell('D'+rr,row.subRegion||'—',9);layout.groups.forEach(g=>{const kg=groupAt(row,g.name);g.inds.forEach((ind,j)=>{const x=kg?.indicators?.[j];z+=cell(col(ind.target)+rr,x?.target,10)+cell(col(ind.actual)+rr,x?.actual,10)+cell(col(ind.ach)+rr,frac(x?.ach),achStyle(x?.ach))+cell(col(ind.weighted)+rr,weighted(x),13);});z+=cell(col(g.total)+rr,frac(kg?.score),14);});(sheet.groups||[]).forEach((g,j)=>z+=cell(col(layout.finalCols[j])+rr,frac(groupAt(row,g.name)?.score),21));z+=cell(col(layout.final)+rr,frac(row.kpi?.score),22);r.push(`<row r="${rr}">${z}</row>`);});

   const tr=body+rows.length;let z=cell('B'+tr,'TOTAL',16)+cell('C'+tr,'',16)+cell('D'+tr,'',16);
   layout.groups.forEach(g=>{const kg=groupAt({kpi:total},g.name);g.inds.forEach((ind,j)=>{const x=kg?.indicators?.[j];z+=cell(col(ind.target)+tr,x?.target,17)+cell(col(ind.actual)+tr,x?.actual,17)+cell(col(ind.ach)+tr,frac(x?.ach),18)+cell(col(ind.weighted)+tr,weighted(x),34);});z+=cell(col(g.total)+tr,frac(kg?.score),39);});
   (sheet.groups||[]).forEach((g,j)=>z+=cell(col(layout.finalCols[j])+tr,frac(groupAt({kpi:total},g.name)?.score),23));
   z+=cell(col(layout.final)+tr,frac(total?.score),24);r.push(`<row r="${tr}" ht="18">${z}</row>`);return tr;
  };
  let end=section('Pencapaian KPI Sales '+(sheet.scopeLabel||sheet.region),'SALES','ASM',sheet.salesRows||[],sheet.salesTotal,3);
  if((sheet.asmRows||[]).length)end=section('Pencapaian KPI ASM '+sheet.region,'ASM','RGM',sheet.asmRows,sheet.asmTotal,end+3);
  return `<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView showGridLines="0" zoomScale="70" zoomScaleNormal="70" workbookViewId="0"><pane xSplit="5" ySplit="8" topLeftCell="F9" activePane="bottomRight" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="15"/><cols>${cols.join('')}</cols><sheetData>${r.join('')}</sheetData><pageMargins left="0.25" right="0.25" top="0.4" bottom="0.4" header="0.2" footer="0.2"/><pageSetup orientation="landscape" fitToWidth="1" fitToHeight="0"/></worksheet>`;
 };

 const rankingSheet=(title,pack,level)=>{
  const rows=pack?.rows||[],groups=data.groupNames||[],last=7+groups.length,r=[],cols=[`<col min="1" max="1" width="2.5" customWidth="1"/>`,`<col min="2" max="2" width="8" customWidth="1"/>`,`<col min="3" max="3" width="30" customWidth="1"/>`,`<col min="4" max="4" width="18" customWidth="1"/>`,`<col min="5" max="5" width="18" customWidth="1"/>`,`<col min="6" max="6" width="26" customWidth="1"/>`];
  for(let c=7;c<=last;c++)cols.push(`<col min="${c}" max="${c}" width="14" customWidth="1"/>`);
  r.push(`<row r="2">${cell('B2',title,1)}</row>`,`<row r="3">${cell('B3','PERIODE : '+fullDate(pack?.cutoff),2)}</row>`,`<row r="4">${cell('B4','RANKING BERDASARKAN : '+(data.rankGroup==='FINAL'?'KPI AKHIR':data.rankGroup),33)}</row>`);
  const heads=['RANK','NAMA '+level,'REGION','SUB REGION','ATASAN',...groups.map(g=>'% '+g),'% KPI AKHIR'];let h='';heads.forEach((x,i)=>h+=cell(col(i+2)+'6',x,25));r.push(`<row r="6" ht="18">${h}</row>`);
  rows.forEach((x,i)=>{const rr=7+i,txt=x.highlight==='TOP'?28:x.highlight==='BOTTOM'?30:26,pctStyle=x.highlight==='TOP'?29:x.highlight==='BOTTOM'?31:27;let z=cell('B'+rr,x.rank??'',txt)+cell('C'+rr,x.nama,txt)+cell('D'+rr,x.region,txt)+cell('E'+rr,x.subRegion,txt)+cell('F'+rr,x.atasan||'—',txt);(x.groupScores||[]).forEach((v,j)=>z+=cell(col(7+j)+rr,frac(v),pctStyle));z+=cell(col(last)+rr,frac(x.final),pctStyle);r.push(`<row r="${rr}">${z}</row>`);});
  const end=Math.max(7,6+rows.length);
  return `<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView showGridLines="0" zoomScale="85" zoomScaleNormal="85" workbookViewId="0"><pane ySplit="6" topLeftCell="A7" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="15"/><cols>${cols.join('')}</cols><sheetData>${r.join('')}</sheetData><autoFilter ref="B6:${col(last)}${end}"/><pageMargins left="0.3" right="0.3" top="0.5" bottom="0.5" header="0.2" footer="0.2"/><pageSetup orientation="landscape" fitToWidth="1" fitToHeight="0"/></worksheet>`;
 };

 if(data.ranking){defs.push({name:safeName('RANKING SALES',used),xml:rankingSheet('Peringkat Nasional Sales',data.rankingSales,'SALES')},{name:safeName('RANKING ASM',used),xml:rankingSheet('Peringkat Nasional ASM',data.rankingAsm,'ASM')});}
 (data.sheets||[]).forEach(sheet=>defs.push({name:safeName(sheet.region,used),xml:detailSheet(sheet)}));
 xlsxZipDownload_(data.name||'KPI-Report.xlsx',defs.map(x=>x.name),defs.map(x=>x.xml),styles);
}

async function openBrandExport(){
 modal('Export Brand','<p role="status">Menyiapkan pilihan export…</p>');
 try{
  const opt=await rpc('apiBrandExportOptions',TOKEN);if(!$('mask').classList.contains('on'))return;
  const brandBoxes=opt.brands.map(b=>`<label><input type="checkbox" name="brandExportBrand" value="${esc(b)}" checked> <span>${esc(b)}</span></label>`).join('');
  $('mbody').innerHTML=`<form id="brandExportForm"><div class="userForm"><label>Tampilan berdasarkan<select class="fi hl" id="brandExportLevel"><option value="BIG">Big Region</option><option value="SUB">Sub Region</option></select></label></div><fieldset><legend>Cakupan region</legend><div id="brandExportScope"></div></fieldset><fieldset><legend>Brand yang diexport</legend><label class="confirm"><input type="checkbox" id="brandExportAll" checked> Pilih semua brand</label><div class="regionChecks" id="brandExportBrands">${brandBoxes}</div></fieldset><fieldset><legend>Isi export</legend><div class="regionChecks"><label><input type="checkbox" id="brandExportSummary" checked> <span>Summary Brand</span></label><label><input type="checkbox" id="brandExportType" checked> <span>Per Type · ST/SO by week</span></label></div></fieldset><p class="hint">Satu brand dapat menghasilkan 2 sheet: BRAND - SUMMARY dan BRAND - TYPE. Filter wilayah dan periode dipakai bersama.</p><p id="brandExportStatus" role="status"></p><button class="chip ioAction" id="brandExportRun">Export Excel</button></form>`;
  const level=$('brandExportLevel'),scope=$('brandExportScope'),drawScope=()=>{if(level.value==='BIG'){scope.innerHTML=`<label class="confirm"><input type="checkbox" id="brandBigAll" checked> Pilih semua Big Region</label><div class="regionChecks">${opt.bigRegions.map(r=>`<label><input type="checkbox" name="brandBig" value="${esc(r)}" checked> <span>${esc(r)}</span></label>`).join('')}</div>`;$('brandBigAll').onchange=e=>scope.querySelectorAll('[name=brandBig]').forEach(x=>x.checked=e.target.checked);scope.querySelectorAll('[name=brandBig]').forEach(x=>x.onchange=()=>{$('brandBigAll').checked=[...scope.querySelectorAll('[name=brandBig]')].every(y=>y.checked);});}else{const parents=opt.subParents||[];scope.innerHTML=`<label>Big Region induk<select class="fi hl" id="brandParentBig">${parents.map(r=>`<option value="${esc(r)}" ${r===opt.defaultBig?'selected':''}>${esc(r)}</option>`).join('')}</select></label><div id="brandSubList"></div>`;const drawSubs=()=>{const p=$('brandParentBig').value,subs=opt.subRegions[p]||[];$('brandSubList').innerHTML=`<label class="confirm"><input type="checkbox" id="brandSubAll" checked> Pilih semua Sub Region</label><div class="regionChecks">${subs.map(r=>`<label><input type="checkbox" name="brandSub" value="${esc(r)}" checked> <span>${esc(r)}</span></label>`).join('')}</div>`;$('brandSubAll').onchange=e=>$('brandSubList').querySelectorAll('[name=brandSub]').forEach(x=>x.checked=e.target.checked);$('brandSubList').querySelectorAll('[name=brandSub]').forEach(x=>x.onchange=()=>{$('brandSubAll').checked=[...$('brandSubList').querySelectorAll('[name=brandSub]')].every(y=>y.checked);});};$('brandParentBig').onchange=drawSubs;drawSubs();}};
  level.onchange=drawScope;drawScope();$('brandExportAll').onchange=e=>$('brandExportBrands').querySelectorAll('[name=brandExportBrand]').forEach(x=>x.checked=e.target.checked);$('brandExportBrands').querySelectorAll('[name=brandExportBrand]').forEach(x=>x.onchange=()=>{$('brandExportAll').checked=[...$('brandExportBrands').querySelectorAll('[name=brandExportBrand]')].every(y=>y.checked);});
  $('brandExportForm').onsubmit=async e=>{e.preventDefault();const btn=$('brandExportRun'),status=$('brandExportStatus'),brands=[...$('brandExportBrands').querySelectorAll('[name=brandExportBrand]:checked')].map(x=>x.value),includeSummary=$('brandExportSummary').checked,includeType=$('brandExportType').checked;if(!brands.length){status.textContent='Pilih minimal satu brand.';return;}if(!includeSummary&&!includeType){status.textContent='Pilih Summary Brand dan/atau Per Type.';return;}const selection={level:level.value,brands,includeSummary,includeType};if(level.value==='BIG'){selection.bigRegions=[...scope.querySelectorAll('[name=brandBig]:checked')].map(x=>x.value);if(!selection.bigRegions.length){status.textContent='Pilih minimal satu Big Region.';return;}}else{selection.parentBig=$('brandParentBig').value;selection.subRegions=[...scope.querySelectorAll('[name=brandSub]:checked')].map(x=>x.value);if(!selection.subRegions.length){status.textContent='Pilih minimal satu Sub Region.';return;}}btn.disabled=true;const sheetCount=brands.length*((includeSummary?1:0)+(includeType?1:0));status.textContent='Menyiapkan '+sheetCount+' sheet…';try{const data=await rpc('apiBrandExportData',TOKEN,REPORT.period,selection);downloadBrandReportXlsx(data);status.textContent='Export siap · '+sheetCount+' sheet.';}catch(err){status.textContent=err.message;}finally{btn.disabled=false;}};
 }catch(err){$('mbody').innerHTML='<p>'+esc(err.message)+'</p>';}
