function targetActual(t,a){return `<span class="targetActual"><span>${targetText(t)}</span><span class="taSlash"> / </span><b>${num(a)}</b></span>`;}
function groupedTable(leading,groups,rows){const count=leading.length+groups.reduce((n,g)=>n+g.cols.length,0),starts=[];let n=leading.length;groups.forEach(g=>{starts.push(n);n+=g.cols.length;});return `<div class="table-scroll"><table class="grouped"><thead><tr>${leading.map((h,i)=>`<th rowspan="2" class="lc lc${i}">${h}</th>`).join('')}${groups.map((g,i)=>`<th class="metricHead metric${i}" colspan="${g.cols.length}">${g.name}</th>`).join('')}</tr><tr>${groups.map(g=>g.cols.map((h,i)=>`<th class="${i===0?'groupStart':''}">${h}</th>`).join('')).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr class="${row[0]==='Total'?'totalRow':''}">${row.map((v,i)=>`<td class="${starts.includes(i)?'groupStart':''}${i<leading.length?' lc lc'+i:''}">${v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${count}" class="empty">Tidak ada data.</td></tr>`}</tbody></table></div>`;}
function addTopTableScroll(root=document){const wraps=[];if(root?.matches?.('.table-scroll'))wraps.push(root);root?.querySelectorAll?.('.table-scroll').forEach(x=>wraps.push(x));wraps.forEach(bottom=>{if(bottom.dataset.topScrollReady)return;bottom.dataset.topScrollReady='1';const top=document.createElement('div'),spacer=document.createElement('div');top.className='table-scroll-top';top.setAttribute('aria-label','Geser tabel secara horizontal dari atas');top.appendChild(spacer);bottom.before(top);let syncing=false;const size=()=>{if(!bottom.isConnected)return;spacer.style.width=bottom.scrollWidth+'px';top.hidden=bottom.scrollWidth<=bottom.clientWidth+1;top.scrollLeft=bottom.scrollLeft;};top.addEventListener('scroll',()=>{if(syncing)return;syncing=true;bottom.scrollLeft=top.scrollLeft;syncing=false;});bottom.addEventListener('scroll',()=>{if(syncing)return;syncing=true;top.scrollLeft=bottom.scrollLeft;syncing=false;});if(window.ResizeObserver){const observer=new ResizeObserver(size);observer.observe(bottom);const table=bottom.querySelector('table');if(table)observer.observe(table);}requestAnimationFrame(size);});}
function qtyTrend(r){
  const pts=r.trend,n=pts.length,w=Math.max(620,n*85+85),h=290,pad=48,bottom=235,top=35,qmax=Math.max(1,...pts.map(p=>p.qty)),qmin=Math.min(0,...pts.map(p=>p.qty)),yq=q=>bottom-(q-qmin)/(qmax-qmin)*(bottom-top),gvalues=pts.filter(p=>p.growth!=null).map(p=>p.growth),gmin=Math.min(-10,...gvalues),gmax=Math.max(10,...gvalues),yg=g=>bottom-(g-gmin)/(gmax-gmin)*(bottom-top),x=i=>pad+(i+.5)*(w-pad*2)/Math.max(n,1),zero=yq(0);
  let svg=`<svg viewBox="0 0 ${w} ${h}" style="min-width:620px;--chart-width:${w}px" role="img" aria-label="Tren unit device dan persentase growth bulanan">`;
  for(let i=0;i<4;i++){const q=qmin+(qmax-qmin)*i/3,y=yq(q),g=gmin+(gmax-gmin)*i/3;svg+=`<line x1="${pad}" y1="${y}" x2="${w-pad}" y2="${y}" stroke="#dce4ea"/><text x="${pad-7}" y="${y+4}" text-anchor="end" class="axisLabel">${num(q)}</text><text x="${w-pad+7}" y="${y+4}" class="axisLabel">${decimal(g)}%</text>`;}
  svg+=pts.map((p,i)=>{const y=yq(p.qty),selected=p.period===r.period;return `<g class="trendPoint" data-trend="${p.period}" role="button" tabindex="0" aria-label="${esc(bulan(p.period))}: ${num(p.qty)} unit" aria-pressed="${selected}"><title>${esc(bulan(p.period))} · ${num(p.qty)} unit · ${p.closed?'bulan penuh':'MTD s.d. '+tgl(p.cutoff)}</title><rect class="plotBar" x="${x(i)-20}" y="${Math.min(y,zero)}" width="40" height="${Math.max(2,Math.abs(zero-y))}" rx="3" fill="${selected?'#f0a400':'#10394e'}"/><text x="${x(i)}" y="${Math.min(y,zero)-7}" text-anchor="middle" class="qtyLabel">${num(p.qty)}</text><text x="${x(i)}" y="257" text-anchor="middle" class="monthLabel">${esc(new Date(p.period+'-01').toLocaleDateString('id-ID',{month:'short',timeZone:'Asia/Jakarta'}))} ${p.period.slice(2,4)}</text>${p.closed?'':`<text x="${x(i)}" y="273" text-anchor="middle" class="mtdLabel">MTD</text>`}</g>`;}).join('');
  // Disconnected segments leave gaps when the growth denominator is unavailable or zero.
  for(let i=1;i<n;i++)if(pts[i-1].growth!=null&&pts[i].growth!=null)svg+=`<line x1="${x(i-1)}" y1="${yg(pts[i-1].growth)}" x2="${x(i)}" y2="${yg(pts[i].growth)}" stroke="#d07345" stroke-width="2" stroke-dasharray="4 3" pointer-events="none"/>`;
  svg+=pts.map((p,i)=>p.growth==null?'':`<g pointer-events="none"><circle cx="${x(i)}" cy="${yg(p.growth)}" r="4" fill="#d07345" stroke="white"/><text class="growthLabel" x="${x(i)}" y="${yg(p.growth)+16}" text-anchor="middle">${p.growth>0?'+':''}${pct(p.growth)}</text></g>`).join('')+'</svg>';
  return `<div class="chartLegend"><span>Total SELLTHRU ${num(pts.reduce((n,p)=>n+p.qty,0))} unit (${pts.length} periode)</span><span><i></i> Unit device · sumbu kiri</span><span><i class="growthKey"></i> Growth · sumbu kanan</span></div><div class="qtyChartScroll">${svg}</div><div id="trendDetail" class="trendDetail" aria-live="polite"></div>`;
}
function selectTrend(period){const p=(PAGE==='brand'?REPORT.brandHistory?.[brandChoice]||[]:REPORT.trend).find(p=>p.period===period);if(!p)return;document.querySelectorAll('[data-trend]').forEach(el=>{const yes=el.dataset.trend===period;el.setAttribute('aria-pressed',String(yes));el.querySelector('rect').setAttribute('fill',yes?'#f0a400':'#10394e');});const growth=p.previousQty==null?'Pembanding belum lengkap':p.previousQty===0?'Growth — (basis pembanding 0)':`${p.growth>0?'+':''}${pct(p.growth)} · ${p.qty-p.previousQty>0?'+':''}${num(p.qty-p.previousQty)} unit`;$('trendDetail').innerHTML=`<b>${esc(bulan(period))}</b> · ${num(p.qty)} unit ${p.closed?'(bulan penuh)':'(MTD s.d. '+tgl(p.cutoff)+')'}<br>${growth} · vs ${p.closed?'LM':'LMTD'} ${esc(bulan(p.previousPeriod))}${p.closed?'':' tanggal 1–'+Number(p.previousCutoff.slice(8))}`;}
let v6MobSize=20;

/* ===== v6: proyeksi, time gone, dan butuh/hari (dihitung di tampilan dari data yang sudah ada) ===== */
function v6Pace(r){const cal=+PortalCore_end(r.period).slice(8),calRun=r.coverage.closed?cal:Math.min(cal,+r.coverage.cutoff.slice(8));let days=0,run=0;for(let i=1;i<=cal;i++){if(v6Off(r.period+'-'+String(i).padStart(2,'0')))continue;days++;if(i<=calRun)run++;}if(!days){days=cal;run=calRun;}return {days,run,left:days-run,tg:run/days*100,cal,calRun};}
function PortalCore_end(p){const d=new Date(+p.slice(0,4),+p.slice(5,7),0);return p+'-'+String(d.getDate()).padStart(2,'0');}
function v6Tone(p,tg){return p==null?'info':p>=tg?'good':p>=tg*0.7?'warn':'bad';}
function v6Color(p,tg){return {good:'var(--c6-green)',warn:'var(--c6-amber)',bad:'var(--c6-red)',info:'var(--c6-blue)'}[v6Tone(p,tg)];}
function v6Mini(p,tg){if(p==null)return '';return `<div class="v6mb"><i style="width:${Math.min(100,Math.max(0,p))}%;background:${v6Color(p,tg)}"></i><em style="left:${Math.min(100,tg)}%"></em></div>`;}
function v6TargetSum(list,key){const ts=list.map(b=>b[key]).filter(Boolean);return {value:ts.reduce((n,t)=>n+(t.value||0),0),complete:ts.some(t=>t.value>0)&&ts.filter(t=>t.value>0).every(t=>!(t.missing||[]).length)};}
function v6Totals(r){const q=v6TargetSum(r.brands,'target'),da=v6TargetSum(r.brands,'targetDA'),noo=v6TargetSum(r.brands,'targetNOO');return {q,da,noo};}
function v6Ring(p,label,sub,tg){const R=54,C=2*Math.PI*R,col=v6Color(p,tg);return `<div class="v6ring"><svg width="128" height="128" viewBox="0 0 128 128" aria-hidden="true"><circle cx="64" cy="64" r="${R}" fill="none" stroke="#EEF2F7" stroke-width="12"/>${p==null?'':`<circle cx="64" cy="64" r="${R}" fill="none" stroke="${col}" stroke-width="12" stroke-linecap="round" stroke-dasharray="${C*Math.min(p,100)/100} ${C}" transform="rotate(-90 64 64)"/>`}<line x1="64" y1="4" x2="64" y2="19" stroke="#0A2E57" stroke-width="2" transform="rotate(${tg*3.6} 64 64)"/></svg><div class="c"><div><b>${label}</b><small>${sub}</small></div></div></div>`;}
function v6Hero(r){
 const pc=v6Pace(r),T=v6Totals(r),t=r.total,k=r.kpi,hasT=T.q.value>0,ach=hasT?t.qty/T.q.value*100:null,rr=pc.run?t.qty/pc.run:0,proj=rr*pc.days,projP=hasT?proj/T.q.value*100:null,need=hasT&&pc.left>0?Math.max(0,T.q.value-t.qty)/pc.left:0;
 const scope=$('scopeSelect')?.selectedOptions?.[0]?.textContent||'',who=(r.v6Title?r.v6Title+' · ':'')+(BOOT.user.wilayah||'Nasional')+(scope?' · '+scope:'');
 const kScore=k&&k.score!=null?k.score:null,ringP=kScore!=null?kScore:ach,ringL=kScore!=null?pct(kScore):ach!=null?pct(ach):'—',ringS=kScore!=null?'Skor KPI':ach!=null?num(T.q.value)+' / '+num(t.qty):'Target belum ada';
 const today=(r.daily||[]).filter(d=>d.date===r.coverage.cutoff).reduce((a,d)=>a+(d.qty||0),0);
 const tipRR=v6Tip({t:'Run rate per hari kerja',rows:[['SELL THRU MTD',num(t.qty)],['Hari kerja berjalan',pc.run],['Run rate',num(t.qty)+' ÷ '+pc.run+' = '+num(rr)]]}),tipProj=hasT?v6Tip({t:'Proyeksi akhir bulan',s:'Dihitung dari hari kerja (Senin–Sabtu, di luar Hari_Libur)',rows:[['Run rate',num(rr)+' / hari kerja'],['Proyeksi',num(rr)+' × '+pc.days+' = '+num(proj)],['Target',num(T.q.value)],['Butuh per hari kerja',pc.left?num(Math.max(0,T.q.value-t.qty))+' ÷ '+pc.left+' = '+num(need):'—']],v:projP>=100?['gd','Diproyeksikan tembus target.']:['bd','Kurang ~'+num(Math.max(0,T.q.value-proj))+' unit. Naikkan '+num(Math.max(0,need-rr))+' unit/hari kerja dari run rate sekarang.']}):'';
 const vsTG=ach!=null?ach-pc.tg:null,lm=r.previousAvailable&&r.previous.qty?(t.qty-r.previous.qty)/r.previous.qty*100:null;
 const tags=[ach!=null?`<span class="v6pill v6${v6Tone(ach,pc.tg)}">SELL THRU ${pct(ach)}${r.coverage.closed?'':' · '+(vsTG>=0?'+':'')+decimal(vsTG)+' poin vs TG'}</span>`:'<span class="v6pill v6info">Target SELL THRU belum diisi</span>',
  lm!=null?`<span class="v6pill v6${lm>=0?'good':'bad'}"${(()=>{const z=r.v6tutupLM;if(!z||!z.n||!r.previous.qty)return '';const pe=r.previous.qty-z.q,ce=t.qty-(z.c||0),ge=pe>0?(ce-pe)/pe*100:null;return v6Tip({t:'vs '+(r.coverage.closed?'LM':'LMTD'),rows:[[r.coverage.closed?'Bulan lalu':'LMTD',num(r.previous.qty)],['Termasuk dari '+z.n+' dealer yang sudah tutup',num(z.q)+' unit'],['Growth',(lm>=0?'+':'')+pct(lm)]].concat(ge==null?[]:[['Growth tanpa dealer tutup',(ge>=0?'+':'')+pct(ge)]])});})()}>vs ${r.coverage.closed?'LM':'LMTD'} ${lm>=0?'+':''}${pct(lm)}</span>`:'',
  r.coverage.closed?'<span class="v6pill v6info">Bulan penuh</span>':`<span class="v6pill v6info"${v6Tip({t:'Hari kerja',s:'Senin–Sabtu, di luar tanggal di sheet Hari_Libur',rows:[['Hari kerja berjalan',pc.run+' dari '+pc.days],['Sisa hari kerja',pc.left],['Time gone',pct(pc.tg)]]})}>Hari kerja ${pc.run}/${pc.days} · sisa ${pc.left}</span>`,
  k&&k.score==null?`<span class="v6pill v6warn">KPI ${esc(k.status||'belum final')}</span>`:''].join('');
 const bar=hasT?`<div class="v6tl"><div class="row6"><span>${r.coverage.closed?'SELL THRU bulan penuh <b style="color:var(--c6-text)">'+num(t.qty)+'</b>':'Today <b style="color:var(--c6-text)">'+num(today)+'</b>'}</span><span>${r.coverage.closed?'':`Est. akhir bulan <b class="v6tap" style="color:var(--c6-blue)"${tipProj}>${num(proj)}</b> (${pct(projP)})`}</span></div><div class="v6bar">${r.coverage.closed?'':`<div class="p" style="width:${Math.min(100,projP)}%"></div>`}<div class="a" style="width:${Math.min(100,ach)}%"></div><div class="tg" style="left:${Math.min(100,pc.tg)}%"></div></div><div class="v6tlfoot"><span class="v6tgl" style="left:clamp(52px,${Math.min(100,pc.tg)}%,calc(100% - 52px))">▲ time gone ${pct(pc.tg)}</span>${T.q.complete?'':'<span class="v6tt"><b title="Ada sales yang target brand-nya belum diisi">*</b> target belum lengkap</span>'}</div></div>`:'';
  const stats=[['Run rate / hari kerja','<span class="v6tap"'+tipRR+'>'+num(rr)+' unit</span>','rata-rata '+pc.run+' hari kerja'],
  hasT?['Butuh / hari kerja',pc.left?'<span class="v6tap"'+tipProj+'>'+num(need)+' unit</span>':'—',pc.left?(rr?pct(need/rr*100)+' dari run rate':'sisa '+pc.left+' hari kerja'):'bulan selesai']:['SELL OUT',soNum(t.sellout),'unit'],
  ['Proyeksi omzet',moneyShort(r.coverage.closed?t.omzet:t.omzet/Math.max(1,pc.run)*pc.days),r.coverage.closed?'aktual bulan penuh':'jika ritme tetap'],
  hasT?['Gap ke target',num(Math.max(0,T.q.value-t.qty))+' unit',pc.left?'sisa '+pc.left+' hari kerja':'akhir bulan']:['Dealer aktif',num(t.da),num(t.outlets)+' dealer unik']];
 return `<section class="v6hero">${v6Ring(ringP,ringL,ringS+(kScore!=null&&ach!=null?'<br>ST '+pct(ach)+'<br>'+num(T.q.value)+' / '+num(t.qty):''),pc.tg)}<div><h2>${esc(who)}</h2><div class="meta">${esc(bulan(r.period))} · ${r.coverage.closed?'bulan penuh':'MTD s.d. '+tgl(r.coverage.cutoff)} · ${num(r.scopeCount||0)} sales</div><div class="v6tags">${tags}</div>${bar}</div><div class="v6stats">${stats.map(x=>`<div class="v6stat"><div class="l">${x[0]}</div><div class="v">${x[1]}</div><div class="s">${x[2]}</div></div>`).join('')}</div></section>`;
}
function moneyShort(n){return 'Rp '+(Math.abs(n)>=1e9?(n/1e9).toLocaleString('id-ID',{maximumFractionDigits:2})+' M':Math.abs(n)>=1e6?(n/1e6).toLocaleString('id-ID',{maximumFractionDigits:1})+' jt':num(n));}
let V6PROJSEQ=0;
function v6CumPanel(r){
 const pc=v6Pace(r),T=v6Totals(r),target=T.q.value,W=720,H=250,P={l:58,r:18,t:18,b:32},iw=W-P.l-P.r,ih=H-P.t-P.b;
 const byDay={};(r.daily||[]).forEach(d=>{byDay[+d.date.slice(8)]=(byDay[+d.date.slice(8)]||0)+(d.qty||0);});
 const cum=[];let s0=0;for(let d=1;d<=pc.calRun;d++){s0+=byDay[d]||0;cum.push(s0);}
 const rr=pc.run?s0/pc.run:0,proj=rr*pc.days,mx=Math.max(1,target,proj,s0)*1.10,X=d=>P.l+iw*((d-1)/Math.max(1,pc.cal-1)),Y=v=>P.t+ih*(1-v/mx),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
 const line=a=>a.map((v,i)=>`${i?'L':'M'}${X(i+1).toFixed(1)},${Y(v).toFixed(1)}`).join('');let g=`<rect x="${P.l}" y="${P.t}" width="${iw}" height="${ih}" fill="#FBFDFF"/>`;
 for(let i=0;i<=6;i++){const v=mx*i/6,major=i%2===0;g+=`<line x1="${P.l}" x2="${W-P.r}" y1="${Y(v)}" y2="${Y(v)}" stroke="${major?'#DCE6F0':'#EDF2F7'}" stroke-width="${major?1.05:.65}"/>`;if(major)g+=`<text x="${P.l-7}" y="${Y(v)+3}" class="v6projAxis" text-anchor="end">${num(v)}</text>`;}
 for(let d=1;d<=pc.cal;d++){const major=d===1||d===pc.cal||d%5===0;g+=`<line x1="${X(d)}" x2="${X(d)}" y1="${P.t}" y2="${H-P.b}" stroke="${major?'#DCE6F0':'#F0F4F8'}" stroke-width="${major ? .9 : .45}"/>`;if(major)g+=`<text x="${X(d)}" y="${H-9}" class="v6projAxis" text-anchor="middle">${d}</text>`;}
 const targetPts=target?Array.from({length:pc.cal},(_,i)=>target*v6WorkUpTo(r.period,i+1)/pc.days):[];
 if(targetPts.length)g+=`<path d="${line(targetPts)}L${X(pc.cal)},${Y(0)}L${X(1)},${Y(0)}Z" fill="url(#v6prRed)"/>`;
 if(cum.length)g+=`<path d="${line(cum)}L${X(pc.calRun)},${Y(0)}L${X(1)},${Y(0)}Z" fill="url(#v6prBlue)"/>`;
 if(pc.left>0&&cum.length)g+=`<path d="M${X(pc.calRun)},${Y(s0)}L${X(pc.cal)},${Y(proj)}L${X(pc.cal)},${Y(0)}L${X(pc.calRun)},${Y(0)}Z" fill="url(#v6prGrey)"/>`;
 if(targetPts.length)g+=`<path d="${line(targetPts)}" stroke="#E5484D" stroke-width="2.4" stroke-dasharray="7 5" fill="none"/>`;
 if(cum.length)g+=`<path d="${line(cum)}" stroke="#0B5CAD" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round" fill="none"/>`;
 if(pc.left>0&&cum.length)g+=`<path d="M${X(pc.calRun)},${Y(s0)}L${X(pc.cal)},${Y(proj)}" stroke="#7FB3E6" stroke-width="2.8" stroke-dasharray="6 5" stroke-linecap="round" fill="none"/>`;
 if(cum.length)g+=`<circle class="v6actualBlink" cx="${X(pc.calRun)}" cy="${Y(s0)}" r="6.2" fill="#F59A23" stroke="#FFF4DF" stroke-width="2.3"/>`;
 if(target){const ty=clamp(Y(target)-9,P.t+10,H-P.b-12);g+=`<text x="${W-P.r-2}" y="${ty}" class="v6projAnn" fill="#E5484D" text-anchor="end">Target ${num(target)}</text>`;}
 if(cum.length){const right=X(pc.calRun)>W*.72,ax=X(pc.calRun)+(right?-10:10),ay=clamp(Y(s0)-13,P.t+16,H-P.b-18);g+=`<text x="${ax}" y="${ay}" class="v6projAnn" fill="#D98210" text-anchor="${right?'end':'start'}">Aktual MTD ${num(s0)}</text><text x="${ax}" y="${ay+10}" class="v6projSub" text-anchor="${right?'end':'start'}">s.d. hari berjalan</text>`;}
 if(pc.left>0&&cum.length){let py=clamp(Y(proj)+18,P.t+24,H-P.b-18);if(target&&Math.abs(py-(Y(target)-9))<18)py=clamp(py+18,P.t+24,H-P.b-18);g+=`<text x="${W-P.r-2}" y="${py}" class="v6projAnn" fill="#567B9D" text-anchor="end">Proyeksi ${num(proj)}</text><text x="${W-P.r-2}" y="${py+10}" class="v6projSub" text-anchor="end">${target?pctLegacy(proj/target*100)+' dari target':'akhir bulan'}</text>`;}
 const legend=`<div class="v6projLegend"><span><i class="target"></i>Target</span><span><i class="actual"></i>Aktual</span>${pc.left?'<span><i class="proj"></i>Proyeksi</span>':''}</div>`;
 const defs=`<defs><linearGradient id="v6prBlue" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#5D9FE0" stop-opacity=".42"/><stop offset=".42" stop-color="#77AFE5" stop-opacity=".25"/><stop offset="1" stop-color="#8FBEE9" stop-opacity="0"/></linearGradient><linearGradient id="v6prGrey" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#B8C2CE" stop-opacity=".34"/><stop offset=".5" stop-color="#CCD4DC" stop-opacity=".17"/><stop offset="1" stop-color="#E5EAF0" stop-opacity="0"/></linearGradient><linearGradient id="v6prRed" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#EC676F" stop-opacity=".30"/><stop offset=".45" stop-color="#EF7F86" stop-opacity=".15"/><stop offset="1" stop-color="#F3A2A7" stop-opacity="0"/></linearGradient></defs>`;
 const content=`<div class="v6projChart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="SELL THRU kumulatif harian dibanding target dan proyeksi">${defs}${g}</svg>${legend}</div>`;
 const id='v6projlegacy'+(++V6PROJSEQ),action=`<button type="button" title="Layar penuh" aria-label="Layar penuh" class="v6xfsBtn v6projFsBtn" data-v6projfs="${id}">⛶</button>`;
 const ttl='Proyeksi SELL THRU'+(r.v6Title?' · '+esc(r.v6Title):'');
 return `<div class="v6projFs" id="${id}"><section class="panel" data-v2-skip-fold="1"><div class="ph"><h3>${ttl}</h3><span class="hint">Kumulatif harian vs target</span>${action}</div><div class="pb">${content}</div></section></div>`;
}
function v6BrandPanel(r,prior){
 const pc=v6Pace(r),rows=r.brands.filter(b=>(b.current.qty||0)||(b.previous.qty||0)||(b.target?.value||0)).map(b=>{const t=b.target?.value||0,a=b.current.qty||0,p=t?a/t*100:null,proj=pc.run?a/pc.run*pc.days:a;return [esc(b.brand),t?num(t):'—',num(a),p==null?'<span class="hint">—</span>':`<div class="v6achc">${v6Mini(p,pc.tg)}<b style="color:${v6Color(p,pc.tg)}">${pct(p)}</b></div>`,p==null||r.coverage.closed?'—':`<b style="color:${p>=pc.tg?'var(--c6-green)':'var(--c6-red)'}">${p-pc.tg>=0?'+':''}${decimal(p-pc.tg)}</b>`,t?v6PJ(proj,proj/t*100):num(proj),!t?'—':a>=t?'<b style="color:var(--c6-green)">✓ tercapai</b>':pc.left?num((t-a)/pc.left):'—',delta(a,b.previous.qty)];});
 const T=v6Totals(r).q.value,A=r.total.qty,P=T?A/T*100:null,PJ=pc.run?A/pc.run*pc.days:A;
 rows.push(['Total',T?num(T):'—',num(A),P==null?'—':pct(P),P==null||r.coverage.closed?'—':(P-pc.tg>=0?'+':'')+decimal(P-pc.tg),T?v6PJ(PJ,PJ/T*100):num(PJ),!T?'—':A>=T?'✓':pc.left?num((T-A)/pc.left):'—',delta(A,r.previous.qty)]);
 return panel('SELL THRU per brand',table(['Brand','Target','QTY','Ach','vs TG','Proyeksi','Butuh/hari',prior],rows),(r.coverage.closed?'Pembanding bulan penuh':'Pembanding tanggal 1–'+Number(r.previousCutoff.slice(8)))+' · time gone '+pct(pc.tg));
}

/* ===== v6.1: heatmap sel, kalender harian, medali peringkat, animasi angka ===== */
function v6Heat(q,max,label){q=Number(q)||0;const f=max>0?q/max:0,a=q?(0.12+f*0.78).toFixed(2):0,dark=f>0.5;return q?`<span class="v6heat" style="background:rgba(11,92,173,${a});color:${dark?'#fff':'#0A2E57'}" title="${esc(label||'')}${label?': ':''}${num(q)} unit">${num(q)}</span>`:'<span class="v6heat v6zero">0</span>';}
function v6Medal(rank){const m={1:['🥇','v6gold'],2:['🥈','v6silver'],3:['🥉','v6bronze']}[rank];return m?`<span class="v6medal ${m[1]}" aria-label="Peringkat ${rank}">${m[0]}<b>${rank}</b></span>`:(rank??'—');}
function v6Calendar(r){
 const pc=v6Pace(r),T=v6Totals(r).q.value,daily={},first=new Date(r.period+'-01T00:00:00');(r.daily||[]).forEach(d=>daily[+d.date.slice(8)]=d);
 const target=T/pc.days,sisa=pc.left?Math.max(0,T-r.total.qty)/pc.left:0,maxQ=Math.max(1,...(r.daily||[]).map(d=>d.qty||0));
 const lead=(first.getDay()+6)%7;let cells=['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map((d,i)=>`<div class="v6calh${i===6?' v6sun':''}">${d}</div>`).join('')+'<div></div>'.repeat(lead);
 for(let day=1;day<=pc.cal;day++){const d=daily[day],date=r.period+'-'+String(day).padStart(2,'0'),dow=(lead+day-1)%7;
  const off=v6Off(date),hol=v6Hol(date);if(off&&!(daily[day]?.qty)){cells+=`<div class="v6day v6off${hol?' v6hol':''}${day>pc.calRun?' v6offF':''}"${v6TipShort(tgl(date)+' · '+(hol?'Hari libur (sheet Hari_Libur)':'Minggu · libur')+', tidak dihitung sebagai hari kerja')}><b>${day}</b><span>Libur</span></div>`;continue;}
  if(day<=pc.calRun){const q=d?.qty||0,p=target&&!off?q/target*100:null,cls=p==null?'':p>=100?'v6ok':p>=60?'v6mid':'v6low',style=p==null?`background:rgba(11,92,173,${(0.08+q/maxQ*0.6).toFixed(2)})`:'';
   cells+=`<button type="button" class="v6day v6tipD ${cls}${day===pc.calRun&&!r.coverage.closed?' v6today':''}${off?' v6off':''}" style="${off?'':style}" data-v6day="${date}"${v6Tip({t:esc(tgl(date)),rows:[['SELL THRU',num(q)+' unit'],['Dealer order',num(d?.outlets||0)]].concat((()=>{const bs=d?.brands||[],mi=bs.indexOf(Math.max(0,...bs));return mi>=0&&bs[mi]>0?[['Brand teratas',esc(REPORT.brands[mi]?.brand||'')+' · '+num(bs[mi])]]:[];})()).concat(p==null?[]:[['Target harian',num(target)+' unit'],['Capaian',pct(p)]]),v:off?['md','Transaksi di hari libur — tidak ikut dianalisa.']:p==null?null:p>=100?['gd','Di atas target harian.']:p>=60?['md','Sedikit di bawah target harian.']:['bd','Jauh di bawah target harian.']})}><b>${day}</b><span>${num(q)} unit</span><small>${num(d?.outlets||0)} dealer</small>${p==null?'':`<i style="width:${Math.min(100,p)}%"></i>`}</button>`;}
  else cells+=`<div class="v6day v6future${dow===6?' v6sunday':''}"><b>${day}</b>${T?`<span>butuh</span><small>${num(sisa)} unit</small>`:'<small>—</small>'}</div>`;}
 const legend=T?`<div class="v6legend"><span><i style="background:#12A86B"></i>≥ target harian (${num(target)} unit / hari kerja)</span><span><i style="background:#F2C14E"></i>60–99%</span><span><i style="background:#F07B84"></i>&lt; 60%</span><span><i style="background:#F7F9FC;border:1px dashed #C9D3E0"></i>Sisa hari</span><span><i class="v6lgOff"></i>Minggu / libur</span></div>`:'<div class="v6legend"><span>Warna = jumlah ST per hari (makin gelap makin banyak) · target belum tersedia</span></div>';
 return panel('Kalender SELL THRU harian',legend+`<div class="v6cal">${cells}</div><div class="v6note">Klik tanggal untuk melihat penjualan per brand hari itu — bisa dipecah per Big Region, Region, RGM, ASM, atau Sales.</div>`,'Unit per hari · bulan pilihan');
}
function v6BindCalendar(){document.querySelectorAll('[data-v6day]').forEach(b=>b.onclick=()=>v6DayPopup(b.dataset.v6day));}
let v6DayLevel='SALES';const v6DayCache=new Map();
function v6OrgOf(nik){const people=BOOT.people||[],byNik=Object.fromEntries(people.map(p=>[p.nik,p])),p=byNik[nik],up=role=>{let x=p,guard=0;while(x&&guard++<12){if(x.role===role)return x;x=byNik[x.atasan];}return null;};
 const reg=x=>x?(x.portfolio||x.region||'—'):'—',rg=up('RGM'),as=up('ASM');return {BIG:p?.wilayah||'—',REGION:reg(p),RGM:rg?.nama||'—',ASM:as?.nama||'—',SALES:p?.nama||nik,_reg:{RGM:rg?reg(rg):'—',ASM:as?reg(as):'—',SALES:reg(p)},_big:{RGM:rg?.wilayah||p?.wilayah||'—',ASM:as?.wilayah||p?.wilayah||'—',SALES:p?.wilayah||'—'}};}
async function v6DayRows(date){const key=TOKEN+'|'+REPORT.period+'|'+$('scopeSelect').value+'|'+date;if(v6DayCache.has(key))return v6DayCache.get(key);let page=0,rows=[],total=0;
 do{const r=await rpc('apiTransactions',TOKEN,REPORT.period,$('scopeSelect').value,'',page,date,date,null,200);rows=rows.concat(r.rows||[]);total=r.total||0;page++;if(page>60)break;}while(rows.length<total);
 v6DayCache.set(key,rows);return rows;}
function v6DayTable(date,rows){const brands=REPORT.brands.map(b=>b.brand),lv=v6DayLevel,groups=new Map(),tot={q:{},unit:0,amt:0,dealers:new Set()};
 rows.forEach(t=>{const o=v6OrgOf(t.nik),g=o[lv];if(!groups.has(g))groups.set(g,{name:g,regs:new Set(),bigs:new Set(),q:{},unit:0,amt:0,dealers:new Set()});const x=groups.get(g),q=t.deviceQty||0;if(o._reg[lv])x.regs.add(o._reg[lv]);if(o._big[lv])x.bigs.add(o._big[lv]);x.q[t.brand]=(x.q[t.brand]||0)+q;x.unit+=q;x.amt+=t.amount||0;x.dealers.add(t.customer);tot.q[t.brand]=(tot.q[t.brand]||0)+q;tot.unit+=q;tot.amt+=t.amount||0;tot.dealers.add(t.customer);});
 const list=[...groups.values()].sort((a,b)=>b.unit-a.unit),used=brands.filter(b=>tot.q[b]),max=Math.max(1,...list.flatMap(x=>used.map(b=>x.q[b]||0))),label={BIG:'Big Region',REGION:'Region',RGM:'RGM',ASM:'ASM',SALES:'Sales'}[lv];
 const withReg=['RGM','ASM','SALES'].includes(lv),body=list.map(x=>[esc(x.name),...(withReg?[esc([...x.regs].join(', ')||'—')+'<small class="cellsub">'+esc([...x.bigs].join(', '))+'</small>']:[]),num(x.dealers.size),...used.map(b=>v6Heat(x.q[b]||0,max,x.name+' · '+b)),'<b>'+num(x.unit)+'</b>',moneyShort(x.amt)]);
 body.push(['Total',...(withReg?['']:[]),num(tot.dealers.size),...used.map(b=>num(tot.q[b])),num(tot.unit),moneyShort(tot.amt)]);
 return list.length?`<div class="v6dailyTable">${table([label,...(withReg?['Region']:[]),'Dealer',...used.map(esc),'Total unit','Omzet'],body)}</div>`:'<div class="empty">Tidak ada transaksi pada tanggal ini.</div>';}
async function v6DayPopup(date){const d=(REPORT.daily||[]).find(x=>x.date===date),pc=v6Pace(REPORT),T=v6Totals(REPORT).q.value,target=T/pc.days,p=target&&d?d.qty/target*100:null;
 const levels=[['BIG','Big Region'],['REGION','Region'],['RGM','RGM'],['ASM','ASM'],['SALES','Sales']];
 modal('Penjualan '+tgl(date),`<div class="v6popHead"><div class="v6stat"><div class="l">SELL THRU</div><div class="v">${num(d?.qty||0)} unit</div><div class="s">${p==null?'target harian belum ada':pct(p)+' dari target harian '+num(target)}</div></div><div class="v6stat"><div class="l">Dealer bertransaksi</div><div class="v">${num(d?.outlets||0)}</div><div class="s">dealer unik</div></div><div class="v6stat"><div class="l">Hari</div><div class="v">${esc(new Date(date+'T00:00:00').toLocaleDateString('id-ID',{weekday:'long'}))}</div><div class="s">${esc(bulan(REPORT.period))}</div></div></div>
 <div class="v6seg" role="tablist" aria-label="Tampilkan berdasarkan">${levels.map(l=>`<button type="button" class="v6segBtn ${l[0]===v6DayLevel?'on':''}" data-v6lv="${l[0]}">${l[1]}</button>`).join('')}</div>
 <div id="v6DayBody"><div class="empty v6load">Memuat transaksi ${esc(tgl(date))}…</div></div>
 <div class="toolbar" style="margin-top:12px"><button type="button" class="chip primary" id="v6DayDetail">Lihat rincian transaksi tanggal ini →</button></div>`);
 const draw=rows=>{$('v6DayBody').innerHTML=v6DayTable(date,rows);if(typeof addTopTableScroll==='function')addTopTableScroll($('v6DayBody'));};
 $('v6DayDetail').onclick=()=>{closeModal();trxDates={period:REPORT.period,from:date,to:date};transactionPage=0;render().then(()=>document.querySelector('.transactionDetailPanel')?.scrollIntoView({behavior:'smooth',block:'start'}));};
 try{const rows=await v6DayRows(date);if(!$('v6DayBody'))return;draw(rows);document.querySelectorAll('[data-v6lv]').forEach(b=>b.onclick=()=>{v6DayLevel=b.dataset.v6lv;document.querySelectorAll('[data-v6lv]').forEach(x=>x.classList.toggle('on',x===b));draw(rows);});}
 catch(e){if($('v6DayBody'))$('v6DayBody').innerHTML='<div class="banner bad">'+esc(e.message)+'</div>';}}
function v6CountUp(root){
 const els=[...root.querySelectorAll('.kval,.v6stat .v,.v6ring b')].flatMap(el=>el.childElementCount?[...el.querySelectorAll('.moneyShort')]:[el]);
 els.forEach(el=>{if(el.dataset.v6done)return;el.dataset.v6done='1';const txt=el.textContent,m=txt.match(/^(\D*?)(-?[\d.]+(?:,\d+)?)(.*)$/);if(!m)return;const dec=(m[2].split(',')[1]||'').length,val=parseFloat(m[2].replace(/\./g,'').replace(',','.'));if(!isFinite(val)||val===0)return;
  const fmt=v=>m[1]+v.toLocaleString('id-ID',{minimumFractionDigits:dec,maximumFractionDigits:dec})+m[3],t0=performance.now(),dur=650;
  const step=now=>{const k=Math.min(1,(now-t0)/dur),e=1-Math.pow(1-k,3);el.textContent=fmt(val*e);if(k<1)requestAnimationFrame(step);else el.textContent=txt;};requestAnimationFrame(step);});
}
function v6StickyHead(root){(root||document).querySelectorAll('table').forEach(t=>{const rows=[...(t.tHead?.rows||[])];if(rows.length<2)return;let off=0;for(let i=0;i<rows.length;i++){const h=rows[i].getBoundingClientRect().height;if(!h)return;if(i>0)[...rows[i].cells].forEach(th=>{th.style.top=off+'px';th.style.zIndex=String(20-i);});else [...rows[i].cells].forEach(th=>{if(!th.style.zIndex)th.style.zIndex='21';});off+=h;}});}
window.addEventListener('resize',()=>v6StickyHead(document));document.addEventListener('toggle',()=>setTimeout(()=>v6StickyHead(document),30),true);
/* v12: posisi vertikal header kolom .lc (Nama/ASM/Region dsb) di beberapa browser tidak ikut nempel (bug repaint 2-axis sticky bawaan browser untuk sel tabel yang sticky kiri+atas sekaligus). Di-fix manual lewat transform mengikuti scroll, bukan andalkan position:sticky untuk sumbu atasnya. */
function v6AlignText(root){root.querySelectorAll('.v6dailyTable table,.weeklyTable table').forEach(t=>{if(t.dataset.v6al)return;const body=t.tBodies[0];if(!body||!body.rows.length)return;t.dataset.v6al='1';const rows=[...body.rows],n=rows[0].cells.length,oneHead=t.tHead&&t.tHead.rows.length===1;for(let c=0;c<n;c++){let tot=0,txt=0;rows.forEach(r=>{const x=r.cells[c];if(!x||x.colSpan>1)return;const v=x.textContent.trim();if(!v||v==='—'||v==='-'||x.querySelector('.v6pjc,.v6achc,svg'))return;tot++;if(!/^[\d.,\s%+\-−\/×*↑↓▲▼✓]+(unit|hari)?$/i.test(v))txt++;});if(tot&&txt/tot>.5){rows.forEach(r=>{const x=r.cells[c];if(x&&x.colSpan===1)x.classList.add('v6tl');});if(oneHead){const h=t.tHead.rows[0].cells[c];if(h)h.classList.add('v6tl');}}}});}
async function v6CoverInit(){const box=document.getElementById('v6cov');if(!box||box.dataset.i)return;box.dataset.i='1';let brand='';const draw=async()=>{box.querySelector('.v6covTbl')&&(box.querySelector('.v6covTbl').style.opacity='.5');try{const r=await rpc('apiCoverageMatrix',TOKEN,brand);brand=r.brand||'';const cell=c=>{const a=c.st!=='none',b=c.so!=='none',tip=(c.stc?'Sell Thru s.d. '+tgl(c.stc):'Sell Thru kosong')+' · '+(c.soc?'Sell Out s.d. '+tgl(c.soc):'Sell Out kosong');return a&&b?`<td class="cvOk" title="${esc(tip)}">✓</td>`:a?`<td class="cvHalf" title="${esc(tip)}">ST</td>`:b?`<td class="cvHalf" title="${esc(tip)}">SO</td>`:`<td class="cvNo" title="${esc(tip)}">—</td>`;};const first=(row,k)=>{const i=row.cells.findIndex(c=>c[k]!=='none');return i<0?'—':bulan(r.months[i]).replace(' 20',' ');};box.innerHTML=`<div class="toolbar"><label>Brand <select class="fi" id="v6covBrand"><option value="">SEMUA BRAND (status upload)</option>${r.brands.map(b=>`<option${b===brand?' selected':''}>${esc(b)}</option>`).join('')}</select></label></div><div class="table-scroll v6covTbl"><table class="dgTable"><thead><tr><th>Region</th>${r.months.map(m=>`<th>${esc(bulan(m).replace(' 20',' '))}</th>`).join('')}<th>Mulai ada (ST)</th><th>Mulai ada (SO)</th></tr></thead><tbody>${r.rows.map(row=>`<tr><td class="dgName">${esc(row.region)}</td>${row.cells.map(cell).join('')}<td>${first(row,'st')}</td><td>${first(row,'so')}</td></tr>`).join('')}</tbody></table></div><small class="hint">✓ = Sell Thru dan Sell Out ada · ST / SO = hanya salah satu · — = kosong (dianggap 0).${brand?' Mode brand: "ada" berarti ada transaksi '+esc(brand)+' di region dan bulan itu.':' Mode status upload: "ada" berarti file region itu sudah di-upload untuk bulan itu.'}</small>`;$('v6covBrand').onchange=e=>{brand=e.target.value;draw();};}catch(e){box.innerHTML='<p class="v6rmErr">'+esc(e.message||e)+'</p>';}};draw();}
function v6GtResize(root){root.querySelectorAll('.v6gttable').forEach(t=>{if(t.dataset.gtr)return;const h1=t.querySelector('thead tr:first-child th:nth-child(1)'),h2=t.querySelector('thead tr:first-child th:nth-child(2)');if(!h1||!h2)return;t.dataset.gtr='1';let sv={};try{sv=JSON.parse(localStorage.getItem('sp-gtw')||'{}')||{};}catch(e){}if(sv.a)t.style.setProperty('--gt1',sv.a+'px');if(sv.b)t.style.setProperty('--gt2',sv.b+'px');[[h1,'--gt1','a'],[h2,'--gt2','b']].forEach(([th,v,k])=>{if(getComputedStyle(th).position==='static')th.style.position='sticky';const g=document.createElement('i');g.className='v6gth';g.title='Tarik untuk mengubah lebar';th.appendChild(g);g.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();g.setPointerCapture(e.pointerId);g.classList.add('on');const x0=e.clientX,w0=th.getBoundingClientRect().width;const mv=ev=>{const w=Math.max(90,Math.min(520,Math.round(w0+ev.clientX-x0)));t.style.setProperty(v,w+'px');sv[k]=w;};const up=()=>{g.classList.remove('on');g.removeEventListener('pointermove',mv);g.removeEventListener('pointerup',up);try{localStorage.setItem('sp-gtw',JSON.stringify(sv));}catch(e){}};g.addEventListener('pointermove',mv);g.addEventListener('pointerup',up);});g.addEventListener('click',e=>e.stopPropagation());});});}
function v6NumCols(root){root.querySelectorAll('table').forEach(t=>{if(t.dataset.v6nc)return;const th=t.querySelector('thead th');if(!th)return;const txt=th.textContent.replace(/[↕▲▼\s]/g,'').toLowerCase();if(['#','no','no.','peringkat','rank','urutan','nomor'].includes(txt)){t.classList.add('v6numcol');}t.dataset.v6nc='1';});}
(function v6Observe(){const main=document.getElementById('main'),mb=document.getElementById('mbody');if(!main||!window.MutationObserver)return;let t=0;const run=()=>{clearTimeout(t);t=setTimeout(()=>{v6NumCols(main);if(mb)v6NumCols(mb);v6AlignText(main);if(mb)v6AlignText(mb);v6CoverInit();v6GtResize(main);if(mb)v6GtResize(mb);v6StickyHead(main);if(mb)v6StickyHead(mb);if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)v6CountUp(main);},30);};new MutationObserver(run).observe(main,{childList:true,subtree:true});if(mb)new MutationObserver(run).observe(mb,{childList:true,subtree:true});})();

/* ===== v6.6: ringkasan & proyeksi per brand (menu Brand) ===== */
function v6BrandReport(r,brand){const i=r.brands.findIndex(b=>b.brand===brand),b=r.brands[i];if(!b)return r;return {...r,v6Title:brand,total:{...b.current},previous:b.previous||{},brands:[b],daily:(r.daily||[]).map(d=>({...d,qty:(d.brands||[])[i]||0})),kpi:null};}

/* ===== v6.8: ringkasan Beranda lebih tajam + pola hari ===== */
function v6BerandaSummary(r){
 const pc=v6Pace(r),T=v6Totals(r).q.value,t=r.total,dev=r.brands.filter(b=>(b.target?.value||0)>0||(b.current.qty||0)>0||(b.previous.qty||0)>0),mv=dev.map(b=>({n:b.brand,d:(b.current.qty||0)-(b.previous.qty||0),p:b.target?.value?b.current.qty/b.target.value*100:null})).sort((a,b)=>b.d-a.d),top=mv[0],low=mv[mv.length-1];
 const cs=r.customers||[],cnt=s=>cs.filter(c=>c.status===s).length,daLalu=cnt('DA BULAN LALU'),belum=cs.filter(c=>c.status!=='AKTIF').length,need=T&&pc.left?Math.max(0,T-t.qty)/pc.left:0,rr=pc.run?t.qty/pc.run:0,proj=rr*pc.days;
 const lagging=dev.filter(b=>b.target?.value&&b.current.qty/b.target.value*100<pc.tg).sort((a,b)=>a.current.qty/a.target.value-b.current.qty/b.target.value).map(b=>b.brand);
 const happening=T?`Proyeksi akhir bulan ${num(proj)} unit (${pct(proj/T*100)} target). ${top&&top.d>0?top.n+' naik '+num(top.d)+' unit vs '+(r.coverage.closed?'LM':'LMTD')+'.':''}`:`${top?top.n+' '+(top.d>=0?'naik ':'turun ')+num(Math.abs(top.d))+' unit vs bulan lalu.':'Data brand belum tersedia.'}`;
 const cause=`${lagging.length?lagging.slice(0,3).join(', ')+' masih di bawah time gone. ':''}${belum?num(belum)+' dealer belum aktif'+(daLalu?' — '+num(daLalu)+' di antaranya order bulan lalu.':'.'):'Mayoritas dealer aktif.'}`;
 const action=T&&need?`Kejar ${num(need)} unit/hari kerja (${rr?pct(need/rr*100):'—'} dari ritme sekarang). ${daLalu?'Mulai dari '+num(daLalu)+' dealer DA bulan lalu.':''}`:'Pertahankan ritme dan pantau perubahan mingguan.';
 return analysisSummaryPanel('Ringkasan Analisa',happening,cause,action,[['Brand terkuat',top?top.n+(top.d?' ('+(top.d>0?'+':'')+num(top.d)+')':''):'—'],['Brand terlemah',low?low.n+(low.d?' ('+(low.d>0?'+':'')+num(low.d)+')':''):'—'],['Dealer perlu dikejar',num(belum)],['Butuh / hari',need?num(need)+' unit':'—']]);
}

function v12DowDraw(){const D=window.v12DOW,tb=document.getElementById('v12dwTb');if(!D||!tb)return;const col=k=>k>=150?['#2F6FB5','#fff']:k>=120?['#6EA0D4','#0F2A44']:k>=105?['#BCD3EC','#0F2A44']:k>=95?['#EEF2F8','#16202E']:k>=80?['#F6D0D4','#5A1A25']:k>=60?['#EDA9B1','#4A121C']:['#E08792','#3F0D16'],txt=(v,k)=>D.mode==='u'?num(v):(k>=100?'+':'−')+Math.abs(Math.round(k)-100)+'%';
 const best=k=>D.days.reduce((b,i)=>k[i]>k[b]?i:b,D.days[0]);
 const rows=D.rows.map((x,ri)=>'<tr><td class="nm"><b>'+esc(x.n)+'</b><small>rata-rata '+num(x.m)+'/hari</small></td>'+D.NM.map((_,i)=>{const c=col(x.k[i]);return '<td><span class="cell" data-v12c="'+ri+'" data-i="'+i+'" style="background:'+c[0]+';color:'+c[1]+'">'+txt(x.v[i],x.k[i])+'</span></td>'}).join('')+'<td><span class="best">'+(D.days.length?D.DNm[best(x.k)]:'—')+'</span></td></tr>').join('');
 tb.innerHTML='<thead><tr><th class="nm">Brand</th>'+D.NM.map(d=>'<th>'+d+'</th>').join('')+'<th>Hari terbaik</th></tr></thead><tbody>'+rows+'<tr class="tot"><td class="nm"><b>Semua brand</b><small>rata-rata '+num(D.tot.m)+'/hari</small></td>'+D.NM.map((_,i)=>'<td>'+txt(D.tot.v[i],D.tot.k[i])+'</td>').join('')+'<td><span class="best">'+(D.days.length?D.DNm[best(D.tot.k)]:'—')+'</span></td></tr></tbody>';
 const lt=document.getElementById('v12dwLt');if(lt)lt.textContent=D.mode==='u'?'Angka = unit per hari. Warna = lebih sepi (merah) atau lebih ramai (biru) dari rata-rata brand itu sendiri.':'Angka = selisih dari rata-rata hari kerja brand itu sendiri. Warna sama seperti sebelumnya.';}
document.addEventListener('click',e=>{const m=e.target.closest&&e.target.closest('[data-v12m]');if(m&&window.v12DOW){window.v12DOW.mode=m.dataset.v12m;document.querySelectorAll('[data-v12m]').forEach(b=>b.classList.toggle('on',b===m));v12DowDraw();return}
 const c=e.target.closest&&e.target.closest('[data-v12c]');if(!c||!window.v12DOW)return;const D=window.v12DOW,x=D.rows[+c.dataset.v12c],i=+c.dataset.i,k=x.k[i];v12Sheet(esc(x.n)+' · '+D.DNm[i],'<div class="v12Dl"><span>Rata-rata penjualan hari ini</span><b>'+num(x.v[i])+' unit</b><span>Rata-rata semua hari kerja '+esc(x.n)+'</span><b>'+num(x.m)+' unit</b><span>Selisih</span><b style="color:'+(k>=100?'#0E9F6E':'#D63A55')+'">'+(k>=100?'+':'−')+Math.abs(Math.round(k)-100)+'%</b></div>');});
function v6DowPanel(r){
 const names=['Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu'],pc=v6Pace(r),byDay={};(r.daily||[]).forEach(d=>byDay[+d.date.slice(8)]=d);
 const cnt=Array(7).fill(0),sum=Array(7).fill(0),bsum=r.brands.map(()=>Array(7).fill(0));let offQ=0,offDays=0;
 for(let day=1;day<=pc.calRun;day++){const date=r.period+'-'+String(day).padStart(2,'0'),w=(new Date(date+'T00:00:00').getDay()+6)%7,d=byDay[day];
  if(v6Off(date)){offQ+=d?.qty||0;if(d?.qty)offDays++;if(w!==6)continue;}
  cnt[w]++;sum[w]+=d?.qty||0;(d?.brands||[]).forEach((q,i)=>bsum[i][w]+=q||0);}
 const avgD=sum.map((s,i)=>cnt[i]?s/cnt[i]:0),wd=[0,1,2,3,4,5].filter(i=>cnt[i]),all=(wd.reduce((a,i)=>a+avgD[i],0)/(wd.length||1))||1,mx=Math.max(1,...avgD);
 const bars=`<div class="v6dow">${avgD.map((v,i)=>{if(i===6)return `<div class="v6dowb v6dowOff"${v6TipShort('Minggu · libur, tidak ikut dianalisa'+(v?' (rata-rata '+decimal(v)+' unit)':''))}><b>${num(v)}</b><i style="height:6px"></i><small>Min</small><span class="v6pill v6off">Libur</span></div>`;const dv=(v/all-1)*100;return `<div class="v6dowb"${v6TipShort(names[i]+' · rata-rata '+decimal(v)+' unit/hari · '+(dv>=0?'+':'')+Math.round(dv)+'% dari rata-rata hari kerja · '+cnt[i]+' hari')}><b>${num(v)}</b><i class="${v<all*0.6?'low':''}" style="height:${Math.max(3,v/mx*125)}px"></i><small>${names[i].slice(0,3)}</small><span class="v6pill v6${dv>=0?'good':'bad'}">${dv>=0?'+':''}${Math.round(dv)}%</span></div>`}).join('')}</div>`;
 const brands=r.brands.map((b,i)=>({b:b.brand,a:bsum[i].map((s,w)=>cnt[w]?s/cnt[w]:0)})).filter(x=>x.a.some(v=>v>0));
 const idx=brands.map(x=>{const m=(wd.reduce((a,w)=>a+x.a[w],0)/(wd.length||1))||1;return [esc(x.b),...x.a.map((v,w)=>{if(w===6)return `<span class="v6heat v6heatOff"${v6TipShort(esc(x.b)+' · Minggu: '+decimal(v)+' unit/hari · libur, tidak dianalisa')}>${num(v)}</span>`;const k=Math.round(v/m*100),hi=k>=100;return `<span class="v6heat" style="background:${hi?`rgba(11,92,173,${Math.min(.85,.15+(k-100)/150).toFixed(2)})`:`rgba(229,72,77,${Math.min(.75,.12+(100-k)/130).toFixed(2)})`};color:${(hi&&k>150)||(!hi&&k<45)?'#fff':'#152238'}"${v6TipShort(esc(x.b)+' · '+names[w]+': '+decimal(v)+' unit/hari · indeks '+k+' (100 = rata-rata hari kerja brand ini)')}>${k}</span>`;})];});
 const best=wd.reduce((b,i)=>avgD[i]>avgD[b]?i:b,wd[0]??0),worst=wd.reduce((b,i)=>avgD[i]<avgD[b]?i:b,wd[0]??0);
 const note=`<div class="v6insight"><b>${names[best]}</b> jadi hari order terbesar (${(avgD[best]/all-1)>=0?'+':''}${pct((avgD[best]/all-1)*100)} dari rata-rata hari kerja), <b>${names[worst]}</b> paling rendah di antara hari kerja (${pct((avgD[worst]/all-1)*100)}). Minggu libur, tidak dianalisa. Indeks 100 = rata-rata hari kerja brand itu sendiri.</div>`;
 const offNote=offQ?`<div class="v6note"><span class="v6pill v6off">Ada ${num(offQ)} unit transaksi di hari Minggu / libur (${offDays} hari) — tidak ikut dianalisa.</span></div>`:'';
 if(isMobile()){const NM=['Sen','Sel','Rab','Kam','Jum','Sab'],DNm=['Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'],avgW=wd.length?wd.reduce((a,i)=>a+avgD[i],0)/wd.length:0;
  window.v12DOW={mode:'u',days:wd,rows:brands.map(x=>{const m=wd.length?wd.reduce((a,w)=>a+x.a[w],0)/wd.length:0;return{n:x.b,m,v:x.a,k:x.a.map(v=>m?v/m*100:100)}}),tot:{m:avgW,v:avgD,k:avgD.map(v=>avgW?v/avgW*100:100)},NM,DNm};
  setTimeout(v12DowDraw,0);
  return panel('Pola hari penjualan','<div class="v12dw"><div class="v12dwS">Rata-rata SELL THRU per hari · '+esc(bulan(r.period))+' (s.d. '+tgl(r.coverage.cutoff)+') · Senin sampai Sabtu</div><div class="v12dwT" id="v12dwT"><button data-v12m="u" class="on">UNIT / HARI</button><button data-v12m="p">SELISIH %</button></div><div class="v12dwL"><span class="v12dwSc"><i style="background:#E8A3AC"></i><i style="background:#F6D0D4"></i><i style="background:#EEF2F8"></i><i style="background:#BCD3EC"></i><i style="background:#6EA0D4"></i></span><span id="v12dwLt"></span></div><div class="v12dwW"><table id="v12dwTb"></table></div></div>','');}
 return panel('Pola hari penjualan',`<div class="v6dowGrid"><div>${bars}<div class="v6note">Rata-rata SELL THRU per hari dalam ${esc(bulan(r.period))} (s.d. ${tgl(r.coverage.cutoff)}). Persen dibanding rata-rata <b>Senin–Sabtu</b>; tanggal merah di sheet Hari_Libur ikut dikeluarkan.</div>${offNote}</div><div>${brands.length?`<div class="v6dailyTable v6dowTable">${table(['Brand',...names.map(n=>n==='Minggu'?'Min · libur':n.slice(0,3))],idx)}</div>`:''}${note}</div></div>`,'Rata-rata unit per hari · pembanding Senin–Sabtu');
}

/* ===== v6.9: helper umum ===== */
function v6Wa(hp,text,label){let n=String(hp||'').replace(/[\s()+.-]/g,'');if(!/^\d{8,15}$/.test(n))return '<span class="hint">No. HP belum ada</span>';if(n.startsWith('0'))n='62'+n.slice(1);else if(n.startsWith('8'))n='62'+n;return `<a class="v6wa" href="https:&#47;&#47;wa.me/${n}?text=${encodeURIComponent(text||'')}" target="_blank" rel="noopener noreferrer">✆ ${esc(label||'WhatsApp')}</a>`;}
function v6Spark(a,c,w=96,h=26){if(!a||!a.length)return '';const mx=Math.max(1,...a),mn=Math.min(...a);return `<svg class="v6spark" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" aria-hidden="true"><polyline fill="none" stroke="${c}" stroke-width="2" stroke-linejoin="round" points="${a.map((v,i)=>`${(i/Math.max(1,a.length-1)*(w-4)+2).toFixed(1)},${(h-3-(v-mn)/((mx-mn)||1)*(h-6)).toFixed(1)}`).join(' ')}"/><circle cx="${w-2}" cy="${(h-3-(a[a.length-1]-mn)/((mx-mn)||1)*(h-6)).toFixed(1)}" r="2.5" fill="${c}"/></svg>`;}
function v6Seg(name,items,cur){return `<div class="v6seg" role="tablist">${items.map(i=>`<button type="button" class="v6segBtn ${i[0]===cur?'on':''}" data-${name}="${esc(i[0])}">${esc(i[1])}</button>`).join('')}</div>`;}
function v6Kpis(items){return '<div class="kpis v6kpis">'+items.map(x=>`<div class="kpi">${kBody(x)}</div>`).join('')+'</div>';}
function v6Mon(p){return new Date(p+'-01T00:00:00').toLocaleDateString('id-ID',{month:'short',year:'2-digit'});}

/* ===== v6.9: EARLY WARNING (menu Tim) ===== */
let v6EW={metric:'QTY'};
async function v6LoadEW(seq){const box=$('v6EW');if(!box)return;
 box.innerHTML=panel('Early Warning','<div class="empty">Menghitung proyeksi…</div>','Ikut filter Tingkat, Brand, dan wilayah di atas');
 try{const r=await rpc('apiEarlyWarning',TOKEN,REPORT.period,teamLevel,brandChoice,v6EW.metric,$('scopeSelect').value,teamScope);if(seq!==SEQUENCE||!$('v6EW'))return;box.innerHTML=v6EWHtml(r);if(isMobile())v12EWMob(box);v6BindEW(seq);}
 catch(e){if($('v6EW'))box.innerHTML=panel('Early Warning','<div class="banner bad">'+esc(e.message)+'</div>');}}

function v12EWMob(box){const X=window.v12EW,t=box.querySelector('.v6ewTable');if(!X||!t)return;const h=document.createElement('div');h.id='v12ewT';t.replaceWith(h);const rows=X.rows,wt=rows.filter(x=>x.target),T=wt.reduce((n,x)=>n+x.target,0),A=rows.reduce((n,x)=>n+(x.actual||0),0),TA=wt.reduce((n,x)=>n+(x.actual||0),0),PJ=wt.reduce((n,x)=>n+(x.proj||0),0),stl={good:'Aman',warn:'Waspada',bad:'Bahaya',na:'Tanpa target'},cl=x=>'<b style="color:'+X.col(x.st)+'">';
 v12HpTable('v12ewT',{lead:X.lvName,rows,title:x=>esc(x.nama),name:x=>'<b>'+esc(x.nama)+'</b><small>'+esc(x.region)+'</small>',tot:{T,A,TA,PJ,n:rows.length},totNote:rows.length+' '+esc(X.lvName),
 groups:[{id:'t',t:'Target',cls:'gSt',cc:'cSt',col:'#2B7BE0',cols:[{h:'Target',f:x=>x.target?num(x.target):'—',t:o=>num(o.T)},{h:'Aktual',f:x=>'<b>'+num(x.actual)+'</b>',t:o=>num(o.A)},{h:'Ach',f:x=>x.p==null?'—':cl(x)+pct(x.p)+'</b>',t:o=>o.T?pct(o.TA/o.T*100):'—'}]},
 {id:'p',t:'Proyeksi',cls:'gSo',cc:'cSo',col:'#F07A0C',cols:[{h:'Proyeksi',f:x=>num(x.proj),t:o=>num(o.PJ)},{h:'% target',f:x=>x.pp==null?'—':cl(x)+pct(x.pp)+'</b>',t:o=>o.T?pct(o.PJ/o.T*100):'—'},{h:'Run rate',f:x=>decimal(x.rr)},{h:'Butuh/hari',f:x=>!x.target?'—':x.actual>=x.target?'✓':X.left?decimal(x.need):'—'}]},
 {id:'s',t:'Status',cls:'gDs',cc:'cDs',col:'#6D3FD8',cols:[{h:'Status',f:x=>'<span class="v6pill v6'+(x.st==='na'?'info':x.st)+'">'+stl[x.st]+'</span>'}]}]});}

function v12TeamMob(box,rows,bossH){const tb=box.querySelector('table');if(!tb)return;const w=tb.closest('.table-scroll')||tb.parentNode,h=document.createElement('div');h.id='v12teamT';w.replaceWith(h);const ta=(a,b)=>targetActual(a,b);
 v12HpTable('v12teamT',{lead:'Nama',rows,title:p=>esc(p.nama),name:p=>'<b>'+esc(p.nama)+'</b><small>'+esc(p.region)+'</small>',tot:null,
 groups:[{id:'st',t:'Sell thru',cls:'gSt',cc:'cSt',col:'#2B7BE0',cols:[{h:'Target / Aktual',f:p=>ta(p.target,p.total.qty)},{h:'%Achv',f:p=>bar(ach(p.total.qty,p.target))},{h:'Growth',f:p=>p.previousAvailable?delta(p.total.qty,p.previous.qty):'—'}]},
 {id:'da',t:'Dealer aktif',cls:'gSo',cc:'cSo',col:'#F07A0C',cols:[{h:'Target / Aktual',f:p=>ta(p.targetDA,p.total.da)},{h:'%Achv',f:p=>bar(ach(p.total.da,p.targetDA))},{h:'Growth',f:p=>p.previousAvailable?delta(p.total.da,p.previous.da,'dealer'):'—'}]},
 {id:'noo',t:'NOO',cls:'gDs',cc:'cDs',col:'#6D3FD8',cols:[{h:'Target / Aktual',f:p=>ta(p.targetNOO,p.total.noo)},{h:'%Achv',f:p=>bar(ach(p.total.noo,p.targetNOO))}]},
 {id:'so',t:'SO & Omzet',cls:'gSt',cc:'cSt',col:'#16a34a',cols:[{h:'Sell out',f:p=>soNum(p.total.sellout)},{h:'Omzet',f:p=>rupiah(p.total.omzet)}]}]});}
function v6EWHtml(r){
 const tg=r.run/r.days*100,left=r.days-r.run,unit={QTY:'unit',DA:'dealer',NOO:'NOO'}[r.metric],label={QTY:'SELL THRU',DA:'Dealer Aktif',NOO:'NOO'}[r.metric];
 const rows=r.rows.map(x=>{const p=x.target?x.actual/x.target*100:null,proj=r.run?x.actual/r.run*r.days:x.actual,pp=x.target?proj/x.target*100:null,rr=r.run?x.actual/r.run:0,need=x.target&&left?Math.max(0,x.target-x.actual)/left:0;return {...x,p,proj,pp,rr,need,hard:rr?need/rr:null,st:pp==null?'na':pp>=100?'good':pp>=80?'warn':'bad'};}).sort((a,b)=>(a.pp??999)-(b.pp??999));
 const c=s=>rows.filter(x=>x.st===s).length,gap=rows.reduce((n,x)=>n+Math.max(0,(x.target||0)-x.actual),0),col=s=>({good:'var(--c6-green)',warn:'var(--c6-amber)',bad:'var(--c6-red)',na:'var(--c6-muted)'})[s];
 const lvName={SALES:'Sales',ASM:'ASM',RGM:'RGM','BIG REGION':'Big Region',REGION:'Region'}[r.level]||r.level;
 const ctrl=`<div class="v6ctrl">${v6Seg('ewm',[['QTY','SELL THRU'],['DA','Dealer Aktif'],['NOO','NOO']],r.metric)}<span class="v6pill v6info">Tingkat: ${esc(lvName)}</span><span class="v6pill v6info">Brand: ${esc(r.brand==='ALL'?'Semua':r.brand)}</span><span class="hint">time gone ${pct(tg)} · sisa ${left} hari kerja · ikut filter di atas</span></div>`;
 const kp=v6Kpis([['Diproyeksikan tembus',`${c('good')} / ${rows.length}`,'proyeksi ≥ 100% target'],['Bahaya',num(c('bad')),'proyeksi &lt; 80% target'],['Waspada',num(c('warn')),'proyeksi 80–99%'],['Gap tim',num(gap)+' '+unit,left?'butuh '+num(gap/left)+' '+unit+'/hari kerja · sisa '+left+' hari kerja':'bulan selesai']]);
 const body=rows.map((x,i)=>[`<b>${i+1}</b>`,`<div class="v6who"><span class="v6av">${esc(x.nama.split(' ').slice(0,2).map(w=>w[0]).join(''))}</span><div><b>${esc(x.nama)}</b><small class="cellsub">${esc(x.bossRole||'Atasan')} ${esc(x.boss)}${x.teamSize>1?' · '+x.teamSize+' sales':''}</small></div></div>`,esc(x.region)+'<small class="cellsub">'+esc(x.big)+'</small>',x.target?num(x.target)+(x.targetComplete?'':' *'):'—',`<b>${num(x.actual)}</b>`,x.p==null?'—':`<div class="v6achc">${v6Mini(x.p,tg)}<b style="color:${col(x.st)}">${pct(x.p)}</b></div>`,x.pp==null?`<div class="v6pjc"><b>${num(x.proj)}</b></div>`:`<div class="v6pjc"><b class="v6tap" style="color:${col(x.st)}"${v6Tip({t:'Proyeksi · '+esc(x.nama),s:'Dihitung dari hari kerja',rows:[['Aktual',num(x.actual)],['Run rate',num(x.actual)+' ÷ '+r.run+' = '+decimal(x.rr)+' / hari kerja'],['Proyeksi',decimal(x.rr)+' × '+r.days+' = '+num(x.proj)],['Target',num(x.target)],['Butuh / hari kerja',left?decimal(x.need):'—']],v:x.st==='good'?['gd','Diproyeksikan tembus target.']:x.st==='warn'?['md','Waspada: proyeksi '+pct(x.pp)+' dari target.']:['bd','Bahaya: proyeksi '+pct(x.pp)+' dari target.']})}>${num(x.proj)}</b><span class="v6pjp v6pj-${x.pp>=100?'gd':x.pp>=80?'md':'bd'}">${pct(x.pp)} dari target</span></div>`,x.rr?decimal(x.rr):'—',!x.target?'—':x.actual>=x.target?'<b style="color:var(--c6-green)">✓</b>':left?`<b style="color:${x.hard>1.5||!x.rr?'var(--c6-red)':'inherit'}">${decimal(x.need)}</b> ${!x.rr?'<span class="v7rit md">belum jualan</span>':`<span class="v7rit ${x.hard>1.5?'dn':x.hard>1?'md':'up'}" title="Harus jualan ${decimal(x.hard||0)}× ritme sekarang">${decimal(x.hard||0)}× ritme</span>`}`:'—',v6Spark(x.daily7,col(x.st)),`<span class="v6pill v6${x.st==='na'?'info':x.st}">${{good:'Aman',warn:'Waspada',bad:'Bahaya',na:'Tanpa target'}[x.st]}</span>`,(String(x.nik).startsWith('AREA:')?'':`<button type="button" class="chip" data-person="${esc(x.nik)}">Detail →</button>`)]);
 if(rows.length){const wt=rows.filter(x=>x.target),T=wt.reduce((n,x)=>n+x.target,0),A=rows.reduce((n,x)=>n+(x.actual||0),0),TA=wt.reduce((n,x)=>n+(x.actual||0),0),PJ=wt.reduce((n,x)=>n+(x.proj||0),0),RRt=rows.reduce((n,x)=>n+(x.rr||0),0),inc=wt.some(x=>!x.targetComplete)||wt.length<rows.length,tp=T?TA/T*100:null,ppT=T?PJ/T*100:null;body.push(['Total',`<b>${rows.length} ${esc(lvName)}</b>`,'',T?'<b>'+num(T)+'</b>'+(inc?' *':''):'—','<b>'+num(A)+'</b>',tp==null?'—':`<div class="v6achc">${v6Mini(tp,tg)}<b>${pct(tp)}</b></div>`,T?'<div class="v6pjc"><b>'+num(PJ)+'</b><span class="hint">'+pct(ppT)+' dari target</span></div>':'—',RRt?decimal(RRt):'—',left&&T?'<b>'+decimal(Math.max(0,T-TA)/left)+'</b>':'—','','','']);}
 const note=`<div class="v6note">Urut dari yang paling jauh dari target. <b>Proyeksi</b> = aktual ÷ ${r.run} hari kerja × ${r.days} hari kerja (Minggu & Hari_Libur tidak dihitung). <b>Butuh/hari ×2,0</b> = harus jualan 2× ritme sekarang. Tren = unit SELL THRU 7 hari kerja terakhir (${tgl(r.last7[0])}–${tgl(r.last7[r.last7.length-1])}). ${r.metric!=='QTY'?'Proyeksi '+label+' bersifat perkiraan karena tidak selalu naik rata per hari.':''} * target belum lengkap.</div>`;
 window.v12EW={rows,tg,left,lvName,col,unit};
 return `<section class="panel"><div class="ph"><h3>Early Warning · ${esc(label)}</h3><span class="hint">Siapa yang proyeksinya belum tembus target</span></div><div class="pb">${ctrl}${kp}<div class="v6dailyTable v6ewTable">${table(['#',lvName,'Region','Target','Aktual','Ach vs time gone','Proyeksi','Run rate','Butuh/hari','Tren 7 hari','Status',''],body)}</div>${note}</div></section>`;
}
function v6BindEW(seq){document.querySelectorAll('[data-ewm]').forEach(b=>b.onclick=()=>{v6EW.metric=b.dataset.ewm;v6LoadEW(seq);});document.querySelectorAll('#v6EW [data-person]').forEach(b=>b.onclick=()=>person(b.dataset.person));if(typeof addTopTableScroll==='function')addTopTableScroll($('v6EW'));}


/* ===== v6.10: MENU ANALISA (filter bertingkat Big Region > Region > RGM > ASM > Sales) ===== */
let v6NooSets={};let v6ANA=null,v6AnaTab='cross',v6ReFilter='ALL',v6AF={BIG:'ALL',REGION:'ALL',RGM:'ALL',ASM:'ALL',SALES:'ALL'};
const V6LV=[['BIG','Big Region'],['REGION','Region'],['RGM','RGM'],['ASM','ASM'],['SALES','Sales']];
const v6OrgCache=new Map();function v6Org(nik){if(!v6OrgCache.has(nik))v6OrgCache.set(nik,v6OrgOf(nik));return v6OrgCache.get(nik);}
function v6Pass(nik,upto){const o=v6Org(nik);for(const [k] of V6LV){if(upto===k)return true;if(v6AF[k]!=='ALL'&&o[k]!==v6AF[k])return false;}return true;}
function v6AnaNiks(){if(!v6ANA)return [];return v6AnaTab==='cross'?v6ANA.crossSell.dealers.map(d=>d.nik):v6AnaTab==='react'?v6ANA.reactivation.rows.map(r=>r.nik):v6ANA.noo.pairs.map(p=>p.nik);}
function v6FilterBar(){const niks=[...new Set(v6AnaNiks())];return `<div class="v6fbar">${V6LV.map(([k,l])=>{const opts=[...new Set(niks.filter(n=>v6Pass(n,k)).map(n=>v6Org(n)[k]))].filter(x=>x&&x!=='—').sort((a,b)=>a.localeCompare(b,'id'));if(v6AF[k]!=='ALL'&&!opts.includes(v6AF[k]))v6AF[k]='ALL';return `<label>${l}<select class="fi" data-v6af="${k}"><option value="ALL">Semua ${l}</option>${opts.map(o=>`<option ${o===v6AF[k]?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;}).join('')}<button type="button" class="chip" id="v6AFReset">Reset</button></div>`;}
async function v6AnalisaView(v,seq){
 v.innerHTML=`<div class="v6anaHead">${v6Seg('anatab',[['cross','⊞ Cross-sell Brand'],['react','↻ Reaktivasi Dealer'],['noo','★ Dealer Baru']],v6AnaTab)}<span class="hint">Data s.d. ${tgl(REPORT.coverage.cutoff)} · sesuai cakupan</span></div><div id="v6AnaFilter"></div><div id="v6AnaBody"><div class="empty">Menghitung analisa…</div></div>`;
 const key=(BOOT&&BOOT.user?BOOT.user.nik:'')+'|'+TOKEN+'|'+REPORT.period+'|'+$('scopeSelect').value;
 try{if(!v6ANA||v6ANA._key!==key){v6ANA=await rpc('apiAnalisa',TOKEN,REPORT.period,$('scopeSelect').value);v6ANA._key=key;}if(seq!==SEQUENCE)return;v6AnaDraw();}
 catch(e){if($('v6AnaBody'))$('v6AnaBody').innerHTML='<div class="banner bad">'+esc(e.message)+'</div>';}
 document.querySelectorAll('[data-anatab]').forEach(b=>b.onclick=()=>{v6AnaTab=b.dataset.anatab;document.querySelectorAll('[data-anatab]').forEach(x=>x.classList.toggle('on',x===b));v6AnaDraw();});
}
function v6AnaDraw(){const box=$('v6AnaBody');if(!box||!v6ANA)return;
 $('v6AnaFilter').innerHTML=v6FilterBar();
 $('v6AnaFilter').querySelectorAll('[data-v6af]').forEach(s=>s.onchange=()=>{const k=s.dataset.v6af,i=V6LV.findIndex(x=>x[0]===k);v6AF[k]=s.value;V6LV.slice(i+1).forEach(([x])=>v6AF[x]='ALL');v6AnaDraw();});
 $('v6AFReset').onclick=()=>{V6LV.forEach(([x])=>v6AF[x]='ALL');v6AnaDraw();};
 box.innerHTML=v6AnaTab==='cross'?v6CrossHtml(v6ANA.crossSell):v6AnaTab==='react'?v6ReactHtml(v6ANA.reactivation):v6NooHtml(v6ANA.noo);
 box.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>detail(b.dataset.customer));
 box.querySelectorAll('[data-noopop]').forEach(b=>b.onclick=()=>v6NooPopup(b.dataset.noopop));
 box.querySelectorAll('[data-refilter]').forEach(b=>b.onclick=()=>{v6ReFilter=b.dataset.refilter;v6AnaDraw();});
 box.querySelectorAll('[data-v6opp]').forEach(b=>b.onclick=()=>{const [id,brand]=JSON.parse(b.dataset.v6opp),d=v6ANA.crossSell.dealers.find(x=>x.id===id)||{},est=d.cells?.[brand]?.est||0;modal('Peluang '+brand+' · '+(d.nama||id),`<div class="v6popHead"><div class="v6stat"><div class="l">Estimasi potensi</div><div class="v">± ${num(est)} unit/bln</div><div class="s">median dealer sejenis</div></div><div class="v6stat"><div class="l">Order dealer ini</div><div class="v">${decimal(d.avg||0)} unit/bln</div><div class="s">${d.taken||0} brand diambil</div></div><div class="v6stat"><div class="l">Sales</div><div class="v" style="font-size:15px">${esc(d.sales||'—')}</div><div class="s">${esc(d.kota||'')}</div></div></div><div class="toolbar">${v6Wa(d.hp,'Halo '+(d.nama||'')+', ada program '+brand+' bulan ini. Boleh kami tawarkan?','Tawarkan via WhatsApp')}<button type="button" class="chip" data-customer="${esc(id)}">Lihat detail dealer →</button></div>`);$('mbody').querySelectorAll('[data-customer]').forEach(x=>x.onclick=()=>detail(x.dataset.customer));});
 if(typeof addTopTableScroll==='function')addTopTableScroll(box);}
function v6CrossHtml(cs){
 const ds=cs.dealers.filter(d=>v6Pass(d.nik)),opps=[];ds.forEach(d=>cs.brands.forEach(b=>{const x=d.cells[b];if(x&&!x.has&&x.est)opps.push({...d,brand:b,est:x.est});}));opps.sort((a,b)=>b.est-a.est||b.avg-a.avg);
 const avgB=ds.length?ds.reduce((n,d)=>n+d.taken,0)/ds.length:0;
 const kp=v6Kpis([['Dealer aktif',num(ds.length),'order bulan ini / bulan lalu'],['Peluang terbuka',num(opps.length),'pasangan dealer × brand'],['Estimasi potensi','± '+num(opps.reduce((n,o)=>n+o.est,0)*0.3)+' unit','per bulan jika 30% terkonversi'],['Rata-rata brand / dealer',decimal(avgB),'dari '+cs.brands.length+' brand']]);
 const show=ds.slice(0,80),head=['Dealer',...cs.brands.map(esc),'Brand'],body=show.map(d=>[`<button class="textlink" data-customer="${esc(d.id)}">${esc(d.nama)}</button><small class="cellsub">${esc(d.kota)} · ${esc(d.sales)} · ${decimal(d.avg)} unit/bln</small>`,...cs.brands.map(b=>{const x=d.cells[b]||{};return x.has?`<span class="v6ws has" title="${esc(b)}: rata-rata ${decimal(x.avg)} unit/bln selama 3 bulan terakhir">${x.avg<1?decimal(x.avg):num(x.avg)}</span>`:x.est?`<button type="button" class="v6ws opp v6tipD" data-v6opp='${esc(JSON.stringify([d.id,b]))}'${v6Tip({t:'Peluang '+esc(b)+' · ± '+x.est+' unit/bln',s:'Estimasi order bulanan kalau dealer ini mulai ambil '+esc(b)+'.',rows:[['Estimasi','± '+x.est+' unit/bln'],['Dasar','median order'],['Pembanding',num(x.n||0)+' dealer sudah ambil'],['Cakupan',esc(x.basis||'cakupan sejenis')],['Periode','3 bulan terakhir'],['Batas atas','50% dari '+decimal(d.avg)+' unit/bln']],v:['md','Dealer ini belum ambil '+esc(b)+' dalam 3 bulan terakhir.']})}>+${x.est}</button>`:'<span class="v6ws none">–</span>';}),`<b>${d.taken}</b>/${cs.brands.length}`]);
 const top=opps.slice(0,12).map((o,i)=>`<div class="v6opp"><span class="v6rk">${i+1}</span><div><button class="textlink" data-customer="${esc(o.id)}">${esc(o.nama)}</button><div class="hint">Belum ambil <b style="color:#8A5E00">${esc(o.brand)}</b> · order ${decimal(o.avg)} unit/bln · ${esc(o.sales)}</div></div><div class="v6oppR"><b>± ${num(o.est)} unit</b>${v6Wa(o.hp,'Halo '+o.nama+', ada program '+o.brand+' bulan ini. Boleh kami tawarkan?','Tawarkan')}</div></div>`).join('')||'<div class="empty">Belum ada peluang pada filter ini.</div>';
 return kp+`<div class="v6stack">`+panel('Matriks dealer × brand',`<div class="v6legend"><span><i style="background:#DDEBFA"></i>Sudah ambil (angka = unit/bln, ${cs.months.length} bulan)</span><span><i style="background:#FFF3DC;border:1.5px dashed #E0A93A"></i>Peluang (klik)</span><span><i style="background:#F4F6F9"></i>Belum ada pembanding</span></div><div class="v6dailyTable v6csTable">${table(head,body)}</div><div class="v6note">Estimasi = median ST/bulan brand itu di dealer sejenis — pembanding Sub Region (min 5 dealer), kalau kurang naik ke Region, lalu Nasional — maks 50% dari rata-rata ST per bulan dealer. Menampilkan ${num(show.length)} dari ${num(ds.length)} dealer (terbesar dulu).</div>`,'Klik kotak kuning untuk detail & WhatsApp')+panel('Top peluang minggu ini',top,'Urut estimasi potensi')+`</div>`;
}
function v6ReactHtml(re){
 const base=re.rows.filter(r=>v6Pass(r.nik)),f=v6ReFilter,rows=base.filter(r=>f==='ALL'||r.status===f),cls={'DA BULAN LALU':'warn','IDLE':'vio','PASIF':'bad'},back=re.reactivated.filter(n=>v6Pass(n)).length;
 const kp=v6Kpis([['Dealer perlu dihubungi',num(base.length),'DA bulan lalu · Idle · Pasif'],['Potensi hilang','± '+num(base.reduce((n,r)=>n+r.avg,0))+' unit','rata-rata/bulan mereka dulu'],['Paling mudah',num(base.filter(r=>r.status==='DA BULAN LALU').length),'DA bulan lalu (baru 1 bulan)'],['Berhasil aktif lagi',num(back),'bulan ini order lagi setelah absen']]);
 const list=rows.slice(0,80).map((r,i)=>`<article class="v6dcard"><div class="v6who"><span class="v6av ${i<3?'hot':''}">${i+1}</span><div><button class="textlink" data-customer="${esc(r.id)}">${esc(r.nama)}</button> <span class="v6pill v6${cls[r.status]}">${esc(r.status)}</span><small class="cellsub">${esc(r.kota)} · Sales ${esc(r.sales)} · terakhir order ${r.last?tgl(r.last)+' ('+num(r.jeda)+' hari lalu)':'—'}</small></div></div><div class="v6dmid"><div class="v6pot">Rata-rata dulu<b>${decimal(r.avg)} unit/bln</b></div><div class="v6pot">${re.months.length} bulan terakhir${v6Spark(r.series,'#7A5AF8',110,28)}<small>${re.months.map(v6Mon).join(' · ')}</small></div></div><div class="v6dact">${v6Wa(r.hp,'Halo '+r.nama+', sudah lama belum order. Ada stok & program baru bulan ini, boleh kami bantu?','WhatsApp')}<button type="button" class="chip" data-customer="${esc(r.id)}">Riwayat →</button></div></article>`).join('')||'<div class="empty">Tidak ada dealer untuk filter ini.</div>';
 return kp+panel('Daftar telepon · prioritas',`<div class="v6ctrl">${v6Seg('refilter',[['ALL','Semua'],['DA BULAN LALU','DA bulan lalu'],['IDLE','Idle'],['PASIF','Pasif']],f)}<span class="hint">${num(rows.length)} dealer${rows.length>80?' · tampil 80 teratas':''} · skor = rata-rata unit × peluang kembali</span></div>${list}<div class="v6note">DA bulan lalu = order bulan lalu, belum order bulan ini · Idle = terakhir order 2 bulan lalu · Pasif = lebih lama lagi. Rata-rata dihitung dari bulan yang ada order-nya.</div>`,'Urut dari potensi terbesar');
}
function v6NooHtml(n){
 const P=n.pairs.filter(p=>v6Pass(p.nik)),L=P.filter(p=>p.m===n.prev),C=P.filter(p=>p.m===n.current),pc0=(a,b)=>b?a/b*100:null,pp=v=>v==null?'—':pct(v);
 const fl={base:L.length,rep:L.filter(p=>p.pres[1]).length,act:L.filter(p=>p.qCur>=2).length,multi:L.filter(p=>p.pres[1]&&p.multi>=2).length};
 const fc={base:C.length,rep:C.filter(p=>p.again).length,act:C.filter(p=>p.qCur>=2).length,multi:C.filter(p=>p.multi>=2).length};
 const dBase=fl.base?(fc.base-fl.base)/fl.base*100:null,mP=bulan(n.prev),mC=bulan(n.current);
 const kp=v6Kpis([['Dealer baru '+esc(mC)+' (MTD)',num(fc.base),dBase==null?'bulan lalu belum ada':`${dBase>=0?'▲':'▼'} ${pct(Math.abs(dBase))} vs ${esc(mP)} (${num(fl.base)})`],['Dealer baru '+esc(mP),num(fl.base),'sebulan penuh'],['Order lagi · '+esc(mP),pp(pc0(fl.rep,fl.base)),num(fl.rep)+' dari '+num(fl.base)+' order di '+esc(mC)],['Order lagi · '+esc(mC),pp(pc0(fc.rep,fc.base)),num(fc.rep)+' dari '+num(fc.base)+' order ulang di bulan yang sama']]);
 const fun=(f,label,rows,defs)=>{const b=Math.max(1,f.base);return `<div class="v6funHead">${esc(label)}</div><div class="v6funnel">${defs.map(s=>`<button type="button" class="v6fr v6frBtn" data-noopop="${s[3]}" title="Klik untuk lihat daftar dealer"><b>${esc(s[0])}</b><div class="v6fb"><i style="width:${s[1]/b*100}%;background:${s[2]}"></i><span>${num(s[1])}</span></div><b style="text-align:right">${f.base?pct(s[1]/b*100,0):'—'}</b></button>`).join('')}</div>`;};
 v6NooSets={'L0':['Dealer baru '+mP,L],'L1':['Dealer baru '+mP+' yang order lagi di '+mC,L.filter(p=>p.pres[1])],'L2':['Dealer baru '+mP+' dengan SELL THRU ≥2 di '+mC,L.filter(p=>p.qCur>=2)],'L3':['Dealer baru '+mP+' yang order lagi & ambil ≥2 brand di '+mC,L.filter(p=>p.pres[1]&&p.multi>=2)],'C0':['Dealer baru '+mC,C],'C1':['Dealer baru '+mC+' yang order ulang di bulan yang sama',C.filter(p=>p.again)],'C2':['Dealer baru '+mC+' dengan SELL THRU ≥2 bulan ini',C.filter(p=>p.qCur>=2)],'C3':['Dealer baru '+mC+' yang ambil ≥2 brand bulan ini',C.filter(p=>p.multi>=2)]};
 const cmp=`<div class="v6cmp2"><div class="v6cmpBox">${fun(fl,mP+' · sebulan penuh',L,[['Dealer baru',fl.base,'#0A2E57','L0'],['Order lagi di '+mC,fl.rep,'#0B5CAD','L1'],['SELL THRU ≥2 di '+mC,fl.act,'#12A86B','L2'],['Ambil ≥2 brand di '+mC,fl.multi,'#7A5AF8','L3']])}</div><div class="v6cmpBox cur">${fun(fc,mC+' · berjalan s.d. '+tgl(REPORT.coverage.cutoff),C,[['Dealer baru',fc.base,'#0A2E57','C0'],['Order ulang bulan ini',fc.rep,'#0B5CAD','C1'],['SELL THRU ≥2 bulan ini',fc.act,'#12A86B','C2'],['Ambil ≥2 brand bulan ini',fc.multi,'#7A5AF8','C3']])}</div></div>`;
 const bySales={};P.filter(p=>p.m===n.prev||p.m===n.current).forEach(p=>{const s=bySales[p.nik]||(bySales[p.nik]={nik:p.nik,l:0,lr:0,c:0,cr:0});if(p.m===n.prev){s.l++;if(p.pres[1])s.lr++;}else{s.c++;if(p.again)s.cr++;}});
 const sRows=Object.values(bySales).sort((a,b)=>(b.l+b.c)-(a.l+a.c)).map(s=>{const o=v6Org(s.nik),a=s.l?s.lr/s.l*100:null,d=s.c-s.l;return [esc(o.SALES)+`<small class="cellsub">${esc(o.REGION)} · ${esc(o.BIG)}</small>`,num(s.l),num(s.lr),a==null?'—':`<div class="v6achc">${v6Mini(a,60)}<b>${pct(a)}</b></div>`,`<b>${num(s.c)}</b>`,num(s.cr),`<b style="color:${d>=0?'var(--c6-green)':'var(--c6-red)'}">${d>=0?'+':''}${num(d)}</b>`];});
 const ps=table(['Sales',esc(mP)+' · baru','Order lagi','% order lagi',esc(mC)+' · baru','Order lagi','Selisih baru'],sRows);
 const coh=n.months.filter(m=>m!==n.current).map(m=>{const list=P.filter(p=>p.m===m);if(!list.length)return null;const len=list[0].pres.length;return {m,count:list.length,cells:Array.from({length:len},(_,k)=>k?Math.round(list.filter(p=>p.pres[k]).length/list.length*100):100)};}).filter(Boolean).slice(-5);
 const maxK=Math.max(1,...coh.map(c=>c.cells.length)),cohT=coh.length?table(['Bulan jadi dealer baru','Jumlah',...Array.from({length:maxK},(_,k)=>k?'Bulan ke-'+k:'Bulan pertama')],coh.map(c=>[esc(bulan(c.m)),num(c.count),...Array.from({length:maxK},(_,k)=>{const v=c.cells[k];if(v==null)return '<span class="hint">–</span>';const last=k===c.cells.length-1&&k>0&&!REPORT.coverage.closed;return `<span class="v6heat" style="background:rgba(18,168,107,${(0.12+v/100*0.8).toFixed(2)});color:${v>55?'#fff':'#0B5E45'}" title="${last?'bulan berjalan (belum penuh)':''}">${v}%${last?'*':''}</span>`;})])):'<div class="empty">Belum ada data dealer baru untuk filter ini.</div>';
 return kp+panel('Dealer Baru: Order Lagi atau Nggak?',cmp+`<div class="v6note"><b>Klik batang mana saja</b> untuk melihat daftar dealernya. Kiri: dealer baru bulan lalu, dicek aktivitasnya di bulan ini (bulan ini baru berjalan ${num(v6Pace(REPORT).run)} hari). Kanan: dealer baru bulan ini, dicek aktivitasnya di bulan yang sama. Dihitung per pasangan dealer × brand, sama seperti NOO.</div>`,'Bulan lalu vs bulan berjalan')+panel('Per sales · bulan lalu vs bulan ini',`<div class="v6dailyTable">${ps}</div>`,'Urut jumlah dealer baru')+panel('Dealer Baru per Bulan: Masih Order Sampai Sekarang?',`<div class="v6dailyTable">${cohT}</div><div class="v6note">Baca per baris: dari dealer yang jadi dealer baru di bulan itu, berapa persen yang masih order di bulan-bulan berikutnya. * = bulan berjalan, belum penuh.</div>`,'Makin hijau makin bagus');
}

function v6NooPopup(k){const [title,list]=v6NooSets[k]||['',[]],n=v6ANA.noo,rows=list.slice().sort((a,b)=>(b.qCur-a.qCur)||(b.qM-a.qM)||a.n.localeCompare(b.n,'id'));
 const body=rows.map(p=>{const o=v6Org(p.nik);return [`<button class="textlink" data-customer="${esc(p.c)}">${esc(p.n)}</button><small class="cellsub">${esc(p.c)} · ${esc(p.k)}</small>`,esc(p.b),esc(o.SALES)+`<small class="cellsub">${esc(o.REGION)}</small>`,tgl(p.d),num(p.qM),p.m===n.current?'—':num(p.qCur),(p.bl&&p.bl.length?p.bl.map(x=>`<span class="v6bchip ${x===p.b?'on':''}">${esc(x)}</span>`).join(' '):'<span class="hint">belum ada</span>'),p.last?tgl(p.last):'—',v6Wa(p.hp,'Halo '+p.n+', terima kasih sudah order '+p.b+'. Ada stok & program bulan ini, boleh kami bantu order lagi?','WA')];});
 modal(title+' · '+num(rows.length)+' pasangan',`<div class="v6note" style="margin:0 0 10px">Satu baris = satu pasangan dealer × brand (definisi NOO). <b>SELL THRU bulan pertama</b> = total SELL THRU brand itu di bulan dealer pertama kali order. <b>SELL THRU bulan ini</b> = SELL THRU brand itu di ${esc(bulan(n.current))} s.d. ${tgl(REPORT.coverage.cutoff)} (0 = belum order lagi). <b>Brand diambil bulan ini</b> = brand apa saja yang diambil dealer ini di bulan ini (yang disorot = brand baris ini). Semua dari data SELL THRU, bukan SELL OUT.</div><div class="v6dailyTable">${table(['Dealer','Brand','Sales','Order pertama','SELL THRU bulan pertama','SELL THRU bulan ini','Brand diambil bulan ini','Order terakhir','Hubungi'],body)}</div>`);
 $('mbody').querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>detail(b.dataset.customer));if(typeof addTopTableScroll==='function')addTopTableScroll($('mbody'));}
document.addEventListener('click',e=>{const b=e.target.closest('[data-v6brand]');if(!b)return;const s=document.getElementById('detailBrand');if(!s)return;s.value=b.dataset.v6brand;s.dispatchEvent(new Event('change',{bubbles:true}));});

/* ===== v6.19: hari kerja (Minggu + Hari_Libur tidak dihitung) ===== */
function v6Off(d){return new Date(d+'T00:00:00').getDay()===0||((typeof BOOT!=='undefined'&&BOOT&&BOOT.v6hol)||[]).includes(d);}
function v6Hol(d){return ((typeof BOOT!=='undefined'&&BOOT&&BOOT.v6hol)||[]).includes(d);}
function v6WorkUpTo(period,day){let n=0;for(let i=1;i<=day;i++)if(!v6Off(period+'-'+String(i).padStart(2,'0')))n++;return n;}

/* ===== v6.19: tooltip angka — desktop hover (kotak gelap), HP tap (panel dari bawah) ===== */
const V6TIPS=new Map();let v6TipSeq=0;
function v6Tip(o){if(V6TIPS.size>6000)V6TIPS.clear();const id='t'+(++v6TipSeq);V6TIPS.set(id,o);return ` data-v6tip="${id}"`;}
function v6TipShort(text){return v6Tip({short:text});}
function v6IsTouch(){return (typeof isMobile==='function'&&isMobile())||window.matchMedia('(hover:none)').matches;}
function v6TipHtml(o,full){if(o.short)return `<div class="v6tt-s">${o.short}</div>`;const mx=o.m?Math.max(1,...o.m):1;
 return `${o.t?`<div class="v6tt-t">${o.t}</div>`:''}${o.s?`<div class="v6tt-sub">${o.s}</div>`:''}${full&&o.m&&o.m.length?`<div class="v6tt-mini">${o.m.map((v,i)=>`<i class="${i===o.m.length-1&&o.mNow?'now':''}" style="height:${Math.max(4,v/mx*100)}%"></i>`).join('')}</div><div class="v6tt-ml">${(o.ml||[]).map(x=>`<span>${x}</span>`).join('')}</div>`:''}${o.rows?`<div class="v6tt-rows">${o.rows.map(r=>`<div><span>${r[0]}</span><b>${r[1]}</b></div>`).join('')}</div>`:''}${o.v?`<div class="v6tt-v v6tt-${o.v[0]}">${o.v[1]}</div>`:''}`;}
(function(){
 let box=null,sheet=null;
 const ensure=()=>{if(box)return;box=document.createElement('div');box.className='v6tipbox';document.body.appendChild(box);
  sheet=document.createElement('div');sheet.className='v6sheetWrap';sheet.innerHTML='<div class="v6shade"></div><div class="v6sheet" role="dialog" aria-modal="true"><div class="v6grab"></div><div class="v6sheetBody"></div><button type="button" class="v6sheetClose">Tutup</button></div>';document.body.appendChild(sheet);
  const close=()=>sheet.classList.remove('on');sheet.querySelector('.v6shade').onclick=close;sheet.querySelector('.v6sheetClose').onclick=close;
  let y0=null;const sh=sheet.querySelector('.v6sheet');sh.addEventListener('touchstart',e=>{y0=e.touches[0].clientY;},{passive:true});sh.addEventListener('touchend',e=>{if(y0!=null&&e.changedTouches[0].clientY-y0>60)close();y0=null;});};
 const hide=()=>{if(box)box.style.display='none';};
 document.addEventListener('mouseover',e=>{if(v6IsTouch())return;const el=e.target.closest&&e.target.closest('[data-v6tip]');if(!el){hide();return;}const o=V6TIPS.get(el.dataset.v6tip);if(!o)return;ensure();
  box.innerHTML=v6TipHtml(o,false);box.style.display='block';const r=el.getBoundingClientRect(),w=box.offsetWidth,h=box.offsetHeight;let x=r.left+r.width/2-w/2;x=Math.max(8,Math.min(x,window.innerWidth-w-8));let y=r.bottom+8,up=false;if(y+h>window.innerHeight-8){y=r.top-h-8;up=true;}
  box.style.left=x+'px';box.style.top=y+'px';box.classList.toggle('up',up);box.style.setProperty('--ax',Math.max(10,Math.min(w-16,r.left+r.width/2-x-6))+'px');});
 window.addEventListener('scroll',hide,true);
 document.addEventListener('click',e=>{if(!v6IsTouch())return;const el=e.target.closest&&e.target.closest('[data-v6tip]');if(!el||el.classList.contains('v6tipD'))return;const o=V6TIPS.get(el.dataset.v6tip);if(!o)return;e.preventDefault();e.stopPropagation();ensure();
  if(o.short){const host=el.closest('.pb')||el.parentElement;document.querySelectorAll('.v6tipSel').forEach(x=>x.classList.remove('v6tipSel'));el.classList.add('v6tipSel');let n=host.querySelector(':scope > .v6tipnote');if(!n){n=document.createElement('div');n.className='v6tipnote';host.appendChild(n);}n.innerHTML=o.short;return;}
  sheet.querySelector('.v6sheetBody').innerHTML=v6TipHtml(o,true);sheet.classList.add('on');},true);
})();
const V6STATUS={'AKTIF':'Order minimal 2 unit di bulan ini.','BELUM MINIMUM DA':'Sudah order bulan ini, tapi belum mencapai minimal unit Dealer Aktif.','DA BULAN LALU':'Order di bulan lalu, belum order di bulan ini.','IDLE':'Terakhir order dua bulan lalu.','PASIF':'Tiga bulan terakhir tanpa order.','BELUM ORDER':'Belum pernah order di periode yang dipantau.'};
function v6CardTip(label,actual,target,pc,prev,unit){const path=target?target*pc.tg/100:0,rows=[['Aktual',num(actual)+' '+unit]];if(target){rows.push(['Target',num(target)]);rows.push(['Estimasi s.d. hari ini ('+pc.run+'/'+pc.days+' hari kerja)',num(path)]);}if(prev!=null)rows.push([REPORT.coverage.closed?'Bulan lalu':'Bulan lalu di tanggal yang sama',num(prev)+(prev?' ('+(actual>=prev?'+':'')+pct((actual-prev)/prev*100)+')':'')]);
 const p=path?actual/path*100:null;return v6Tip({t:label+' · '+esc(bulan(REPORT.period)),s:REPORT.coverage.closed?'Bulan penuh':'s.d. '+tgl(REPORT.coverage.cutoff),rows,v:p==null?null:p>=100?['gd','Sesuai / di atas estimasi ('+pct(p)+' dari estimasi s.d. hari ini).']:p>=70?['md','Agak ketinggalan ('+pct(p)+' dari estimasi s.d. hari ini).']:['bd','Jauh di bawah estimasi ('+pct(p)+' dari estimasi s.d. hari ini).']});}

/* ===== v6.19: DOS — filter baru dimuat saat klik Terapkan ===== */
function v6DosBind(){const ids=['dosRegion','dosSubRegion','dosBrand','dosType','dosStatus','dosQuery'],keys=['region','subRegion','brand','type','status','query'],btn=$('dosApply');if(!btn)return;
 const mark=()=>{let n=0;ids.forEach((id,i)=>{const el=$(id);if(!el)return;const ch=String(el.value)!==String(dosFilter[keys[i]]??'');el.classList.toggle('v6chg',ch);if(ch)n++;});
  btn.classList.toggle('v6pulse',n>0);btn.textContent=n?`Terapkan (${n})`:'Terapkan';const tb=btn.closest('.toolbar');let w=$('v6dosPend');
  if(n){if(!w){w=document.createElement('div');w.id='v6dosPend';w.className='v6pend';tb.after(w);}w.textContent='⚠ '+n+' filter diubah dan belum diterapkan. Data di bawah masih memakai filter lama — klik Terapkan.';}else if(w)w.remove();
  let el=tb.nextElementSibling;while(el){if(el.id!=='v6dosPend')el.classList.toggle('v6stale',n>0);el=el.nextElementSibling;}};
 $('dosRegion').onchange=()=>{const reg=$('dosRegion').value,subs=[...new Set(BOOT.people.filter(p=>reg==='ALL'||p.wilayah===reg).map(p=>p.portfolio||p.region).filter(Boolean))].sort();$('dosSubRegion').innerHTML='<option value="ALL">Semua</option>'+subs.map(x=>`<option>${esc(x)}</option>`).join('');mark();};
 $('dosBrand').onchange=()=>{const b=$('dosBrand').value,cur=$('dosType').value,types=[...new Set((REPORT.types||[]).filter(t=>b==='ALL'||t.brand===b).map(t=>t.type))].sort();$('dosType').innerHTML='<option value="ALL">Semua</option>'+types.map(x=>`<option ${x===cur?'selected':''}>${esc(x)}</option>`).join('');mark();};
 ['dosSubRegion','dosType','dosStatus'].forEach(id=>$(id)&&$(id).addEventListener('change',mark));$('dosQuery')&&$('dosQuery').addEventListener('input',mark);mark();}

/* ===== v6.19: Daftar dealer — potensi per brand & GAP POTENSI ===== */
let v6POT={key:'',data:null,loading:false};
function v6PotLoad(){const key=REPORT.period+'|'+$('scopeSelect').value;if(v6POT.key===key&&(v6POT.data||v6POT.loading))return;v6POT={key,data:null,loading:true};
 rpc('apiPotensi',TOKEN,REPORT.period,$('scopeSelect').value).then(d=>{if(v6POT.key!==key)return;v6POT.data=d;v6POT.loading=false;const r=$('customerRows');if(r&&r._redraw)r._redraw();}).catch(e=>{if(v6POT.key===key){v6POT.loading=false;v6POT.err=e.message;}});}
function v6PotOf(c,b){return v6POT.data?.map?.[c.id]?.[b]||null;}
function v6PotExp(p){const d=v6POT.data;return p&&d?p.v*d.run/Math.max(1,d.days):0;}
/* Status dealer per brand (AKTIF/IDLE/PASIF/NOO). Dealer yang belum pernah order brand tersebut dikosongkan. Ambang idle/pasif per brand: Admin › Master › Brand. */
const V6BSL={BULAN:'BULAN LALU'};
const V6BSC={AKTIF:'#0E7C6B',IDLE:'#b25e09',PASIF:'#c0392b',NOO:'#6D3FD8'};
function v6BsBadge(c,b){const s=c.bs&&c.bs[b];return s?`<span class="bsb bs-${s}">${V6BSL[s]||s}</span>`:'';}
function v6BsMatch(c,sel){const bs=c.bs||{},f=customerFilter.brand,m=x=>x==='BULAN'?'DA BULAN LALU':x;if(f&&f!=='ALL')return sel.includes(m(bs[f]));return sel.includes('NOO')&&Object.values(bs).includes('NOO');}
function v6BsDetail(c){const bs=c.bs||{},r=c.bsr||{},ks=Object.keys(bs);if(!ks.length)return '';const why=k=>{const x=r[k]||{};if(bs[k]==='NOO')return 'Order pertama brand ini bulan ini';if(bs[k]==='AKTIF')return 'Ada order bulan ini';if(bs[k]==='BULAN')return 'Terakhir order '+x.last+', belum order bulan ini (idle mulai '+x.idle+' bulan tanpa order)';return 'Terakhir order '+x.last+', '+x.gap+' bulan tanpa order (idle ≥ '+x.idle+', pasif ≥ '+x.pasif+' bulan)';};return `<section class="v6bsd"><h4>Status per brand</h4>${ks.map(k=>`<div class="v6bsRow"><b>${esc(k)}</b><span class="bsb bs-${bs[k]}">${V6BSL[bs[k]]||bs[k]}</span><small>${esc(why(k))}</small></div>`).join('')}</section>`;}
function v6BsSummary(c){const bs=c.bs||{},f=customerFilter.brand;if(f&&f!=='ALL')return bs[f]?[bs[f],f+' · '+(V6BSL[bs[f]]||bs[f])]:null;const vals=Object.entries(bs);if(!vals.length)return null;for(const k of ['PASIF','IDLE','NOO','BULAN']){const n=vals.filter(x=>x[1]===k),L=V6BSL[k]||k;if(n.length)return [k,n.length>1?L+' di '+n.length+' brand':L+' di '+n[0][0]];}return ['AKTIF','AKTIF SEMUA'];}
function v6Qty(c,b){return c.brands.find(x=>x.brand===b)?.qty||0;}
function v6Gap(c){if(!v6POT.data)return 0;return Math.round(REPORT.brands.reduce((n,b)=>{const p=v6PotOf(c,b.brand);return p?n+Math.max(0,v6PotExp(p)-v6Qty(c,b.brand)):n;},0));}
function v6PotCell(c,b){return v6PotCell0(c,b)+v6BsBadge(c,b);}
function v6PotCell0(c,b){const q=v6Qty(c,b);if(!v6POT.data)return num(q);const p=v6PotOf(c,b),d=v6POT.data;if(!p)return `<div class="v6pc v6pc-na"><b>${num(q)}</b><small>—</small></div>`;
 const exp=v6PotExp(p),path='Estimasi s.d. hari ini ('+d.run+'/'+d.days+' hari kerja)';
 if(p.k==='p'&&q<=0)return `<div class="v6pc v6pc-op"${v6Tip({t:'Peluang '+esc(b)+' · '+esc(c.nama),s:'Dealer ini belum ambil '+esc(b)+' dalam 3 bulan terakhir',rows:[['Pembanding',num(p.n)+' dealer '+esc(p.l)],['Median dealer sejenis','~'+num(p.v)+' / bulan'],[path,num(exp)]],v:['op','Peluang cross-sell ~'+num(p.v)+' unit / bulan.']})}><b>0</b><small>peluang ~${num(p.v)}</small></div>`;
 const ratio=exp>0?q/exp:1,cls=ratio>=1?'gd':ratio>=0.7?'md':'bd',diff=q-exp;
 const rows=(p.k==='h'?[[d.months.map(v6Mon).join(' · '),p.m.map(num).join(' · ')],['Potensi / bulan',num(p.v)]]:[['Pembanding',num(p.n)+' dealer '+esc(p.l)],['Potensi / bulan','~'+num(p.v)]]).concat([[path,num(exp)],['Aktual',num(q)]]);
 return `<div class="v6pc v6pc-${cls}"${v6Tip({t:esc(b)+' · '+esc(c.nama),s:p.k==='h'?'Potensi = rata-rata 3 bulan terakhir':'Belum ada history — pakai median dealer sejenis',rows,m:p.k==='h'?p.m.concat([q]):null,ml:d.months.map(v6Mon).concat(['Bulan ini']),mNow:1,v:cls==='gd'?['gd','Sesuai / di atas estimasi ('+(diff>=0?'+':'')+num(diff)+' unit).']:cls==='md'?['md','Agak ketinggalan, kurang '+num(-diff)+' unit dari estimasi s.d. hari ini.']:['bd','Jauh di bawah estimasi, kurang '+num(-diff)+' unit.']})}><b>${num(q)}</b><small>pot ${num(p.v)}</small></div>`;}
function v6GapCell(c){if(!v6POT.data)return v6POT.loading?'<span class="v6spin" title="Menghitung potensi…"></span>':'—';const g=v6Gap(c),d=v6POT.data;if(!g)return '<span class="v6gap ok">0</span>';
 const parts=REPORT.brands.map(b=>{const p=v6PotOf(c,b.brand);if(!p)return null;const e=v6PotExp(p),q=v6Qty(c,b.brand),k=Math.max(0,e-q);return k>=0.5?[esc(b.brand)+(p.k==='p'&&q<=0?' (peluang)':''),p.k==='p'&&q<=0?num(p.v)+' × '+d.run+'/'+d.days+' ≈ '+num(k):num(e)+' − '+num(q)+' = '+num(k)]:null;}).filter(Boolean);
 return `<span class="v6gap"${v6Tip({t:'GAP POTENSI · '+esc(c.nama),s:'Kekurangan dari estimasi s.d. hari ini, per brand (brand yang lebih tidak menutup brand lain)',rows:parts.concat([['Total','+'+num(g)]]),v:['bd','Urutkan kolom ini untuk daftar prioritas kunjungan.']})}>+${num(g)}</span>`;}

function v6PJ(v,p){return `<span class="v6pj"><b>${num(v)}</b><span class="v6pjp v6pj-${p>=100?'gd':p>=80?'md':'bd'}">${pct(p)} dari target</span></span>`;}

/* ===== v6.20: loading — garis progres atas, spinner + kerangka tabel, pesan kalau lama ===== */
let v6BusyN=0;
function v6Busy(d){v6BusyN=Math.max(0,v6BusyN+d);let bar=document.getElementById('v6topbar');if(!bar){bar=document.createElement('div');bar.id='v6topbar';bar.innerHTML='<i></i>';document.body.appendChild(bar);}bar.classList.toggle('on',v6BusyN>0);}
const V6LOADRE=/^(Memuat|Menghitung|Memeriksa|Menyiapkan|Mengambil)\b[^\n]{0,90}…$/;
function v6MarkLoading(root){(root||document).querySelectorAll('#view p:not([data-v6ld]), #view div:not([data-v6ld]):empty, #view div:not([data-v6ld]):not(:has(*)), #view span:not([data-v6ld]):not(:has(*)), #mbody p, #mbody div:not(:has(*))').forEach(el=>{
 if(el.dataset.v6ld||el.children.length||el.closest('button,select,option,.aiBubble,.v6tt,.v6sheet'))return;const t=(el.textContent||'').trim();if(!V6LOADRE.test(t))return;
 el.dataset.v6ld=1;el.classList.add('v6loading');const big=!el.closest('td,.pager,.filterSummary,.toolbar,label');
 if(big&&!(el.nextElementSibling&&el.nextElementSibling.classList.contains('v6skel'))){const sk=document.createElement('div');sk.className='v6skel';sk.innerHTML='<i></i><i></i><i></i><i></i>';el.after(sk);}
 setTimeout(()=>{if(el.isConnected&&V6LOADRE.test((el.textContent||'').trim())&&!el.querySelector('.v6slow')){const s=document.createElement('span');s.className='v6slow';s.textContent='⏳ Datanya cukup besar, masih diproses… mohon tunggu, jangan klik ulang.';el.appendChild(s);}},8000);});
 document.querySelectorAll('.v6loading').forEach(el=>{const t=(el.textContent||'').replace(/⏳.*$/,'').trim();if(!V6LOADRE.test(t)){el.classList.remove('v6loading');delete el.dataset.v6ld;el.querySelectorAll('.v6slow').forEach(x=>x.remove());}});
 document.querySelectorAll('.v6skel').forEach(sk=>{const p=sk.previousElementSibling;if(!p||!p.classList.contains('v6loading')||!V6LOADRE.test((p.textContent||'').replace(/⏳.*$/,'').trim()))sk.remove();});}
(function(){let q=0;const run=()=>{q=0;try{v6MarkLoading();}catch(e){}};new MutationObserver(recs=>{if(q)return;for(const r of recs){if(document.querySelector('.v6loading,.v6skel')){q=requestAnimationFrame(run);return;}for(const n of r.addedNodes){const t=n.nodeType===3?n.data:(n.nodeType===1?n.textContent:'');if(t&&t.length<200000&&t.indexOf('…')>=0){q=requestAnimationFrame(run);return;}}}}).observe(document.body,{childList:true,subtree:true});})();

/* ===== v6.20 #15: Dealer Tutup ===== */
let V6TUTUP={rows:[],map:{},pend:{},rej:{},admin:false},v6TTab='pend',v6TUp=null;
function v6TutupSet(r){if(!r)return;V6TUTUP={rows:r.rows||[],admin:!!r.admin,map:{},pend:{},rej:{}};V6TUTUP.rows.filter(x=>x.current).forEach(x=>{if(x.status==='TUTUP')V6TUTUP.map[x.id]=x;else if(x.status==='PENGAJUAN')V6TUTUP.pend[x.id]=x;else if(x.status==='DITOLAK')V6TUTUP.rej[x.id]=x;});}
async function v6TutupLoad(){try{v6TutupSet(await rpc('apiDealerTutupList',TOKEN));}catch(e){}}
function v6ApplyTutup(r){if(!r||!r.customers)return;const cut=r.coverage?.cutoff||'9999-12-31';r.v6tutupLM={q:0,n:0};r.v6tutupNow=0;
 r.customers.forEach(c=>{if(c.v6orig!=null){c.status=c.v6orig;delete c.v6orig;}delete c.v6tutup;delete c.v6warn;const t=V6TUTUP.map[c.id];
  if(t&&t.date<=cut){c.v6orig=c.status;c.v6tutup=t;c.status='TUTUP';c.v6warn=!!(c.last&&c.last>t.date);r.v6tutupLM.q+=c.previous?.qty||0;r.v6tutupLM.c=(r.v6tutupLM.c||0)+(c.current?.qty||0);r.v6tutupLM.n++;if(t.date.slice(0,7)===r.period)r.v6tutupNow++;}});}
function v6Tgl(d){try{return new Date(d+'T00:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short'});}catch(e){return d;}}
function v6TutupTag(id){const t=V6TUTUP.map[id],p=V6TUTUP.pend[id];if(t)return `<span class="v6bdg v6b-tutup"${v6TipShort('Dealer tutup sejak '+esc(tgl(t.date))+' · '+esc(t.alasan))}>TUTUP · ${v6Tgl(t.date)}</span>`;if(p)return `<span class="v6bdg v6b-ajuan"${v6TipShort('Pengajuan tutup oleh '+esc(p.byName)+' ('+esc(p.at)+') · menunggu admin')}>PENGAJUAN TUTUP</span>`;return '';}
function v6TutupBanner(c){const t=V6TUTUP.map[c.id],p=V6TUTUP.pend[c.id],rj=V6TUTUP.rej[c.id],adm=V6TUTUP.admin;
 if(t)return `<div class="v6tban grey">🚫 <b>Dealer tutup sejak ${esc(tgl(t.date))}</b> · ${esc(t.alasan)} · ${t.procName?'disetujui '+esc(t.procName)+' ('+esc(t.procAt)+')':''}${c.v6warn?'<br><b style="color:#B42318">⚠ Ada transaksi setelah tanggal tutup (terakhir '+esc(tgl(c.last))+'). Cek apakah dealer buka lagi.</b>':''}${adm?` <button type="button" class="chip" data-v6t="buka" data-row="${t.row}">Buka lagi</button>`:''}</div>`;
 if(p)return `<div class="v6tban yel">⏳ <b>Pengajuan tutup</b> oleh ${esc(p.byName)} (${esc(p.at)}) · tanggal tutup ${esc(tgl(p.date))} · ${esc(p.alasan)}. Dealer masih dihitung normal sampai disetujui.${adm?` <span class="v6tact"><button type="button" class="chip primary" data-v6t="setuju" data-row="${p.row}">Setujui</button><button type="button" class="chip" data-v6t="tolak" data-row="${p.row}">Tolak</button></span>`:''}</div>`;
 return `<div class="v6tban plain">${rj?`<span class="hint">Pengajuan tutup sebelumnya <b>ditolak</b>${rj.note?': '+esc(rj.note):''}.</span> `:''}<button type="button" class="chip" data-v6t="form" data-id="${esc(c.id)}">${adm?'Tandai dealer tutup':'Ajukan dealer tutup'}</button><div class="v6tform" hidden></div></div>`;}
function v6JktToday(){return new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Jakarta'});}
function v6TutupFormHtml(id){const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Jakarta'});return `<div class="v6tf"><label>Tanggal tutup<input type="date" class="fi" id="v6tDate" max="${today}" value="${today}"></label><label class="full">Alasan<textarea class="fi" id="v6tWhy" maxlength="300" placeholder="Contoh: toko tutup permanen, pindah usaha"></textarea></label><div class="full"><button type="button" class="chip primary" data-v6t="kirim" data-id="${esc(id)}">${V6TUTUP.admin?'Simpan (langsung berlaku)':'Kirim pengajuan'}</button> <span class="hint">${V6TUTUP.admin?'Admin: status langsung TUTUP.':'Menunggu persetujuan admin wilayah.'}</span></div></div>`;}
async function v6TutupAfter(msg){await v6TutupLoad();v6ApplyTutup(REPORT);if(typeof closeModal==='function'&&$('mask')?.classList.contains('on'))closeModal();if(msg)alert(msg);render();}
document.addEventListener('click',async e=>{const b=e.target.closest&&e.target.closest('[data-v6t]');if(!b)return;const a=b.dataset.v6t;
 try{
  if(a==='form'){const f=b.parentElement.querySelector('.v6tform');f.hidden=!f.hidden;if(!f.innerHTML)f.innerHTML=v6TutupFormHtml(b.dataset.id);return;}
  if(a==='kirim'){b.disabled=true;const r=await rpc('apiDealerTutupAjukan',TOKEN,b.dataset.id,$('v6tDate').value,$('v6tWhy').value);await v6TutupAfter(r.status==='TUTUP'?'Dealer ditandai tutup.':'Pengajuan terkirim. Menunggu persetujuan admin.');return;}
  if(a==='setuju'||a==='buka'){if(!confirm(a==='setuju'?'Setujui dealer ini sebagai TUTUP?':'Buka lagi dealer ini (status tutup dicabut)?'))return;b.disabled=true;await rpc('apiDealerTutupProses',TOKEN,+b.dataset.row,a==='setuju'?'SETUJU':'BUKA','');await v6TutupAfter();return;}
  if(a==='tolak'){const why=prompt('Alasan penolakan (akan terlihat oleh sales):');if(!why)return;b.disabled=true;await rpc('apiDealerTutupProses',TOKEN,+b.dataset.row,'TOLAK',why);await v6TutupAfter();return;}
  if(a==='tab'){v6TTab=b.dataset.tab;v6TutupDraw();return;}
  if(a==='dl'){const rows=V6TUTUP.rows.filter(x=>x.current&&x.status==='TUTUP');window.V6XNAME='Dealer-Tutup.xlsx';downloadContactXlsx([['KODE CUSTOMER','NAMA DEALER','SUB REGION','TANGGAL TUTUP','ALASAN','DIAJUKAN OLEH','DISETUJUI OLEH','DISETUJUI PADA'],...rows.map(x=>[x.id,x.nama,x.sub,x.date,x.alasan,x.byName,x.procName,x.procAt])]);return;}
  if(a==='tpl'){window.V6XNAME='Template-Dealer-Tutup.xlsx';downloadContactXlsx([['KODE CUSTOMER','TANGGAL TUTUP','ALASAN'],['005.094','2026-09-20','Toko tutup permanen']]);return;}
  if(a==='save'){if(!v6TUp)return;b.disabled=true;const r=await rpc('apiDealerTutupUpload',TOKEN,v6TUp,true);v6TUp=null;await v6TutupAfter('Tersimpan: '+r.saved+' dealer. Dilewati: '+r.skipped+' baris.');return;}
 }catch(err){b.disabled=false;fail(err);}});
async function v6ReadSheetFile(file){if(/\.csv$/i.test(file.name)){const s=(await file.text()).replace(/^﻿/,''),l=s.split(/\r?\n/)[0],d=l.split(';').length>l.split(',').length?';':',';return s.split(/\r?\n/).filter(x=>x.trim()).map(x=>x.split(d).map(v=>v.replace(/^"|"$/g,'').trim()));}
 const buf=await file.arrayBuffer(),dv=new DataView(buf),u8=new Uint8Array(buf);let eo=-1;for(let i=u8.length-22;i>=Math.max(0,u8.length-66000);i--){if(dv.getUint32(i,true)===0x06054b50){eo=i;break;}}if(eo<0)throw Error('File bukan XLSX/CSV yang valid.');
 const n=dv.getUint16(eo+10,true),files={};let p=dv.getUint32(eo+16,true);for(let k=0;k<n;k++){const nl=dv.getUint16(p+28,true),el=dv.getUint16(p+30,true),cl=dv.getUint16(p+32,true);files[new TextDecoder().decode(u8.subarray(p+46,p+46+nl))]={m:dv.getUint16(p+10,true),cs:dv.getUint32(p+20,true),off:dv.getUint32(p+42,true)};p+=46+nl+el+cl;}
 const read=async name=>{const f=files[name];if(!f)return null;const s=f.off+30+dv.getUint16(f.off+26,true)+dv.getUint16(f.off+28,true),data=u8.subarray(s,s+f.cs);if(!f.m)return new TextDecoder().decode(data);return new TextDecoder().decode(await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());};
