 rpc(id==='GT'?'apiGrowthType':'apiCompare',TOKEN,REPORT.period,$('scopeSelect').value,...(id==='GT'?[brandChoice,o]:[o])).then(d=>{if(C.key!==key)return;C.data=d;if(!C.st.wA){const day=+d.cutoff.slice(8),full=day%7===0||d.cutoff===PortalCore_end(d.period);C.st.wA=Math.max(full?1:2,full?d.maxWeek:d.maxWeek-1);if(C.st.wA<2)C.st.wA=2;}if(!C.st.wB)C.st.wB=Math.max(1,C.st.wA-1);v6CmpDraw(id);}).catch(e=>{const h=$(C.host);if(h)h.innerHTML=panel(title,'<div class="banner bad">'+esc(e.message)+'</div>');});}
