 const iN={ST:'SELL THRU',SO:'SELL OUT',OMZET:'OMZET',DA:'Dealer Aktif',NOO:'NOO'}[d.metric],LA=d.A.label,LB=d.B.label,unit=money?'':{DA:' dealer',NOO:' NOO'}[d.metric]||' unit';
