 const rgms=d.level==='RGM'?[]:uniq(r2.map(r=>r.rgm));if(S.rgm&&!rgms.includes(S.rgm))S.rgm='';const r3=r2.filter(r=>!S.rgm||r.rgm===S.rgm);
 const asms=d.level==='SALES'?uniq(r3.map(r=>r.asm)):[];if(S.asm&&!asms.includes(S.asm))S.asm='';const r4=r3.filter(r=>!S.asm||r.asm===S.asm);
 const sales=!isT&&d.level==='SALES'?uniq(r4.map(r=>r.nama)):[];if(S.sales&&!sales.includes(S.sales))S.sales='';let R=r4.filter(r=>!S.sales||r.nama===S.sales);
 const shortN=n=>{if(!isT)return n;const b=String(d.brand||'').toUpperCase();let x=String(n);if(b&&x.toUpperCase().startsWith(b+' '))x=x.slice(b.length+1);return x;};
 const cols=isT&&S.mode==='model'?Object.values(d.cols.reduce((m,t)=>{(m[t.model]=m[t.model]||{name:t.model,keys:[]}).keys.push(t.key);return m;},{})):d.cols.map(t=>({name:t.key,keys:[t.key]}));
 const val=(r,c)=>c.keys.reduce((a,k)=>{const x=r.cells[k]||[0,0];return [a[0]+x[0],a[1]+x[1]];},[0,0]);
