 if(Cc.length>MAXC){const rest=Cc.slice(MAXC-1);Cc=Cc.slice(0,MAXC-1).concat([{name:'Lainnya ('+rest.length+')',keys:rest.flatMap(x=>x.keys),t:rest.reduce((a,x)=>[a[0]+x.t[0],a[1]+x.t[1]],[0,0])}]);}
 const TA=Cc.reduce((n,c)=>n+c.t[0],0),TL=Cc.reduce((n,c)=>n+c.t[1],0),lbl=isT?(S.mode==='var'?'TYPE':'Model'):'brand',who={SALES:'Sales',ASM:'ASM',RGM:'RGM'}[d.level];
