document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-v6c],[data-v6ca]');if(!b)return;if(b.dataset.v6ca){const C=V6CMP[b.dataset.v6ca],g=b.dataset.g;C.st.closed.has(g)?C.st.closed.delete(g):C.st.closed.add(g);v6CmpDraw(b.dataset.v6ca);return;}const C=V6CMP[b.dataset.v6c];C.st[b.dataset.k]=b.dataset.v;v6CmpDraw(b.dataset.v6c);});
