window.v12TK=window.v12TK||{mode:'o',sort:'v',all:false};
function v12TimMob(d,asm,bigs){const A=asm.slice().sort((a,b)=>b.proj-a.proj),top=A.slice(0,3),bot=A.length>3?A.slice(-3).reverse():[];const cl=p=>p>=100?'c-g':p>=80?'c-y':'c-r',f1=v=>String(Math.round(v*10)/10).replace('.',',')+'%';
 const row=(x,i)=>`<div class="ar ${cl(x.proj)}"><div class="t"><div class="rk">${i+1}</div><div class="n"><b>${esc(x.nama)}</b><small>${esc(x.region)}</small></div><div class="p">${f1(x.proj)}</div></div><div class="dt"><span>Target</span><b>${num(x.target)} unit</b><span>Aktual MTD</span><b>${num(x.actual)} unit</b><span>Estimasi akhir bulan</span><b>${f1(x.proj)}</b></div></div>`;
 const ib=t=>`<button type="button" class="ib" data-v12tip="${t}">i</button>`;
 const asmH=A.length?`<div class="hd"><b>ASM · Estimasi tertinggi &amp; terendah</b>${ib('v12t1')}</div><div class="tip" id="v12t1">Urutan berdasarkan estimasi % target akhir bulan. Ketuk nama untuk melihat target dan aktual.</div><div class="pn" id="v12asm"><span class="gl u">TERTINGGI</span>${top.map(row).join('')}${bot.length?'<span class="gl d" style="margin-top:8px">TERENDAH</span>'+bot.map(row).join(''):''}</div>`:'';
 window.v12TKd={d,bigs};
 return asmH+`<div class="hd"><b>KPI · Omzet per Big Region</b>${ib('v12t2')}</div><div class="tip" id="v12t2">Omzet MTD per Big Region dengan growth vs LMTD. Tab KPI menampilkan skor KPI per Big Region.</div><div class="pn"><div class="tg" id="v12tg"><button data-v12tm="k" class="${window.v12TK.mode==='k'?'on':''}">KPI</button><button data-v12tm="o" class="${window.v12TK.mode==='o'?'on':''}">OMZET</button></div><div class="sort" id="v12so"></div><div id="v12rg"></div><button class="all" id="v12al" data-v12tm="all"></button></div>`+'<img alt="" width="1" height="1" style="position:absolute;opacity:0" src="data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==" onload="v12TimDraw()">';}
function v12TimDraw(){const K=window.v12TK,X=window.v12TKd;if(!X||!document.getElementById('v12rg'))return;const{d,bigs}=X,cl=p=>p>=100?'c-g':p>=80?'c-y':'c-r';
 const R=bigs.map(k=>{const n=d.nodes[k],m=v6XM(n,'ALL','om');return{n:n.name,a:m.a,lm:m.lm,kpi:d.kpi?.[n.name]}});const gr=r=>r.lm?(r.a/r.lm-1)*100:null;
 document.getElementById('v12so').innerHTML=[['v',K.mode==='o'?'Omzet terbesar':'Skor tertinggi'],['g',K.mode==='o'?'Growth':'Skor terendah']].map(x=>`<button data-v12ts="${x[0]}" class="${K.sort===x[0]?'on':''}">${x[1]}</button>`).join('');
 const a=R.slice().sort((x,y)=>K.mode==='o'?(K.sort==='v'?y.a-x.a:(gr(y)??999)-(gr(x)??999)):(K.sort==='v'?(y.kpi??-1)-(x.kpi??-1):(x.kpi??999)-(y.kpi??999))),l=K.all?a:a.slice(0,5);
 document.getElementById('v12rg').innerHTML=l.map(r=>{if(K.mode==='k')return `<div class="rg"><div class="t"><b>${esc(r.n)}</b><strong class="${r.kpi==null?'':cl(r.kpi)}">${r.kpi==null?'—':pct(r.kpi)}</strong></div></div>`;const g=gr(r),ch=g==null?'<span class="v12k cn">BARU</span>':`<span class="v12k ${g>=0?'cu':'cd'}">${g>=0?'▲':'▼'} ${decimal(Math.abs(g))}%</span>`;return `<div class="rg"><div class="t"><b>${esc(r.n)}</b><strong>${moneyShort(r.a)}</strong></div><div class="s">${ch}<span>${g==null?'belum ada LMTD':'dari LMTD '+moneyShort(r.lm)}</span></div></div>`}).join('');
 const al=document.getElementById('v12al');al.textContent=K.all?'Tampilkan ringkas':'Lihat semua '+R.length+' wilayah';al.hidden=R.length<=5;}
document.addEventListener('click',e=>{const t=e.target.closest&&e.target.closest('[data-v12tip]');if(t){const el=document.getElementById(t.dataset.v12tip);if(el)el.classList.toggle('on');return}
