 const m=e.target.closest&&e.target.closest('[data-v12tm]');if(m){const K=window.v12TK;if(m.dataset.v12tm==='all')K.all=!K.all;else{K.mode=m.dataset.v12tm;K.sort='v';K.all=false;document.querySelectorAll('#v12tg button').forEach(b=>b.classList.toggle('on',b===m))}v12TimDraw();return}
