function v6XM(node,brand,ind){const x=node&&node.m&&(node.m[brand]||null);if(!x)return {a:0,lm:0,td:0,t:0};return {a:x[ind][0],lm:x[ind][1],td:x[ind][2],t:x.t?(x.t[ind]||0):0};}
function v6XF(v,ind){return ind==='om'?moneyShort(v):num(Math.round(v));}
function v6XCol(p){return p==null?'var(--c6-muted)':p>=100?'var(--c6-green)':p>=80?'var(--c6-amber)':'var(--c6-red)';}
function v6XSt(p){return p==null?'':p>=100?'g':p>=80?'w':'bd';}
function v6XCalc(m,ind,d){const hasT=['st','da','noo'].includes(ind)&&m.t>0,tg=d.run/d.days*100,proj=d.run?m.a/d.run*d.days:m.a,pp=hasT?proj/m.t*100:null,cap=hasT?m.a/m.t*100:null,g=ind==='noo'?m.a-m.lm:(m.lm?(m.a-m.lm)/m.lm*100:null);return {hasT,tg,proj,pp,cap,g};}
function v6XGrowth(m,c,ind){if(c.g==null)return '<span class="v6mut">LMTD –</span>';const up=c.g>=0;return `<span class="${up?'v6up':'v6dn'}">${up?'▲ +':'▼ '}${ind==='noo'?num(c.g):decimal(c.g)+'%'} · LMTD ${v6XF(m.lm,ind)}</span>`;}
function v6XRing(p,label,sub,col,tg){const R=33,C=2*Math.PI*R;return `<div class="v6xring"><svg viewBox="0 0 78 78"><circle cx="39" cy="39" r="${R}" fill="none" stroke="#EEF2F7" stroke-width="8"/>${p==null?'':`<circle cx="39" cy="39" r="${R}" fill="none" stroke="${col}" stroke-width="8" stroke-linecap="round" stroke-dasharray="${C*Math.max(0,Math.min(100,p))/100} ${C}" transform="rotate(-90 39 39)"/>`}${tg!=null?`<line x1="39" y1="2" x2="39" y2="11" stroke="#0A2E57" stroke-width="2" transform="rotate(${tg*3.6} 39 39)"/>`:''}</svg><div><b>${label}</b><small>${sub}</small></div></div>`;}
function v6XHero(node,brand,ind,title,d,withStats){const m=v6XM(node,brand,ind),c=v6XCalc(m,ind,d),L=V6XI.find(x=>x[0]===ind),lbl=L[1],natHero=node===d.nodes.N&&ind==='st';
 const tR=v6Tip({t:'% Capai',s:'Aktual MTD dibanding target bulan ini',rows:c.hasT?[['Target',v6XF(m.t,ind)],['Aktual MTD',v6XF(m.a,ind)],['Capai',v6XF(m.a,ind)+' ÷ '+v6XF(m.t,ind)+' = '+pct(c.cap)]]:[['LMTD',v6XF(m.lm,ind)],['Aktual MTD',v6XF(m.a,ind)]]}),tT=v6Tip({t:'Today',s:'Transaksi di tanggal data terakhir ('+tgl(d.cutoff)+')',rows:[['Today',v6XF(m.td,ind)]]}),tE=v6Tip({t:'Estimasi akhir bulan',s:'Kalau ritme per hari kerja tetap sampai akhir bulan',rows:[['Aktual MTD',v6XF(m.a,ind)],['Hari kerja berjalan',d.run+' dari '+d.days],['Hitungan',v6XF(m.a,ind)+' ÷ '+d.run+' × '+d.days+' = '+v6XF(c.proj,ind)]].concat(c.hasT?[['vs target',pct(c.pp)]]:[]),v:c.hasT?(c.pp>=100?['gd','Diperkirakan tembus target.']:['bd','Diperkirakan kurang '+v6XF(Math.max(0,m.t-c.proj),ind)+'.']):null}),tG=v6Tip({t:'Time gone',s:'Persentase hari kerja yang sudah lewat. Idealnya % capai ≥ time gone.',rows:[['Hari kerja lewat',d.run+' dari '+d.days],['Time gone',pct(c.tg)]]});
 const ring=c.hasT?v6XRing(c.cap,pct(c.cap),'capai',v6XCol(c.pp),c.tg):v6XRing(m.lm?Math.min(100,m.a/m.lm*100):null,c.g==null?'—':(c.g>=0?'+':'')+(ind==='noo'?num(c.g):decimal(c.g)+'%'),'vs LMTD',c.g>=0?'var(--c6-green)':'var(--c6-red)',null);
 const pills=(c.hasT?`<span class="v6pill v6${c.cap>=c.tg?'good':'bad'}"${v6Tip({t:'Poin vs time gone',s:'Selisih % capai dengan % hari kerja yang sudah lewat. Plus = lebih cepat dari jadwal.',rows:[['Capai',pct(c.cap)],['Time gone',pct(c.tg)],['Selisih',decimal(c.cap-c.tg)+' poin']]})}>${(c.cap-c.tg>=0?'+':'')+decimal(c.cap-c.tg)} poin vs TG</span>`:'')+(c.hasT&&c.g!=null?`<span class="v6pill v6${c.g>=0?'good':'bad'}"${v6Tip({t:'vs LMTD',s:'Dibanding bulan lalu di tanggal yang sama (1 s.d. '+tgl(d.prevCutoff)+')',rows:[['LMTD',v6XF(m.lm,ind)],['MTD',v6XF(m.a,ind)],['Growth',ind==='noo'?num(c.g):decimal(c.g)+'%']]})}>${c.g>=0?'+':''}${ind==='noo'?num(c.g):decimal(c.g)+'%'} vs LMTD (${v6XF(m.lm,ind)})</span>`:'');
 const bar=`<div class="v6xprow"><span>${!natHero&&ind!=='da'?`<span${tT} class="v6xu">Today <b>${v6XF(m.td,ind)}</b></span>`:''}</span><span${tE} class="v6xu">Est. akhir bulan <b style="color:var(--c6-blue)">${v6XF(c.proj,ind)}</b>${c.hasT?' ('+pct(c.pp)+')':''}</span></div><div class="v6xpbar"><div class="p" style="width:${c.hasT?Math.min(100,c.pp):100}%"></div><div class="a" style="width:${c.hasT?Math.min(100,c.cap):(c.proj?Math.min(100,m.a/Math.max(c.proj,m.lm||0)*100):0)}%"></div>${c.hasT?`<em style="left:${Math.min(100,c.tg)}%"></em>`:(m.lm&&c.proj?`<em class="lm" style="left:${Math.min(100,m.lm/Math.max(c.proj,m.lm)*100)}%"></em>`:'')}</div><div class="v6xprow">${c.hasT?`<span class="v6xtg"${tG} style="cursor:help;margin-left:${Math.max(0,Math.min(80,c.tg-10))}%">▲ time gone ${pct(c.tg)}</span>`:(m.lm&&c.proj?`<span class="v6xlmt" style="margin-left:${Math.max(0,Math.min(75,m.lm/Math.max(c.proj,m.lm)*100-10))}%">▲ LMTD ${v6XF(m.lm,ind)}</span>`:'<span>dibanding LMTD</span>')}</div>`;
 return `<div class="v6xhero${natHero?' v6xheroNat':''}"><div class="v6xhr"><div${tR} style="cursor:help">${ring}</div><div style="flex:1;min-width:0"><h4>${esc(title)}</h4><div class="v6xmeta">s.d. ${tgl(d.cutoff)} · hari kerja ${d.run}/${d.days}</div><div class="v6tags">${pills}</div></div></div>${bar}${node===d.nodes.N&&ind==='st'?v6XSplit(d,brand):''}${withStats?v6XStats(node,brand,d,ind):''}</div>`;}
function v6XCard(node,key,brand,ind,d,lead,noSales){const m=v6XM(node,brand,ind),c=v6XCalc(m,ind,d),st=c.hasT?v6XSt(c.pp):(c.g==null?'':c.g>=5?'g':c.g>=-5?'w':'bd');
 const tag=c.hasT?`<span class="v6xst ${st}">${pct(c.pp)} proyeksi</span>`:`<span class="v6xst ${st}">${c.g==null?'—':(c.g>=0?'▲ +':'▼ ')+(ind==='noo'?num(c.g):decimal(c.g)+'%')}</span>`;
 const mx=Math.max(m.a,m.lm,1),bar=c.hasT?`<div class="v6xbar"><i style="width:${Math.min(100,c.cap)}%;background:${v6XCol(c.pp)}"></i><em style="left:${Math.min(100,c.tg)}%"></em></div>`:`<div class="v6xbar"><i style="width:${m.a/mx*100}%;background:${(c.g||0)>=0?'var(--c6-green)':'var(--c6-red)'}"></i><em style="left:${m.lm/mx*100}%"></em></div>`;
 return `<div class="v6xcard ${st}${node.online?' onl':''}" data-v6xd="${esc(key)}"><div class="t"><span><b>${esc(node.name)}</b>${node.online?'<em class="v6xob">ONLINE</em>':''}${lead?` <small>| ${esc(lead)}</small>`:''}${noSales?' <em class="v6xnos">belum ada penjualan bulan ini</em>':''}</span>${tag}</div>${bar}<div class="n"><span>${c.hasT?`${v6XF(m.t,ind)} / <b>${v6XF(m.a,ind)}</b> · capai <b>${pct(c.cap)}</b>`:`<b>${v6XF(m.a,ind)}</b>`}${ind!=='da'?` · today <b>${v6XF(m.td,ind)}</b>`:''}</span>${v6XGrowth(m,c,ind)}</div></div>`;}
function v6XCum(d,dailyKey,brand,node){const daily=(d.daily||{})[dailyKey]||{},m=v6XM(node,brand,'st'),cal=+PortalCore_end(d.period).slice(8),calRun=+d.cutoff.slice(8),W=720,H=250,P={l:58,r:18,t:18,b:32},iw=W-P.l-P.r,ih=H-P.t-P.b;
 let s0=0;const cum=[];for(let i=1;i<=calRun;i++){const dt=d.period+'-'+String(i).padStart(2,'0'),x=daily[dt]||{};s0+=brand==='ALL'?Object.values(x).reduce((a,b)=>a+b,0):(x[brand]||0);cum.push(s0);}
 const proj=d.run?s0/d.run*d.days:s0,target=m.t,mx=Math.max(1,target,proj,s0)*1.10,X=i=>P.l+iw*(i-1)/Math.max(1,cal-1),Y=v=>P.t+ih*(1-v/mx),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),path=a=>a.map((v,i)=>(i?'L':'M')+X(i+1).toFixed(1)+','+Y(v).toFixed(1)).join('');
 let g=`<rect x="${P.l}" y="${P.t}" width="${iw}" height="${ih}" fill="#FBFDFF"/>`;
 for(let i=0;i<=6;i++){const v=mx*i/6,major=i%2===0;g+=`<line x1="${P.l}" x2="${W-P.r}" y1="${Y(v)}" y2="${Y(v)}" stroke="${major?'#DCE6F0':'#EDF2F7'}" stroke-width="${major?1.05:.65}"/>`;if(major)g+=`<text x="${P.l-7}" y="${Y(v)+3}" class="v6projAxis" text-anchor="end">${v>=1000?Math.round(v/100)/10+'rb':Math.round(v)}</text>`;}
 for(let i=1;i<=cal;i++){const major=i===1||i===cal||i%5===0;g+=`<line x1="${X(i)}" x2="${X(i)}" y1="${P.t}" y2="${H-P.b}" stroke="${major?'#DCE6F0':'#F0F4F8'}" stroke-width="${major ? .9 : .45}"/>`;if(major)g+=`<text x="${X(i)}" y="${H-9}" class="v6projAxis" text-anchor="middle">${i}</text>`;}
 const targetPts=target?Array.from({length:cal},(_,i)=>target*v6WorkUpTo(d.period,i+1)/d.days):[];
 if(targetPts.length)g+=`<path d="${path(targetPts)}L${X(cal)},${Y(0)}L${X(1)},${Y(0)}Z" fill="url(#v6xpRed)"/>`;
 if(cum.length)g+=`<path d="${path(cum)}L${X(calRun)},${Y(0)}L${X(1)},${Y(0)}Z" fill="url(#v6xpBlue)"/>`;
 if(calRun<cal&&cum.length)g+=`<path d="M${X(calRun)},${Y(s0)}L${X(cal)},${Y(proj)}L${X(cal)},${Y(0)}L${X(calRun)},${Y(0)}Z" fill="url(#v6xpGrey)"/>`;
 if(targetPts.length)g+=`<path d="${path(targetPts)}" stroke="#E5484D" stroke-width="2.4" stroke-dasharray="7 5" fill="none"/>`;
 if(cum.length)g+=`<path d="${path(cum)}" stroke="#0B5CAD" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round" fill="none"/>`;
 if(calRun<cal&&cum.length)g+=`<path d="M${X(calRun)},${Y(s0)}L${X(cal)},${Y(proj)}" stroke="#7FB3E6" stroke-width="2.8" stroke-dasharray="6 5" stroke-linecap="round" fill="none"/>`;
 if(cum.length)g+=`<circle class="v6actualBlink" cx="${X(calRun)}" cy="${Y(s0)}" r="6.2" fill="#F59A23" stroke="#FFF4DF" stroke-width="2.3"/>`;
 if(target){const ty=clamp(Y(target)-9,P.t+10,H-P.b-12);g+=`<text x="${W-P.r-2}" y="${ty}" class="v6projAnn" fill="#E5484D" text-anchor="end">Target ${num(target)}</text>`;}
 if(cum.length){const right=X(calRun)>W*.72,ax=X(calRun)+(right?-10:10),ay=clamp(Y(s0)-13,P.t+16,H-P.b-18);g+=`<text x="${ax}" y="${ay}" class="v6projAnn" fill="#D98210" text-anchor="${right?'end':'start'}">Aktual MTD ${num(s0)}</text><text x="${ax}" y="${ay+10}" class="v6projSub" text-anchor="${right?'end':'start'}">s.d. hari berjalan</text>`;}
 if(calRun<cal&&cum.length){let py=clamp(Y(proj)+18,P.t+24,H-P.b-18);if(target&&Math.abs(py-(Y(target)-9))<18)py=clamp(py+18,P.t+24,H-P.b-18);g+=`<text x="${W-P.r-2}" y="${py}" class="v6projAnn" fill="#567B9D" text-anchor="end">Proyeksi ${num(proj)}</text><text x="${W-P.r-2}" y="${py+10}" class="v6projSub" text-anchor="end">${target?pctLegacy(proj/target*100)+' dari target':'akhir bulan'}</text>`;}
