function v6XProjPanel(title,chart,id){return `<div class="v6projFs" id="${id}"><div class="v6xsec">${title}<button type="button" title="Layar penuh" aria-label="Layar penuh" class="v6xfsBtn v6projFsBtn" data-v6projfs="${id}">⛶</button></div><div class="v6xbox">${chart}</div></div>`;}
function v6XHist(d,key,brand){const H=d.hist;if(!H||!H.months||!H.months.length)return '<p class="hint">History bulanan belum tersedia.</p>';
