 const rows=H.months.map(mo=>{const a=val(mo),cur=mo===d.period&&!d.closed,est=cur&&d.run?a/d.run*d.days:a,t=tg(mo);return {mo,a,est,t,cur,cap:t?(cur?est:a)/t*100:null};});
