 for(let k=0;k<=4;k++){const q=qmax*k/4,y=yq(q),g=gmin+(gmax-gmin)*k/4;s+=`<line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" stroke="#E6ECF3"/><text class="ax" x="${L-8}" y="${y+3.5}" text-anchor="end">${F(q)}</text><text class="ax" x="${W-R+8}" y="${y+3.5}">${Math.round(g)}%</text>`;}
 rows.forEach((r,i)=>{const xx=x(i)-bw/2,y=yq(r.a);s+=`<g class="v7tp" data-i="${i}" tabindex="0" role="button" aria-label="${esc(bulan(r.mo))}"><rect x="${x(i)-cw/2}" y="${T-34}" width="${cw}" height="${B-T+86}" fill="transparent"/>`;
