  s+=`<rect class="b" x="${xx}" y="${y}" width="${bw}" height="${Math.max(1,B-y)}" rx="4" fill="${r.cur?'#0B5CAD':'#8FB6E0'}"/>`;
  if(r.t)s+=`<line x1="${xx-6}" y1="${yq(r.t)}" x2="${xx+bw+6}" y2="${yq(r.t)}" stroke="#C2362F" stroke-width="2.5"/>`;
  const lv=r.cur?r.est:r.a;s+=`<text class="ql" x="${x(i)}" y="${Math.min(yq(lv),r.t?yq(r.t):B)-7}" text-anchor="middle">${F(lv)}${r.cur?'*':''}</text>`;
