 const tot=rows.reduce((a,r)=>a+r.a,0),data=rows.map((r,i)=>({m:bulan(r.mo),a:r.a,e:r.est,t:r.t,c:r.cap,g:G[i],cur:r.cur,p:i?ml(rows[i-1].mo):''}));
 return `<div class="v7trend" data-rows="${esc(JSON.stringify(data))}" data-lmc="${esc(d.cutoff||'')}"><div class="v7tleg"><span class="tot">Total SELL THRU ${F(tot)} unit (${n} periode)</span><span><i class="k bar"></i>Aktual (sumbu kiri)</span><span><i class="k est"></i>Estimasi akhir bulan</span><span><i class="k tg"></i>Target</span><span><i class="k ln"></i>Growth (sumbu kanan)</span></div><div class="v7tscroll"><svg viewBox="0 0 ${W} ${B+56}" style="min-width:${Math.min(W,760)}px" role="img" aria-label="Tren SELL THRU bulanan">${s}<g pointer-events="none">${ln}</g></svg></div><div class="v7tdet" aria-live="polite"></div><div class="v7tfn">* estimasi akhir bulan · growth bulan berjalan = MTD vs LMTD (tanggal sama), bulan lain vs bulan sebelumnya · garis merah = target</div></div>`;}
function v6XStats(node,brand,d,ind){ind=ind||'st';const m=v6XM(node,brand,ind),c=v6XCalc(m,ind,d),F=v=>v6XF(v,ind),U={st:' unit',so:' unit',da:' dealer',noo:' NOO',om:''}[ind],left=Math.max(0,d.days-d.run),rr=d.run?m.a/d.run:0,need=left&&m.t?Math.max(0,m.t-m.a)/left:0,gap=m.t?Math.max(0,m.t-m.a):null,diff=m.a-m.lm;
