 const tRR=T('Run rate',[['Aktual MTD',F(m.a)],['Hari kerja berjalan',d.run],['Run rate',F(m.a)+' ÷ '+d.run+' = '+F(rr)+' /hari']]),tEst=T('Estimasi akhir bulan',[['Hitungan',F(m.a)+' ÷ '+d.run+' × '+d.days+' = '+F(c.proj)]]),tLM=T('vs LMTD',[['LMTD',F(m.lm)],['MTD',F(m.a)],['Selisih',sg(diff)]]);
