 if(ind==='st'){const om=v6XM(node,brand,'om'),po=d.run?om.a/d.run*d.days:om.a;
  b4=[box('Run rate / hari kerja',F(rr)+U,'rata-rata '+d.run+' hari kerja',tRR,'sb'),box('Butuh / hari kerja',m.t&&left?F(need)+U:'—',m.t?(left?(rr?(need/rr>=1.5?decimal(need/rr)+'× run rate':pct(need/rr*100)+' dari run rate'):'sisa '+left+' hari'):'bulan selesai'):'target belum ada',T('Butuh per hari kerja',[['Target',F(m.t)],['Aktual MTD',F(m.a)],['Sisa hari kerja',left],['Butuh',m.t&&left?F(Math.max(0,m.t-m.a))+' ÷ '+left+' = '+F(need):'—']]),need>rr*1.2?'red':'sp'),box('Proyeksi omzet',moneyShort(po),d.closed?'aktual bulan penuh':'jika ritme tetap',T('Proyeksi omzet',[['Omzet MTD',moneyShort(om.a)],['Hitungan',moneyShort(om.a)+' ÷ '+d.run+' × '+d.days]]),'sg'),box('Gap ke target',gap==null?'—':F(gap)+U,left?'sisa '+left+' hari kerja':'akhir bulan',T('Gap ke target',[['Target',F(m.t)],['Aktual',F(m.a)],['Gap',gap==null?'—':F(gap)]]),'so')];}
