const V6XINFO={'Proyeksi SELL THRU':'Merah putus-putus = Target. Biru solid = Aktual kumulatif sampai hari berjalan. Biru putus-putus = Proyeksi sampai akhir bulan. Titik orange berkedip menandai posisi aktual hari ini.','Heatmap':'Pilih SELL THRU atau DEALER AKTIF, lalu PROYEKSI / AKTUAL. Tampilan biasa menunjukkan % target dan unit/dealer. Full Screen menambahkan Target serta Growth MTD vs LMTD beserta selisih. Cell tanpa data cukup tanda –.','Brand nasional':'Capaian tiap brand: bar = % capai, garis = time gone, angka = estimasi akhir bulan, lalu growth vs LMTD.','Brand per Big Region':'Pilih brand dan indikator, kartu di bawah berubah. Format angka: target / aktual · capai · today, lalu growth vs LMTD (angka LMTD di belakangnya).','Region di':'Semua sub region di bawah atasan yang sama. Rincian hanya bisa dibuka untuk area sendiri.','Sales ':'Kartu tiap sales: target / aktual, capai, today, dan growth vs LMTD. Tap untuk rincian.','Brand saya':'Kartu tiap brand: target / aktual, capai, today, growth vs LMTD, dan butuh berapa unit per hari kerja untuk tembus target.','Posisi di':'Urutan berdasarkan estimasi % target akhir bulan. Angka = target / aktual MTD.','Tren bulanan':'SELL THRU per bulan sejak Januari. ▲▼ = naik/turun vs bulan sebelumnya. Bulan berjalan pakai estimasi akhir bulan (*). Garis merah = target.','Rata-rata harian':'Rata-rata SELL THRU per hari (Senin–Sabtu) selama bulan ini, di luar hari libur. Merah muda = di bawah 80% rata-rata.','Kalender transaksi':'Unit SELL THRU per tanggal. Hijau = di atas kebutuhan harian, kuning 60–99%, merah <60%. Tap tanggal untuk rincian per brand.','ASM':'ASM dengan estimasi % target akhir bulan tertinggi dan terendah.','Kesehatan dealer':'DEALER AKTIF = dealer yang ambil minimal 2 unit (brand yang sama) bulan ini. NOO = dealer baru pertama kali order.','Dealer saya':'DEALER AKTIF = dealer yang ambil minimal 2 unit (brand yang sama) bulan ini. NOO = dealer baru pertama kali order.','Dealer perlu':'Diurutkan: belum order (padahal bulan lalu order) → turun >40% → dealer baru → cuma 1 brand. Stok = perkiraan SELL IN − SELL OUT.','Dealer prioritas':'Diurutkan: belum order (padahal bulan lalu order) → turun >40% → dealer baru → cuma 1 brand. Stok = perkiraan SELL IN − SELL OUT.','Status KPI':'Skor KPI = rata-rata tertimbang capaian tiap indikator (dibatasi nilai maksimal skor). Skor sementara bisa berubah sampai akhir bulan.','KPI':'Skor KPI per Big Region dan omzet MTD dengan growth vs LMTD.','Ringkasan analisa':'Catatan otomatis dari data: siapa/apa yang paling perlu perhatian dan aksinya.'};
function v6XApplyFsFocus(){const v=$('view');if(!v)return;v.classList.toggle('v6xPresent',document.fullscreenElement===v);document.querySelectorAll('.v6xfsPanel').forEach(x=>x.classList.toggle('v6xFocus',!!V6X.fsFocus&&x.id===V6X.fsFocus));document.querySelectorAll('[data-v6xfs]').forEach(b=>{{const on=document.fullscreenElement===v&&b.dataset.v6xfs===V6X.fsFocus;b.textContent=on?'↙':'⛶';b.title=on?'Keluar layar penuh':'Layar penuh';b.setAttribute('aria-label',b.title);}});}
function v6XFsOrientation(lock){/* Fullscreen heatmap respects the device's current orientation. */}
function v6XInfoAll(){document.querySelectorAll('.v6xwrap .v6xsec').forEach(el=>{if(el.querySelector('.v6xi'))return;const tx=el.textContent.trim().toLowerCase(),k=Object.keys(V6XINFO).find(k=>tx.startsWith(k.toLowerCase()));if(!k)return;const i=document.createElement('i');i.className='v6xi';i.textContent='i';i.setAttribute('data-v6tip',v6Tip({t:el.childNodes[0].textContent.trim(),s:V6XINFO[k]}).match(/"(.*)"/)[1]);i.style.margin='0 6px 0 0';el.insertBefore(i,el.firstChild);});v6XApplyFsFocus();}
function v6XKeep(fn){const y=window.scrollY,sel='.v6xwrap .v6xchips,.v6xwrap .v6xhistw',sl=[...document.querySelectorAll(sel)].map(e=>e.scrollLeft);fn();const re=()=>{window.scrollTo(0,y);document.querySelectorAll(sel).forEach((e,i)=>{if(sl[i])e.scrollLeft=sl[i];});v6XApplyFsFocus();};re();requestAnimationFrame(re);setTimeout(re,80);}
function v6XSplit(d,brand){const ob=(d.onlineBigs||[]).map(b=>d.nodes['B|'+b]).filter(Boolean);if(!ob.length)return '';const tot=v6XM(d.nodes.N,brand,'st').a,on=ob.reduce((a,n)=>a+v6XM(n,brand,'st').a,0);if(!on)return '';const sp=tot?(tot-on)/tot*100:0;
