function v6XCalChips(d){const cb=V6X.calB||'ALL';return `<div class="v6xchips">${['ALL'].concat(d.brands).map(b=>`<button type="button" class="${cb===b?'on':''}" data-v6xcalb="${esc(b)}">${b==='ALL'?'Semua':esc(b)}</button>`).join('')}</div>`;}
function v6XCal(d,dailyKey,brand,node,ctx){const daily=(d.daily||{})[dailyKey]||{},m=v6XM(node,brand,'st'),cal=+PortalCore_end(d.period).slice(8),calRun=+d.cutoff.slice(8),tgtDay=m.t&&d.days?m.t/d.days:0,lead=(new Date(d.period+'-01T00:00:00').getDay()+6)%7;
 let h=['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(x=>`<div class="dh">${x}</div>`).join('')+'<div></div>'.repeat(lead);let s=0;const sum=x=>brand==='ALL'?Object.values(x).reduce((a,b)=>a+b,0):(x[brand]||0);
 for(let i=1;i<=calRun;i++)s+=sum(daily[d.period+'-'+String(i).padStart(2,'0')]||{});const left=d.days-d.run,need=left&&m.t?Math.max(0,m.t-s)/left:0;
