  if(i>calRun){h+=`<div class="c ${off?'off':'fut'}"><b>${i}</b>${off?'Libur':need?num(need):''}</div>`;continue;}
  if(off&&!q){h+=`<div class="c off"><b>${i}</b>Libur</div>`;continue;}const p=tgtDay&&!off?q/tgtDay*100:null;
  h+=`<button type="button" class="c ${p==null?'nt':p>=100?'ok':p>=60?'mid':'low'}" data-v6xday="${dt}" data-ctx="${esc(ctx)}"><b>${i}</b>${num(q)}</button>`;}
 return `<div class="v6xcal">${h}</div><div class="v6legend">${tgtDay?`<span><i style="background:#DDF4E9"></i>≥ ${num(tgtDay)}/hari kerja</span><span><i style="background:#FFF1CC"></i>60–99%</span><span><i style="background:#FFE1E4"></i>&lt;60%</span>`:''}<span><i class="v6lgOff"></i>Libur</span><span>tap tanggal = rincian</span></div>`;}
function v6XDayPop(dt,ctx){const d=V6X.data;if(!d)return;{const bg=Object.keys(d.nodes).filter(k=>k.startsWith('B|'));if(ctx==='N'&&bg.length===1)ctx=bg[0];}const brands=d.brands,rows=[];
 if(ctx==='N'){Object.keys(d.nodes).filter(k=>k.startsWith('B|')).forEach(k=>{const x=((d.daily||{})[k]||{})[dt]||{};rows.push([d.nodes[k].name,...brands.map(b=>x[b]||0)]);});}
 else if(ctx==='O'&&d.level==='ASM'){Object.keys(d.nodes).filter(k=>k.startsWith('P|')).forEach(k=>{const x=((d.daily||{})[k]||{})[dt]||{};rows.push([d.nodes[k].name,...brands.map(b=>x[b]||0)]);});}
 else if(ctx.startsWith('B|')){const pre='S|'+ctx.slice(2)+'|',subs=Object.keys(d.nodes).filter(k=>k.startsWith(pre));subs.forEach(k=>{const x=((d.daily||{})[k]||{})[dt]||{};rows.push([d.nodes[k].name,...brands.map(b=>x[b]||0)]);});if(!subs.length){const x=((d.daily||{})[ctx]||{})[dt]||{};rows.push([d.nodes[ctx]?.name||'',...brands.map(b=>x[b]||0)]);}}
 else{const x=((d.daily||{})[ctx]||{})[dt]||{};rows.push([d.nodes[ctx]?.name||'',...brands.map(b=>x[b]||0)]);}
