function v6XDealerTags(x,b){const mtd=b?(x.br[b]||0):x.mtd,lm=b?(x.lmBr[b]||0):x.lm,lmtd=b?null:x.lmtd,out=[];
 if(lm>0&&!mtd)out.push({p:1,c:'r',t:'Belum order',s:'Bulan lalu '+num(lm)+' unit'+(b?'':' · '+Object.keys(x.lmBr).join(', '))});
 else if(lmtd&&mtd<lmtd*0.6)out.push({p:2,c:'y',t:'Turun '+Math.round((1-mtd/lmtd)*100)+'%',s:'LMTD '+num(lmtd)+' → '+num(mtd)+' unit'});
 if(x.noo&&x.n<2)out.push({p:3,c:'g',t:'🆕 Baru',s:'NOO '+tgl(x.noo)+' · baru 1x order — dorong order ke-2'});
 if(!b&&mtd>0&&Object.keys(x.br).length===1)out.push({p:4,c:'b',t:'1 brand',s:'Hanya '+Object.keys(x.br)[0]});
 return out;}
function v6XDealerRow(x,b,all){const tg=v6XDealerTags(x,b),mtd=b?(x.br[b]||0):x.mtd;if(!tg.length&&!all)return '';const t=tg[0]||{c:'n',t:'Aktif',s:'MTD '+num(mtd)+' unit'};
 return `<div class="v6xdl"><button type="button" class="textlink" data-customer="${esc(x.id)}">${esc(x.nama)}</button><span class="v6xtag ${t.c}">${esc(t.t)}</span><small>${esc(t.s)}${tg[1]?' · '+esc(tg[1].t):''}</small><div class="v6xdla">${x.hp?v6Wa(x.hp,'Halo '+x.nama+', ','WhatsApp'):''}<button type="button" class="v6xmini" data-customer="${esc(x.id)}">Riwayat order</button>${x.stok!=null?`<span class="v6xtag n">stok ±${num(x.stok)} unit</span>`:''}</div></div>`;}
function v6XDealerList(list,b,max){const sc=x=>{const t=v6XDealerTags(x,b);return t.length?t[0].p*1e6-(b?(x.lmBr[b]||0):x.lm):9e9;};const rows=list.filter(x=>!b||x.br[b]||x.lmBr[b]).sort((a,c)=>sc(a)-sc(c));const pri=rows.filter(x=>v6XDealerTags(x,b).length);
 const show=(pri.length?pri:rows).slice(0,max||15);return show.map(x=>v6XDealerRow(x,b,!pri.length)).join('')+(pri.length>(max||15)?`<p class="hint">+${pri.length-(max||15)} dealer lain · lihat menu Dealer</p>`:'')||'<p class="hint">Tidak ada dealer prioritas. Mantap.</p>';}
function v6XKpi(k){if(!k)return '<p class="hint">KPI belum tersedia.</p>';const col=v=>v==null?'#8A94A6':v6XCol(v);
 return `<div class="pl"><span>Skor ${k.status==='FINAL'?'':'sementara'}</span><b style="font-size:20px;color:${col(k.score)}">${k.score==null?'—':pct(k.score)}</b></div>`+(k.groups||[]).map(g=>(k.groups.length>1?`<div class="v6xsep"></div><div class="pl"><b>${esc(g.name)}</b><b style="color:${col(g.score)}">${g.score==null?'—':pct(g.score)}</b></div>`:'')+g.ind.map(x=>`<div class="pl"><span>${esc(x.label)} <small>(bobot ${num(x.weight)}%)</small><br><small>${num(x.target)} / <b>${num(x.actual)}</b></small></span><b style="color:${col(x.ach)}">${x.ach==null?esc(x.state||'—'):pct(x.ach)}</b></div>`).join('')).join('');}
function v6XAnalisa(d,sales){const o=d.nodes.O,out=[],B=d.brands;if(!o)return '';const m=v6XM(o,'ALL','st'),c=v6XCalc(m,'st',d),left=d.days-d.run,need=left&&m.t?Math.max(0,m.t-m.a)/left:0;
 if(sales){const bl=(d.dealers||[]).filter(x=>x.lm>0&&!x.mtd);if(bl.length)out.push(['🎯',`Prioritas: kunjungi <b>${bl.length} dealer</b> yang bulan lalu order tapi bulan ini belum (total ${num(bl.reduce((a,x)=>a+x.lm,0))} unit bulan lalu).`]);}
 else{const ps=Object.keys(d.nodes).filter(k=>k.startsWith('P|')&&!v6IsVac(k.slice(2),d.nodes[k].name)).map(k=>({n:d.nodes[k],c:v6XCalc(v6XM(d.nodes[k],'ALL','st'),'st',d),m:v6XM(d.nodes[k],'ALL','st')})).filter(x=>x.c.pp!=null).sort((a,b)=>a.c.pp-b.c.pp);if(ps[0]&&ps[0].c.pp<100){const w=ps[0],nd=left&&w.m.t?Math.max(0,w.m.t-w.m.a)/left:0;out.push(['📉',`<b>${esc(w.n.name)}</b> paling tertinggal: estimasi ${pct(w.c.pp)}${w.c.g!=null?`, ${w.c.g>=0?'naik':'turun'} ${decimal(Math.abs(w.c.g))}% vs LMTD`:''}. Butuh <b>${num(nd)} unit/hari</b>.`]);}
  const bl=(d.dealers||[]).filter(x=>x.lm>0&&!x.mtd);if(bl.length){const by={};bl.forEach(x=>{const nm=d.nodes['P|'+x.nik]?.name||x.nik;by[nm]=(by[nm]||0)+1;});const top=Object.entries(by).sort((a,b)=>b[1]-a[1]).slice(0,2);out.push(['🏪',`<b>${bl.length} dealer</b> order bulan lalu tapi belum order bulan ini — terbanyak: ${top.map(t=>esc(t[0])+' ('+t[1]+')').join(', ')}.`]);}}
 const br=B.map(b=>{const x=v6XM(o,b,'st');return [b,x.a-x.lm,x.lm?(x.a-x.lm)/x.lm*100:null];}).filter(x=>x[1]<0).sort((a,b)=>a[1]-b[1])[0];if(br)out.push(['🔻',`<b>${esc(br[0])}</b> turun paling dalam: ${num(br[1])} unit${br[2]!=null?' ('+decimal(br[2])+'%)':''} vs LMTD.`]);
 const one=(d.dealers||[]).filter(x=>x.mtd>0&&Object.keys(x.br).length===1);if(one.length)out.push(['🔀',`<b>${one.length} dealer</b> cuma ambil 1 brand bulan ini${sales?': '+one.slice(0,2).map(x=>esc(x.nama)).join(', ')+(one.length>2?' dst':''):''} — peluang cross-sell.`]);
 const mn=v6XM(o,'ALL','noo');if(mn.t)out.push(['🆕',`NOO <b>${num(mn.a)}/${num(mn.t)}</b>${mn.a<mn.t&&left?` — perlu ${num(mn.t-mn.a)} lagi dalam ${left} hari kerja`:' — target tercapai'}.`]);
 if(need&&c.pp!=null&&c.pp<100)out.unshift(['⏱',`Butuh <b>${num(need)} unit/hari</b> kerja untuk kejar target SELL THRU (run rate sekarang ${num(d.run?m.a/d.run:0)}).`]);
 return out.map(([i,t])=>`<div class="v6xan"><i>${i}</i><div>${t}</div></div>`).join('')||'<p class="hint">Belum ada catatan.</p>';}
function v6ExecLow(d){const v=$('view'),sales=d.level==='SALES',B=V6X.brand,I=V6X.ind,o=d.nodes.O;if(!o){v.innerHTML='<div class="banner">Belum ada data untuk cakupan ini.</div>';return;}
