 const m=v6XM(o,'ALL','st'),c=v6XCalc(m,'st',d),left=d.days-d.run,need=left&&m.t?Math.max(0,m.t-m.a)/left:0,bl=(d.dealers||[]).filter(x=>x.lm>0&&!x.mtd).length;
 const alert=(c.pp!=null&&c.pp<100)||bl?`<div class="v6xalert">⚠ ${c.pp!=null&&c.pp<100?`${sales?'Lu butuh':'Butuh'} <b>${num(need)} unit/hari</b> buat kejar target`:''}${c.pp!=null&&c.pp<100&&bl?' · ':''}${bl?`<b>${bl} dealer</b> bulan lalu order, bulan ini belum`:''}</div>`:'';
