  const team=Object.keys(d.nodes).filter(k=>k.startsWith('P|')).map(k=>({k,n:d.nodes[k],m:v6XM(d.nodes[k],'ALL','st')})).map(x=>({...x,c:v6XCalc(x.m,'st',d),vac:v6IsVac(x.k.slice(2),d.nodes[x.k].name)})).sort((a,b)=>(a.vac-b.vac)||(b.c.pp??-1)-(a.c.pp??-1));let V6RN=0;
  peers=team.map((x,i)=>`<div class="v6xrk${x.k==='P|'+d.me?' me':''}${x.vac?' v6vac':''}"><span class="n">${x.vac?'—':'#'+(++V6RN)}</span><b>${esc(x.n.name)}</b><span class="t">${num(x.m.t)} / ${num(x.m.a)}</span><b style="color:${v6XCol(x.c.pp)}">${x.c.pp==null?'—':pct(x.c.pp)}</b></div>`).join('')+'<div class="v6legend"><span>target / aktual MTD · % = estimasi akhir bulan</span></div>';}
