function v6ExecBrandDealers(b){const d=V6X.data,o=d.nodes.O,v=$('view');
 v.innerHTML=`<div class="v6xwrap"><button type="button" class="v6xback" data-v6xback="1">‹ Kembali</button>
  ${v6XHero(o,b,'st',esc(b)+' · SELL THRU',d,1)}
