 v6XInfoAll();if(typeof bind==='function')bind();window.scrollTo(0,0);}
function v6ExecDrill(k){const d=V6X.data,n=d.nodes[k],v=$('view'),B=V6X.brand,I=V6X.ind;
 const subs=Object.keys(d.nodes).filter(x=>x.startsWith('S|'+n.name+'|'));
 const m=v6XM(n,'ALL','st'),c=v6XCalc(m,'st',d),bw=d.brands.map(b=>{const x=v6XM(n,b,'st');return [b,x.a-x.lm];}).sort((a,b)=>a[1]-b[1])[0];
 const asmIn=(d.asm||[]).filter(x=>x.big===n.name),weak=asmIn.filter(x=>x.proj<80).length,da=v6XM(n,'ALL','da');
 const why=[bw&&bw[1]<0?`${bw[0]} turun ${num(-bw[1])} unit vs LMTD`:null,asmIn.length?`${weak} dari ${asmIn.length} ASM estimasinya < 80%`:null,da.t?`Dealer aktif ${pct(da.a/da.t*100)} dari target`:null,c.pp!=null?`Estimasi SELL THRU ${pct(c.pp)} dari target`:null].filter(Boolean);
 const subCards=subs.map(s=>({s,c:v6XCalc(v6XM(d.nodes[s],B,I),I,d)})).sort((a,b)=>a.c.hasT?(a.c.pp??999)-(b.c.pp??999):(a.c.g??999)-(b.c.g??999)).map(x=>v6XHierCard(d.nodes[x.s],x.s,B,I,d,{kind:'region',label:'SUB REGION',lead:d.nodes[x.s].lead||''})).join('');
 const brandRows=d.brands.map(b=>{const x=v6XM(n,b,'st'),cc=v6XCalc(x,'st',d);return {b,x,cc};}).filter(y=>y.x.a||y.x.t).sort((a,b)=>(a.cc.pp??999)-(b.cc.pp??999)).map(y=>`<div class="v6xbrow"><b>${esc(y.b)}</b><div class="v6xbar"><i style="width:${Math.min(100,y.cc.cap||0)}%;background:${v6XCol(y.cc.pp)}"></i><em style="left:${Math.min(100,y.cc.tg)}%"></em></div><b style="color:${v6XCol(y.cc.pp)}">${y.cc.pp==null?'—':pct(y.cc.pp)}</b><span class="${(y.cc.g||0)>=0?'v6up':'v6dn'}">${y.cc.g==null?'':(y.cc.g>=0?'+':'')+decimal(y.cc.g)+'%'}</span></div>`).join('');
 const chips=(arr,cur,attr)=>`<div class="v6xchips">${arr.map(([kk,l])=>`<button type="button" class="${kk===cur?'on':''}" ${attr}="${esc(kk)}">${esc(l)}</button>`).join('')}</div>`;
 v.innerHTML=`<div class="v6xwrap"><button type="button" class="v6xback" data-v6xback="1">‹ Nasional</button>
  ${v6XHero(n,'ALL','st',n.name+(n.lead?' | '+n.lead:''),d,1)}
  ${v6XOrgHeat(d,n)}
  <div class="v6xsec">Penyebab utama</div><div class="v6xbox"><ul class="v6xwhy">${why.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>
  ${v6XProjPanel('Proyeksi SELL THRU '+esc(n.name),v6XCum(d,k,'ALL',n),'v6xproj-detail')}
  <div class="v6xfsPanel" id="v6xsubpanel"><div class="v6xsec">Sub Region <button type="button" title="Layar penuh" aria-label="Layar penuh" class="v6xfsBtn" data-v6xfs="v6xsubpanel">⛶</button></div><div class="v6xbox">${chips([['ALL','Semua']].concat(d.brands.map(b=>[b,b])),B,'data-v6xbrand')}${chips(V6XI.map(x=>[x[0],x[1]]),I,'data-v6xind')}<div class="v6xhierGrid">${subCards||'<p class="hint">—</p>'}</div></div></div>
  <div class="v6xsec">Tren bulanan SELL THRU ${esc(n.name)} <span>${esc(V6X.brand==='ALL'?'semua brand':V6X.brand)}</span></div><div class="v6xbox">${v6XHist(d,k,V6X.brand)}</div>
  <div class="v6xsec">Kalender transaksi ${esc(n.name)}</div><div class="v6xbox">${v6XCalChips(d)}${v6XCal(d,k,V6X.calB||'ALL',n,k)}</div></div>`;
 v6XInfoAll();window.scrollTo(0,0);}
document.addEventListener('click',e=>{const t=e.target.closest&&e.target.closest('[data-v6xbrand],[data-v6xind],[data-v6xcalb],[data-v6xp],[data-v6xbd],[data-v6xd],[data-v6xback],[data-v6xfull],[data-v6xfs],[data-v6xday],[data-v6xtab],[data-v6xhmet],[data-v6xhm],[data-v6xah],[data-v6xrh],[data-v6xrl],[data-v6xbh],[data-v6xbl],.v6xheat [data-v6xb],.v6xbrow[data-v6xb]');if(!t||(PAGE!=='beranda'&&PAGE!=='eksekutif'))return;
 if(t.dataset.v6xhmet){V6X.heatMetric=['st','da','noo'].includes(t.dataset.v6xhmet)?t.dataset.v6xhmet:'st';return v6XKeep(v6ExecDraw);}
 if(t.dataset.v6xah){V6X.asmHeatMode=t.dataset.v6xah==='actual'?'actual':'proj';return v6XKeep(v6ExecDraw);}
 if(t.dataset.v6xrh){V6X.rgmHeatMode=t.dataset.v6xrh==='actual'?'actual':'proj';return v6XKeep(v6ExecDraw);}
 if(t.dataset.v6xrl){V6X.rgmHeatLevel=t.dataset.v6xrl==='sales'?'sales':'asm';return v6XKeep(v6ExecDraw);}
 if(t.dataset.v6xbh){V6X.bigHeatMode=t.dataset.v6xbh==='actual'?'actual':'proj';return v6XKeep(v6ExecDraw);}
 if(t.dataset.v6xbl){V6X.bigHeatLevel=t.dataset.v6xbl==='asm'?'asm':'sub';return v6XKeep(v6ExecDraw);}
 if(t.dataset.v6xhm){V6X.heatMode=t.dataset.v6xhm==='actual'?'actual':'proj';return v6XKeep(v6ExecDraw);}
 if(t.dataset.v6xbrand){V6X.brand=t.dataset.v6xbrand;return v6XKeep(v6ExecDraw);}
 if(t.dataset.v6xp){if(document.fullscreenElement===$('view')){V6X.fsFocus=null;document.exitFullscreen?.();}V6X.drill=t.dataset.v6xp;v6ExecDraw();return;}
 if(t.dataset.v6xbd){if(document.fullscreenElement===$('view')){V6X.fsFocus=null;document.exitFullscreen?.();}V6X.drill='BD|'+t.dataset.v6xbd.replace(/^BD\|/,'');v6ExecDraw();return;}
 if(t.dataset.v6xcalb){V6X.calB=t.dataset.v6xcalb;return v6XKeep(v6ExecDraw);}
 if(t.dataset.v6xind){V6X.ind=t.dataset.v6xind;return v6XKeep(v6ExecDraw);}
 if(t.dataset.v6xb){V6X.brand=t.dataset.v6xb;V6X.ind=v6XHeatMetric();v6ExecDraw();document.getElementById('v6xbpb')?.scrollIntoView({behavior:'smooth'});return;}
 if(t.dataset.v6xtab){V6X.tab=t.dataset.v6xtab;return v6XKeep(v6ExecDraw);}
 if(t.dataset.v6xday)return v6XDayPop(t.dataset.v6xday,t.dataset.ctx);
 if(t.dataset.v6xback){if(document.fullscreenElement===$('view'))V6X.fsFocus='v6xbpbpanel';V6X.drill=null;v6ExecDraw();window.scrollTo(0,0);return;}
 if(t.dataset.v6xfs){const view=$('view'),id=t.dataset.v6xfs,el=document.getElementById(id);if(!view||!el)return;if(document.fullscreenElement===view&&V6X.fsFocus===id){document.exitFullscreen?.();return;}V6X.fsFocus=id;V6X.fsLandscape=/heatpanel$/i.test(id);v6XApplyFsFocus();if(document.fullscreenElement!==view){const rq=view.requestFullscreen?.();if(rq&&rq.then)rq.then(()=>v6XFsOrientation(V6X.fsLandscape)).catch(()=>{});}else v6XFsOrientation(V6X.fsLandscape);return;}
 if(t.dataset.v6xfull){try{sessionStorage.setItem('v6full','1');}catch(err){}V6X.drill=null;navigateTo('beranda');return;}
 if(t.dataset.v6xd){const own=V6X.data&&V6X.data.ownBig;if(own&&!own.includes(t.dataset.v6xd.split('|')[1])){t.classList.add('v6xlock');setTimeout(()=>t.classList.remove('v6xlock'),1500);return;}if(document.fullscreenElement===$('view'))V6X.fsFocus='v6xsubpanel';V6X.drill=t.dataset.v6xd;v6ExecDrill(V6X.drill);}});

document.addEventListener('fullscreenchange',()=>{const view=$('view');if(document.fullscreenElement!==view){V6X.fsFocus=null;V6X.fsLandscape=false;v6XFsOrientation(false);if(view)view.classList.remove('v6xPresent');}else if(V6X.fsLandscape)v6XFsOrientation(true);v6XApplyFsFocus();});

function v6ProjFsSync(){document.querySelectorAll('[data-v6projfs]').forEach(b=>{const el=document.getElementById(b.dataset.v6projfs);{const on=document.fullscreenElement===el;b.textContent=on?'↙':'⛶';b.title=on?'Keluar layar penuh':'Layar penuh';b.setAttribute('aria-label',b.title);}});}
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-v6projfs]');if(!b)return;const el=document.getElementById(b.dataset.v6projfs);if(!el)return;if(document.fullscreenElement===el){document.exitFullscreen?.();return;}el.requestFullscreen?.().catch(()=>{});});
