/* ===== Animasi pembuka (Ombak DSM) — sekali per sesi, bisa dilewati ===== */
(function v6Splash(){try{
 if(sessionStorage.getItem('v6splash'))return;sessionStorage.setItem('v6splash','1');
 if(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const logo=(document.querySelector('.navBrand')||{}).src||'';
 const wave=(n,c)=>`<svg class="wv wv${n}" viewBox="0 0 800 200" preserveAspectRatio="none"><path d="M0 60 Q100 20 200 60 T400 60 T600 60 T800 60 V200 H0Z" fill="${c}"/></svg>`;
 const el=document.createElement('div');el.id='v6splash';
 el.innerHTML=`<span class="sk">Lewati ›</span>${wave(2,'rgba(47,184,214,.35)')}${wave(1,'rgba(255,255,255,.12)')}<div class="pl">${logo?`<img src="${logo}" alt="">`:''}</div><div class="tg">DSM</div>`;
 const done=()=>{if(!el.parentNode)return;el.classList.add('out');setTimeout(()=>el.remove(),450);};
 el.addEventListener('click',done);document.body.appendChild(el);setTimeout(done,2400);
}catch(e){}})();
/* PROMOTOR — sel kolom Daftar dealer. Filter brand aktif: brand itu tebal, brand lain samar; tanpa promotor brand itu = "-" + keterangan kecil. */
function v6PromHas(c,brand){const p=c&&c.promotor;if(!p)return false;if(!brand||brand==='ALL')return true;const B=String(brand).toUpperCase();return (p.brands||[]).some(x=>x[0]===B&&x[1]>0);}
function v6PromCell(c,brand){const p=c&&c.promotor;if(!p)return '<span class="v6prnone">-</span>';const B=brand&&brand!=='ALL'?String(brand).toUpperCase():'',list=p.brands||[],txt=x=>esc(x[0])+' '+num(x[1]);
 if(B&&!v6PromHas(c,brand))return `<span class="v6prom"><span class="v6prnone">-</span><small class="v6prbr v6prfade">${list.length?'ada promotor: '+list.map(txt).join(' · '):'brand belum diisi'}</small></span>`;
 const d=list.length?list.slice().sort((a,b)=>(b[0]===B)-(a[0]===B)).map(x=>!B?txt(x):x[0]===B?'<b class="v6prsel">'+txt(x)+'</b>':'<span class="v6prfade">'+txt(x)+'</span>').join(' · '):'brand belum diisi';
 return `<span class="v6prom"><span class="v6prpill">BER-PROMOTOR</span><small class="v6prbr">${d}</small></span>`;}
/* GRADE — kolom Grade di Daftar dealer: ikut filter Brand. */
function v6GradeOf(c,brand){const g=c&&c.grade;if(!g||!brand||brand==='ALL')return '';const B=String(brand).toUpperCase(),x=g.find(y=>y[0]===B);return x?x[1]:'';}
function v6GradeOk(c,brand,grade){if(!grade||grade==='ALL'||!brand||brand==='ALL')return true;return v6GradeOf(c,brand)===grade;}
function v6GradeSort(c,brand){return brand&&brand!=='ALL'?(v6GradeOf(c,brand)||'~'):(c.grade?c.grade.map(x=>x[1]).join(' '):'~');}
function v6GradeCell(c,brand){const g=c&&c.grade;if(!g||!g.length)return '<span class="v6prnone">-</span>';if(brand&&brand!=='ALL'){const v=v6GradeOf(c,brand);return v?'<span class="v6grade">'+esc(v)+'</span>':'<span class="v6prnone">-</span>';}return '<small class="v6grall">'+g.map(x=>esc(x[0])+' <b>'+esc(x[1])+'</b>').join(' · ')+'</small>';}
function v6GradeOpts(cs,brand,cur){if(!brand||brand==='ALL')return '<option value="ALL">Pilih brand dulu</option>';const B=String(brand).toUpperCase(),vals=[...new Set((cs||[]).map(c=>v6GradeOf(c,B)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'id',{numeric:true}));return '<option value="ALL">Semua grade'+(vals.length?' ('+vals.map(esc).join(', ')+')':'')+'</option>'+vals.map(v=>`<option value="${esc(v)}" ${v===cur?'selected':''}>${esc(v)}</option>`).join('');}
/* History Dealer: promotor & grade. */
let V6HG={brand:'',opts:[]};
function v6HistGradeOpts(cur){if(!V6HG.brand)return '<option value="ALL">Pilih 1 brand dulu</option>';return '<option value="ALL">Semua grade'+(V6HG.opts.length?' ('+V6HG.opts.map(esc).join(', ')+')':'')+'</option>'+V6HG.opts.map(v=>`<option value="${esc(v)}" ${v===cur?'selected':''}>${esc(v)}</option>`).join('');}
function v6HistGradeSync(r){V6HG={brand:r.promBrand||'',opts:r.gradeOptions||[]};const s=$('historyGrade');if(!s)return;s.innerHTML=v6HistGradeOpts(historyFilter.grade);s.disabled=!V6HG.brand;}
function v6HistGradeCell(c,brand){if(!c.grade||!c.grade.length)return '<span class="v6prnone">-</span>';if(brand)return c.gradeText?'<span class="v6grade">'+esc(c.gradeText)+'</span>':'<span class="v6prnone">-</span>';return '<small class="v6grall">'+c.grade.map(x=>esc(x[0])+' <b>'+esc(x[1])+'</b>').join(' · ')+'</small>';}
function v6HistPromCompare(r){const pc=r.promCompare;if(!pc||!r.months?.length)return '';const mo=r.months.map(m=>new Date(m.period+'-01T00:00:00Z').toLocaleDateString('id-ID',{month:'short',year:'2-digit',timeZone:'UTC'})),f=v=>v==null?'—':num(v),B=r.promBrand?' '+esc(r.promBrand):'',tot=pc.yes.sum.map((y,i)=>y==null&&pc.no.sum[i]==null?null:(y||0)+(pc.no.sum[i]||0)),share=pc.yes.sum.map((y,i)=>tot[i]?(Math.round((y||0)/tot[i]*1000)/10).toLocaleString('id-ID')+'%':'—');
 const row=(lbl,vals,cls='')=>`<tr class="${cls}"><td class="lbl">${lbl}</td>${vals.map(v=>`<td>${v}</td>`).join('')}</tr>`;
 return `<div class="v6hpc"><div class="v6hpch"><b>Ber-promotor vs Non promotor${B}</b><small>Total SELL THRU per bulan${r.promBrand?' (brand '+esc(r.promBrand)+')':' (brand yang ditampilkan)'} · seluruh hasil filter, bukan cuma halaman ini · status promotor = kondisi saat ini</small></div><div class="table-scroll"><table><thead><tr><th>Kelompok</th>${mo.map(m=>`<th>${esc(m)}</th>`).join('')}</tr></thead><tbody>${row('Ber-promotor · '+num(pc.yes.count)+' dealer',pc.yes.sum.map(f),'yes')}${row('Non promotor · '+num(pc.no.count)+' dealer',pc.no.sum.map(f))}${row('Total',tot.map(f),'tot')}${row('Kontribusi ber-promotor',share,'dif')}</tbody></table></div></div>`;}

/* Tampil/sembunyi kolom Promotor & Grade — per perangkat. */
const V6DOPT=['sub','asm','sales','status','prom','grade'],V6DDEF=['sub','status','prom','grade'],V6DLBL={sub:'Sub Region',asm:'ASM',sales:'Sales',status:'Status',prom:'Promotor',grade:'Grade'};
function v6DealerColKey(){return 'sp-dealer-cols2-'+((typeof BOOT!=='undefined'&&BOOT&&BOOT.user&&BOOT.user.nik)||'');}
function v6DealerCols(){try{const v=JSON.parse(localStorage.getItem(v6DealerColKey())||'null');if(Array.isArray(v))return v.filter(x=>V6DOPT.includes(x));}catch(e){}return V6DDEF.slice();}
function v6DealerColPicker(){const on=v6DealerCols();return `<details class="v6coltg"><summary class="chip">Kolom ▾</summary><div class="v6colbox"><label class="v6colfix"><input type="checkbox" checked disabled> Kode &amp; nama dealer</label><label class="v6colfix"><input type="checkbox" checked disabled> Big Region</label>${V6DOPT.map(k=>`<label><input type="checkbox" data-v6dc="${k}" ${on.includes(k)?'checked':''}> ${V6DLBL[k]}</label>`).join('')}<button type="button" class="chip" data-v6dcreset>Reset ke standar</button></div></details>`;}
document.addEventListener('change',e=>{const t=e.target;if(!t||!t.dataset||!t.dataset.v6dc)return;const on=new Set(v6DealerCols());t.checked?on.add(t.dataset.v6dc):on.delete(t.dataset.v6dc);try{localStorage.setItem(v6DealerColKey(),JSON.stringify([...on]));}catch(err){}$('customerRows')?._redraw?.();});
document.addEventListener('click',e=>{if(!e.target.closest||!e.target.closest('[data-v6dcreset]'))return;try{localStorage.removeItem(v6DealerColKey());}catch(err){}document.querySelectorAll('[data-v6dc]').forEach(c=>c.checked=V6DDEF.includes(c.dataset.v6dc));$('customerRows')?._redraw?.();});
/* History Dealer: kolom tetap = Kode | Nama dealer | Big Region; kolom tambahan bisa dipilih. */
const V6HOPT=['sub','sales','asm','rgm','grade','prom'],V6HDEF=['sub','sales','grade','prom'],V6HLBL={sub:'Sub Region',sales:'Sales',asm:'ASM',rgm:'RGM',grade:'Kategori',prom:'Promotor'};
function v6HKey(){return 'sp-hcols3-'+((typeof BOOT!=='undefined'&&BOOT&&BOOT.user&&BOOT.user.nik)||'');}
function v6HCols(){try{const v=JSON.parse(localStorage.getItem(v6HKey())||'null');if(Array.isArray(v))return V6HOPT.filter(x=>v.includes(x));}catch(e){}return V6HDEF.slice();}
function v6HistColPicker(){const on=v6HCols();return `<details class="v6coltg"><summary class="chip">Kolom ▾</summary><div class="v6colbox"><label class="v6colfix"><input type="checkbox" checked disabled> Kode dealer</label><label class="v6colfix"><input type="checkbox" checked disabled> Nama dealer</label><label class="v6colfix"><input type="checkbox" checked disabled> Big Region</label>${V6HOPT.map(k=>`<label><input type="checkbox" data-v6hc="${k}" ${on.includes(k)?'checked':''}> ${V6HLBL[k]}</label>`).join('')}<button type="button" class="chip" data-v6hcreset>Reset ke standar</button></div></details>`;}
let V6HLAST=null;
function v6HistRedraw(){const el=document.getElementById('dealerHistoryRows');if(!el||!V6HLAST)return;const sc=el.querySelector('.table-scroll');if(!sc)return;const prev=sc.previousElementSibling;if(prev&&prev.classList.contains('table-scroll-top'))prev.remove();const ind=V6HLAST.filters.indicators?.length?V6HLAST.filters.indicators:['ST','SO','OMZET'];sc.outerHTML=historyBrandMatrix(V6HLAST,ind);addTopTableScroll(el);el.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>detail(b.dataset.customer));if(typeof enableTableSorting==='function')enableTableSorting();}
document.addEventListener('change',e=>{const t=e.target;if(!t||!t.dataset||!t.dataset.v6hc)return;const on=new Set(v6HCols());t.checked?on.add(t.dataset.v6hc):on.delete(t.dataset.v6hc);try{localStorage.setItem(v6HKey(),JSON.stringify([...on]));}catch(err){}v6HistRedraw();});
document.addEventListener('click',e=>{if(!e.target.closest||!e.target.closest('[data-v6hcreset]'))return;try{localStorage.removeItem(v6HKey());}catch(err){}document.querySelectorAll('[data-v6hc]').forEach(c=>c.checked=V6HDEF.includes(c.dataset.v6hc));v6HistRedraw();});
const V6COLK={dealer:'sp-cols-dealer',history:'sp-cols-history'};
function v6ColGet(k){try{return JSON.parse(localStorage.getItem(V6COLK[k])||'{}')||{};}catch(e){return {};}}
function v6ColApply(){['history'].forEach(k=>{const c=v6ColGet(k);document.body.classList.toggle('v6h-'+k+'-prom',c.prom===false);document.body.classList.toggle('v6h-'+k+'-grade',c.grade===false);});}
function v6ColToggle(k){const c=v6ColGet(k);return `<details class="v6coltg"><summary class="chip">Kolom ▾</summary><div class="v6colbox"><label><input type="checkbox" data-v6col="${k}:prom" ${c.prom===false?'':'checked'}> Promotor</label><label><input type="checkbox" data-v6col="${k}:grade" ${c.grade===false?'':'checked'}> Grade</label></div></details>`;}
document.addEventListener('change',e=>{const t=e.target;if(!t||!t.dataset||!t.dataset.v6col)return;const [k,f]=t.dataset.v6col.split(':'),c=v6ColGet(k);c[f]=t.checked;try{localStorage.setItem(V6COLK[k],JSON.stringify(c));}catch(err){}v6ColApply();});
document.addEventListener('click',e=>{document.querySelectorAll('details.v6coltg[open]').forEach(d=>{if(!d.contains(e.target))d.open=false;});});
try{v6ColApply();}catch(e){document.addEventListener('DOMContentLoaded',v6ColApply);}
/* Export daftar user (tanpa PIN) — pakai daftar user di Admin > Akun pengguna (sudah sesuai kewenangan admin). */
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('#v6UserExport');if(!b)return;modal('Export daftar user',`<p class="hint">File berisi semua user yang Anda kelola + kolom STATUS PIN.</p><label style="display:flex;gap:8px;align-items:flex-start;margin:10px 0"><input type="checkbox" id="v6uxPin"> <span><b>Buat PIN sementara untuk user yang belum pernah login</b><br><small class="hint">PIN baru hanya untuk user yang belum punya PIN / belum pernah login (masih PIN sementara). User yang sudah login & ganti PIN tidak disentuh, kolom PIN-nya kosong. Export ulang = PIN sementara dibuat ulang, pakai file terakhir.</small></span></label><div class="v6oldTpl" id="v6uxWarn" hidden>File akan berisi PIN. Kirim ke masing-masing orang, jangan disebar ke grup.</div><div class="toolbar"><button class="chip primary" type="button" id="v6uxGo">Export</button><span id="v6uxMsg" class="hint"></span></div>`);$('v6uxPin').onchange=x=>{$('v6uxWarn').hidden=!x.target.checked;};$('v6uxGo').onclick=async x=>{x.target.disabled=true;$('v6uxMsg').textContent='Menyiapkan…';try{const pin=await rpc('apiUserPinExport',TOKEN,$('v6uxPin').checked);v6UserExportRun(pin.users);$('v6uxMsg').innerHTML='<b style="color:#15803d">✓ File di-download'+(pin.made?' · '+pin.made+' PIN sementara dibuat':'')+'.</b>';}catch(err){$('v6uxMsg').innerHTML='<b style="color:#b91c1c">'+esc(err.message||err)+'</b>';x.target.disabled=false;}};});
function v6UserExportRun(pins){pins=pins||{};try{const a=window.V6ADMIN;const users=(a&&a.users)||[];if(!users.length){alert('Daftar user belum dimuat.');return;}const by={};(a.bosses||[]).concat(users).forEach(u=>by[u.nik]=u);
 const rows=[['NIK','NAMA','JABATAN','RANGKAP SALES','REGION','SUB REGION / PORTOFOLIO','BIG REGION','NIK ATASAN','NAMA ATASAN','WILAYAH ADMIN','STATUS AKUN','STATUS PIN','PIN SEMENTARA']].concat(users.slice().sort((x,y)=>String(x.wilayah||'').localeCompare(String(y.wilayah||''))||String(x.role).localeCompare(String(y.role))||String(x.nama).localeCompare(String(y.nama))).map(u=>[u.nik,u.nama,u.role,u.sales&&u.role!=='SALES'?'YA':'',u.region||'',u.portfolio||'',u.wilayah||'',u.atasan||'',by[u.atasan]?.nama||'',(u.adminRegions||[]).join(' | '),u.active?'AKTIF':'NONAKTIF',(pins[u.nik]||{}).status||(u.hasPin?'ADA':'BELUM ADA PIN'),(pins[u.nik]||{}).pin||'']));
 window.V6XNAME='Daftar-User-'+new Date().toISOString().slice(0,10)+(Object.values(pins).some(x=>x.pin)?'-PIN':'')+'.xlsx';downloadContactXlsx(rows);}catch(err){alert('Export gagal: '+err.message);}}
