let V6RM=null;
function v6UploadLast(v){let r=null;try{r=JSON.parse(localStorage.getItem('sp-upload-last')||'null');}catch(e){}if(!r||!r.at)return;const d=document.createElement('div');d.className='v6upLast';d.innerHTML=`<b>✅ Upload terakhir berhasil</b> · ${r.kind==='ST'?'Sell Thru':'Sell Out'} ${r.multi?'multi-bulan ':''}<b>${esc((r.months||[]).join(', '))}</b> · lengkap s/d ${esc(tgl(r.cutoff))} · ${num(r.rows)} baris · QTY ${num(r.qty)} · ${esc((r.regions||[]).join(', '))}<small>${esc(new Date(r.at).toLocaleString('id-ID'))} oleh ${esc(r.by||'')}${r.warn?' · '+r.warn+' peringatan saat pemeriksaan':''}</small><button type="button" class="chip" aria-label="Tutup">Tutup</button>`;d.querySelector('button').onclick=()=>{try{localStorage.removeItem('sp-upload-last');}catch(e){}d.remove();};v.prepend(d);}
var V6BR=null;
/* Ambang status dealer per brand (Admin › Master › Brand): idle & pasif = bulan tanpa order. Kosong = ikut standar. */
function v6BrandThrPanel(v){v.insertAdjacentHTML('beforeend',panel('Brand · Ambang Status Dealer',`<p class="hint">Status dealer per brand dihitung dari bulan tanpa order brand tersebut. <b>Idle</b> = jumlah bulan tanpa order mulai dianggap idle, <b>Pasif</b> = mulai dianggap pasif. Kosongkan baris brand untuk ikut Standar. KPI Dealer Idle tetap memakai aturannya sendiri di editor KPI.</p><div id="v6thrBox"><p class="hint v6load">Memuat…</p></div>`,'Admin'));
 const draw=r=>{const std=r.thresholds?.std||[2,3];$('v6thrBox').innerHTML=`<div class="table-scroll"><table><thead><tr><th>Brand</th><th>Idle (bulan tanpa order)</th><th>Pasif (bulan tanpa order)</th><th>Keterangan</th></tr></thead><tbody><tr><td><b>Standar (semua brand)</b></td><td><input class="fi" data-thr="*:idle" value="${std[0]}" inputmode="numeric" style="width:70px"></td><td><input class="fi" data-thr="*:pasif" value="${std[1]}" inputmode="numeric" style="width:70px"></td><td><small>Dipakai bila brand tidak punya aturan sendiri</small></td></tr>${(r.rows||[]).filter(x=>x.aktif).map(x=>`<tr><td><b>${esc(x.brand)}</b></td><td><input class="fi" data-thr="${esc(x.brand)}:idle" value="${x.idle??''}" placeholder="standar" inputmode="numeric" style="width:70px"></td><td><input class="fi" data-thr="${esc(x.brand)}:pasif" value="${x.pasif??''}" placeholder="standar" inputmode="numeric" style="width:70px"></td><td><small>${x.idle!=null||x.pasif!=null?'Aturan khusus':'Ikut standar'}</small></td></tr>`).join('')}</tbody></table></div><div class="toolbar"><input class="fi" id="v6thrWhy" placeholder="Alasan perubahan, minimal 5 karakter" style="min-width:260px"><button class="chip primary" id="v6thrSave" type="button">Simpan & publish</button></div><p class="hint" id="v6thrMsg" role="alert"></p>`;
  $('v6thrSave').onclick=async()=>{const rows={};document.querySelectorAll('[data-thr]').forEach(i=>{const [b,k]=i.dataset.thr.split(':');(rows[b]=rows[b]||{brand:b})[k]=i.value.trim();});try{$('v6thrSave').disabled=true;await rpc('apiBrandThresholdSave',TOKEN,Object.values(rows),$('v6thrWhy').value);$('v6thrMsg').textContent='Tersimpan. Muat ulang halaman untuk melihat status terbaru.';rpc('apiBrandAdmin',TOKEN).then(draw);}catch(e){$('v6thrMsg').textContent=e.message;}finally{if($('v6thrSave'))$('v6thrSave').disabled=false;}};};
 rpc('apiBrandAdmin',TOKEN).then(draw).catch(e=>{$('v6thrBox').innerHTML='<div class="banner bad">'+esc(e.message||e)+'</div>';});}
function v6AdminBrandPanel(v){v.insertAdjacentHTML('beforeend',panel('Brand & Klasifikasi',`<p class="hint">Satu tempat untuk brand induk dan klasifikasi produk. Contoh: <b>TECNO ACC → TECNO · ACC · tidak masuk QTY device</b>. Nama klasifikasi existing dikunci; Brand Induk, Kategori, Hitung QTY, Status, dan Catatan bisa diubah dengan alasan + publish.</p><div class="toolbar"><button class="chip primary" id="v6brAdd" type="button">+ Tambah klasifikasi</button></div><div id="v6brBox"><p class="hint v6load">Memuat brand & klasifikasi…</p></div>`,'Admin'));
 const load=r=>{V6BR=r;v6BrDraw();};
 rpc('apiBrandAdmin',TOKEN).then(load).catch(e=>{$('v6brBox').innerHTML='<div class="banner bad">'+esc(e.message||e)+'</div>';});
 $('v6brAdd').onclick=()=>v6BrEdit(null);
 $('v6brBox').onclick=e=>{const b=e.target.closest('[data-br-edit]');if(!b)return;const r=(V6BR?.classifications||[])[+b.dataset.brEdit];if(r)v6BrEdit(r);};}
function v6BrDraw(){const box=$('v6brBox'),rows=V6BR?.classifications||[];if(!box)return;if(!rows.length){box.innerHTML='<p class="hint">Belum ada klasifikasi.</p>';return;}
 box.innerHTML='<div class="tableWrap"><table class="v6brT"><thead><tr><th>Klasifikasi</th><th>Brand Induk</th><th>Kategori Default</th><th>Hitung QTY Device</th><th class="n">Produk</th><th>Status</th><th>Catatan</th><th></th></tr></thead><tbody>'+rows.map((r,i)=>`<tr class="${r.active?'':'v6brOff'}"><td><b>${esc(r.name)}</b>${r.missingRule?'<small class="cellsub" style="color:#b45309">Belum ada Product Rule · klik Edit untuk melengkapi</small>':''}</td><td>${esc(r.parent||'—')}</td><td>${esc(r.category||'—')}</td><td>${r.qty?'<span class="pill ok">YA</span>':'<span class="pill">TIDAK</span>'}</td><td class="n">${num(r.products||0)}</td><td>${r.active?'<span class="pill ok">AKTIF</span>':'<span class="pill">NONAKTIF</span>'}</td><td>${esc(r.note||'')}</td><td><button class="chip" type="button" data-br-edit="${i}">Edit</button></td></tr>`).join('')+'</tbody></table></div>';}
function v6BrEdit(r){const parents=[...new Set([...(V6BR?.parents||[]),r?.parent||''].filter(Boolean))],cats=[...new Set([...(V6BR?.categories||[]),r?.category||''].filter(Boolean))];
 const pList='<datalist id="v6brParents">'+parents.map(x=>`<option value="${esc(x)}">`).join('')+'</datalist>',cList='<datalist id="v6brCats">'+cats.map(x=>`<option value="${esc(x)}">`).join('')+'</datalist>';
 modal(r?'Edit Brand & Klasifikasi':'Tambah Brand & Klasifikasi',`<form id="v6brForm">${pList}${cList}<div class="userForm"><label>Klasifikasi<input class="fi" name="name" value="${esc(r?.name||'')}" ${r?'readonly':''} maxlength="40" required><small>Contoh: TECNO / TECNO ACC / ACC MOTOPAD.</small></label><label>Brand Induk<input class="fi" name="parent" list="v6brParents" value="${esc(r?.parent||'')}" maxlength="40" required><small>Untuk brand utama baru, isi sama dengan Klasifikasi.</small></label><label>Kategori Default<input class="fi" name="category" list="v6brCats" value="${esc(r?.category||'')}" maxlength="40" placeholder="HP / ACC / LDU" required></label><label>Hitung QTY Device<select class="fi" name="qty"><option value="1" ${!r||r.qty?'selected':''}>YA</option><option value="0" ${r&&!r.qty?'selected':''}>TIDAK</option></select></label><label>Status<select class="fi" name="active"><option value="1" ${!r||r.active?'selected':''}>AKTIF</option><option value="0" ${r&&!r.active?'selected':''}>NONAKTIF</option></select></label><label>Catatan<input class="fi" name="note" value="${esc(r?.note||'')}" maxlength="200" placeholder="Opsional"></label></div>${r&&r.products?`<div class="v6oldTpl"><b>${num(r.products)} produk</b> memakai klasifikasi ini. Mengubah Brand Induk / Kategori / aturan QTY dapat mengubah pengelompokan histori, KPI, dan laporan periode sebelumnya.</div>`:''}<label>Alasan perubahan<input class="fi" id="v6brReason" placeholder="min. 5 karakter" required></label><button class="chip primary">${r?'Simpan & publish':'Tambah & publish'}</button></form>`);
 $('v6brForm').onsubmit=async e=>{e.preventDefault();const f=e.target,reason=$('v6brReason').value.trim();if(reason.length<5){fail(Error('Isi alasan minimal 5 karakter.'));return;}const x=Object.fromEntries(new FormData(f));x.original=r?.name||'';x.qty=x.qty==='1';x.active=x.active==='1';if(r&&r.products&&(x.parent!==r.parent||x.category!==r.category||x.qty!==!!r.qty)&&!confirm('Perubahan ini dapat mengubah pengelompokan histori/KPI. Lanjutkan?'))return;const b=f.querySelector('button');b.disabled=true;try{V6BR=await rpc('apiBrandClassificationSave',TOKEN,x,reason);closeModal();v6BrDraw();}catch(err){fail(err);b.disabled=false;}};}
function v6RegionMapPanel(v){v.insertAdjacentHTML('beforeend',panel('Region Map · Super Admin',`<p class="hint">Edit langsung tanpa upload. REGION = nama region/sub region yang dipakai user & dealer (mis. BIG PURWOKERTO). BIG REGION = kelompok besarnya (mis. JAWA TENGAH). Region yang masih dipakai user tidak bisa dihapus / diganti nama.</p><div class="toolbar"><input class="fi" id="v6rmQ" placeholder="Cari region / big region…" style="max-width:260px"><button class="chip" id="v6rmLoad" type="button">Muat Region Map</button><button class="chip" id="v6rmAdd" type="button" disabled>+ Tambah region</button></div><div id="v6rmBox"></div>`));
 $('v6rmLoad').onclick=async e=>{e.target.disabled=true;$('v6rmBox').innerHTML='<p class="hint v6load">Memuat…</p>';try{V6RM=await rpc('apiRegionMapGet',TOKEN);V6RM.orig=JSON.stringify(V6RM.rows.map(r=>[r.region,r.big,r.kanal]));$('v6rmAdd').disabled=false;v6RmDraw();}catch(err){$('v6rmBox').innerHTML='<p class="v6rmErr">'+esc(err.message||err)+'</p>';}finally{e.target.disabled=false;}};
 $('v6rmAdd').onclick=()=>{V6RM.rows.push({region:'',big:'',kanal:'',used:0,fresh:true});$('v6rmQ').value='';v6RmDraw();const ins=document.querySelectorAll('#v6rmBox input[data-f="region"]');ins[ins.length-1]?.focus();};
 $('v6rmQ').oninput=()=>v6RmDraw();}
function v6RmDraw(){if(!V6RM)return;const q=($('v6rmQ')?.value||'').toUpperCase().trim(),dl='<datalist id="v6rmBigs">'+V6RM.bigs.map(b=>`<option value="${esc(b)}">`).join('')+'</datalist>',cnt={};V6RM.rows.forEach(r=>{const k=r.region.trim().toUpperCase();if(k)cnt[k]=(cnt[k]||0)+1;});
 const rows=V6RM.rows.map((r,i)=>({r,i})).filter(x=>!x.r.del&&(!q||x.r.fresh||(x.r.region+' '+x.r.big).toUpperCase().includes(q)));
 const body=rows.map(({r,i})=>{const dup=cnt[r.region.trim().toUpperCase()]>1,miss=!r.region.trim()||!r.big.trim();return `<tr class="${dup||miss?'v6rmBad':''}"><td><input class="fi" data-i="${i}" data-f="region" value="${esc(r.region)}" ${r.used?'readonly title="Dipakai user — tidak bisa diganti nama"':''}></td><td><input class="fi" data-i="${i}" data-f="big" list="v6rmBigs" value="${esc(r.big)}"></td><td><select class="fi" data-i="${i}" data-f="kanal"><option value="" ${!r.kanal?'selected':''}>—</option><option value="ONLINE" ${r.kanal==='ONLINE'?'selected':''}>ONLINE</option></select></td><td class="n">${r.used?num(r.used)+' user':'<span class="hint">—</span>'}</td><td>${r.used?'<span class="hint">🔒</span>':`<button class="chip" type="button" data-rmdel="${i}">Hapus</button>`}</td></tr>`;}).join('');
 const live=V6RM.rows.filter(r=>!r.del),changed=JSON.stringify(live.filter(r=>r.region.trim()||r.big.trim()).map(r=>[r.region.trim(),r.big.trim(),r.kanal]))!==V6RM.orig,nDup=Object.values(cnt).filter(c=>c>1).length;
 $('v6rmBox').innerHTML=dl+`<p class="hint">${num(live.length)} region · ${num(V6RM.bigs.length)} Big Region${nDup?` · <b style="color:#b91c1c">${nDup} REGION dobel</b>`:''}</p><div class="table-scroll v6rmTable"><table><thead><tr><th>REGION</th><th>BIG REGION (WILAYAH_KPI)</th><th>KANAL</th><th class="n">DIPAKAI</th><th></th></tr></thead><tbody>${body||'<tr><td colspan="5">Tidak ada yang cocok.</td></tr>'}</tbody></table></div><div class="toolbar" style="margin-top:10px"><input class="fi" id="v6rmReason" placeholder="Alasan perubahan (min. 5 karakter)" style="max-width:340px"><button class="chip primary" id="v6rmSave" type="button" ${changed?'':'disabled'}>Simpan perubahan</button><span class="hint" id="v6rmMsg">${changed?'Ada perubahan belum disimpan.':(V6RM.flash||'Belum ada perubahan.')}</span></div>`;
 $('v6rmBox').querySelectorAll('[data-f]').forEach(el=>el.onchange=()=>{const r=V6RM.rows[+el.dataset.i];r[el.dataset.f]=el.dataset.f==='kanal'?el.value:el.value;v6RmDraw();});
 $('v6rmBox').querySelectorAll('[data-rmdel]').forEach(b=>b.onclick=()=>{const r=V6RM.rows[+b.dataset.rmdel];if(r.region&&!confirm('Hapus region '+r.region+'?'))return;r.del=true;v6RmDraw();});
 $('v6rmSave').onclick=async e=>{const reason=$('v6rmReason').value.trim();if(reason.length<5){$('v6rmMsg').innerHTML='<b style="color:#b91c1c">Isi alasan minimal 5 karakter.</b>';return;}e.target.disabled=true;$('v6rmMsg').textContent='Menyimpan & mem-publish…';try{const r=await rpc('apiRegionMapSave',TOKEN,V6RM.rows.filter(x=>!x.del).map(x=>({region:x.region,big:x.big,kanal:x.kanal})),reason);const fl=`<b style="color:#15803d">✓ Tersimpan & dipublish: ${num(r.total)} region (+${num(r.added)} / −${num(r.removed)}).</b>`;V6RM=await rpc('apiRegionMapGet',TOKEN);V6RM.orig=JSON.stringify(V6RM.rows.map(r=>[r.region,r.big,r.kanal]));V6RM.flash=fl;v6RmDraw();}catch(err){$('v6rmMsg').innerHTML='<span class="v6rmErr">'+esc(err.message||err).replace(/\n/g,'<br>')+'</span>';e.target.disabled=false;}};}

/* VACANT: user sales bayangan untuk area kosong (NIK diawali VAC / nama diawali VACANT).
   Angka tetap masuk total ASM/RGM; tidak ikut diberi nomor peringkat; tampil abu-abu. */
function v6IsVac(nik,nama){return /^VAC/i.test(String(nik||''))||/^VACANT\b/i.test(String(nama||'').trim());}
function v6MarkVac(root){(root||document).querySelectorAll('tbody tr:not([data-v6vac])').forEach(tr=>{tr.dataset.v6vac='1';const cs=[...tr.cells].slice(0,2);cs.forEach(c=>{const t=c.textContent.trim();if(/^VACANT\b/i.test(t)||/^VAC[-_]/i.test(t)){tr.classList.add('v6vac');if(!/^VACANT\b/i.test(t)&&!c.querySelector('.v6vacb'))c.insertAdjacentHTML('afterbegin','<span class="v6vacb">VACANT</span> ');}});if(tr.classList.contains('v6vac')&&/^\s*\d+\s*$/.test(tr.cells[0]?.textContent||''))tr.cells[0].textContent='—';});}
try{let V6VT=0;new MutationObserver(()=>{clearTimeout(V6VT);V6VT=setTimeout(()=>v6MarkVac(document.getElementById('view')),120);}).observe(document.getElementById('view')||document.body,{childList:true,subtree:true});}catch(e){}
/* ===== Cek Kesehatan Master ===== */
let V6H=null,V6HSTEP=0;
function v6HealthPanelHtml(){return panel('Cek Kesehatan Master',`<p class="hint">Cek semua master sekaligus. Ikuti urutan langkah — bereskan yang <b style="color:#b91c1c">merah</b> dulu (bikin data gagal publish), baru yang oranye.</p><div class="toolbar"><button class="chip primary" type="button" id="v6hRun">Periksa sekarang</button><button class="chip" type="button" id="v6hXls" disabled>Download hasil (Excel)</button><span class="hint" id="v6hMeta"></span></div><div id="v6hBox"></div>`);}
function v6HDraw(){const r=V6H,box=$('v6hBox');if(!r||!box)return;const lv={r:['GAGAL PUBLISH','v6hR'],o:['DATA','v6hO'],i:['INFO','v6hI']},acts={regionmap:['Region Map','Region Map'],users:['Akun pengguna','Akun pengguna'],merge:['Akun pengguna','Gabung akun'],productrules:['Brand & Klasifikasi','Brand & Klasifikasi'],dealer:['Bulk edit customer','Upload dealer'],transfer:['Transfer dealer','Transfer dealer'],'cari & edit':['Cari & edit dealer','Edit dealer'],product:['Master Product','Master Product'],picbrand:['PIC Dealer per Brand','Atur PIC']};
 const list=r.issues.filter(x=>!V6HSTEP||x.step===V6HSTEP);
 box.innerHTML=`<div class="v6hNext ${r.steps.some(s=>s.red)?'bad':'ok'}">${esc(r.next)}</div><div class="v6hSteps">${r.steps.map(s=>`<button type="button" class="v6hStep ${s.red?'bad':s.orange?'warn':'ok'} ${V6HSTEP===s.id?'on':''}" data-v6hstep="${s.id}"><b>${s.id}. ${esc(s.name)}</b><span>${s.red?s.red+' merah':''}${s.red&&s.orange?' · ':''}${s.orange?s.orange+' oranye':''}${!s.red&&!s.orange?(s.info?s.info+' info':'OK ✓'):''}</span></button>`).join('')}</div>`+
 (list.length?`<div class="table-scroll"><table class="v6hTable"><thead><tr><th>Langkah</th><th>Tingkat</th><th>Masalah</th><th>Cara benerin</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td>${x.step}. ${esc((r.steps.find(s=>s.id===x.step)||{}).name||'')}</td><td><span class="v6hPill ${lv[x.level][1]}">${lv[x.level][0]}</span></td><td>${esc(x.problem)}</td><td class="v6hFix">${esc(x.fix)}</td><td>${acts[x.action]?`<button class="chip" type="button" data-v6hgo="${esc(acts[x.action][0])}">${esc(acts[x.action][1])} →</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<p class="hint">Tidak ada masalah di langkah ini ✓</p>')+
 `<p class="hint">${num(r.info.users)} user · ${num(r.info.dealers)} dealer · ${num(r.info.products)} produk · ${num(r.info.regions)} region${r.info.cutoff?' · data s.d. '+esc(r.info.cutoff):''} · dicek dalam ${(r.info.ms/1000).toFixed(1)} dtk${r.total>r.issues.length?' · menampilkan '+r.issues.length+' dari '+r.total+' (lengkap di Excel)':''}</p>`;}
document.addEventListener('click',async e=>{const t=e.target.closest&&e.target.closest('#v6hRun,#v6hXls,[data-v6hstep],[data-v6hgo]');if(!t)return;
 if(t.id==='v6hRun'){t.disabled=true;$('v6hMeta').textContent='Memeriksa semua master… (bisa 10–40 detik)';try{V6H=await rpc('apiHealthCheck',TOKEN);V6HSTEP=0;$('v6hMeta').textContent='Terakhir: '+V6H.at+' · '+V6H.total+' temuan';$('v6hXls').disabled=false;v6HDraw();v6HBanner();}catch(err){$('v6hMeta').innerHTML='<b style="color:#b91c1c">'+esc(err.message||err)+'</b>';}finally{t.disabled=false;}return;}
 if(t.id==='v6hXls'&&V6H){const L={r:'GAGAL PUBLISH',o:'DATA',i:'INFO'};window.V6XNAME='Cek-Kesehatan-Master-'+new Date().toISOString().slice(0,10)+'.xlsx';downloadContactXlsx([['LANGKAH','TINGKAT','MASALAH','CARA BENERIN'],...V6H.issues.map(x=>[x.step+'. '+((V6H.steps.find(s=>s.id===x.step)||{}).name||''),L[x.level],x.problem,x.fix])]);return;}
 if(t.dataset.v6hstep){const s=+t.dataset.v6hstep;V6HSTEP=V6HSTEP===s?0:s;v6HDraw();return;}
 if(t.dataset.v6hgo){const key=t.dataset.v6hgo.toLowerCase(),h=[...document.querySelectorAll('#view .panel h3, #view summary')].find(x=>x.textContent.toLowerCase().includes(key));if(h){if(typeof v6TabGo==='function')v6TabGo(h);let el=h;while(el){if(el.tagName==='DETAILS')el.open=true;el=el.parentElement;}const sec=h.closest('section,details')||h;sec.scrollIntoView({behavior:'smooth',block:'start'});sec.classList.add('v6hFlash');setTimeout(()=>sec.classList.remove('v6hFlash'),1800);}}});
function v6HBanner(){const v=$('view');if(!v||!V6H)return;let b=$('v6hBanner');const red=V6H.issues.filter(x=>x.level==='r').length,or=V6H.issues.filter(x=>x.level==='o').length;if(!red&&!or){if(b)b.remove();return;}if(!b){b=document.createElement('div');b.id='v6hBanner';v.prepend(b);}b.className='v6hBanner';b.innerHTML=`⚠ <span>${red?`<b>${red} masalah master merah</b>`:''}${red&&or?' · ':''}${or?`${or} perlu dicek`:''}</span><a href="#" onclick="document.getElementById('v6hBox').scrollIntoView({behavior:'smooth'});return false;">Lihat →</a>`;}
/* ===== Gabung akun & Hapus akun (Super Admin) ===== */
function v6AcctOpts(){const us=(window.V6ADMIN&&V6ADMIN.users)||[];return '<datalist id="v6AcctList">'+us.map(u=>`<option value="${esc(u.nik)}">${esc(u.nama)} · ${esc(u.role)}</option>`).join('')+'</datalist>';}
function v6AcctMergeOpen(){modal('Gabung akun',`<p class="hint">Untuk orang yang sama dengan dua NIK. Semua yang menunjuk ke akun yang <b>dihapus</b> (bawahan, dealer, target, akses) dipindah ke akun yang <b>dipertahankan</b>, lalu akun lama dihapus. NIK yang dihapus boleh NIK yang cuma muncul sebagai atasan (tidak punya akun).</p>${v6AcctOpts()}<div class="userForm"><label>Pertahankan (NIK)<input class="fi" id="v6mKeep" list="v6AcctList" placeholder="mis. JEJEN"></label><label>Hapus / gabungkan (NIK)<input class="fi" id="v6mDrop" list="v6AcctList" placeholder="mis. 2014.01.08.01"></label></div><button class="chip" id="v6mPrev" type="button">Lihat pratinjau</button><div id="v6mBox"></div>`);
 $('v6mPrev').onclick=async e=>{e.target.disabled=true;$('v6mBox').innerHTML='<p class="hint">Memeriksa…</p>';try{const r=await rpc('apiAccountMergePreview',TOKEN,$('v6mKeep').value,$('v6mDrop').value);
  const refs=r.refs.length?'<ul>'+r.refs.map(x=>`<li>${num(x.count)} ${esc(x.what)} <span class="hint">(${esc(x.sheet)})</span></li>`).join('')+'</ul>':'<p class="hint">Tidak ada data yang menunjuk ke akun ini.</p>';
  $('v6mBox').innerHTML=`<div class="note"><b>${esc(r.drop)}${r.dropName?' · '+esc(r.dropName):''}</b> → <b>${esc(r.keep)}${r.keepName?' · '+esc(r.keepName):''}</b>${r.roles.length?' · jabatan di akun lama: '+r.roles.map(esc).join(', '):' · (tidak punya baris akun, hanya direferensikan)'}${refs}</div>`+(r.block.length?`<p class="v6rmErr">${r.block.map(esc).join('<br>')}</p>`:`<div class="toolbar"><input class="fi" id="v6mReason" placeholder="Alasan (min. 5 karakter)"><button class="chip primary" id="v6mGo" type="button">Gabungkan</button></div><p class="hint" id="v6mMsg"></p>`);
  if($('v6mGo'))$('v6mGo').onclick=async b=>{if(!confirm('Gabungkan '+r.drop+' ke '+r.keep+'? Akun '+r.drop+' akan dihapus.'))return;b.target.disabled=true;$('v6mMsg').textContent='Menyimpan & publish…';try{await rpc('apiAccountMergeCommit',TOKEN,r.keep,r.drop,$('v6mReason').value);$('v6mMsg').innerHTML='<b style="color:#15803d">✓ Selesai. Tampilan akan dimuat ulang.</b>';setTimeout(()=>{closeModal?.();render();},1200);}catch(err){$('v6mMsg').innerHTML='<span class="v6rmErr">'+esc(err.message||err)+'</span>';b.target.disabled=false;}};
 }catch(err){$('v6mBox').innerHTML='<p class="v6rmErr">'+esc(err.message||err)+'</p>';}finally{e.target.disabled=false;}};}
function v6AcctDelOpen(){modal('Hapus akun',`<p class="hint">Hanya untuk akun salah input yang belum dipakai: tidak punya bawahan, dealer, target, atau transaksi. Akun yang pernah dipakai → Nonaktifkan saja. Orang yang sama dengan dua NIK → Gabung akun.</p>${v6AcctOpts()}<div class="userForm"><label>NIK<input class="fi" id="v6dNik" list="v6AcctList"></label></div><button class="chip" id="v6dChk" type="button">Periksa</button><div id="v6dBox"></div>`);
 $('v6dChk').onclick=async e=>{e.target.disabled=true;try{const r=await rpc('apiAccountDeleteCheck',TOKEN,$('v6dNik').value);$('v6dBox').innerHTML=`<div class="note"><b>${esc(r.nik)}${r.nama?' · '+esc(r.nama):''}</b></div>`+(r.block.length?`<p class="v6rmErr">${r.block.map(esc).join('<br>')}</p>`:`<div class="toolbar"><input class="fi" id="v6dReason" placeholder="Alasan (min. 5 karakter)"><button class="chip primary" id="v6dGo" type="button">Hapus akun</button></div><p class="hint" id="v6dMsg"></p>`);
  if($('v6dGo'))$('v6dGo').onclick=async b=>{if(!confirm('Hapus akun '+r.nik+'?'))return;b.target.disabled=true;try{await rpc('apiAccountDelete',TOKEN,r.nik,$('v6dReason').value);$('v6dMsg').innerHTML='<b style="color:#15803d">✓ Akun dihapus.</b>';setTimeout(()=>{closeModal?.();render();},1200);}catch(err){$('v6dMsg').innerHTML='<span class="v6rmErr">'+esc(err.message||err)+'</span>';b.target.disabled=false;}};
 }catch(err){$('v6dBox').innerHTML='<p class="v6rmErr">'+esc(err.message||err)+'</p>';}finally{e.target.disabled=false;}};}
document.addEventListener('click',e=>{const t=e.target.closest&&e.target.closest('#v6AcctMerge,#v6AcctDel');if(!t)return;if(t.id==='v6AcctMerge')v6AcctMergeOpen();else v6AcctDelOpen();});
/* ===== Upload dealer (tambah + edit) — mesin sama dengan Sync ===== */
function v6DealerUploadHtml(){return panel('Upload dealer (tambah + edit)',`<p class="hint">Satu file untuk dealer baru & perubahan data dealer. Aturan sama persis dengan Sync Master Customer. Maks 20.000 baris. Baris yang salah dilewati — download file DITOLAK untuk memperbaikinya.</p><div class="toolbar"><button class="chip" type="button" id="v6duAll">Download data dealer</button></div><form id="v6duForm"><input type="hidden" name="token" value="${esc(TOKEN)}"><div class="toolbar"><input class="fi" type="file" name="file" accept=".xlsx,.csv" required><button class="chip primary" type="submit">Periksa file</button></div></form><div id="v6duBox"></div>`);}
document.addEventListener('click',async e=>{const t=e.target.closest&&e.target.closest('#v6duAll');if(!t)return;t.disabled=true;const old=t.textContent;t.textContent='Menyiapkan…';try{downloadBase64(await rpc('apiDealerDownloadAll',TOKEN));}catch(err){fail(err);}finally{t.disabled=false;t.textContent=old;}});
document.addEventListener('submit',async e=>{if(e.target.id!=='v6duForm')return;e.preventDefault();const f=e.target,b=f.querySelector('button'),box=$('v6duBox');b.disabled=true;box.innerHTML='<p class="hint">Memeriksa file… (file besar bisa 20–60 detik)</p>';
 try{const r=await rpc('apiDealerUploadStage',f);
  box.innerHTML=`<div class="note"><b>${esc(r.name)}</b> · ${num(r.total)} baris → <b style="color:#15803d">${num(r.add)} baru</b> · ${num(r.upd)} update · ${num(r.same)} sama${r.dupSame?' · '+num(r.dupSame)+' kembar dilewati':''} · <b style="color:${r.rejected?'#b91c1c':'#15803d'}">${num(r.rejected)} ditolak</b></div>`+((r.induk&&r.induk.length)||r.namaFix?`<p class="note" style="background:#eff6ff;border-color:#93c5fd">${r.induk&&r.induk.length?`<b>Ganti kode induk ${r.induk.length}:</b> ${r.induk.slice(0,8).map(x=>esc(x.lama)+' → '+esc(x.baru)).join(' · ')}${r.induk.length>8?' · dst.':''} — semua toko di induk lama ikut pindah, histori tetap nyambung. `:''}${r.namaFix?`Nama induk diseragamkan di ${num(r.namaFix)} baris.`:''}</p>`:'')+(r.ignored&&r.ignored.length?`<p class="v6oldTpl">⚠ Kolom ini <b>tidak dikenal & diabaikan</b>: ${r.ignored.map(esc).join(', ')}. Kemungkinan file pakai <b>template lama</b> atau nama kolom berubah — isinya TIDAK tersimpan. Download data dealer terbaru, pindahkan isinya ke kolom yang benar, lalu upload lagi.</p>`:'')+
  (r.rejected?`<div class="toolbar"><button class="chip" type="button" id="v6duRej">Download DITOLAK (${num(r.rejected)} baris + alasan & solusi)</button></div><div class="table-scroll"><table><thead><tr><th>ID_DEALER</th><th>KODE</th><th>Alasan</th><th>Solusi</th></tr></thead><tbody>${r.sample.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.kode)}</td><td class="v6rmErr" style="font-weight:600">${esc(x.alasan)}</td><td class="v6hFix">${esc(x.solusi)}</td></tr>`).join('')}</tbody></table></div>${r.rejected>50?'<p class="hint">Menampilkan 50 pertama — lengkap di file DITOLAK.</p>':''}`:'')+
  (r.add||r.upd?`<div class="toolbar" style="margin-top:8px"><input class="fi" id="v6duReason" placeholder="Alasan (min. 5 karakter)" style="max-width:320px"><button class="chip primary" type="button" id="v6duGo">Simpan ${num(r.add+r.upd)} baris</button></div>`:'<p class="hint">Tidak ada perubahan untuk disimpan.</p>')+'<p class="hint" id="v6duMsg"></p>';
  if($('v6duRej'))$('v6duRej').onclick=async x=>{x.target.disabled=true;try{downloadBase64(await rpc('apiDealerUploadRejected',TOKEN,r.id));}catch(err){fail(err);}finally{x.target.disabled=false;}};
  if($('v6duGo'))$('v6duGo').onclick=async x=>{x.target.disabled=true;$('v6duMsg').textContent='Menyimpan & publish…';try{const c=await rpc('apiDealerUploadCommit',TOKEN,r.id,$('v6duReason').value);$('v6duMsg').innerHTML='<b style="color:#15803d">✓ '+esc(c.note)+'</b>';}catch(err){$('v6duMsg').innerHTML='<span class="v6rmErr">'+esc(err.message||err)+'</span>';x.target.disabled=false;}};
 }catch(err){box.innerHTML='<p class="v6rmErr">Gagal: '+esc(err.message||err)+'</p>';}finally{b.disabled=false;}});
function v6UserRejHtml(r){if(!r.rejected)return '';return `<div class="note"><b style="color:#b91c1c">${num(r.rejected)} baris ditolak</b> — baris lain tetap bisa dibuat. <button class="chip" type="button" id="v6urRej">Download DITOLAK (alasan & solusi)</button></div><div class="table-scroll"><table><thead><tr><th>NIK</th><th>Nama</th><th>Alasan</th><th>Solusi</th></tr></thead><tbody>${r.rejectedSample.map(x=>`<tr><td>${esc(x.nik)}</td><td>${esc(x.nama)}</td><td class="v6rmErr" style="font-weight:600">${esc(x.alasan)}</td><td class="v6hFix">${esc(x.solusi)}</td></tr>`).join('')}</tbody></table></div>`;}
/* ===== Update status akun massal ===== */
function v6StatusBulkOpen(){modal('Update status akun massal',`<p class="hint">Pakai file dari <b>Export daftar user</b>. Ubah kolom <b>STATUS AKUN</b> jadi AKTIF / NONAKTIF, lalu upload. Hanya kolom NIK & STATUS AKUN yang dibaca. Akun yang diaktifkan tapi belum punya PIN otomatis dibuatkan PIN sementara.</p><form id="v6sbForm"><input type="hidden" name="token" value="${esc(TOKEN)}"><div class="toolbar"><input class="fi" type="file" name="file" accept=".xlsx,.csv" required><button class="chip primary" type="submit">Periksa file</button></div></form><div id="v6sbBox"></div>`);}
document.addEventListener('click',e=>{if(e.target.closest&&e.target.closest('#v6StatusBulk'))v6StatusBulkOpen();});
document.addEventListener('submit',async e=>{if(e.target.id!=='v6sbForm')return;e.preventDefault();const b=e.target.querySelector('button'),box=$('v6sbBox');b.disabled=true;box.innerHTML='<p class="hint">Memeriksa file…</p>';
 try{const r=await rpc('apiStatusBulkStage',e.target),on=r.changes.filter(x=>x.to==='AKTIF'),off=r.changes.filter(x=>x.to==='NONAKTIF');
  box.innerHTML=`<div class="note"><b style="color:#15803d">${num(on.length)} diaktifkan</b> · <b style="color:#b45309">${num(off.length)} dinonaktifkan</b> · ${num(r.same)} tetap · <b style="color:${r.rejected?'#b91c1c':'#15803d'}">${num(r.rejected)} ditolak</b></div>`+
  (r.changes.length?`<div class="table-scroll"><table><thead><tr><th>NIK</th><th>Nama</th><th>Jabatan</th><th>Sekarang</th><th>Jadi</th></tr></thead><tbody>${r.changes.slice(0,100).map(x=>`<tr><td>${esc(x.nik)}</td><td>${esc(x.nama)}</td><td>${esc(x.role)}</td><td>${esc(x.from)}</td><td><b>${esc(x.to)}</b>${x.newPin?' <span class="hint">+ PIN baru</span>':''}</td></tr>`).join('')}</tbody></table></div>`:'')+
  (r.rejected?`<div class="toolbar"><button class="chip" type="button" id="v6sbRej">Download DITOLAK</button></div><div class="table-scroll"><table><tbody>${r.rejectedSample.map(x=>`<tr><td>${esc(x.nik)}</td><td class="v6rmErr" style="font-weight:600">${esc(x.alasan)}</td><td class="v6hFix">${esc(x.solusi)}</td></tr>`).join('')}</tbody></table></div>`:'')+
  (r.changes.length?`<div class="toolbar"><input class="fi" id="v6sbReason" placeholder="Alasan (min. 5 karakter)" style="max-width:300px"><button class="chip primary" type="button" id="v6sbGo">Simpan ${num(r.changes.length)} perubahan</button></div>`:'<p class="hint">Tidak ada perubahan status.</p>')+'<div id="v6sbMsg"></div>';
  if($('v6sbRej'))$('v6sbRej').onclick=async x=>{try{downloadBase64(await rpc('apiStatusBulkRejected',TOKEN,r.id));}catch(err){fail(err);}};
  if($('v6sbGo'))$('v6sbGo').onclick=async x=>{if(off.length&&!confirm(off.length+' akun dinonaktifkan — mereka tidak bisa login. Lanjut?'))return;x.target.disabled=true;try{const c=await rpc('apiStatusBulkCommit',TOKEN,r.id,$('v6sbReason').value);$('v6sbMsg').innerHTML=`<p style="color:#15803d;font-weight:700">✓ ${num(c.updated)} akun diperbarui.</p>`+(c.pins.length?`<p class="hint">PIN sementara (sampaikan pribadi; wajib ganti saat masuk):</p><button class="chip primary" type="button" id="v6sbPin">Unduh PIN sementara</button>`:'');if($('v6sbPin'))$('v6sbPin').onclick=()=>{window.V6XNAME='PIN-Sementara-'+new Date().toISOString().slice(0,10)+'.xlsx';downloadContactXlsx([['NIK','NAMA','JABATAN','PIN SEMENTARA'],...c.pins.map(p=>[p.nik,p.nama,p.role,p.pin])]);};}catch(err){$('v6sbMsg').innerHTML='<p class="v6rmErr">'+esc(err.message||err)+'</p>';x.target.disabled=false;}};
 }catch(err){box.innerHTML='<p class="v6rmErr">Gagal: '+esc(err.message||err)+'</p>';}finally{b.disabled=false;}});
/* ===== Status Sync di aplikasi ===== */
function v6SyncPanelHtml(){return panel('Status Sync',`<p class="hint">Riwayat upload &amp; perubahan data terakhir. Upload data dilakukan lewat halaman Admin (ST, SO, Dealer, User, dst.); file DITOLAK diunduh langsung dari hasil upload.</p><div class="toolbar"><button class="chip" type="button" id="v6syLoad">Muat status</button><button class="chip primary" type="button" id="v6syRun" disabled>Sync sekarang</button><button class="chip" type="button" id="v6sySch" disabled>Jadwal otomatis</button><span class="hint" id="v6syMsg"></span></div><div id="v6syBox"></div>`);}
async function v6SyLoad(){const box=$('v6syBox');box.innerHTML='<p class="hint v6load">Memuat…</p>';const r=await rpc('apiSyncStatus',TOKEN);window.V6SY=r;$('v6syRun').disabled=!r.configured;$('v6sySch').disabled=!r.configured;$('v6sySch').textContent='Jadwal otomatis: '+(r.schedule?'ON':'OFF');
 if(!r.configured){box.innerHTML=(r.log.length?'<h4 style="margin:10px 0 4px">Riwayat (40 terakhir)</h4><div class="table-scroll"><table><thead><tr>'+Object.keys(r.log[0]).map(k=>`<th>${esc(k)}</th>`).join('')+'</tr></thead><tbody>'+r.log.map(x=>`<tr>${Object.values(x).map(v=>`<td style="white-space:normal">${esc(v)}</td>`).join('')}</tr>`).join('')+'</tbody></table></div>':'<p class="hint">Belum ada riwayat.</p>');return;}
 const st=x=>/GAGAL|DITOLAK/.test(x)?'color:#b91c1c':/SEBAGIAN/.test(x)?'color:#b45309':'color:#15803d';
 box.innerHTML=`<div class="v6hSteps"><div class="v6hStep ${r.masuk?'warn':'ok'}"><b>1. MASUK</b><span>${num(r.masuk)} file menunggu</span></div><div class="v6hStep ok"><b>2. SELESAI</b><span>${num(r.selesai)} file</span></div><div class="v6hStep ${r.gagal?'bad':'ok'}"><b>3. GAGAL</b><span>${num(r.gagal)} file</span></div>${r.folderUrl?`<a class="v6hStep" style="text-decoration:none" href="${esc(r.folderUrl)}" target="_blank" rel="noopener"><b>Buka folder ↗</b><span>Google Drive</span></a>`:''}</div>`+
 (r.failed.length?`<h4 style="margin:8px 0 4px">File di 3. GAGAL</h4><div class="table-scroll"><table><thead><tr><th>File</th><th>Masuk</th><th></th></tr></thead><tbody>${r.failed.map(f=>`<tr><td>${/^DITOLAK-/.test(f.name)?'<span class="v6hPill v6hR">DITOLAK</span> ':''}${esc(f.name)}</td><td>${esc(f.at)}</td><td><button class="chip" type="button" data-v6sydl="${esc(f.id)}">Download</button> ${/^DITOLAK-/.test(f.name)?'':`<button class="chip" type="button" data-v6syre="${esc(f.id)}">Proses ulang</button>`}</td></tr>`).join('')}</tbody></table></div><p class="hint">File DITOLAK: perbaiki baris sesuai kolom SOLUSI, lalu taruh lagi di folder 1. MASUK (atau upload lewat menu terkait).</p>`:'')+
 (r.log.length?`<h4 style="margin:10px 0 4px">Riwayat Sync (40 terakhir)</h4><div class="table-scroll"><table><thead><tr>${Object.keys(r.log[0]).map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${r.log.map(x=>`<tr>${Object.entries(x).map(([k,v])=>`<td style="${/STATUS/i.test(k)?st(v)+';font-weight:700':''};white-space:normal">${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<p class="hint">Belum ada riwayat.</p>');}
document.addEventListener('click',async e=>{const t=e.target.closest&&e.target.closest('#v6syLoad,#v6syRun,#v6sySch,[data-v6sydl],[data-v6syre]');if(!t)return;t.disabled=true;const msg=$('v6syMsg');
 try{if(t.id==='v6syLoad')await v6SyLoad();
  else if(t.id==='v6syRun'){msg.textContent='Memproses file di 1. MASUK… (bisa beberapa menit)';const r=await rpc('apiSyncRunNow',TOKEN);msg.innerHTML=r.busy?'<b style="color:#b45309">Sync lain sedang berjalan, coba lagi sebentar.</b>':r.processed?`<b>Selesai: ${num(r.ok)} sukses${r.partial?' ('+num(r.partial)+' ada baris DITOLAK)':''}, ${num(r.fail)} gagal${r.left?', '+num(r.left)+' file lanjut di putaran berikutnya':''}.</b>`:'Tidak ada file di 1. MASUK.';await v6SyLoad();}
  else if(t.id==='v6sySch'){const on=!(window.V6SY&&V6SY.schedule);if(!confirm('Jadwal otomatis '+(on?'dinyalakan (tiap 15 menit)':'dimatikan')+'?'))return;await rpc('apiSyncSchedule',TOKEN,on);await v6SyLoad();}
  else if(t.dataset.v6sydl)downloadBase64(await rpc('apiSyncFileDownload',TOKEN,t.dataset.v6sydl));
  else if(t.dataset.v6syre){await rpc('apiSyncRetry',TOKEN,t.dataset.v6syre);msg.textContent='File dipindah ke 1. MASUK — klik Sync sekarang.';await v6SyLoad();}
 }catch(err){msg.innerHTML='<span class="v6rmErr">'+esc(err.message||err)+'</span>';}finally{t.disabled=false;if(t.id==='v6syRun'||t.id==='v6sySch')t.disabled=!(window.V6SY&&V6SY.configured);}});

/* ===== Big Region per dealer (Dealer_Region) · Super Admin ===== */
let V6DR=null;
function v6DealerRegionPanel(v){v.insertAdjacentHTML('beforeend',panel('Big Region per dealer · Super Admin',`<p class="hint">Pindahkan satu dealer ke Big Region lain mulai tanggal tertentu, tanpa ganti Sales. Transaksi sebelum tanggal itu tetap di Big Region lama. Transfer dealer ke Sales di Big Region lain sudah otomatis mengisi ini. Riwayat tidak bisa dihapus — koreksi dengan menambah baris baru.</p>
<div class="userForm v6drForm"><label>Kode dealer<input class="fi" id="v6drDealer" placeholder="KODE CUSTOMER"></label><label>Pindah ke Big Region<select class="fi" id="v6drBig"><option value="">— muat dulu —</option></select></label><label>Berlaku mulai<input class="fi" id="v6drDate" type="date"></label><label>Alasan<input class="fi" id="v6drReason" placeholder="Contoh: dealer pindah area"></label></div>
<div class="toolbar"><button class="chip" type="button" id="v6drCheck">Cek dealer</button><button class="chip primary" type="button" id="v6drSave" disabled>Simpan & publish</button><span id="v6drMsg" class="hint"></span></div>
<div class="toolbar"><input class="fi" id="v6drQ" placeholder="Cari kode / nama / Big Region…" style="max-width:260px"><button class="chip" type="button" id="v6drLoad">Muat riwayat</button></div><div id="v6drBox"></div>`));
 const load=async()=>{$('v6drBox').innerHTML='<p class="hint v6load">Memuat…</p>';try{V6DR=await rpc('apiDealerRegionGet',TOKEN,$('v6drQ').value);const sel=$('v6drBig'),cur=sel.value;sel.innerHTML='<option value="">— pilih —</option>'+V6DR.bigs.map(b=>`<option${b===cur?' selected':''}>${esc(b)}</option>`).join('');if(V6DR.minDate){$('v6drDate').min=V6DR.minDate;if(!$('v6drDate').value||$('v6drDate').value<V6DR.minDate)$('v6drDate').value=V6DR.minDate;}$('v6drSave').disabled=false;
  $('v6drBox').innerHTML=`<p class="hint">${num(V6DR.total)} baris${V6DR.minDate?' · tanggal berlaku paling awal <b>'+esc(V6DR.minDate)+'</b> (sebelum itu data sudah dipublikasi)':''}${V6DR.total>V6DR.rows.length?' · menampilkan '+V6DR.rows.length:''}</p><div class="table-scroll"><table><thead><tr><th>Dealer</th><th>Big Region</th><th>Mulai</th><th>Sekarang</th><th>Catatan</th><th>Oleh</th></tr></thead><tbody>${V6DR.rows.map(r=>`<tr><td>${esc(r.nama||'(tidak ada di master)')}<small class="cellsub">${esc(r.dealer)}</small></td><td>${esc(r.big)}</td><td>${esc(r.from)}</td><td>${esc(r.now||'—')}</td><td>${esc(r.note)}</td><td>${esc(r.by)}</td></tr>`).join('')||'<tr><td colspan="6">Belum ada.</td></tr>'}</tbody></table></div>`;}catch(err){$('v6drBox').innerHTML='<p class="v6rmErr">'+esc(err.message||err)+'</p>';}};
 $('v6drLoad').onclick=load;$('v6drQ').onchange=load;
 $('v6drCheck').onclick=async()=>{$('v6drMsg').textContent='Mengecek…';try{if(!V6DR)await load();const r=await rpc('apiDealerRegionLookup',TOKEN,$('v6drDealer').value.trim());$('v6drMsg').innerHTML=`<b>${esc(r.nama)}</b> · Sales ${esc(r.sales||r.nik)} (${esc(r.salesBig||'—')}) · Big Region sekarang <b>${esc(r.now||'—')}</b>`;}catch(err){$('v6drMsg').innerHTML='<b style="color:#b91c1c">'+esc(err.message||err)+'</b>';}};
 $('v6drSave').onclick=async e=>{const d=$('v6drDealer').value.trim(),b=$('v6drBig').value,dt=$('v6drDate').value,rs=$('v6drReason').value.trim();if(!d||!b||!dt){$('v6drMsg').innerHTML='<b style="color:#b91c1c">Isi kode dealer, Big Region, dan tanggal.</b>';return;}if(rs.length<5){$('v6drMsg').innerHTML='<b style="color:#b91c1c">Isi alasan minimal 5 karakter.</b>';return;}if(!confirm('Pindahkan '+d+' ke '+b+' mulai '+dt+'?'))return;e.target.disabled=true;$('v6drMsg').textContent='Menyimpan & publish…';try{const r=await rpc('apiDealerRegionSave',TOKEN,{add:{dealer:d,big:b,date:dt}},rs);$('v6drMsg').innerHTML='<b style="color:#15803d">✓ '+esc(r.msg)+'</b>';$('v6drDealer').value='';$('v6drReason').value='';await load();}catch(err){$('v6drMsg').innerHTML='<b style="color:#b91c1c">'+esc(err.message||err)+'</b>';}finally{e.target.disabled=false;}};}

/* ===== Atur KPI (Super Admin) ===== */
let V6K=null,V6KSEL=null,V6KROWS=[],V6KREASON='';
const V6KM=[['QTY','ST (qty)'],['DA','Dealer aktif'],['NOO','NOO'],['IDDLE','Dealer IDDLE'],['OMZET','Omzet']];
function v6KpiPanel(v){v.insertAdjacentHTML('beforeend',panel('Atur KPI · Super Admin',`<div class="toolbar v6kJump"><button class="chip primary" type="button" disabled aria-current="page">Atur KPI</button><button class="chip" type="button" data-v6hgo="edit target">Edit target →</button></div><p class="hint">KPI per Big Region. Sub region boleh punya KPI sendiri — kalau diisi, tim di sub region itu pakai KPI sub region, bukan KPI Big Region. RGM boleh punya KPI per orang: tiap indikator pilih Big Region mana yang dihitung dan isi targetnya langsung. Total bobot tiap kelompok harus 100.</p>
<div class="toolbar"><label class="hint">Bulan <select class="fi" id="v6kPer" style="width:auto"></select></label><button class="chip" type="button" id="v6kLoad">Muat KPI</button><button class="chip" type="button" id="v6kCopy" disabled>Salin ke bulan lain…</button><span id="v6kMsg" class="hint"></span></div><div id="v6kBox" class="v6kWrap"></div>`));
 const per=$('v6kPer'),now=new Date(),opt=[];for(let i=-2;i<12;i++){const d=new Date(now.getFullYear(),now.getMonth()-i+1,1);opt.push(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'));}per.innerHTML=opt.map(p=>`<option${p===now.toISOString().slice(0,7)?' selected':''}>${p}</option>`).join('');
 $('v6kLoad').onclick=()=>v6KLoad();per.onchange=()=>v6KLoad();
 $('v6kCopy').onclick=async()=>{const to=prompt('Salin semua KPI '+V6K.period+' ke bulan (YYYY-MM):');if(!to)return;$('v6kMsg').textContent='Menyalin…';try{const r=await rpc('apiKpiCopy',TOKEN,V6K.period,to.trim(),'salin KPI '+V6K.period);$('v6kMsg').innerHTML='<b style="color:#15803d">✓ '+r.count+' indikator disalin ke '+esc(to)+'. Target RGM dikosongkan — isi lagi.</b>';per.value=to.trim();v6KLoad();}catch(e){$('v6kMsg').innerHTML='<b style="color:#b91c1c">'+esc(e.message||e)+'</b>';}};}
async function v6KLoad(keep){$('v6kBox').innerHTML='<p class="hint v6load">Memuat…</p>';try{V6K=await rpc('apiKpiGet',TOKEN,$('v6kPer').value);$('v6kCopy').disabled=false;if(!keep){V6KSEL=null;V6KREASON='';}v6KDraw();}catch(e){$('v6kBox').innerHTML='<p class="v6rmErr">'+esc(e.message||e)+'</p>';}}
/* v7: salin KPI (sebagian/semua kelompok) ke region lain */
function v6KCloneOpen(src){
 const key=n=>Object.keys(V6K.cfg).find(x=>x.toUpperCase()===String(n).toUpperCase()),rows=JSON.parse(JSON.stringify(V6K.cfg[key(src)]||[]));
 const G=[...new Set(rows.map(r=>String(r.group||'').trim().toUpperCase()).filter(Boolean))],gOf=list=>[...new Set((list||[]).map(r=>String(r.group||'').trim().toUpperCase()).filter(Boolean))];
 const cnt=g=>rows.filter(r=>String(r.group||'').trim().toUpperCase()===g).length,bob=g=>rows.filter(r=>String(r.group||'').trim().toUpperCase()===g).reduce((a,r)=>a+(+r.weight||0),0);
 const item=(n,sub,big)=>{if(n.toUpperCase()===src.toUpperCase())return '';const have=gOf(V6K.cfg[key(n)]);const st=have.length?`<span class="v7kcS o">punya ${esc(have.join(' + '))}</span>`:`<span class="v7kcS f">${sub?'ikut big region':'belum diisi'}</span>`;
  return `<label class="v7kcR${sub?' sub':''}"><input type="checkbox" class="v7kcT" value="${esc(n)}" data-have="${esc(have.join('|'))}" data-sub="${sub?1:''}"><b>${esc(n)}</b>${sub?`<small> · ${esc(big)}</small>`:''}${st}</label>`;};
 const bigs=V6K.tree.map(t=>item(t.big,false)).join(''),subs=V6K.tree.flatMap(t=>t.subs.map(s=>item(s,true,t.big))).join('');
 modal('Salin KPI '+src+' · '+V6K.period,`<div class="v7kc">
  <div class="v7kcH">KELOMPOK YANG DISALIN</div><div class="v7kcO">${G.map(g=>`<label><input type="checkbox" class="v7kcG" value="${esc(g)}" checked> ${esc(g)} <small>· ${cnt(g)} indikator · bobot ${bob(g)}</small></label>`).join('')}</div>
  <div class="v7kcH">KALAU REGION TUJUAN SUDAH PUNYA KELOMPOK YANG SAMA</div><div class="v7kcO"><label><input type="radio" name="v7kcM" value="skip" checked> Lewati, jangan diubah</label><label><input type="radio" name="v7kcM" value="over"> Timpa kelompok itu</label></div>
  <div class="v7kcH">BIG REGION TUJUAN</div><label class="v7kcR"><input type="checkbox" id="v7kcAll"><b>Pilih semua yang belum diisi</b></label>${bigs}
  <div class="v7kcH">SUB REGION (OPSIONAL, BIAR PUNYA KPI SENDIRI)</div>${subs||'<p class="hint">Tidak ada sub region.</p>'}
  <div class="v7kcW" id="v7kcW" hidden></div>
  <div class="toolbar v7kcF"><input class="fi" id="v7kcReason" placeholder="Alasan (opsional)" value="Disalin dari ${esc(src)}" style="max-width:320px"><button class="chip primary" type="button" id="v7kcGo">Salin & publish</button><span id="v7kcMsg" class="hint">0 region dipilih</span></div></div>`);
 const T=()=>[...document.querySelectorAll('.v7kcT:checked')],SG=()=>[...document.querySelectorAll('.v7kcG:checked')].map(x=>x.value),over=()=>document.querySelector('input[name=v7kcM]:checked').value==='over';
 const upd=()=>{const g=SG(),t=T(),hit=t.filter(x=>x.dataset.have.split('|').some(h=>g.includes(h)));$('v7kcMsg').textContent=t.length+' region dipilih';const w=$('v7kcW');w.hidden=!hit.length;w.textContent=hit.length?(over()?`${hit.length} region sudah punya kelompok yang sama → kelompok itu DITIMPA, kelompok lain tetap.`:`${hit.length} region sudah punya kelompok yang sama → kelompok itu dilewati.`):'';};
 document.querySelectorAll('.v7kcT,.v7kcG,input[name=v7kcM]').forEach(x=>x.addEventListener('change',upd));
 $('v7kcAll').onchange=e=>{document.querySelectorAll('.v7kcT').forEach(x=>{if(!x.dataset.sub&&!x.dataset.have)x.checked=e.target.checked;});upd();};
 $('v7kcGo').onclick=async()=>{const g=SG(),t=T();if(!g.length||!t.length){$('v7kcMsg').innerHTML='<b style="color:#b91c1c">Pilih minimal 1 kelompok dan 1 region.</b>';return;}
  const reason=($('v7kcReason').value.trim()||'Disalin dari '+src).padEnd(5,'.');$('v7kcGo').disabled=true;let ok=0,skip=0;const err=[];
  for(const x of t){const name=x.value,cur=JSON.parse(JSON.stringify(V6K.cfg[key(name)]||[])),have=gOf(cur);let next=cur,changed=false;
   for(const gg of g){if(have.includes(gg)){if(!over())continue;next=next.filter(r=>String(r.group||'').trim().toUpperCase()!==gg);}next=next.concat(JSON.parse(JSON.stringify(rows.filter(r=>String(r.group||'').trim().toUpperCase()===gg))));changed=true;}
   if(!changed){skip++;continue;}
   $('v7kcMsg').textContent='Menyalin ke '+name+'…';try{await rpc('apiKpiSaveRegion',TOKEN,V6K.period,name,next,reason);ok++;}catch(e){err.push(name+': '+(e.message||e));}}
  await v6KLoad(true);v6KDraw();$('v7kcGo').disabled=false;
  $('v7kcMsg').innerHTML=`<b style="color:#15803d">✓ Disalin ke ${ok} region</b>${skip?` · ${skip} dilewati`:''}${err.length?`<br><b style="color:#b91c1c">${esc(err.join(' · '))}</b>`:''}`;};
}
function v6KCount(name){const k=Object.keys(V6K.cfg).find(x=>x.toUpperCase()===String(name).toUpperCase());return k?V6K.cfg[k].length:0;}
function v6KDraw(){const side=V6K.tree.map(t=>`<div class="v6kBig"><button type="button" class="v6kItem ${V6KSEL&&V6KSEL.kind==='R'&&V6KSEL.name===t.big?'on':''}" data-kr="${esc(t.big)}"><b>${esc(t.big)}</b><span class="${v6KCount(t.big)?'ok':'bad'}">${v6KCount(t.big)?v6KCount(t.big)+' indikator':'belum diisi'}</span></button>${t.subs.map(s=>`<button type="button" class="v6kItem sub ${V6KSEL&&V6KSEL.name===s?'on':''}" data-kr="${esc(s)}" data-sub="1">${esc(s)}<span class="${v6KCount(s)?'own':''}">${v6KCount(s)?'KPI sendiri · '+v6KCount(s):'ikut Big Region'}</span></button>`).join('')}</div>`).join('')
  +`<div class="v6kHead">RGM</div>`+V6K.rgms.map(r=>`<button type="button" class="v6kItem ${V6KSEL&&V6KSEL.kind==='G'&&V6KSEL.name===r.nik?'on':''}" data-kg="${esc(r.nik)}"><b>${esc(r.nama)}</b><small>${esc(r.bigs.join(' · ')||r.wilayah||'-')}</small><span class="${r.rows.length?'own':''}">${r.rows.length?'KPI sendiri · '+r.rows.length:'ikut KPI Big Region'}</span></button>`).join('');
 $('v6kBox').innerHTML=`<div class="v6kSide">${side}</div><div class="v6kMain" id="v6kMain">${V6KSEL?'':'<p class="hint">Pilih Big Region, sub region, atau RGM di kiri.</p>'}</div>`;
 $('v6kBox').querySelectorAll('[data-kr]').forEach(b=>b.onclick=()=>{const n=b.dataset.kr,k=Object.keys(V6K.cfg).find(x=>x.toUpperCase()===n.toUpperCase());V6KREASON='';V6KSEL={kind:'R',name:n,sub:!!b.dataset.sub,big:(V6K.tree.find(t=>t.big===n||t.subs.includes(n))||{}).big};V6KROWS=JSON.parse(JSON.stringify(k?V6K.cfg[k]:[]));v6KDraw();});
 $('v6kBox').querySelectorAll('[data-kg]').forEach(b=>b.onclick=()=>{const r=V6K.rgms.find(x=>x.nik===b.dataset.kg);V6KREASON='';V6KSEL={kind:'G',name:r.nik,rgm:r};V6KROWS=JSON.parse(JSON.stringify(r.rows));v6KDraw();});
 if(V6KSEL)v6KEditor();}
function v6KSumHtml(sums){return Object.entries(sums).map(([g,s])=>`<span class="v6kMt ${Math.abs(s-100)>0.001?'bad':'ok'}"><span><b>${esc(g)}</b><strong>${num(s)}% / 100%${Math.abs(s-100)>0.001?'':' ✓'}</strong></span><i class="v6kBar"><u style="width:${Math.max(0,Math.min(100,s))}%"></u></i></span>`).join('');}
function v6KPrevHtml(){const m={};V6KROWS.forEach(r=>{const b=!r.brand||r.brand==='ALL'?'Lainnya':r.brand;m[b]=(m[b]||0)+(+r.weight||0);});const tot=Object.values(m).reduce((a,b)=>a+b,0);return Object.keys(m).length?`<div class="v6kPrev"><b>Pratinjau kolom di panel KPI RGM</b><span class="hint">Indikator dikelompokkan per brand; poin tiap brand maksimal sebesar bobotnya (× batas skor).</span><div class="v6kPv">${Object.entries(m).map(([b,w])=>`<span>${esc(b)}: <b>${num(w)}</b> bobot</span>`).join('')}<span>Total: <b>${num(tot)}</b></span></div></div>`:'';}
function v6KSums(){const sums={};V6KROWS.forEach(r=>{const g=(r.group||'').toUpperCase().trim();if(g)sums[g]=(sums[g]||0)+(+r.weight||0);});const bad=Object.values(sums).some(s=>Math.abs(s-100)>0.001)||V6KROWS.some(r=>!(+r.weight>0)||!String(r.group||'').trim()),noRegion=V6KSEL?.kind==='G'&&V6KROWS.some(r=>!(r.bigs||[]).length);const el=document.querySelector('.v6kSums');if(el)el.innerHTML=v6KSumHtml(sums)+(V6KROWS.some(r=>!(+r.weight>0)||!String(r.group||'').trim())?'<span class="bad">ada indikator tanpa kelompok/bobot</span>':'');const pe=document.querySelector('.v6kPrev');if(pe&&V6KSEL&&V6KSEL.kind==='G')pe.outerHTML=v6KPrevHtml()||'<div class="v6kPrev" hidden></div>';const b=$('v6kSave');if(b){b.disabled=bad||noRegion||V6KREASON.trim().length<5;b.title=bad?'Bobot tiap kelompok harus 100':noRegion?'Pilih minimal satu Big Region di tiap indikator':V6KREASON.trim().length<5?'Isi alasan minimal 5 karakter':'';}}
let V6KDEMO=null;
function v6KIddleDemoResult(history,target,cap,complete){if(!complete)return {actual:null,achievement:null,score:null};const actual=history.filter(h=>h[0]>0&&h[1]<=0&&h[2]<=0&&h[3]>0).length;if(!(target>0))return {actual,achievement:null,score:null};const achievement=actual/target*100;return {actual,achievement,score:Math.min(Math.max(0,cap),achievement)};}
function v6KIddlePreviewHtml(){const rule=V6KROWS.find(r=>r.metric==='IDDLE'),key=V6K.period+'|'+V6KSEL.kind+'|'+V6KSEL.name,brand=rule.brand||'ALL';if(!V6KDEMO||V6KDEMO.key!==key)V6KDEMO={key,target:2,complete:true,history:[[8,0,0,3],[0,0,0,4],[6,2,0,5],[0,0,0,2]]};const [y,m]=V6K.period.split('-').map(Number),months=[-3,-2,-1,0].map(offset=>new Date(y,m-1+offset,1).toLocaleDateString('id-ID',{month:'long'}));
 return `<section class="v6kDemo"><div class="v6kDemoHead"><div><h4>Pratinjau perhitungan Dealer IDDLE</h4><p class="hint">Data dummy · ST net dalam unit · contoh ${esc(brand==='ALL'?'satu brand dalam ALL':brand)}. Tidak mengubah target atau transaksi aplikasi.</p></div><span class="v6kTag">SIMULASI</span></div><div class="table-scroll"><table class="v6kDemoTable"><thead><tr><th>Dealer contoh</th>${months.map(month=>`<th>${esc(month)}</th>`).join('')}<th>Hasil</th></tr></thead><tbody>${V6KDEMO.history.map((h,i)=>`<tr><td><b>${['Maju Jaya','Sinar Baru','Berkah Cell','Prima Phone'][i]}</b><small class="cellsub">${esc(brand==='ALL'?'Contoh brand A':brand)}</small></td>${h.map((qty,j)=>`<td><input class="fi" type="number" value="${qty}" data-kdh="${i}" data-kdm="${j}" aria-label="ST dealer ${i+1} ${esc(months[j])}"></td>`).join('')}<td data-kdr="${i}"></td></tr>`).join('')}</tbody></table></div><div class="v6kDemoTotals"><div><span class="hint">Aktual simulasi</span><strong id="v6kdActual"></strong><small>dealer–brand</small></div><label>Target simulasi<input class="fi" type="number" min="0" id="v6kdTarget" value="${V6KDEMO.target}"></label><div><span class="hint">Pencapaian / skor indikator</span><strong id="v6kdScore"></strong><small id="v6kdFormula"></small></div><label class="v6kdComplete"><input type="checkbox" id="v6kdComplete"${V6KDEMO.complete?' checked':''}> Histori 3 bulan sebelumnya lengkap</label><span id="v6kdStatus" class="hint" role="status" aria-live="polite"></span></div></section>`;}
function v6KIddlePreviewUpdate(){if(!$('v6kdActual')||!V6KDEMO)return;const rule=V6KROWS.find(r=>r.metric==='IDDLE');if(!rule)return;const cap=Number(rule.cap??120),result=v6KIddleDemoResult(V6KDEMO.history,+V6KDEMO.target,cap,V6KDEMO.complete);$('v6kdActual').textContent=result.actual==null?'—':num(result.actual);$('v6kdScore').textContent=!V6KDEMO.complete?'—':!(V6KDEMO.target>0)?'Tidak wajib':pct(result.achievement)+' / '+num(result.score);$('v6kdFormula').textContent=!V6KDEMO.complete?'Menunggu histori lengkap':!(V6KDEMO.target>0)?'Target 0 tidak masuk perhitungan KPI':result.actual+' ÷ '+V6KDEMO.target+' × 100% · batas skor '+cap;$('v6kdStatus').textContent=V6KDEMO.complete?'Contoh simulasi terpisah dari aktual KPI aplikasi.':'HISTORI ST BELUM LENGKAP';$('v6kMain').querySelectorAll('[data-kdr]').forEach(el=>{const h=V6KDEMO.history[+el.dataset.kdr],qualifies=h[0]>0&&h[1]<=0&&h[2]<=0&&h[3]>0;el.innerHTML=!V6KDEMO.complete?'<span class="v6kdResult">Histori belum lengkap</span>':qualifies?'<span class="v6kdResult ok">Terhitung +1</span>':'<span class="v6kdResult">'+(h[3]<=0?'Belum order bulan KPI':h[1]>0||h[2]>0?'Jeda belum tepat 2 bulan':'Pasif ≥3 bulan / dealer baru')+'</span>';});}
function v6KIddlePreviewBind(){if(!$('v6kdTarget'))return;$('v6kdTarget').oninput=e=>{V6KDEMO.target=+e.target.value;v6KIddlePreviewUpdate();};$('v6kdComplete').onchange=e=>{V6KDEMO.complete=e.target.checked;v6KIddlePreviewUpdate();};$('v6kMain').querySelectorAll('[data-kdh]').forEach(el=>el.oninput=()=>{V6KDEMO.history[+el.dataset.kdh][+el.dataset.kdm]=+el.value;v6KIddlePreviewUpdate();});v6KIddlePreviewUpdate();}
function v6KDaRule(r,i){const mode=(+r.perProm>0)?'iot':((r.must&&r.must.length)||r._daq?'daq':'biasa');
 return '<div class="v6kDa"><select class="fi" data-k="damode" data-i="'+i+'" title="Aturan hitung Dealer Aktif"><option value="biasa"'+(mode==='biasa'?' selected':'')+'>DA Biasa</option><option value="daq"'+(mode==='daq'?' selected':'')+'>DAQ · Type Wajib</option><option value="iot"'+(mode==='iot'?' selected':'')+'>DA IoT · Per Promotor</option></select>'
 +(mode==='daq'?'<div class="v6kTp"><button type="button" class="v6kTpBtn" data-ktp="'+i+'" data-kf="must" title="Dealer dihitung kalau total unit brand ≥ Min unit DAN minimal 1 unit dari type yang dicentang">'+((r.must||[]).length?((r.must.length<=2?r.must.map(esc).join(' · '):esc(r.must[0])+' +'+(r.must.length-1))):'<span class="hint">pilih type wajib</span>')+' ▾</button></div>':'')
 +(mode==='iot'?'<input class="fi n" data-k="perProm" data-i="'+i+'" value="'+(r.perProm||3)+'" title="Minimal unit ACC brand per promotor. Batas dealer = angka ini × jumlah promotor (tanpa promotor = 1×). Brand harus dipilih">':'')+'</div>';}
function v6KEditor(){const S=V6KSEL,rgm=S.kind==='G',m=$('v6kMain'),ownB=rgm?S.rgm.bigs:[],allB=(V6K.allBigs&&V6K.allBigs.length?V6K.allBigs:V6K.tree.map(t=>t.big)),bigs=rgm?[...ownB,...allB.filter(b=>!ownB.includes(b))]:[];
 if(rgm)V6KROWS.forEach(r=>{if(!(r.bigs||[]).length&&ownB.length)r.bigs=[...ownB];});
 const keyOf=r=>(r.brand==='ALL'?'ALL BRAND':r.brand)+' '+((r.bigs||[]).join(' + ')||'—'),blk=(r,i)=>rgm&&(i===0||keyOf(V6KROWS[i-1])!==keyOf(r))?`<tr class="v6kBlk"><td colspan="11">TARGET ${esc(keyOf(r))}<span>judul blok otomatis</span></td></tr>`:'';
 const autoOf=r=>{const bg=r.bigs||[];if(!rgm||!bg.length||(r.types||[]).length||!r.brand||r.brand==='ALL')return 0;if(!(r.metric==='QTY'||(r.metric==='DA'&&Number(r.minDA??2)===2)))return 0;return bg.reduce((n,b)=>n+(V6K.autoMap[String(b).toUpperCase()+'|'+r.brand+'|'+r.metric]||0),0);};
 const tl=[...new Set(Object.values(V6K.types).flat())];
