/* ===== Edit target ===== */
let V6T=null,V6TCH={},V6TALL=false,V6TM={QTY:true,DA:false,NOO:false,IDDLE:false,OMZET:false};
function v6TargetPanel(v){v.insertAdjacentHTML('beforeend',panel('Edit target',`<p class="hint">Isi target Sales per bulan langsung di sini. Kolom mengikuti KPI (termasuk KPI sub region & indikator khusus TYPE). Kalau KPI belum diatur, target per brand tetap bisa diisi dulu; centang "tampilkan kolom di luar KPI" untuk brand lain. Baris ASM = jumlah Sales di bawahnya, otomatis. VACANT boleh diisi. Kosong = belum diisi (KPI jadi BELUM FINAL), 0 = tidak diwajibkan. Target RGM diisi di Atur KPI › RGM.</p>
<div class="v6tFilter"><label>Bulan<select class="fi" id="v6tPer"></select></label><label>Big Region<select class="fi" id="v6tBig"><option value="">Semua</option></select></label><label>Sub Region<select class="fi" id="v6tSub"><option value="">Semua</option></select></label><label>Cari<input class="fi" id="v6tQ" placeholder="nama / NIK"></label><button class="chip" type="button" id="v6tLoad">Muat target</button></div><div id="v6tBox"></div>`));
 const per=$('v6tPer'),now=new Date(),opt=[];for(let i=-2;i<12;i++){const d=new Date(now.getFullYear(),now.getMonth()-i+1,1);opt.push(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'));}per.innerHTML=opt.map(p=>`<option${p===now.toISOString().slice(0,7)?' selected':''}>${p}</option>`).join('');
 $('v6tLoad').onclick=()=>v6TLoad();$('v6tBig').onchange=()=>{v6TSubs();v6TLoad();};$('v6tSub').onchange=()=>v6TLoad();per.onchange=()=>v6TLoad();$('v6tQ').oninput=()=>V6T&&v6TDraw();}
function v6TSubs(){if(!V6T)return;const b=$('v6tBig').value,cur=$('v6tSub').value,subs=V6T.tree.filter(t=>!b||t.big===b).flatMap(t=>t.subs);$('v6tSub').innerHTML='<option value="">Semua</option>'+subs.map(s=>`<option${s===cur?' selected':''}>${esc(s)}</option>`).join('');}
async function v6TLoad(){if(Object.keys(V6TCH).length&&!confirm('Ada '+Object.keys(V6TCH).length+' perubahan belum disimpan. Buang?'))return;V6TCH={};$('v6tBox').innerHTML='<p class="hint v6load">Memuat…</p>';try{V6T=await rpc('apiTargetGet',TOKEN,$('v6tPer').value,$('v6tBig').value,$('v6tSub').value);const bs=$('v6tBig'),cb=bs.value;bs.innerHTML='<option value="">Semua</option>'+V6T.tree.map(t=>`<option${t.big===cb?' selected':''}>${esc(t.big)}</option>`).join('');v6TSubs();v6TDraw();}catch(e){$('v6tBox').innerHTML='<p class="v6rmErr">'+esc(e.message||e)+'</p>';}}
function v6TVal(r,k){const ck=r.nik+'¦'+k;return ck in V6TCH?V6TCH[ck]:(k in r.vals?r.vals[k]:'');}
function v6TDraw(){const T=V6T,q=($('v6tQ').value||'').toUpperCase().trim(),need=new Set(T.rows.flatMap(r=>r.need)),cols=T.cols.filter(c=>V6TALL||need.has(c.key)||(!need.size&&c.free&&V6TM[c.metric])||(!need.size&&!c.free));
 if(!T.rows.length){$('v6tBox').innerHTML='<p class="hint">Tidak ada Sales di filter ini.</p>';return;}
 const rows=T.rows.filter(r=>!q||(r.nik+' '+r.nama+' '+r.asmNama).toUpperCase().includes(q)),groups=[];rows.forEach(r=>{let g=groups[groups.length-1];if(!g||g.asm!==r.asm||g.sub!==r.sub)groups.push(g={asm:r.asm,asmNama:r.asmNama,sub:r.sub,rows:[]});g.rows.push(r);});
 const fmt=v=>v===''||v==null?'':num(+v),cell=(r,c)=>{const v=v6TVal(r,c.key),miss=r.need.includes(c.key)&&(v===''||v==null),ch=(r.nik+'¦'+c.key) in V6TCH;return `<td class="n ${c.metric==='IDDLE'?'v6tIddle':''} ${r.need.includes(c.key)?'':'v6tNo'} ${miss?'v6tMiss':''} ${ch?'v6tCh':''}"><input aria-label="Target ${esc(c.label)} ${esc(r.nama)}" class="v6tIn${c.metric==='OMZET'?' w':''}" data-n="${esc(r.nik)}" data-c="${esc(c.key)}" value="${v===''||v==null?'':v}" inputmode="numeric"></td>`;};
 const sum=(rs,c)=>{let s=0,any=false,miss=0;rs.forEach(r=>{const v=v6TVal(r,c.key);if(v===''||v==null){if(r.need.includes(c.key))miss++;}else{s+=+v;any=true;}});return `<td class="n">${any?num(s):''}${miss?`<small class="v6tMissN" title="${miss} Sales belum diisi">·${miss}</small>`:''}</td>`;};
 let body='';groups.forEach(g=>{body+=g.rows.map(r=>`<tr class="${r.vac?'v6vac':''}"><td class="v6tName">${esc(r.nama)}<small class="cellsub">${esc(r.nik)} · ${esc(r.sub)}</small></td>${cols.map(c=>cell(r,c)).join('')}</tr>`).join('');body+=`<tr class="v6tAsm"><td>ASM ${esc(g.asmNama)}<small class="cellsub">${esc(g.sub)} · otomatis</small></td>${cols.map(c=>sum(g.rows,c)).join('')}</tr>`;});
 const missAll=T.rows.reduce((n,r)=>n+r.need.filter(k=>{const v=v6TVal(r,k);return v===''||v==null;}).length,0),nch=Object.keys(V6TCH).length;
 $('v6tBox').innerHTML=`${T.hasKpi?'':'<p class="info">KPI bulan '+esc(T.period)+' belum diatur, tapi <b>target per brand tetap bisa diisi sekarang</b>. Begitu KPI diatur, indikatornya otomatis memakai angka yang sudah diisi di sini. Pilih metrik yang mau diisi: '+['QTY|ST','DA|DA','NOO|NOO','IDDLE|Dealer IDDLE','OMZET|OMZET'].map(x=>{const [k,l]=x.split('|');return `<label style="margin-right:10px"><input type="checkbox" data-v6tm="${k}"${V6TM[k]?' checked':''}> ${l}</label>`;}).join('')+'</p>'}<p class="hint">${num(T.rows.length)} Sales · ${cols.length} kolom${missAll?` · <b style="color:#b45309">${num(missAll)} sel wajib belum diisi</b>`:' · semua target wajib terisi ✓'} · <label><input type="checkbox" id="v6tAll"${V6TALL?' checked':''}> tampilkan kolom di luar KPI</label> · tempel dari Excel: klik sel lalu Ctrl+V</p>
 <div class="table-scroll v6tScroll"><table class="v6tTable"><thead><tr><th class="v6tName">Sales</th>${cols.map(c=>`<th class="n ${c.metric==='IDDLE'?'v6tIddle':''}" title="${esc(c.label)}${c.types&&c.types.length?' · TYPE '+esc(c.types.join(', ')):''}">${esc(c.indicator?c.label:(({QTY:'ST',DA:'DA',NOO:'NOO',IDDLE:'Dealer IDDLE',OMZET:'OMZET'})[c.metric]+' '+c.brand))}${c.indicator?'<small class="cellsub">khusus</small>':''}</th>`).join('')}</tr></thead><tbody>${body}<tr class="totalRow"><td>Total</td>${cols.map(c=>sum(rows,c)).join('')}</tr></tbody></table></div>
 <div class="toolbar"><input class="fi" id="v6tReason" placeholder="Alasan perubahan" style="max-width:320px"><button class="chip primary" type="button" id="v6tSave"${nch?'':' disabled'}>Simpan ${nch?nch+' perubahan':''}</button><button class="chip" type="button" id="v6tUndo"${nch?'':' disabled'}>Batalkan</button><span id="v6tMsg" class="hint"></span></div>`;
 $('v6tAll').onchange=e=>{V6TALL=e.target.checked;v6TDraw();};
 $('v6tBox').querySelectorAll('[data-v6tm]').forEach(c=>c.onchange=()=>{V6TM[c.dataset.v6tm]=c.checked;v6TDraw();});
 const box=$('v6tBox'),colKeys=cols.map(c=>c.key);
 box.querySelectorAll('.v6tIn').forEach(el=>{el.onchange=()=>{try{const r=T.rows.find(x=>x.nik===el.dataset.n),k=el.dataset.c,val=targetInputNumber(el.value),orig=k in r.vals?String(r.vals[k]):'',ck=r.nik+'¦'+k;if(val===orig)delete V6TCH[ck];else V6TCH[ck]=val;const y=window.scrollY,ae=document.activeElement,fk=ae&&ae.classList&&ae.classList.contains('v6tIn')?[ae.dataset.n,ae.dataset.c]:null,sc=box.querySelector('.v6tScroll'),sx=sc?[sc.scrollLeft,sc.scrollTop]:null;v6TDraw();window.scrollTo(0,y);const sc2=$('v6tBox').querySelector('.v6tScroll');if(sc2&&sx){sc2.scrollLeft=sx[0];sc2.scrollTop=sx[1];}if(fk){const f=[...$('v6tBox').querySelectorAll('.v6tIn')].find(i=>i.dataset.n===fk[0]&&i.dataset.c===fk[1]);if(f){f.focus();f.select();}}}catch(err){$('v6tMsg').textContent=err.message;el.focus();}};
  el.onpaste=ev=>{const txt=(ev.clipboardData||window.clipboardData).getData('text');if(!/[\t\n]/.test(txt))return;ev.preventDefault();const lines=txt.replace(/\r/g,'').split('\n').filter((l,i,a)=>l!==''||i<a.length-1),ins=[...box.querySelectorAll('.v6tIn')],names=[...new Set(ins.map(i=>i.dataset.n))],r0=names.indexOf(el.dataset.n),c0=colKeys.indexOf(el.dataset.c);let n=0;const pending={...V6TCH};try{lines.forEach((l,ri)=>l.split('\t').forEach((v,ci)=>{const nik=names[r0+ri],k=colKeys[c0+ci];if(!nik||!k)return;const r=T.rows.find(x=>x.nik===nik),val=targetInputNumber(v),orig=k in r.vals?String(r.vals[k]):'',ck=nik+'¦'+k;if(val===orig)delete pending[ck];else pending[ck]=val;n++;}));V6TCH=pending;v6TDraw();$('v6tMsg').textContent=n+' sel ditempel.';}catch(err){$('v6tMsg').textContent=err.message;}};});
 $('v6tUndo').onclick=()=>{V6TCH={};v6TDraw();};
 $('v6tSave').onclick=async e=>{const reason=$('v6tReason').value.trim();if(reason.length<5){$('v6tMsg').innerHTML='<b style="color:#b91c1c">Isi alasan minimal 5 karakter.</b>';return;}const changes=Object.entries(V6TCH).map(([ck,val])=>{const [nik,key]=ck.split('¦'),[metric,brand,indicator]=key.split('|');return {nik,metric,brand,indicator,value:val};});e.target.disabled=true;$('v6tMsg').textContent='Menyimpan & publish…';try{const r=await rpc('apiTargetSave',TOKEN,T.period,changes,reason);V6TCH={};await v6TLoad();$('v6tMsg').innerHTML='<b style="color:#15803d">✓ '+r.count+' target tersimpan.</b>';}catch(err){$('v6tMsg').innerHTML='<b style="color:#b91c1c">'+esc(err.message||err)+'</b>';e.target.disabled=false;}};}

/* ===== Riwayat aktivitas & Checkpoint ===== */
function v6ActivityPanel(v,sup){v.insertAdjacentHTML('beforeend',panel('Riwayat aktivitas',`<p class="hint">Siapa mengubah apa & kapan.${sup?' Login/publish disembunyikan kecuali dipilih di filter.':' Anda melihat aktivitas Anda sendiri.'}</p><div class="toolbar"><input class="fi" id="v6aQ" placeholder="Cari nama / NIK / isi…" style="max-width:260px"><select class="fi" id="v6aAct" style="width:auto"><option value="">Semua aksi penting</option></select><button class="chip" type="button" id="v6aLoad">Muat</button></div><div id="v6aBox"></div>`+(sup?`<h4 style="margin:18px 0 4px">Checkpoint & kembalikan</h4><p class="hint">Setiap perubahan master otomatis bikin checkpoint (kondisi SEBELUM perubahan). Kembalikan = semua master balik ke kondisi itu (Master Sales/Customer, target, KPI, Region Map, dll). Data ST/SO tidak ikut. PIN yang sudah diganti tidak ditimpa. Sebelum mengembalikan, kondisi sekarang juga di-checkpoint dulu, jadi bisa dibatalkan.</p><div class="toolbar"><button class="chip" type="button" id="v6cpLoad">Muat checkpoint</button><span id="v6cpMsg" class="hint"></span></div><div id="v6cpBox"></div>`:'')));
 const load=async()=>{$('v6aBox').innerHTML='<p class="hint v6load">Memuat…</p>';try{const r=await rpc('apiActivity',TOKEN,$('v6aQ').value,$('v6aAct').value),sel=$('v6aAct'),cur=sel.value;sel.innerHTML='<option value="">Semua aksi penting</option>'+r.actions.map(a=>`<option value="${esc(a.id)}"${a.id===cur?' selected':''}>${esc(a.label)}</option>`).join('');
  $('v6aBox').innerHTML=`<p class="hint">${num(r.total)} aktivitas${r.total>r.rows.length?' · menampilkan '+r.rows.length+' terbaru':''}</p><div class="table-scroll" style="max-height:460px"><table><thead><tr><th>Waktu</th><th>Oleh</th><th>Aksi</th><th>Keterangan</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td style="white-space:nowrap">${esc(x.when)}</td><td>${esc(x.nama||x.nik)}<small class="cellsub">${esc(x.nik)}</small></td><td>${esc(x.label)}</td><td class="v6aDet">${esc(x.detail)}</td></tr>`).join('')||'<tr><td colspan="4">Tidak ada.</td></tr>'}</tbody></table></div>`;}catch(e){$('v6aBox').innerHTML='<p class="v6rmErr">'+esc(e.message||e)+'</p>';}};
 $('v6aLoad').onclick=load;$('v6aAct').onchange=load;$('v6aQ').onchange=load;
 if(sup)$('v6cpLoad').onclick=async()=>{$('v6cpBox').innerHTML='<p class="hint v6load">Memuat…</p>';try{const r=await rpc('apiCheckpoints',TOKEN);$('v6cpBox').innerHTML=`<div class="table-scroll" style="max-height:420px"><table><thead><tr><th>Waktu</th><th>Oleh</th><th>Sebelum perubahan</th><th></th></tr></thead><tbody>${r.rows.map(x=>`<tr><td style="white-space:nowrap">${esc(x.when)}</td><td>${esc(x.nama)}</td><td class="v6aDet">${esc(x.reason)}</td><td><button class="chip" type="button" data-cp="${esc(x.file)}" data-cpw="${esc(x.when)}">Kembalikan</button></td></tr>`).join('')||'<tr><td colspan="4">Belum ada checkpoint.</td></tr>'}</tbody></table></div>`;
  $('v6cpBox').querySelectorAll('[data-cp]').forEach(b=>b.onclick=async()=>{const reason=prompt('Kembalikan semua master ke kondisi '+b.dataset.cpw+' (sebelum perubahan itu)?\nSemua perubahan master setelahnya akan hilang.\n\nTulis alasan:');if(!reason)return;if(reason.trim().length<5){alert('Alasan minimal 5 karakter.');return;}b.disabled=true;$('v6cpMsg').textContent='Mengembalikan & publish…';try{await rpc('apiCheckpointRestore',TOKEN,b.dataset.cp,reason.trim());$('v6cpMsg').innerHTML='<b style="color:#15803d">✓ Master dikembalikan ke '+esc(b.dataset.cpw)+'. Muat ulang halaman untuk melihat hasilnya.</b>';}catch(e){$('v6cpMsg').innerHTML='<b style="color:#b91c1c">'+esc(e.message||e)+'</b>';b.disabled=false;}});}catch(e){$('v6cpBox').innerHTML='<p class="v6rmErr">'+esc(e.message||e)+'</p>';}};}
async function v6AdminBanner(){const v=$('view');if(!v)return;try{const r=await rpc('apiAdminBanner',TOKEN);let b=$('v6aBanner');if(!r.items.length){if(b)b.remove();return;}if(!b){b=document.createElement('div');b.id='v6aBanner';v.prepend(b);}b.className='v6aBanner';{const map={kesehatan:'data','status sync':'data','atur kpi':'kpi','edit target':'kpi','keamanan akun':'sistem'},cnt={};r.items.forEach(x=>{const t=map[x.go];if(t)cnt[t]=(cnt[t]||0)+1;});document.querySelectorAll('[data-v6tb]').forEach(el=>el.textContent=cnt[el.dataset.v6tb]||'');}b.innerHTML='<b>Perlu perhatian</b>'+r.items.map(x=>`<span class="${x.lv==='r'?'r':'o'}">${esc(x.text)}${x.go?` <button type="button" class="chip" data-v6hgo="${esc(x.go)}">Buka</button>`:''}</span>`).join('');}catch(e){}}


/* ===== Admin: Keamanan akun ===== */
function v6SecurityPanel(v){v.insertAdjacentHTML('beforeend',panel('Keamanan akun',`<p class="hint">Status Authenticator (wajib untuk ASM ke atas), akun yang terkunci, dan percobaan login gagal. Akun terkunci otomatis setelah 5 kali salah: 15 menit, lalu 1 jam, lalu 24 jam bila terus berulang.</p><div id="sxBox"><p class="hint v6load">Memuat…</p></div>`));
 let SX=null,onlyIssue=true,q='';
 const lockTxt=ms=>{const m=Math.ceil(ms/60000);return m<60?m+' mnt':Math.ceil(m/60)+' jam';};
 const draw=()=>{if(!SX)return;const s=SX.summary,qq=q.trim().toLowerCase();
  const rows=SX.rows.filter(r=>(!onlyIssue||r.lockLeftMs>0||r.fails24>0||r.tfa==='off')&&(!qq||(r.nama+' '+r.nik+' '+r.role).toLowerCase().includes(qq)));
  $('sxBox').innerHTML=`<div class="sxKp"><div><b>${s.on} / ${s.need}</b><small>ASM ke atas dengan Authenticator aktif</small></div><div class="${s.locked?'bad':''}"><b>${s.locked}</b><small>Akun terkunci sekarang</small></div><div><b>${s.fails24}</b><small>Gagal login 24 jam terakhir</small></div></div>
  <div class="toolbar"><input class="fi" id="sxQ" placeholder="Cari nama / NIK / jabatan…" value="${esc(q)}" style="max-width:260px"><label class="hint" style="display:flex;gap:6px;align-items:center"><input type="checkbox" id="sxOnly"${onlyIssue?' checked':''}> Hanya yang perlu perhatian</label><button class="chip" type="button" id="sxRef">Muat ulang</button></div>
  <div class="table-scroll" style="max-height:480px"><table><thead><tr><th>Nama</th><th>Jabatan</th><th>Authenticator</th><th>Gagal 24 jam</th><th>Gagal 7 hari</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.nama)}<small class="cellsub">${esc(r.nik)}</small></td><td>${esc(r.role)}</td><td>${r.tfa==='on'?'<span class="sxp ok">Aktif</span>':r.tfa==='off'?'<span class="sxp no">Belum aktif</span>':'<span class="sxp na">Tidak wajib</span>'}</td><td>${r.fails24}</td><td>${r.fails7}</td><td>${r.lockLeftMs>0?'<span class="sxp lock">Terkunci '+lockTxt(r.lockLeftMs)+'</span>':'<span class="sxp ok">Normal</span>'}</td><td style="white-space:nowrap">${r.lockLeftMs>0?`<button class="chip" type="button" data-sxu="${esc(r.nik)}" data-n="${esc(r.nama)}">Buka kunci</button> `:''}${r.tfa==='on'?`<button class="chip" type="button" data-sxr="${esc(r.nik)}" data-n="${esc(r.nama)}">Reset Authenticator</button>`:''}</td></tr>`).join('')||'<tr><td colspan="7">Tidak ada yang perlu perhatian ✓</td></tr>'}</tbody></table></div><p class="hint" id="sxMsg"></p>`;
  $('sxQ').oninput=e=>{q=e.target.value;const pos=e.target.selectionStart;draw();const n=$('sxQ');n.focus();n.setSelectionRange(pos,pos);};
  $('sxOnly').onchange=e=>{onlyIssue=e.target.checked;draw();};$('sxRef').onclick=load;
  $('sxBox').querySelectorAll('[data-sxu]').forEach(b=>b.onclick=async()=>{if(!confirm('Buka kunci akun '+b.dataset.n+'?'))return;b.disabled=true;try{await rpc('apiUnlockAccount',TOKEN,b.dataset.sxu);await load();$('sxMsg').innerHTML='<b style="color:#15803d">✓ Kunci '+esc(b.dataset.n)+' dibuka.</b>';}catch(e){$('sxMsg').innerHTML='<b style="color:#b91c1c">'+esc(e.message||e)+'</b>';b.disabled=false;}});
  $('sxBox').querySelectorAll('[data-sxr]').forEach(b=>b.onclick=async()=>{if(!confirm('Reset Authenticator '+b.dataset.n+'?\n\nOrangnya keluar dari sesi dan harus mendaftarkan Authenticator lagi saat login berikutnya (kode cadangan lama hangus).'))return;b.disabled=true;try{await rpc('apiResetTfa',TOKEN,b.dataset.sxr);await load();$('sxMsg').innerHTML='<b style="color:#15803d">✓ Authenticator '+esc(b.dataset.n)+' direset.</b>';}catch(e){$('sxMsg').innerHTML='<b style="color:#b91c1c">'+esc(e.message||e)+'</b>';b.disabled=false;}});};
 const load=async()=>{try{SX=await rpc('apiSecurityPanel',TOKEN);draw();}catch(e){$('sxBox').innerHTML='<p class="v6rmErr">'+esc(e.message||e)+'</p>';}};
 load();}

function v6RegionBrandPanel(v){v.insertAdjacentHTML('beforeend',panel('Region per brand & target Big Region · Super Admin',`<p class="hint">Atur region mana yang tampil di Beranda untuk tiap brand, sekaligus target Big Region (khusus SELL THRU dan Dealer Aktif). Tiga lapis: <b>ditetapkan manual</b> mengalahkan <b>otomatis masuk</b> (ada penjualan atau target) yang mengalahkan <b>otomatis hilang</b> (3 bulan tanpa penjualan dan target). Target Big Region dikosongkan = memakai jumlah target Sales. Target ini hanya dipakai untuk persen Big Region di Beranda RGM ke atas; KPI, peringkat, dan sub region tetap memakai target Sales.</p><div id="rbBox"><p class="hint v6load">Memuat…</p></div>`));
 let RB=null,brand=null,E={};
 const key=(b,r)=>b+'|'+r,fmt=n=>n==null?'':String(n);
 const cur=(big,br,c)=>{const e=E[key(big,br)]||{};return {mode:'mode' in e?e.mode:c.mode,tQty:'tQty' in e?e.tQty:fmt(c.big.QTY),tDA:'tDA' in e?e.tDA:fmt(c.big.DA)};};
 const setE=(big,br,k,val,orig)=>{const kk=key(big,br);E[kk]=E[kk]||{};E[kk][k]=val;if(String(val)===String(orig))delete E[kk][k];if(!Object.keys(E[kk]).length)delete E[kk];};
 const eff=(c,m)=>m==='TAMPIL'?true:m==='SEMBUNYI'?false:c.auto;
 const msg=(t,ok)=>{const m=$('rbMsg');if(m)m.innerHTML=t?'<b style="color:'+(ok?'#15803d':'#b91c1c')+'">'+esc(t)+'</b>':'';};
 const draw=()=>{if(!RB)return;if(!brand||!RB.brands.includes(brand))brand=RB.brands[0];const n=Object.keys(E).length;
  const shown=b=>RB.rows.filter(r=>eff(r.cells[b],cur(r.big,b,r.cells[b]).mode)).length;
  $('rbBox').innerHTML=`<div class="toolbar"><label class="hint" style="display:flex;gap:6px;align-items:center">Bulan <select class="fi" id="rbPer">${RB.periods.map(p=>`<option${p===RB.period?' selected':''}>${esc(p)}</option>`).join('')}</select></label><button class="chip" type="button" id="rbFill">Isi dari data 3 bulan terakhir</button><button class="chip" type="button" id="rbCopy">Salin target dari ${esc(RB.prev)}</button></div>
  <div class="v6xchips">${RB.brands.map(b=>`<button type="button" class="${b===brand?'on':''}" data-rbb="${esc(b)}">${esc(b)} · ${shown(b)}/${RB.rows.length}</button>`).join('')}</div>
  <div class="table-scroll" style="max-height:520px"><table><thead><tr><th>Big Region</th><th class="n">Penjualan bulan ini</th><th>Tampil di Beranda</th><th>Status</th><th class="n">Target sales · ST</th><th class="n">Target Big Region · ST</th><th class="n">Target sales · DA</th><th class="n">Target Big Region · DA</th></tr></thead><tbody>${RB.rows.map(r=>{const c=r.cells[brand],x=cur(r.big,brand,c),on=eff(c,x.mode),ch=E[key(r.big,brand)]?' class="rbCh"':'';
   const st=x.mode?`<span class="sxp ${on?'ok':'no'}">${on?'Ditetapkan tampil':'Ditetapkan sembunyi'}</span>`:`<span class="sxp ${on?'ok':'na'}">${on?'Otomatis masuk':'Otomatis hilang'}</span>`;
   return `<tr${ch}><td><b>${esc(r.big)}</b></td><td class="n">${num(c.q)}${on&&!c.q?'<small class="cellsub">belum ada penjualan</small>':''}</td><td><select class="fi" data-rbm="${esc(r.big)}"><option value=""${x.mode===''?' selected':''}>Otomatis</option><option value="TAMPIL"${x.mode==='TAMPIL'?' selected':''}>Selalu tampil</option><option value="SEMBUNYI"${x.mode==='SEMBUNYI'?' selected':''}>Sembunyikan</option></select></td><td>${st}</td><td class="n">${num(c.sales.QTY)}</td><td class="n"><input class="fi n" style="width:92px" inputmode="numeric" data-rbt="tQty" data-rbg="${esc(r.big)}" value="${esc(x.tQty)}" placeholder="${num(c.sales.QTY)}"></td><td class="n">${num(c.sales.DA)}</td><td class="n"><input class="fi n" style="width:92px" inputmode="numeric" data-rbt="tDA" data-rbg="${esc(r.big)}" value="${esc(x.tDA)}" placeholder="${num(c.sales.DA)}"></td></tr>`;}).join('')}</tbody></table></div>
  <div class="toolbar"><input class="fi" id="rbWhy" placeholder="Alasan perubahan (min. 5 huruf)" style="min-width:260px"><button class="chip primary" type="button" id="rbSave"${n?'':' disabled'}>Simpan${n?' ('+n+' region × brand)':''}</button>${n?'<button class="chip" type="button" id="rbReset">Batalkan perubahan</button>':''}</div><p class="hint" id="rbMsg"></p>`;
  $('rbPer').onchange=e=>{if(n&&!confirm('Perubahan yang belum disimpan akan hilang. Lanjut?')){e.target.value=RB.period;return;}E={};load(e.target.value);};
  $('rbBox').querySelectorAll('[data-rbb]').forEach(b=>b.onclick=()=>{brand=b.dataset.rbb;draw();});
  $('rbBox').querySelectorAll('[data-rbm]').forEach(sel=>sel.onchange=()=>{const big=sel.dataset.rbm;setE(big,brand,'mode',sel.value,RB.rows.find(r=>r.big===big).cells[brand].mode);draw();});
  $('rbBox').querySelectorAll('[data-rbt]').forEach(inp=>inp.onchange=()=>{const big=inp.dataset.rbg,k=inp.dataset.rbt,c=RB.rows.find(r=>r.big===big).cells[brand],val=inp.value.replace(/[^0-9.]/g,'');setE(big,brand,k,val,fmt(c.big[k==='tQty'?'QTY':'DA']));draw();});
  $('rbFill').onclick=()=>{if(!confirm('Isi penetapan semua Big Region × brand dari data 3 bulan terakhir?\n\nYang ada penjualan atau target ditetapkan TAMPIL, yang tidak ada ditetapkan SEMBUNYI. Belum tersimpan sampai lu tekan Simpan.'))return;let k=0;RB.rows.forEach(r=>RB.brands.forEach(b=>{const c=r.cells[b],m=c.auto?'TAMPIL':'SEMBUNYI';if(c.mode!==m){setE(r.big,b,'mode',m,c.mode);k++;}}));draw();msg(k+' penetapan diisi dari data. Periksa lalu tekan Simpan.',true);};
  $('rbCopy').onclick=()=>{let k=0;RB.rows.forEach(r=>RB.brands.forEach(b=>{const c=r.cells[b];[['tQty','QTY'],['tDA','DA']].forEach(([f,m])=>{const have=cur(r.big,b,c)[f];if(have===''&&c.prev[m]!=null){setE(r.big,b,f,fmt(c.prev[m]),fmt(c.big[m]));k++;}});}));draw();msg(k?k+' target disalin dari '+RB.prev+' (hanya yang masih kosong). Tekan Simpan untuk menyimpan.':'Tidak ada target kosong yang bisa disalin dari '+RB.prev+'.',!!k);};
  const rs=$('rbReset');if(rs)rs.onclick=()=>{E={};draw();};
  $('rbSave').onclick=async()=>{const why=$('rbWhy').value.trim();if(why.length<5){msg('Isi alasan minimal 5 karakter.',false);return;}const ch=[];Object.entries(E).forEach(([kk,e])=>{const i=kk.indexOf('|'),big=kk.slice(0,i),br=kk.slice(i+1),o={big,brand:br};if('mode' in e)o.mode=e.mode;if('tQty' in e)o.tQty=e.tQty;if('tDA' in e)o.tDA=e.tDA;ch.push(o);});
   $('rbSave').disabled=true;msg('Menyimpan…',true);try{await rpc('apiRegionBrandSave',TOKEN,RB.period,ch,why);E={};await load(RB.period);msg('✓ Tersimpan. Beranda memakai pengaturan baru.',true);}catch(e){msg(e.message||String(e),false);$('rbSave').disabled=false;}};};
 const load=async per=>{try{RB=await rpc('apiRegionBrandGet',TOKEN,per||null);draw();}catch(e){$('rbBox').innerHTML='<p class="v6rmErr">'+esc(e.message||e)+'</p>';}};
 load();}

/* ===== v10: panel KPI RGM ===== */
function v6RgmKpiPanel(v){
 if(!['RGM','HEAD OF SALES','CHIEF OPERATING OFFICER','CHIEF COMMERCIAL OFFICER','BOARD OF DIRECTOR','ADMIN','SUPER ADMIN'].includes(BOOT.user.role))return;
 v.insertAdjacentHTML('beforeend',`<details class="panel foldPanel rgPanel" id="rgmKpiPanel" open><summary>KPI RGM<small>Pencapaian semua RGM · tidak ikut filter Big Region</small></summary><div class="pb" id="rgmKpiBody"><div class="empty v6load">Memuat KPI RGM…</div></div></details>`);
 const token=TOKEN,period=REPORT.period;
 rpc('apiKpiRgmPanel',token,period).then(d=>{const b=$('rgmKpiBody');if(token!==TOKEN||!b)return;b.innerHTML=v6RgmKpiHtml(d);}).catch(e=>{const b=$('rgmKpiBody');if(b)b.innerHTML='<div class="empty">'+esc(e.message||e)+'</div>';});
}
function v6RgmKpiHtml(d){
 if(!d.rows.length)return '<div class="empty">Belum ada KPI RGM untuk periode ini.</div>';
 /* v7 revisi #10/#12: tabel ringkas + kartu per RGM */
 const BN=b=>b==='LAINNYA'?'LAINNYA':String(b).toUpperCase(),PT=x=>x==null?'—':new Intl.NumberFormat('id-ID',{minimumFractionDigits:1,maximumFractionDigits:1}).format(x),
  BC={IPHONE:['#5B3FD6','#EFEBFC'],ITEL:['#0E6E64','#E2F4F1'],MOTOPAD:['#B33D0B','#FCEEE4'],MOTOROLA:['#1E5FB8','#E3EEFB'],REALME:['#2E7D32','#E5F4E6'],TECNO:['#B4204F','#FCE7EE'],VILLAON:['#455A64','#E9EEF1'],INFINIX:['#7A5B00','#FFF4D6'],SAMSUNG:['#1B3F8F','#E4EAF7'],OPPO:['#1C7A4A','#E3F4EB'],VIVO:['#2149A8','#E5EBF9'],XIAOMI:['#C2410C','#FDEDE3']},
  col=b=>BC[BN(b)]||['#3D4A5C','#EEF1F5'],tier=x=>x==null?'':x>=100?'gr':x>=80?'y':'r',chip=(x,suf='%')=>x==null?'<span class="v7rgChip">—</span>':`<span class="v7rgChip ${tier(x)}">${PT(x)}${suf}</span>`,
  brOf=i=>(!i.brand||i.brand==='ALL')?'LAINNYA':i.brand,MN0={ST:'Sell Thru',SELLTHRU:'Sell Thru',SO:'Sell Out',SELLOUT:'Sell Out',DA:'Dealer Aktif',NOO:'NOO',IDDLE:'Dealer IDDLE',OMZET:'Omzet'},MN=new Proxy({},{get:(o,k)=>MN0[String(k).toUpperCase().replace(/[^A-Z]/g,'')]}),
  inds=r=>(r.kpi?.groups||[]).flatMap(g=>g.indicators||[]);
 const badge=r=>r==null?'<span class="rgBadge no">–</span>':r<=3?`<span class="v7rgMd">${['🥇','🥈','🥉'][r-1]}</span>`:`<span class="v7rgRk">${r}</span>`;
 /* poin maksimal per brand diambil dari bobot KPI */
 const bmax={};d.rows.forEach(r=>{const m={};inds(r).forEach(i=>{const b=brOf(i);m[b]=(m[b]||0)+Number(i.weight||0);});Object.entries(m).forEach(([b,w])=>{bmax[b]=Math.max(bmax[b]||0,w);});});
 const mx=b=>bmax[b]||bmax[BN(b)]||100;
 const pbar=(v,b)=>v==null?'<span class="v7rgNa">-</span>':`<div class="v7rgPb"><span class="t"><i style="width:${Math.max(0,Math.min(100,v/mx(b)*100))}%;background:${col(b)[0]}"></i></span><b>${PT(v)}</b></div>`;
 const stack=(by,tot)=>{const sc=Math.max(100,tot||0);return `<div class="v7rgStack">${d.brands.map(b=>by[b]?`<i style="width:${by[b]/sc*100}%;background:${col(b)[0]}" title="${esc(BN(b))} ${PT(by[b])}"></i>`:'').join('')}</div>`;};
 const sum=`<div class="table-scroll"><table class="rgT v7rgSum"><thead><tr><th class="l" style="width:46px">#</th><th class="l">Nama RGM</th>${d.brands.map(b=>`<th class="br" style="--bb:${col(b)[1]};--bc:${col(b)[0]}">${esc(BN(b))}</th>`).join('')}<th class="res">Total poin</th></tr></thead><tbody>${d.rows.map(r=>`<tr class="${r.me?'rgMe':''}"><td class="l">${badge(r.rank)}</td><td class="l"><b>${esc(r.nama)}</b>${r.me?' <small class="cellsub">Anda</small>':''}</td>${d.brands.map(b=>`<td class="bs" style="--bb:${col(b)[1]};--bc:${col(b)[0]}">${pbar(r.byBrand[b],b)}</td>`).join('')}<td class="res">${chip(r.total)}${stack(r.byBrand,r.total)}</td></tr>`).join('')}</tbody><tfoot><tr class="v7rgAvg"><td></td><td class="l">RATA-RATA</td>${d.brands.map(b=>`<td class="bs" style="--bb:${col(b)[1]};--bc:${col(b)[0]}">${PT(d.avg[b])}</td>`).join('')}<td class="res">${chip(d.avgTotal)}</td></tr></tfoot></table></div>`;
 const det=d.rows.map(r=>{
  const m=new Map();inds(r).forEach(i=>{const bigs=(i.bigs&&i.bigs.length)?i.bigs.join(' + '):'',b=brOf(i),k=b+'|'+bigs;if(!m.has(k))m.set(k,{b,bigs,items:[],rb:false,pts:0});const o=m.get(k);o.items.push(i);if(i.regionBased)o.rb=true;if(i.pts!=null)o.pts+=Number(i.pts);});
  const blocks=[...m.values()],val=(i,x)=>x==null?'—':(i.metric==='OMZET'?moneyShort(x):num(x)),tot=r.total,sc=Math.max(100,tot||0);
  const live=inds(r).filter(i=>i.score!=null&&i.ach!=null),weak=live.length?live.reduce((a,b)=>Number(b.ach)<Number(a.ach)?b:a):null,maxW=Math.max(0,...inds(r).map(i=>Number(i.weight||0)));
  const contrib=r.byBrand&&tot!=null?`<div class="v7rgContrib" title="Sumbangan poin per brand">${d.brands.map(b=>r.byBrand[b]?`<i style="width:${r.byBrand[b]/sc*100}%;background:${col(b)[0]}"></i>`:'').join('')}</div><div class="v7rgLeg">${d.brands.filter(b=>r.byBrand[b]!=null).map(b=>`<span style="--c:${col(b)[0]}">${esc(BN(b))} ${PT(r.byBrand[b])}</span>`).join('')}${tot<100?`<span style="--c:#E3E8EF">belum tercapai ${PT(100-tot)}</span>`:''}</div>`:'';
  const rows=blocks.map(bl=>{const c=col(bl.b);return `<tr class="v7rgBr" style="--bb:${c[1]};--bc:${c[0]}"><td colspan="6">${esc(BN(bl.b))}${bl.bigs?' <small>'+esc(bl.bigs)+'</small>':''}${bl.rb?' <small class="rgRb">dihitung dari semua penjualan region</small>':''}<span>${PT(bl.pts)} poin</span></td></tr>`+bl.items.map(i=>{const off=i.score==null,w=Number(i.weight||0),bw=w?Math.max(2,Math.min(40,(i.pts||0)/w*40)):0;return `<tr class="${off?'rgOff':''}"><td class="l">${esc(MN[i.metric]||MN[String(i.label||'').split(' ')[0]]||String(i.label||i.metric).replace(new RegExp('\\s*'+brOf(i)+'$','i'),''))}${i.types&&i.types.length?'<small class="cellsub">'+i.types.map(esc).join(', ')+'</small>':''}</td><td>${i.target?val(i,i.target):'—'}${i.targetAuto?'<small class="cellsub rgAuto">otomatis · ikut big region</small>':''}</td><td>${val(i,i.actual)}</td><td>${i.ach==null?(off?'<small>tidak dihitung</small>':'—'):chip(i.ach)}</td><td>${PT(w).replace(/,0$/,'')}%</td><td>${i.pts==null?'—':`<span class="v7rgKbar"><i style="width:${bw}px"></i><b>${PT(i.pts)}</b></span>`}</td></tr>`;}).join('');}).join('');
  return `<div class="v7rgCard"><div class="v7rgKh">${badge(r.rank)}<div class="v7rgNm"><b>${esc(r.nama)}</b><small>${esc(r.region||'')}${r.own?'':' · KPI Big Region'}${r.status?' · '+esc(r.status):''}</small></div><div class="v7rgTot"><b class="${tier(tot)}">${tot==null?'—':PT(tot)+'%'}</b><small>TOTAL KPI</small></div></div>${contrib}<div class="table-scroll"><table class="rgT v7rgNt"><thead><tr><th class="l">Indikator</th><th>Target</th><th>Aktual</th><th>% Achv</th><th>Bobot</th><th>Poin KPI</th></tr></thead><tbody>${rows}</tbody></table></div><div class="v7rgKf"><span>${weak?`Terlemah: <b>${esc(String(weak.label||weak.metric).replace(new RegExp('\\s*'+brOf(weak)+'$','i'),'')+' '+BN(brOf(weak)))} ${PT(weak.ach)}%</b> (bobot ${PT(weak.weight).replace(/,0$/,'')}%${Number(weak.weight)===maxW?' · terbesar':''})`:''}</span><span>Total <b>${tot==null?'—':PT(tot)+'%'}</b></span></div></div>`;}).join('');
 return `<div class="v7rgNote">${d.partial?'<span class="v7rgSt">SEMENTARA</span>':''}Data s.d. ${esc(tgl(d.cutoff))} · angka per brand = poin yang menyumbang ke total</div>${sum}<h4 class="rgH4">RINCIAN PER RGM</h4><div class="v7rgGrid">${det}</div>`;
}

/* ===== Admin 6 tab ===== */
const V6TABS=[['data','🩺 Data & Kesehatan',['cek kesehatan','upload regional','kelengkapan data','catatan kualitas','status sync']],
 ['user','👥 User & Akses',['akun pengguna','tambah user massal','hak export','penugasan telemarketing']],
 ['dealer','🏬 Dealer',['cari & edit dealer','pic dealer per brand','upload dealer','ganti kode induk','transfer dealer','update kontak dealer','approval data dealer','dealer tutup','tambah dealer','bulk edit customer']],
 ['kpi','🎯 Target & KPI',['edit target','atur kpi','kpi khusus','kpi telemarketing','region per brand']],
 ['master','🗂️ Master',['brand','master product','download data master','region map','big region per dealer','hari libur','bulk master','badan usaha form order','master & kebijakan']],
 ['sistem','🛡️ Sistem',['keamanan akun','riwayat aktivitas','autobackup','kunci periode','pemulihan regional']]];
let V6TAB=(()=>{try{return localStorage.getItem('sp-admin-tab')||'data'}catch(e){return 'data'}})();
function v6AdminTabs(){const v=$('view');if(!v||$('v6Tabs'))return;const items=[...v.querySelectorAll(':scope>details.adminFeature')];if(!items.length)return;
 const title=d=>(d.querySelector('summary')?.textContent||'').toLowerCase(),tabOf={},order={};
 items.forEach(d=>{const t=title(d);let hit=null,pos=99;V6TABS.forEach(([id,,keys])=>keys.forEach((k,i)=>{if(!hit&&t.startsWith(k)){hit=id;pos=i;}}));if(!hit)V6TABS.forEach(([id,,keys])=>keys.forEach((k,i)=>{if(!hit&&t.includes(k)){hit=id;pos=i;}}));d.dataset.v6tab=hit||'sistem';order[d.dataset.feature||t]=pos;if(/^(tambah dealer|bulk edit customer)/.test(t))d.classList.add('v6legacy');});
 // urutkan sesuai daftar tab
 const anchor=items[0].previousElementSibling;const sorted=items.slice().sort((a,b)=>V6TABS.findIndex(x=>x[0]===a.dataset.v6tab)-V6TABS.findIndex(x=>x[0]===b.dataset.v6tab)||(order[a.dataset.feature||title(a)]-order[b.dataset.feature||title(b)]));
 const bar=document.createElement('div');bar.id='v6Tabs';bar.className='v6Tabs';bar.innerHTML=V6TABS.filter(([id])=>items.some(d=>d.dataset.v6tab===id)).map(([id,l])=>`<button type="button" data-v6t="${id}">${l}<span class="v6tBadge" data-v6tb="${id}"></span></button>`).join('');
 (anchor||v.firstChild)?anchor.after(bar):v.prepend(bar);let prev=bar;sorted.forEach(d=>{prev.after(d);prev=d;});
 const legacy=sorted.filter(d=>d.classList.contains('v6legacy'));if(legacy.length){const h=document.createElement('p');h.className='hint v6legacyNote';h.dataset.v6tab='dealer';h.textContent='Cara lama (masih bisa dipakai, tapi Upload dealer di atas sudah mencakup tambah + edit):';legacy[0].before(h);}
 const apply=()=>{const q=($('adminFeatureSearch')?.value||'').trim();v.querySelectorAll('[data-v6tab]').forEach(d=>d.classList.toggle('v6tabOff',!q&&d.dataset.v6tab!==V6TAB));bar.querySelectorAll('[data-v6t]').forEach(b=>b.classList.toggle('on',!q&&b.dataset.v6t===V6TAB));bar.classList.toggle('searching',!!q);};
 bar.onclick=e=>{const b=e.target.closest('[data-v6t]');if(!b)return;V6TAB=b.dataset.v6t;try{localStorage.setItem('sp-admin-tab',V6TAB)}catch(x){}const s=$('adminFeatureSearch');if(s&&s.value){s.value='';s.dispatchEvent(new Event('input'));}apply();};
 $('adminFeatureSearch')?.addEventListener('input',apply);
 if(!bar.querySelector(`[data-v6t="${V6TAB}"]`))V6TAB=bar.querySelector('[data-v6t]').dataset.v6t;apply();}
function v6TabGo(el){const d=el&&el.closest('[data-v6tab]');if(d&&d.dataset.v6tab!==V6TAB){const b=document.querySelector(`#v6Tabs [data-v6t="${d.dataset.v6tab}"]`);if(b)b.click();}}

/* ===== Cari & edit dealer ===== */
let V6DE=null;
function v6DealerEditPanel(v){v.insertAdjacentHTML('beforeend',panel('Cari & edit dealer',`<p class="hint"><b>KODE_UNIQ_CUSTOMER</b> = identitas toko (dipakai di file ST, tidak bisa diubah). <b>KODE CUSTOMER</b> = kode induk (untuk tabel & hitung DA). Satu induk bisa berisi beberapa toko.</p>
<div class="toolbar"><input class="fi" id="v6deQ" placeholder="Cari kode uniq / kode induk / nama dealer" style="flex:1;max-width:520px"><button class="chip primary" type="button" id="v6deGo">Cari</button><span id="v6deMsg" class="hint"></span></div><div id="v6deList"></div><div id="v6deBox"></div>`));
 const go=async()=>{const q=$('v6deQ').value.trim();$('v6deMsg').textContent='Mencari…';try{const r=await rpc('apiDealerSearch',TOKEN,q);$('v6deMsg').textContent=r.total+' hasil'+(r.total>r.rows.length?' · menampilkan '+r.rows.length+' (perjelas pencarian)':'')+' · klik baris untuk edit';
  $('v6deList').innerHTML=`<div class="table-scroll" style="max-height:340px"><table class="v6deTable"><thead><tr><th>KODE_UNIQ_CUSTOMER</th><th>KODE CUSTOMER (induk)</th><th>Nama dealer</th><th>Nama induk</th><th>Sales</th><th>Big Region</th><th>Status</th></tr></thead><tbody>${r.rows.map(x=>`<tr data-deu="${esc(x.uniq)}" style="cursor:pointer"><td><b>${esc(x.uniq)}</b></td><td>${esc(x.induk)}</td><td>${esc(x.nama)}</td><td>${esc(x.namaInduk)}</td><td>${esc(x.sales)}</td><td>${esc(x.big)}</td><td>${x.closed?'<span class="v6pill gr">Tutup</span>':'<span class="v6pill g">Aktif</span>'}</td></tr>`).join('')||'<tr><td colspan="7">Tidak ketemu.</td></tr>'}</tbody></table></div>`;
  $('v6deList').querySelectorAll('[data-deu]').forEach(tr=>tr.onclick=()=>{$('v6deList').querySelectorAll('tr.sel').forEach(x=>x.classList.remove('sel'));tr.classList.add('sel');v6DeOpen(tr.dataset.deu);});}catch(e){$('v6deMsg').innerHTML='<b style="color:#b91c1c">'+esc(e.message||e)+'</b>';}};
 $('v6deGo').onclick=go;$('v6deQ').onkeydown=e=>{if(e.key==='Enter')go();};}
async function v6DeOpen(uniq){const box=$('v6deBox');box.innerHTML='<p class="hint v6load">Memuat dealer…</p>';try{V6DE=await rpc('apiDealerEditDetail',TOKEN,uniq);v6DeDraw();}catch(e){box.innerHTML='<p class="v6rmErr">'+esc(e.message||e)+'</p>';}}
function v6DeDraw(){const d=V6DE,box=$('v6deBox'),multi=d.siblings.length>1,names=d.namaIndukList;
 box.innerHTML=`<div class="v6deGrid"><div class="v6deCard"><div class="v6deHero"><div><b>${esc(d.fields.find(f=>f.key==='NAMA CUSTOMER')?.value||d.namaInduk||d.uniq)}</b><small>KODE_UNIQ_CUSTOMER <b>${esc(d.uniq)}</b> · tidak bisa diubah (identitas toko)</small></div><span class="v6pill bl">${num(d.tx.uniq)} transaksi toko · ${num(d.tx.induk)} induk</span></div>
 <div class="v6deForm">${d.fields.map(f=>`<label${/ALAMAT/.test(f.key)?' style="grid-column:1/-1"':''}>${esc(f.key)}<input class="fi" data-def="${esc(f.key)}" value="${esc(f.value)}"></label>`).join('')}
 <label>NIK Sales default / fallback<input class="fi" readonly value="${esc(d.nik)} · ${esc(d.sales)}"><span class="hint">Dipakai jika brand belum punya PIC khusus</span></label><label>Big Region default<input class="fi" readonly value="${esc(d.big||'-')}"><span class="hint">PIC per brand dapat berbeda / lintas region</span></label></div>
 <div class="v6deInduk"><b>Kode induk (KODE CUSTOMER)</b>
 <div class="v6deForm"><label>Sekarang<input class="fi" readonly value="${esc(d.induk)}"></label><label>Ganti ke (kosongkan kalau tidak ganti)<input class="fi" id="v6deIndukBaru" placeholder="kode induk baru"></label>
 <label style="grid-column:1/-1">Nama induk ${multi?`<span class="hint">— berlaku untuk ${d.siblings.length} toko di induk ini</span>`:''}<input class="fi" id="v6deNamaInduk" value="${esc(d.namaInduk)}"></label></div>
 ${names.length>1?`<div class="v6oldTpl">Nama induk belum seragam: ${names.map(esc).join(' / ')}. Isi nama yang benar di atas lalu simpan — semua toko di induk ini ikut.</div>`:''}<div id="v6deIndukNote"></div></div>
 <div class="toolbar" style="margin-top:10px"><input class="fi" id="v6deReason" placeholder="Alasan perubahan (wajib)" style="flex:1;min-width:200px"><button class="chip primary" type="button" id="v6deSave">Simpan & publish</button></div><p id="v6deSMsg" class="hint"></p>
 <div class="toolbar v6deActs"><button class="chip" type="button" data-v6hgo="PIC Dealer per Brand">PIC per Brand</button><button class="chip" type="button" data-v6hgo="transfer dealer">⇄ Transfer ke sales lain</button><button class="chip" type="button" data-v6hgo="dealer tutup">Tutup dealer</button><button class="chip" type="button" id="v6deDel">Hapus</button><span class="hint">Hapus hanya untuk dealer tanpa transaksi (salah input). Yang punya transaksi → Tutup.</span></div></div>
 <div><div class="v6deCard"><h4>Toko di induk yang sama</h4><table><thead><tr><th>Kode uniq</th><th>Nama</th></tr></thead><tbody>${d.siblings.map(s=>`<tr${s.uniq===d.uniq?' class="sel"':''}><td>${esc(s.uniq)}</td><td>${esc(s.nama)}</td></tr>`).join('')}</tbody></table><p class="hint">DA dihitung per induk: ${d.siblings.length} toko ini = <b>1 dealer aktif</b>.${d.closed?' · <b>Tutup</b> sejak '+esc(d.closed):''}</p></div>
 <div class="v6deCard"><h4>Riwayat dealer ini</h4>${d.history.length?`<table><tbody>${d.history.map(h=>`<tr><td style="white-space:nowrap">${esc(h.when)}</td><td class="v6aDet">${esc(h.text)} · <i>${esc(h.by)}</i></td></tr>`).join('')}</tbody></table>`:'<p class="hint">Belum ada perubahan tercatat.</p>'}</div></div></div>`;
 let peekT=0;$('v6deIndukBaru').oninput=e=>{clearTimeout(peekT);const b=e.target.value.trim(),n=$('v6deIndukNote');if(!b||b===d.induk){n.innerHTML='';return;}peekT=setTimeout(async()=>{try{const r=await rpc('apiDealerIndukPeek',TOKEN,d.uniq,b);n.innerHTML=r.err?`<p class="v6rmErr">${esc(r.err)}</p>`:`<div class="v6oldTpl">Induk <b>${esc(r.lama)}</b> dipakai <b>${r.toko.length} toko</b> (${r.toko.map(esc).join(', ')}) → semua dipindah ke <b>${esc(r.baru)}</b>.<ul style="margin:6px 0 0 18px"><li>Transaksi lama tidak diubah; DA, NOO, history & tren langsung dihitung per <b>${esc(r.baru)}</b> termasuk bulan-bulan lalu.</li>${r.exists?`<li>${esc(r.baru)} sudah dipakai ${r.exists} toko (${r.existsToko.map(esc).join(', ')}) → <b>digabung</b>, nama induk ikut <b>${esc(r.namaBaru||r.baru)}</b>.</li>`:`<li>${esc(r.baru)} induk baru — nama induk pakai isian di atas.</li>`}</ul></div>`;if(r.exists&&r.namaBaru)$('v6deNamaInduk').value=r.namaBaru;}catch(x){n.innerHTML='<p class="v6rmErr">'+esc(x.message||x)+'</p>';}},400);};
 $('v6deSave').onclick=async e=>{const reason=$('v6deReason').value.trim();if(reason.length<5){$('v6deSMsg').innerHTML='<b style="color:#b91c1c">Isi alasan minimal 5 karakter.</b>';return;}const fields={};box.querySelectorAll('[data-def]').forEach(i=>{fields[i.dataset.def]=i.value;});const baru=$('v6deIndukBaru').value.trim(),nm=$('v6deNamaInduk').value.trim(),input={fields};if(baru&&baru!==d.induk){input.indukBaru=baru;input.namaIndukBaru=nm;if(!confirm('Ganti kode induk '+d.induk+' → '+baru+' untuk semua toko di induk ini?'))return;}else if(nm!==d.namaInduk||names.length>1)input.namaInduk=nm;
  e.target.disabled=true;$('v6deSMsg').textContent='Menyimpan & publish…';try{const r=await rpc('apiDealerSave',TOKEN,d.uniq,input,reason);$('v6deSMsg').innerHTML=r.nothing?'Tidak ada yang berubah.':'<b style="color:#15803d">✓ Tersimpan: '+esc((r.log||[]).join('; '))+'</b>';if(!r.nothing){await v6DeOpen(d.uniq);$('v6deSMsg').innerHTML='<b style="color:#15803d">✓ Tersimpan: '+esc((r.log||[]).join('; '))+'</b>';}}catch(x){$('v6deSMsg').innerHTML='<b style="color:#b91c1c">'+esc(x.message||x)+'</b>';}finally{if($('v6deSave'))$('v6deSave').disabled=false;}};
 $('v6deDel').onclick=async e=>{e.target.disabled=true;try{const c=await rpc('apiDealerDeleteCheck',TOKEN,d.uniq);if(c.block.length){$('v6deSMsg').innerHTML='<b style="color:#b91c1c">Tidak bisa dihapus: '+esc(c.block.join(' '))+'</b>';return;}const reason=prompt('Hapus dealer '+d.uniq+' permanen dari Master_Customer?\nTulis alasan:');if(!reason||reason.trim().length<5){if(reason!==null)alert('Alasan minimal 5 karakter.');return;}const r=await rpc('apiDealerDelete',TOKEN,[d.uniq],reason.trim());if(r.deleted){$('v6deBox').innerHTML='<p class="hint" style="color:#15803d"><b>✓ Dealer '+esc(d.uniq)+' dihapus.</b></p>';$('v6deList').querySelector(`[data-deu="${CSS.escape(d.uniq)}"]`)?.remove();}else $('v6deSMsg').innerHTML='<b style="color:#b91c1c">'+esc((r.rejSample[0]||{}).alasan||'Ditolak')+'</b>';}catch(x){$('v6deSMsg').innerHTML='<b style="color:#b91c1c">'+esc(x.message||x)+'</b>';}finally{e.target.disabled=false;}};}

/* ===== Ganti kode induk massal & hapus dealer massal ===== */
function v6IndukBulkPanel(v){v.insertAdjacentHTML('beforeend',panel('Ganti kode induk & hapus dealer massal',`<h4 style="margin:0 0 4px">Ganti kode induk massal</h4><p class="hint">Upload 2 kolom: <b>KODE INDUK LAMA</b> · <b>KODE INDUK BARU</b>. Semua toko di induk lama ikut pindah. Transaksi lama tidak diubah — histori, DA & NOO otomatis ikut induk baru.</p>
<div class="toolbar"><button class="chip" type="button" id="v6ibTpl">Download template</button><form id="v6ibForm" style="display:contents"><input type="hidden" name="token"><input class="fi" type="file" name="file" accept=".xlsx,.csv" required><button class="chip primary">Periksa file</button></form></div><div id="v6ibBox"></div>
<h4 style="margin:18px 0 4px">Hapus dealer massal</h4><p class="hint">Tempel daftar KODE_UNIQ_CUSTOMER (satu per baris, bisa copy dari Excel). Hanya dealer tanpa transaksi ST/SO yang dihapus; sisanya masuk file DITOLAK.</p>
<textarea class="fi" id="v6hdList" rows="4" placeholder="BP07015&#10;BP07016" style="width:100%;max-width:520px"></textarea><div class="toolbar"><input class="fi" id="v6hdReason" placeholder="Alasan (wajib)" style="max-width:320px"><button class="chip" type="button" id="v6hdGo">Hapus dealer</button><span id="v6hdMsg" class="hint"></span></div>`));
 $('v6ibTpl').onclick=async e=>{e.target.disabled=true;try{downloadBase64(await rpc('apiIndukBulkTemplate',TOKEN));}catch(x){fail(x);}finally{e.target.disabled=false;}};
 $('v6ibForm').onsubmit=async e=>{e.preventDefault();e.target.elements.token.value=TOKEN;const box=$('v6ibBox');box.innerHTML='<p class="hint">Memeriksa…</p>';try{const r=await rpc('apiIndukBulkStage',e.target);
