/* KPI dari total tim: jumlahkan target & aktual per indikator lalu hitung skor (sama seperti baris TOTAL TIM). */
function v6KpiTotalScore(people){if(people.some(p=>(p.kpi?.groups||[]).some(g=>(g.indicators||[]).some(i=>i.metric==='IDDLE'&&Number(i.target)>0&&i.actual==null))))return null;const G={};people.forEach(p=>((p.kpi&&p.kpi.groups)||[]).forEach(g=>{const grp=G[g.name]||(G[g.name]={});(g.indicators||[]).forEach(i=>{const k=[i.metric,i.brand,i.indicator||'',(i.types||[]).join('|')].join('¦'),x=grp[k]||(grp[k]={t:0,a:0,w:Number(i.weight||0),cap:Number(i.cap||120)});x.t+=Number(i.target||0);if(i.metric==='IDDLE'&&Array.isArray(i.iddlePairs)){x.pairs=x.pairs||new Set();i.iddlePairs.forEach(pair=>x.pairs.add(pair));x.a=x.pairs.size;}else x.a+=Number(i.actual||0);});}));
 const gs=Object.values(G).map(grp=>{let w=0,ws=0;Object.values(grp).forEach(x=>{if(!(x.t>0)||!(x.w>0))return;const sc=Math.min(x.cap,Math.max(0,x.a/x.t*100));w+=x.w;ws+=sc*x.w;});return w?ws/w:null;}).filter(v=>v!=null);
