function v6KpiHasValue(k){return ((k&&k.groups)||[]).some(g=>(g.indicators||[]).some(i=>Number(i.target||0)>0||Number(i.actual||0)!==0));}
/* Satu angka KPI untuk semua level dalam cakupan: skor tim paling atas (RGM ber-KPI standar) = KPI total region.
   Kalau tidak ada / RGM pakai KPI khusus, pakai total gabungan Sales. */
function v6KpiRegionScore(all){const rg=all.filter(p=>p.role==='RGM'&&p.kpi&&!p.kpi.rgm&&p.kpi.score!=null);if(rg.length===1)return rg[0].kpi.score;
 const asm=all.filter(p=>p.role==='ASM'&&p.kpi&&p.kpi.score!=null),sales=all.filter(p=>p.role==='SALES');return v6KpiTotalScore(sales.length?sales:asm);}

