function customerMonthlyHistory(c,period,selection,token){
 const root=$('customerMonthlyHistory');if(!root)return;let metric='st',range=6,result=null;
 const draw=()=>{if(!root.isConnected||!result)return;const months=result.months||[],brands=result.displayBrands||[],row=(result.rows||[]).find(x=>x.id===c.id),shown=months.map((m,i)=>({m,i})).slice(-range).reverse();
