 };
 root.querySelectorAll('[data-cmh-metric]').forEach(b=>b.onclick=()=>{metric=b.dataset.cmhMetric;draw()});root.querySelector('[data-cmh-range]').onchange=e=>{range=Number(e.target.value);draw()};
 const start=new Date(+period.slice(0,4),+period.slice(5)-12,1),from=start.getFullYear()+'-'+String(start.getMonth()+1).padStart(2,'0');
 rpc('apiDealerHistory',token,selection,'ALL',from,period,0,'',{customer:c.id,dateMode:'FULL',pageSize:50}).then(r=>{if(token!==TOKEN||!root.isConnected||root.dataset.id!==c.id)return;result=r;draw()}).catch(e=>{if(token===TOKEN&&root.isConnected)root.querySelector('.cmhTable').innerHTML='<p class="hint">Histori belum bisa dimuat: '+esc(e.message)+'</p>'});
}
