let infoPage=0,infoQuery='',infoRegion='ALL';
function infoRoleLabel(role){return role==='ALL'?'Semua role':role;}
function infoRoleChoices(){
  const role=String(BOOT?.user?.role||'').toUpperCase();
  if(['ADMIN','SUPER ADMIN'].includes(role))return ['ALL','SALES','TELEMARKETING','ASM','RGM','ADMIN','HEAD OF SALES','CHIEF OPERATING OFFICER','CHIEF COMMERCIAL OFFICER','BOARD OF DIRECTOR','SUPER ADMIN'];
  if(role==='RGM')return ['ASM','SALES'];
  if(role==='ASM')return ['SALES'];
  if(['HEAD OF SALES','CHIEF OPERATING OFFICER','CHIEF COMMERCIAL OFFICER','BOARD OF DIRECTOR'].includes(role))return ['RGM','ASM','SALES'];
  return ['SALES'];
}
function infoCheckOptions(name,items,{selected=[],allToggleLabel='',allToggleId=''}={}){
  const selectedSet=new Set(selected);
  return (allToggleLabel?`<label class="confirm"><input type="checkbox" id="${allToggleId}"> ${allToggleLabel}</label>`:'')+
    `<div class="regionChecks">${items.map(item=>`<label><input type="checkbox" name="${name}" value="${esc(item.value)}" ${selectedSet.has(item.value)?'checked':''}> <span>${esc(item.label)}</span></label>`).join('')}</div>`;
}
function wireChecklistAll(allId,name,root){
  const host=root||document,all=$(allId),items=[...host.querySelectorAll(`[name="${name}"]`)];
  if(!all||!items.length)return;
  const sync=()=>all.checked=items.every(x=>x.checked);
  all.onchange=e=>items.forEach(x=>x.checked=e.target.checked);
  items.forEach(x=>x.onchange=sync);
  sync();
}
function wireInfoRoleRules(root){
  const wrap=root||document,checks=[...wrap.querySelectorAll('[name="infoRoleChoice"]')],allRole=checks.find(x=>x.value==='ALL');
  if(!checks.length)return;
  const sync=()=>{if(allRole&&allRole.checked){checks.filter(x=>x!==allRole).forEach(x=>x.checked=false);}if(allRole)allRole.disabled=checks.some(x=>x!==allRole&&x.checked);};
  checks.forEach(ch=>ch.onchange=()=>{if(ch.value==='ALL'&&ch.checked)checks.filter(x=>x!==ch).forEach(x=>x.checked=false);else if(ch.value!=='ALL'&&ch.checked&&allRole)allRole.checked=false;sync();});
  sync();
}
