function renderMyDevices(v,rows){
  v.innerHTML=`<div class="infoIntro"><div><h3>Perangkat yang masuk ke akun ini</h3><p>Maksimal 5 perangkat per akun. Hapus perangkat yang sudah tidak dipakai supaya bisa masuk dari perangkat baru.</p></div><span class="statusBadge status-active">${rows.length}/5 perangkat</span></div><div class="infoGrid">${rows.length?rows.map(d=>deviceCard(d)).join(''):'<div class="empty">Belum ada perangkat terdaftar.</div>'}</div>`;
  v.querySelectorAll('[data-dev-rename]').forEach(b=>b.onclick=async()=>{
    const id=b.dataset.devRename,nama=prompt('Nama baru untuk perangkat ini:');
    if(nama===null||!nama.trim())return;
    b.disabled=true;
    try{const rows=await rpc('apiRenameDevice',TOKEN,id,nama.trim());if(TOKEN)renderMyDevices(v,rows);}catch(e){fail(e);}finally{b.disabled=false;}
  });
  v.querySelectorAll('[data-dev-remove]').forEach(b=>b.onclick=async()=>{
    const id=b.dataset.devRemove,self=id===DEVICE_ID;
    if(!confirm(self?'Hapus perangkat ini? Anda akan langsung keluar dari akun ini di perangkat ini.':'Hapus perangkat ini? Perangkat tersebut akan langsung keluar dari akun ini.'))return;
    b.disabled=true;
    try{
      const rows=await rpc('apiRemoveDevice',TOKEN,id);
      if(self){logout(false);return;}
      renderMyDevices(v,rows);
    }catch(e){fail(e);b.disabled=false;}
  });
}

async function adminDevicePanel(nik,nama){
  modal('Perangkat · '+nama,'<p class="v6load">Memuat…</p>');
  const token=TOKEN;
  let rows;
  try{rows=await rpc('apiAdminListDevices',token,nik);}catch(e){if(token===TOKEN)$('mbody').innerHTML='<div class="info">'+esc(e.message)+'</div>';return;}
  if(token!==TOKEN)return;
  renderAdminDevices(nik,nama,rows);
}
function renderAdminDevices(nik,nama,rows){
  $('mbody').innerHTML=(rows.length?rows.map(d=>`<article class="infoCard"><h3>${esc(d.nama)}</h3><div class="infoMeta">Terdaftar ${esc(d.created?new Date(d.created).toLocaleDateString('id-ID',{timeZone:'Asia/Jakarta'}):'—')} · Terakhir aktif ${esc(d.lastSeen?new Date(d.lastSeen).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})+' WIB':'—')}</div><div class="toolbar"><button class="chip" data-admin-dev-remove="${esc(d.deviceId)}">Hapus</button></div></article>`).join(''):'<div class="empty">Belum ada perangkat terdaftar.</div>')+`<p class="hint">${rows.length}/5 perangkat terpakai.</p>`;
  $('mbody').querySelectorAll('[data-admin-dev-remove]').forEach(b=>b.onclick=async()=>{
    if(!confirm('Hapus perangkat ini dari akun '+nama+'? Perangkat tersebut langsung keluar.'))return;
