  });
}

function soNum(n){return n==null?'—':num(n);}
function soNote(){return REPORT.so?.cutoff?'s.d. '+tgl(REPORT.so.cutoff)+(REPORT.so.complete?'':' · belum sejajar ST'):'SO belum diimpor';}
function sumTarget(items){return {exists:items.length>0&&items.every(t=>t&&t.exists),value:items.reduce((n,t)=>n+(t?.value||0),0),missing:items.flatMap(t=>t?.missing||['?'])};}
function sumSO(items){return items.some(x=>x==null)?null:items.reduce((n,x)=>n+x,0);}
function sumBy(rows,key){return rows.reduce((n,r)=>n+(Number(r[key])||0),0);}

