 if(b.t==='bars')return '<div class="aiBl"><h5>'+esc(b.title||'')+'</h5>'+b.rows.map(x=>'<div class="aiBr'+(x.wide?' w':'')+'" style="--c:'+esc(x.c)+'"><span>'+esc(x.l)+'</span><i><s style="width:'+Math.max(2,Math.min(100,+x.v||0))+'%"></s></i><span>'+esc(x.txt)+'</span></div>').join('')+'</div>';
 if(b.t==='table'){const hx=new Set(b.html||[]),n=b.cols.length,g='grid-template-columns:minmax(96px,1.7fr) repeat('+(n-1)+',minmax(54px,1fr))';return '<div class="aiBl"><h5>'+esc(b.title||'')+'</h5><div class="aiTg"><div class="aiTr h" style="'+g+'">'+b.cols.map(c=>'<span>'+esc(c)+'</span>').join('')+'</div>'+b.rows.map(r=>'<div class="aiTr" style="'+g+'">'+r.map((c,i)=>'<span>'+(hx.has(i)?c:esc(c))+'</span>').join('')+'</div>').join('')+'</div></div>';}
 if(b.t==='note')return '<div class="aiNote">'+esc(b.text)+'</div>';
 if(b.t==='chips')return '<div class="aiCh">'+b.items.map(q=>'<button type="button" class="v6aichip" data-v6ask="'+esc(q)+'">'+esc(q)+'</button>').join('')+'</div>';
 return '';}
function aiRenderMessages(){const box=$('aiMessages');if(!box)return;if(!AI_HISTORY.length){box.innerHTML='<div class="aiEmpty"><b>Tanya apa aja soal data penjualan.</b>Scope AI mengikuti pilihan Cakupan dan Periode di atas.</div>'+v6AiChips();return;}box.innerHTML=AI_HISTORY.map(m=>`<div class="aiMsg ${m.role}"><div class="aiBubble">${esc(m.text)}${(m.blocks||[]).map(aiBlock).join('')}${m.meta&&['ADMIN','SUPER ADMIN'].includes(BOOT.user.role)?`<div class="aiMeta">${esc(m.meta)}</div>`:''}</div></div>`).join('')+v6AiFollow();box.scrollTop=box.scrollHeight;}
