let dosB=null;
function dosBGet(){if(dosB)return dosB;dosB={m:'n',n:30};try{const x=JSON.parse(localStorage.getItem('dsm_dosb_'+(BOOT&&BOOT.user?BOOT.user.nik:''))||'null');if(x&&(x.m==='mtd'||x.m==='n'))dosB={m:x.m,n:Math.min(90,Math.max(3,+x.n||30))};}catch(e){}return dosB;}
function dosBSave(){try{localStorage.setItem('dsm_dosb_'+(BOOT&&BOOT.user?BOOT.user.nik:''),JSON.stringify(dosB));}catch(e){}}
function dosLbl(){const b=dosBGet();return b.m==='mtd'?'bulan berjalan':b.n+' hari';}
function dosShort(){const b=dosBGet();return b.m==='mtd'?'MTD':String(b.n);}
function dosBasisBar(r){const b=dosBGet();return '<div class="dosBasis"><span class="dosbSeg"><button type="button" class="chip '+(b.m==='mtd'?'primary':'')+'" data-dosb="mtd">DOS Bulan Berjalan</button><button type="button" class="chip '+(b.m==='n'?'primary':'')+'" data-dosb="n">DOS '+(b.n)+' Hari Terakhir</button></span>'+(b.m==='n'?'<span class="dosbN">'+[7,14,30,60].map(n=>'<button type="button" class="chip '+(b.n===n?'primary':'')+'" data-dosn="'+n+'">'+n+'</button>').join('')+'<input class="fi" id="dosNIn" type="number" min="3" max="90" value="'+b.n+'" aria-label="Jumlah hari"><small>hari (3–90)'+(b.n!==30?' · <a href="#" data-dosn="30">Kembalikan 30</a>':'')+'</small></span>':'')+(b.m==='mtd'&&r.soDays<8?'<div class="hint" style="flex:1 1 100%">SO baru '+r.soDays+' hari, DOS bisa melonjak di awal bulan. DOS ≥ 1000 hari ditandai SO terlalu kecil.</div>':'')+'</div>';}
function dosBBind(v){v.querySelectorAll('[data-dosb]').forEach(el=>el.onclick=()=>{dosBGet().m=el.dataset.dosb;dosBSave();dosPage=0;render();});v.querySelectorAll('[data-dosn]').forEach(el=>el.onclick=e=>{e.preventDefault();dosBGet().n=+el.dataset.dosn;dosB.m='n';dosBSave();dosPage=0;render();});const i=v.querySelector('#dosNIn');if(i)i.onchange=()=>{dosBGet().n=Math.min(90,Math.max(3,parseInt(i.value)||30));dosB.m='n';dosBSave();dosPage=0;render();};}
