/* v12: komponen tabel HP (chip lompat per kelompok kolom, header berwarna, Padat/Lega, ketuk baris = rincian) */
function v12Sheet(title,html){const old=document.getElementById('v12Sheet');if(old)old.remove();const o=document.createElement('div');o.id='v12Sheet';o.className='v12Ov';o.innerHTML='<div class="v12Sh" role="dialog" aria-modal="true"><div class="v12Grab"></div><h3>'+title+'</h3><div class="v12Sb">'+html+'</div><button type="button" class="v12Ok">TUTUP</button></div>';document.body.append(o);const close=()=>{o.classList.remove('on');setTimeout(()=>o.remove(),200);};o.onclick=e=>{if(e.target===o||e.target.classList.contains('v12Ok'))close();};requestAnimationFrame(()=>o.classList.add('on'));}
function v12HpTable(id,cfg){const el=document.getElementById(id);if(!el)return;let dense=true;const groups=cfg.groups;const draw=()=>{const cols=groups.flatMap(g=>g.cols.map(c=>({...c,g})));const thG='<tr class="g"><th class="nm"></th>'+groups.map(g=>'<th colspan="'+g.cols.length+'" class="'+g.cls+'" data-g="'+g.id+'">'+g.t+'</th>').join('')+'</tr>';const thH='<tr class="h"><th class="nm">'+cfg.lead+'</th>'+cols.map(c=>'<th>'+c.h+'</th>').join('')+'</tr>';const rows=cfg.rows.map((r,i)=>'<tr class="rw" data-i="'+i+'"><td class="nm">'+cfg.name(r)+'</td>'+cols.map(c=>'<td class="'+c.g.cc+'">'+c.f(r)+'</td>').join('')+'</tr>').join('');const tot=cfg.tot?'<tr class="tot"><td class="nm"><b>Total</b><small>'+(cfg.totNote||'Seluruh hasil filter')+'</small></td>'+cols.map(c=>'<td class="'+c.g.cc+'">'+(c.t?c.t(cfg.tot):'')+'</td>').join('')+'</tr>':'';el.innerHTML='<div class="v12Jc">'+groups.map(g=>'<button type="button" data-j="'+g.id+'" style="--c:'+g.col+'">'+g.t+'</button>').join('')+'<span class="v12Tg">'+['Padat','Lega'].map((x,i)=>'<button type="button" data-d="'+(i?'l':'p')+'" class="'+((i?!dense:dense)?'on':'')+'">'+x+'</button>').join('')+'</span></div><div class="v12Sc'+(dense?'':' lg')+'"><table><thead>'+thG+thH+'</thead><tbody>'+rows+tot+'</tbody></table></div><div class="v12Pos"><i></i></div>';const sc=el.querySelector('.v12Sc'),bar=el.querySelector('.v12Pos i');sc.onscroll=()=>{const m=sc.scrollWidth-sc.clientWidth||1,w=Math.max(18,sc.clientWidth/sc.scrollWidth*100);bar.style.width=w+'%';bar.style.marginLeft=(sc.scrollLeft/m*(100-w))+'%';};sc.onscroll();el.querySelectorAll('[data-j],[data-g]').forEach(b=>b.onclick=()=>{const gid=b.dataset.j||b.dataset.g,th=el.querySelector('thead tr.g th[data-g="'+gid+'"]');sc.scrollTo({left:th.offsetLeft-122,behavior:'smooth'});el.querySelectorAll('[data-j]').forEach(x=>x.classList.toggle('on',x.dataset.j===gid));});el.querySelectorAll('.v12Tg button').forEach(b=>b.onclick=()=>{dense=b.dataset.d==='p';draw();});el.querySelectorAll('tr.rw').forEach(tr=>tr.onclick=()=>{const r=cfg.rows[tr.dataset.i];v12Sheet(cfg.title(r),'<div class="v12Dl">'+cols.map(c=>'<span>'+(groups.length>1?c.g.t+' · ':'')+c.h+'</span><b>'+c.f(r)+'</b>').join('')+'</div>');});};draw();}
const V12LEG=[['bh','HABIS','Stok 0 padahal masih ada penjualan 30 hari terakhir'],['bx','PERLU CEK DATA','Stok negatif atau data belum lengkap'],['bm','MENIPIS','DOS di bawah batas minimum (default 7 hari, bisa beda per region)'],['ba','CUKUP','DOS di antara batas minimum dan maksimum'],['bt','STOK TINGGI','DOS di atas batas maksimum (default 45 hari)'],['bg','BELUM BERGERAK','Ada stok, tapi tidak ada penjualan 30 hari'],['bg','TIDAK AKTIF','Stok 0 dan tidak ada penjualan']];
function v12Legend(){return '<button type="button" class="v12Lgb" data-v12leg>Arti kondisi ▾</button><div class="v12Lgd">'+V12LEG.map(x=>'<div><span class="v12Bd '+x[0]+'">'+x[1]+'</span><span>'+x[2]+'</span></div>').join('')+'</div>';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-v12leg]');if(!b)return;const d=b.nextElementSibling,on=d.classList.toggle('on');b.textContent='Arti kondisi '+(on?'▴':'▾');});
function v12DosState(stock,sellout,dos){if(stock<0)return['PERLU CEK DATA','bx'];if(stock===0)return sellout>0?['HABIS','bh']:['TIDAK AKTIF','bg'];if(!(sellout>0))return['BELUM BERGERAK','bg'];if(dos==null)return null;return dos<7?['MENIPIS','bm']:dos>45?['STOK TINGGI','bt']:['CUKUP','ba'];}
function v12DosCls(d){return d==null?'':d<=0?'h':d<7?'m':d>45?'t':'a';}

function v12Panel(title,hint,id){return '<section class="v12Pn"><div class="v12Ph"><h2>'+title+'</h2><small>'+hint+'</small></div><div id="'+id+'"></div>'+v12Legend()+'</section>';}
function v12DosKpi(r){const t=r.total,dosTxt=t.dos==null?'—':decimal(t.dos)+' hari',why=t.dos==null?(!r.covered?'Belum bisa dihitung · histori ST/SO belum lengkap':!r.windowReady?'Belum bisa dihitung · SO '+dosLbl()+' belum lengkap':'Belum bisa dihitung · cek data'):'Stok ÷ rata-rata SO harian';const K=[['Estimasi stok',num(t.stock),'Unit device · sesuai filter','#2B7BE0','▦'],['Sell out '+dosLbl()+'',num(t.sellout),'Periode sejajar posisi stok','#F07A0C','↗'],['Rata-rata / hari',t.avg==null?'—':decimal(t.avg),'Unit sell out per hari','#0E9F6E','◎'],['DOS gabungan',dosTxt,why,'#6D3FD8','◷'],['Menipis / habis',num(t.low),'Pasangan dealer–TYPE','#D63A55','●'],['Perlu cek data',num(t.bad),'Pasangan dealer–TYPE','#8A5CE6','◆']];return '<div class="v12Kp">'+K.map(k=>'<button type="button" class="v12K" style="--c:'+k[3]+'" onclick="this.parentNode.querySelectorAll(\'.v12K\').forEach(x=>x!==this&&x.classList.remove(\'on\'));this.classList.toggle(\'on\')"><span class="ic">'+k[4]+'</span><span class="tx"><small>'+k[0]+'</small><b>'+k[1]+'</b><em>'+k[2]+'</em></span></button>').join('')+'</div>';}
function v12DosTxt(d){return d==null?'—':d>365?'>365 hari':decimal(d)+' hari';}
function v12DosCell(t){const dos=t.dos;let st=v12DosState(t.stock,t.sellout,dos);if(!st&&dos==null&&t.bad>0)st=['PERLU CEK DATA','bx'];return '<span class="v12Dc"><span class="v12Dv '+v12DosCls(dos)+'">'+v12DosTxt(dos)+'</span>'+(st?'<span class="v12Bd '+st[1]+'">'+st[0]+'</span>':'')+'</span>';}
function v12DosWilCfg(r){const rows=r.regions.slice().sort((a,b)=>(b.dos??-1)-(a.dos??-1));return {lead:'Wilayah',rows,tot:r.total,name:t=>'<b>'+esc(t.region)+'</b><small>'+esc(t.big)+'</small>',title:t=>esc(t.region)+' · '+esc(t.big),groups:[{id:'s',t:'Stok',cls:'gSt',cc:'cSt',col:'#2B7BE0',cols:[{h:'Dealer unik',f:t=>num(t.dealerCount),t:t=>num(t.dealerCount)},{h:'Dealer–TYPE menipis/habis',f:t=>t.low?'<span class="v12Bd bm">'+num(t.low)+'</span>':'-',t:t=>num(t.low)},{h:'Est. stok',f:t=>'<b class="'+(t.stock<0?'v12Neg':'')+'">'+num(t.stock)+'</b>',t:t=>num(t.stock)}]},{id:'o',t:'Sell out',cls:'gSo',cc:'cSo',col:'#F07A0C',cols:[{h:'SO '+dosLbl()+'',f:t=>num(t.sellout),t:t=>num(t.sellout)},{h:'Rata-rata/hari',f:t=>t.avg==null?'—':decimal(t.avg),t:t=>t.avg==null?'—':decimal(t.avg)}]},{id:'d',t:'DOS',cls:'gDs',cc:'cDs',col:'#6D3FD8',cols:[{h:'DOS',f:v12DosCell,t:t=>'<span class="v12Dv '+v12DosCls(t.dos)+'">'+v12DosTxt(t.dos)+'</span>'}]}]};}
function v12DosBrandCfg(r,bs){const rows=Object.values(bs).map(t=>{t.avg=r.windowReady?t.sellout/(r.soDays||30):null;t.dos=r.covered&&!t.bad&&t.avg>0?t.stock/t.avg:null;return t;});return {lead:'Brand',rows,tot:r.total,name:t=>'<b>'+esc(t.brand)+'</b>',title:t=>esc(t.brand),groups:[{id:'s',t:'Stok',cls:'gSt',cc:'cSt',col:'#2B7BE0',cols:[{h:'Est. stok',f:t=>'<b class="'+(t.stock<0?'v12Neg':'')+'">'+num(t.stock)+'</b>',t:t=>num(t.stock)}]},{id:'o',t:'Sell out',cls:'gSo',cc:'cSo',col:'#F07A0C',cols:[{h:'SO '+dosLbl()+'',f:t=>num(t.sellout),t:t=>num(t.sellout)},{h:'Rata-rata/hari',f:t=>t.avg==null?'—':decimal(t.avg),t:t=>t.avg==null?'—':decimal(t.avg)}]},{id:'d',t:'DOS',cls:'gDs',cc:'cDs',col:'#6D3FD8',cols:[{h:'DOS',f:v12DosCell,t:t=>'<span class="v12Dv '+v12DosCls(t.dos)+'">'+v12DosTxt(t.dos)+'</span>'}]}]};}
async function dosView(v,seq){
 const context=REPORT.period+'|'+$('scopeSelect').value;if(context!==dosContext){dosPage=0;dosContext=context;dosFilter={region:'ALL',subRegion:'ALL',brand:'ALL',type:'ALL',status:'ALL',query:''};}
 v.innerHTML='<p>Memeriksa posisi stok dan kelengkapan data…</p>';const r=await rpc('apiDOS',TOKEN,REPORT.period,$('scopeSelect').value,{...dosFilter,view:dosMode,sort:dosSort,pageSize:dosPageSize,basis:dosBGet().m,soDays:dosBGet().n},dosPage);if(seq!==SEQUENCE)return;
