 const values=t=>[`<b class="stockValue ${t.stock<0?'stockBad':t.stock===0?'stockZero':''}">${num(t.stock)}</b>`,num(t.sellout),t.avg==null?'—':decimal(t.avg),`<span class="dosDays"${t.dos==null?' title="'+esc(dosWhy(t))+'"':v6Tip({t:'DOS (days of stock)',rows:[['Estimasi stok',num(t.stock)+' unit'],['SELL OUT '+dosLbl()+'',num(t.sellout)],['Rata-rata / hari',decimal(t.avg)],['DOS',num(t.stock)+' ÷ '+decimal(t.avg)+' = '+decimal(t.dos)+' hari']],v:t.status?[{'MENIPIS':'bd','HABIS':'bd','STOK TINGGI':'md','CUKUP':'gd'}[t.status]||'md','Kondisi: '+esc(t.status)]:null})}>${t.dos==null?'—':decimal(t.dos)+' hari'}</span>`];
 const hpJobs=[];if(BOOT.user.role!=='SALES'&&isMobile()){v.innerHTML+=v12Panel('DOS per wilayah','Ketuk baris untuk rincian','dosWilHp');hpJobs.push(['dosWilHp',v12DosWilCfg(r)]);}else if(BOOT.user.role!=='SALES')v.innerHTML+=panel('DOS per wilayah dalam cakupan',table(['Region induk','Wilayah','Dealer unik','Dealer–TYPE menipis/habis','Estimasi stok','SO '+dosLbl()+'','Rata-rata/hari','DOS'],r.regions.slice().sort((a,b)=>(b.dos??-1)-(a.dos??-1)).map(t=>[esc(t.big),`<button class="textlink" data-dos-region="${esc(t.region)}">${esc(t.region)}</button>`,num(t.dealerCount),num(t.low),...values(t)]).concat([['Total','Seluruh hasil filter',num(r.total.dealerCount),num(r.total.low),...values(r.total)]])),'Klik wilayah untuk mempersempit hasil');
 const brandSummary={};r.brands.forEach(t=>{const k=t.brand,g=brandSummary[k]||(brandSummary[k]={brand:k,stock:0,sellout:0,bad:0});g.stock+=t.stock;g.sellout+=t.sellout;g.bad+=t.bad;});
 if(isMobile()){v.innerHTML+=v12Panel('DOS ringkasan brand','Gabungan dealer sesuai filter','dosBrnHp');hpJobs.push(['dosBrnHp',v12DosBrandCfg(r,brandSummary)]);}else v.innerHTML+=panel('DOS ringkasan brand',table(['Brand','Estimasi stok','SO '+dosLbl()+'','Rata-rata/hari','DOS'],Object.values(brandSummary).map(t=>{t.avg=r.windowReady?t.sellout/(r.soDays||30):null;t.dos=r.covered&&!t.bad&&t.avg>0?t.stock/t.avg:null;return [esc(t.brand),...values(t)];}).concat([['Total',...values(r.total)]])),'Gabungan dealer sesuai filter');
 v.innerHTML+=`<div class="tabs"><button id="dosByType" class="${dosMode==='TYPE'?'on':''}">Dealer + TYPE</button><button id="dosByBrand" class="${dosMode==='BRAND'?'on':''}">Dealer + Brand</button></div>`;
 if(isMobile())v.innerHTML+=v12Legend();if(isMobile()){/* v7 (M5): HP dikelompokkan per dealer, kondisi terparah di atas, stok/SO/DOS tetap tampil */const list=dosMode==='TYPE'?r.rows:r.brands.slice(r.page*r.pageSize,r.page*r.pageSize+r.pageSize),ORD=['HABIS','PERLU CEK DATA','MENIPIS','STOK TINGGI','BELUM BERGERAK','CUKUP'],rk=x=>{const i=ORD.indexOf(x);return i<0?ORD.length:i;},cls=x=>({'PERLU CEK DATA':'bad','CUKUP':'good','HABIS':'empty','MENIPIS':'low','STOK TINGGI':'high','BELUM BERGERAK':'still'})[x]||'still',groups=new Map();list.forEach(t=>{const k=t.customer;if(!groups.has(k))groups.set(k,{t,rows:[]});groups.get(k).rows.push(t);});const gs=[...groups.values()].map(g=>{g.w=Math.min(...g.rows.map(x=>rk(x.status||'')));g.stock=g.rows.reduce((n,x)=>n+(x.stock||0),0);g.so=g.rows.reduce((n,x)=>n+(x.sellout||0),0);g.dos=g.so>0&&r.windowReady?g.stock/(g.so/(r.soDays||30)):null;return g;}).sort((a,b)=>a.w-b.w);const worst=g=>ORD[g.w]||g.rows[0].status||'';v.innerHTML+=`<div class="v7dosList">${gs.map((g,gi)=>{const w=worst(g),nw=g.rows.filter(x=>x.status===w).length;return `<details class="v7dosDealer v12w-${cls(w)}"${gi===0?' open':''}><summary><div class="v7dn"><b>${esc(g.t.nama)}</b><small>${esc([g.t.sales,g.t.region].filter(Boolean).join(' · '))} · ${g.rows.length} ${dosMode==='TYPE'?'type':'brand'}</small><div class="v7ds"><span>EST. STOK <b class="${g.stock<0?'neg':''}">${num(g.stock)}</b></span><span>SO ${dosShort()} <b>${num(g.so)}</b></span><span>DOS <b>${g.dos==null?'-':decimal(g.dos)+' hari'}</b></span></div></div>${w?`<span class="statusBadge dosBadge dos-${cls(w)}">${esc(w)}${nw>1?' '+nw:''}</span>`:''}</summary><div class="v7db"><table><thead><tr><th>${dosMode==='TYPE'?'TYPE':'BRAND'}</th><th class="n">STOK</th><th class="n">SO ${dosShort()}</th><th class="n">DOS</th></tr></thead><tbody>${g.rows.map(x=>`<tr><td>${esc(dosMode==='TYPE'?(x.type||x.brand):x.brand)}${x.status?`<div><span class="statusBadge dosBadge dos-${cls(x.status)}">${esc(x.status)}</span></div>`:''}${x.reason?`<small class="cellsub">${esc(x.reason)}</small>`:''}</td><td class="n${x.stock<0?' neg':''}">${x.stock===0?'-':num(x.stock)}</td><td class="n">${x.sellout===0?'-':num(x.sellout)}</td><td class="n">${x.dos==null?'-':decimal(x.dos)+' hari'}</td></tr>`).join('')}</tbody></table><button class="textlink v7dopen" data-customer="${esc(g.t.customer)}">Buka detail dealer →</button></div></details>`;}).join('')}</div>`;}
 if(dosMode==='TYPE')v.innerHTML+=panel('Dealer + TYPE',table(['Dealer','Sales / Wilayah','Brand','TYPE','Estimasi stok','SO '+dosLbl()+'','Rata-rata/hari','DOS','Kondisi'],r.rows.map(t=>[esc(t.nama)+'<small class="cellsub">'+esc(t.customer)+'</small>',esc(t.sales)+'<small class="cellsub">'+esc(t.region)+'</small>',esc(t.brand),esc(t.type),...values(t),`<span class="statusBadge dosBadge dos-${({'PERLU CEK DATA':'bad','CUKUP':'good','HABIS':'empty','MENIPIS':'low','STOK TINGGI':'high','BELUM BERGERAK':'still'})[t.status]||'still'}">${esc(t.status)}</span>${t.reason?'<small class="cellsub">'+esc(t.reason)+'</small>':''}`]).concat([['Total','Seluruh hasil filter','','',...values(r.total),num(r.total.dealerCount)+' dealer unik']]))+pager(r.page,r.count,r.pageSize),'Tidak menampilkan SKU. Stok negatif atau data bermasalah perlu diperiksa sebelum restock.');
