function allowedTeamLevels(){if(tmIsMe())return [];
 const rank={SALES:1,ASM:2,RGM:3,ADMIN:3.5,'HEAD OF SALES':4,'CHIEF OPERATING OFFICER':5,'CHIEF COMMERCIAL OFFICER':5,'BOARD OF DIRECTOR':6,'SUPER ADMIN':7};
