}
function brandAnalysisVisible(){return BOOT?.user?.role!=='SALES';}
function closedAnalysisPanel(key,id,title,hint){return `<details class="panel foldPanel brandAnalysisFold" data-fold="${key}" id="${id}" ${collapsePrefs[key]===true?'open':''}><summary>${title}<small>${hint}</small></summary><div class="pb" id="${id}Body"><div class="empty">Buka panel untuk memuat data.</div></div></details>`;}
function cleanTeamRows(rows){
 return (Array.isArray(rows)?rows:[]).filter(p=>{
  const nik=String(p?.nik??'').trim(),nama=String(p?.nama??'').trim().toUpperCase();
  if(!nik)return false;
  if(['TOTAL','ALL','SELURUH'].includes(nik.toUpperCase()))return false;
  if(/^(TOTAL|SELURUH|ALL)(\b|$)/.test(nama))return false;
  return true;
 });
}
function cachedTeamRows(brand,level='SALES'){
