 if(!brandTeamCache.has(key))brandTeamCache.set(key,rpc('apiTeam',TOKEN,REPORT.period,level,brand,$('scopeSelect').value).then(cleanTeamRows).catch(err=>{brandTeamCache.delete(key);throw err;}));
