function teamPersonBig(p){const person=BOOT.people.find(x=>x.nik===p.nik);return person?.wilayah||p.big||p.region||'LAINNYA';}
function teamPersonSub(p){const person=BOOT.people.find(x=>x.nik===p.nik);return p.region||person?.region||person?.portfolio||'LAINNYA';}
