function metricConfig(metric){return ({ST:{label:'SELL THRU',cols:['Target / Aktual','%Achv','Growth']},DA:{label:'DEALER AKTIF',cols:['Target / Aktual','%Achv','Growth']},NOO:{label:'NOO',cols:['Target / Aktual','%Achv']},SO:{label:'SELL OUT',cols:['Aktual']},OMZET:{label:'OMZET',cols:['Aktual']}})[metric]||{label:'SELL THRU',cols:['Target / Aktual','%Achv','Growth']};}
