  result.innerHTML=(isMobile()?'<div id="v12indT"></div>':groupedTable([firstHead],groups,rows))+`<p class="hint">${esc(metric.label)} · ${levelNote} · ${regionNote} · ${subNote} · total dihitung dari data yang tampil.</p>`;
