function isTop(){return ['HEAD OF SALES','CHIEF OPERATING OFFICER','CHIEF COMMERCIAL OFFICER','BOARD OF DIRECTOR'].includes(BOOT?.user.role);}
function scopeOptions(){const ps=BOOT.people.filter(p=>p.nik!==BOOT.user.nik&&(isTop()?['RGM','ASM'].includes(p.role):['RGM','ASM','SALES'].includes(p.role))),groups={};ps.sort((a,b)=>(a.wilayah||'').localeCompare(b.wilayah||'')||({RGM:0,ASM:1,SALES:2}[a.role]-{RGM:0,ASM:1,SALES:2}[b.role])||(BOOT.people.find(p=>p.nik===a.atasan)?.nama||'').localeCompare(BOOT.people.find(p=>p.nik===b.atasan)?.nama||'')||a.nama.localeCompare(b.nama)).forEach(p=>{const boss=BOOT.people.find(b=>b.nik===p.atasan),key=(p.wilayah||'Lainnya')+' · '+p.role+(p.role!=='RGM'&&boss?' · '+boss.nama:'');(groups[key]||(groups[key]=[])).push(p);});return '<option value="ALL">Seluruh cakupan saya</option>'+Object.entries(groups).map(([name,items])=>`<optgroup label="${esc(name)}">${items.map(p=>`<option value="${esc(p.nik)}">${esc(p.nama)}</option>`).join('')}</optgroup>`).join('');}
