function brandTypeGroup(group,max,metric){const state=group.delta>0?'':group.delta<0?'dn':'flat',growth=group.growth==null?'basis 0':(group.delta>0?'+':'')+decimal(group.growth)+'%';return `<div class="brandTypeGroup"><div class="brandTypeBars"><div class="brandTypeBar" style="height:${Math.max(2,group.a/max*220)}px"><b>${analysisValue(metric,group.a)}</b></div><div class="brandTypeBar current" style="height:${Math.max(2,group.b/max*220)}px"><b>${analysisValue(metric,group.b)}</b><span class="brandTypeGrowth ${state}">${growth}</span></div></div><strong title="${esc(group.label)}">${esc(group.label)}</strong></div>`;}
function analysisChart(data,title){const values=data.groups.flatMap(g=>[g.a,g.b]),max=Math.max(1,...values),total=data.groups.find(g=>g.total),types=data.groups.filter(g=>!g.total),best=data.best,worst=data.worst,top=data.topContributor,totalGrowth=total?.growth==null?'basis 0':decimal(total.growth)+'%';return `<div class="weeklyAnalysisGrid"><div class="weeklyChartCard"><b>${esc(title)}</b><div class="brandTypeLegend"><span><i></i>${esc(data.periodA)}</span><span><i class="current"></i>${esc(data.periodB)}</span><span>Geser type ke samping</span></div><div class="brandTypeChart"><div class="brandTypeTotal">${total?brandTypeGroup(total,max,data.metric):''}</div><div class="brandTypeScroll"><div class="brandTypeTrack">${types.map(g=>brandTypeGroup(g,max,data.metric)).join('')||'<div class="empty">Belum ada data type pada filter ini.</div>'}</div></div></div></div><aside class="analysisSummary"><h4>Ringkasan perubahan</h4><p>Total brand tetap terlihat di kiri. Type dapat digeser untuk membandingkan nilai aktual dan perubahan.</p><span class="summaryStat"><small>Total brand</small><b>${total?(total.delta>=0?'+':'')+analysisValue(data.metric,total.delta)+' · '+totalGrowth:'—'}</b></span><span class="summaryStat"><small>Type tumbuh tertinggi</small><b>${best?esc(best.label)+' · '+(best.delta>=0?'+':'')+analysisValue(data.metric,best.delta):'—'}</b></span><span class="summaryStat"><small>Type turun terdalam</small><b>${worst?esc(worst.label)+' · '+(worst.delta>=0?'+':'')+analysisValue(data.metric,worst.delta):'—'}</b></span><span class="summaryStat"><small>Kontributor utama</small><b>${top?esc(top.label)+' · '+analysisValue(data.metric,top.b):'—'}</b></span><span class="summaryStat"><small>Cakupan analisa</small><b>${num(data.scopeCount)} Sales</b></span></aside></div>`;}
