function weeklyPanels(pair,brand){
 if(!pair?.available)return collapsible('stso','Rincian Mingguan per Type · ST/SO','<div class="info">Perbandingan menunggu data ST dan SO semua region pilihan. Pilih cakupan lebih kecil atau lengkapi data.</div>','Tabel detail brand terpilih', 'stTone');
 const sourceRows=pair.types.filter(t=>t.brand===brand),sourceWeeks=pair.weeks||[],weekGroups=[
  {label:'MINGGU 1',from:1,to:7,idx:[0]},
  {label:'MINGGU 2',from:8,to:14,idx:[1]},
  {label:'MINGGU 3',from:15,to:21,idx:[2]},
  {label:'MINGGU 4',from:22,to:28,idx:[3]},
  {label:'MINGGU 5',from:29,to:'akhir',idx:[4]}
 ];
 const n=v=>Number(v)||0,sum=a=>(a||[]).reduce((x,y)=>x+n(y),0),groupValue=(arr,g)=>g.idx.reduce((x,i)=>x+n(arr?.[i]),0),groupFuture=g=>{const ws=g.idx.map(i=>sourceWeeks[i]).filter(Boolean);return ws.length?ws.every(w=>w.future):true;};
 const rows=sourceRows.map(t=>{const stWeeks=weekGroups.map(g=>groupValue(t.st,g)),soWeeks=weekGroups.map(g=>groupValue(t.so,g));return {type:t.type,stWeeks,soWeeks,stTotal:sum(t.st),soTotal:sum(t.so)};});
 const totalST=rows.reduce((x,r)=>x+r.stTotal,0),totalSO=rows.reduce((x,r)=>x+r.soTotal,0),topST=rows.length?Math.max(...rows.map(r=>r.stTotal)):-1;
 const pctContribution=(value,total)=>total>0?pct(value/total*100):'—';
 const head=weekGroups.map(g=>`${g.label}<small class="cellsub">${g.from}–${g.to}</small>`);
 const weekValue=(values,i)=>{if(groupFuture(weekGroups[i]))return '—';const value=values[i];if(i===0)return num(value);const diff=value-values[i-1],state=diff>0?'up':diff<0?'dn':'flat',icon=diff>0?'▲':diff<0?'▼':'•';return `<span class="weekValue">${num(value)}<span class="weekTrend ${state}" title="${diff>0?'Naik':diff<0?'Turun':'Tetap'} dari minggu sebelumnya">${icon}</span></span>`;};
 const rowHtml=rows.map(r=>{const top=r.stTotal===topST&&topST>0;return `<tr class="${top?'topStRow':''}"><td><b>${esc(r.type)}</b>${top?'<span class="topStBadge">TOP ST</span>':''}</td>${r.stWeeks.map((v,i)=>`<td class="${i===0?'bandStart ':''}n">${weekValue(r.stWeeks,i)}</td>`).join('')}<td class="n ${top?'topStTotal':''}">${num(r.stTotal)}</td><td class="n contribCell">${pctContribution(r.stTotal,totalST)}</td>${r.soWeeks.map((v,i)=>`<td class="${i===0?'bandStart ':''}n">${weekValue(r.soWeeks,i)}</td>`).join('')}<td class="n">${num(r.soTotal)}</td><td class="n contribCell">${pctContribution(r.soTotal,totalSO)}</td></tr>`;}).join('');
 const stWeekTotals=weekGroups.map((g,i)=>rows.reduce((x,r)=>x+(groupFuture(g)?0:r.stWeeks[i]),0)),soWeekTotals=weekGroups.map((g,i)=>rows.reduce((x,r)=>x+(groupFuture(g)?0:r.soWeeks[i]),0));
 const totalRow=`<tr class="totalRow"><td>TOTAL</td>${stWeekTotals.map((v,i)=>`<td class="${i===0?'bandStart ':''}n">${weekValue(stWeekTotals,i)}</td>`).join('')}<td class="n">${num(totalST)}</td><td class="n contribCell">${totalST>0?'100,0%':'—'}</td>${soWeekTotals.map((v,i)=>`<td class="${i===0?'bandStart ':''}n">${weekValue(soWeekTotals,i)}</td>`).join('')}<td class="n">${num(totalSO)}</td><td class="n contribCell">${totalSO>0?'100,0%':'—'}</td></tr>`;
 const body=`<div class="typeMovement"><div class="table-scroll"><table class="stSoCombined"><thead><tr><th rowspan="2">TYPE</th><th class="stBand" colspan="7">SELL THRU</th><th class="soBand" colspan="7">SELL OUT</th></tr><tr>${head.map((h,i)=>`<th class="${i===0?'bandStart':''}">${h}</th>`).join('')}<th>TOTAL MTD</th><th>% KONTRIB.</th>${head.map((h,i)=>`<th class="${i===0?'bandStart':''}">${h}</th>`).join('')}<th>TOTAL MTD</th><th>% KONTRIB.</th></tr></thead><tbody>${rowHtml||'<tr><td colspan="15"><div class="empty">Tidak ada data type untuk brand ini.</div></td></tr>'}${rows.length?totalRow:''}</tbody></table></div></div><p class="hint">Minggu: 1–7 · 8–14 · 15–21 · 22–28 · 29–akhir bulan. Mulai Minggu 2, ikon ▲ ▼ • membandingkan nilai dengan minggu sebelumnya tanpa menampilkan persentase. ST dan SO dihitung terpisah.</p>`;
 return collapsible('stso','Rincian Mingguan per Type · ST/SO',body,esc(brand)+' · sejajar s.d. '+tgl(pair.cutoff),'stTone');
