function superAdminPanels(v,a,regionBoxes){const b=a.backup;v.insertAdjacentHTML('beforeend',panel('Master & kebijakan',`<button class="chip primary" id="v4PublishConfig">Publikasikan perubahan master / KPI</button><p class="hint">Bobot dan target tetap per bulan dan big region. Region_Map dapat ditambah untuk wilayah baru.</p>`)+panel('Autobackup',`<p class="${b.overdue?'adminNotice':''}">${b.running?'Backup sedang diproses. ':''}${b.last?'Backup lengkap terakhir: '+esc(b.last.WAKTU):'Belum ada backup lengkap.'}${b.overdue?' · Perlu diperiksa (lebih dari 36 jam / belum pernah).':''}</p><p>Proses terakhir: ${esc(b.lastEvent?.STATUS||'Belum dipasang')} ${esc(b.lastEvent?.KETERANGAN||'')}</p><p>Cadangan Admin 2: ${esc(b.secondary?.status||'Belum dihubungkan')}${b.secondary?.finished?' · '+esc(b.secondary.finished):''}</p><button class="chip primary" id="backupNow">Mulai backup sekarang</button><p class="hint">Pasang jadwal melalui menu DSM di spreadsheet terlebih dahulu. Proses berlanjut tiap 5 menit. Folder backup wajib privat.</p><div class="toolbar"><label>Simpan backup harian terakhir<input id="backupKeep" class="fi" type="number" min="2" max="60" value="${b.retention}"></label><label>ID file status Admin 2<input id="backupStatusId" class="fi" placeholder="Kosong jika belum dipasang"></label><button class="chip" id="backupSettings">Simpan pengaturan backup</button></div>`)+panel('Kunci periode',`<div class="toolbar"><input type="month" id="lockPeriod" class="fi" value="${REPORT.period}"><select id="lockValue" class="fi"><option value="true">Kunci</option><option value="false">Buka kunci</option></select><input id="lockReason" class="fi" placeholder="Alasan wajib"><button class="chip primary" id="lockSave">Simpan</button></div>`+table(['Periode','Terkunci','Alasan'],a.locks.map(r=>[esc(r.PERIODE),String(r.TERKUNCI),esc(r.ALASAN)])))+panel('Pemulihan regional',`<div class="info">Pulihkan satu jenis data pada bulan dan region pilihan. Region lain tetap. Semua pengguna perlu login ulang setelah pemulihan.</div><div class="toolbar"><label>Versi sumber<select class="fi" id="restoreVersion">${a.versions.map(r=>`<option value="${esc(r.SNAPSHOT)}">${esc(r.WAKTU+' · '+r.ALASAN)}</option>`).join('')}</select></label><select class="fi" id="restoreKind"><option>ST</option><option>SO</option></select><input class="fi" id="restorePeriod" type="month" value="${REPORT.period}"><input class="fi" id="restoreReason" placeholder="Alasan pemulihan"></div><div id="restoreRegions" class="regionChecks">${regionBoxes('rr')}</div><button class="chip" id="restoreCheck">Periksa pemulihan</button><div id="restorePreview"></div>`)+panel('Catatan kualitas data',a.notes.length?'<ul>'+a.notes.map(n=>'<li>'+esc(n)+'</li>').join('')+'</ul>':'Tidak ada catatan.'));
 $('v4PublishConfig').onclick=async e=>{e.target.disabled=true;try{await rpc('apiPublishConfig',TOKEN);await start();}catch(err){fail(err);e.target.disabled=false;}};$('backupNow').onclick=async e=>{e.target.disabled=true;try{await rpc('apiStartBackup',TOKEN);await render();}catch(err){fail(err);e.target.disabled=false;}};$('backupSettings').onclick=async()=>{try{await rpc('apiBackupSettings',TOKEN,$('backupKeep').value,$('backupStatusId').value.trim());render();}catch(err){fail(err);}};$('lockSave').onclick=async()=>{try{await rpc('apiPeriodLock',TOKEN,$('lockPeriod').value,$('lockValue').value==='true',$('lockReason').value);render();}catch(err){fail(err);}};$('restoreCheck').onclick=async()=>{try{const s=await rpc('apiStageRestore',TOKEN,$('restoreVersion').value,$('restoreKind').value,$('restorePeriod').value,[...$('restoreRegions').querySelectorAll(':checked')].map(x=>x.dataset.region),$('restoreReason').value);$('restorePreview').innerHTML=table(['Region','QTY sekarang','QTY dipulihkan','Cutoff sumber'],s.controls.map(c=>[esc(c.region),num(c.before.qty),num(c.incoming.qty),tgl(c.cutoff)]))+`<button class="chip primary" id="restoreCommit">Pulihkan bagian ini</button>`;$('restoreCommit').onclick=async e=>{if(!confirm('Pulihkan sesuai pratinjau? Pengguna perlu login ulang.'))return;e.target.disabled=true;try{await rpc('apiCommitRestore',TOKEN,s.id);logout(false);$('lerr').style.display='block';$('lerr').textContent='Pemulihan selesai. Silakan masuk kembali.';}catch(err){fail(err);e.target.disabled=false;}};}catch(err){fail(err);}};
}

async function resumeStoredSession(){const presentationFrame=window.frameElement?.dataset.dsmPresentation==='1';if(portalStorage.getItem('sp-demo-active')==='1'&&!presentationFrame){await rpc('apiStopDemo',TOKEN);portalStorage.removeItem('sp-demo-active');}return start();}
if(TOKEN)resumeStoredSession().catch(e=>{if(e.message.includes('PIN:'))showPin();else{logout(false);$('lerr').style.display='block';$('lerr').textContent=e.message;}});
function enhanceAdmin(v,a){
 const section=$('addUser').closest('.panel'),body=section.querySelector('.pb'),rows=[...section.querySelectorAll('tbody tr')].filter(tr=>tr.querySelector('[data-edit-user]'));
 body.insertAdjacentHTML('afterbegin',`<div class="toolbar accountFilters"><select class="fi" id="accountRegion"><option value="ALL">Semua region</option>${a.regions.map(r=>`<option>${esc(r)}</option>`).join('')}</select><select class="fi" id="accountRole"><option value="ALL">Semua posisi</option>${[...new Set(a.users.map(u=>u.role))].sort().map(r=>`<option>${esc(r)}</option>`).join('')}</select><input id="accountQuery" class="fi" placeholder="Cari nama / NIK"><button class="chip primary" id="accountSearch">Cari</button><button class="chip" id="accountReset">Reset</button></div>`);
 function search(){let count=0,active=0;rows.forEach(tr=>{const u=a.users[+tr.querySelector('[data-edit-user]').dataset.editUser],match=($('accountRegion').value==='ALL'||u.wilayah===$('accountRegion').value||u.adminRegions?.includes($('accountRegion').value))&&($('accountRole').value==='ALL'||u.role===$('accountRole').value)&&(u.nama+' '+u.nik).toLowerCase().includes($('accountQuery').value.trim().toLowerCase());tr.hidden=!match;if(match){count++;if(u.active)active++;}});section.querySelector('.totalRow').innerHTML=`<td>Total</td><td>${num(count)} user sesuai filter</td><td colspan="2">${num(active)} aktif</td>`;}
 $('accountSearch').onclick=search;$('accountRegion').onchange=search;$('accountRole').onchange=search;$('accountQuery').onkeydown=e=>{if(e.key==='Enter')search();};$('accountReset').onclick=()=>{$('accountRegion').value='ALL';$('accountRole').value='ALL';$('accountQuery').value='';search();};
 v.insertAdjacentHTML('beforeend',panel('Tambah dealer',`<p>Tambahkan dealer dan pilih Sales yang memeliharanya. Dealer baru tidak otomatis menjadi NOO.</p><div class="toolbar"><button class="chip primary" id="addDealer">Tambah satu dealer</button><button class="chip" id="dealerTemplate">Download template Excel</button></div><form id="dealerBulk"><input type="hidden" name="token" value="${esc(TOKEN)}"><div class="toolbar"><input type="file" name="file" class="fi" accept=".xlsx,.csv" required><button class="chip primary">Periksa upload dealer</button></div></form><p class="hint">Maksimal 500 dealer / 5 MB. Kode yang sudah ada ditolak. Seluruh baris harus valid sebelum disimpan.</p><div id="dealerPreview"></div>`));
 $('addDealer').onclick=()=>dealerEditor(a);$('dealerTemplate').onclick=async e=>{e.target.disabled=true;try{downloadBase64(await rpc('apiDealerTemplate',TOKEN));}catch(err){fail(err);}finally{e.target.disabled=false;}};
 $('dealerBulk').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;$('dealerPreview').textContent='Memeriksa dealer…';try{const r=await rpc('apiStageDealers',e.target);let page=0,size=100;$('dealerPreview')._sort=sort=>{sortObjects(r.rows,sort,[d=>d.id,d=>d.nama,d=>d.nik,d=>d.sales,d=>d.region]);page=0;draw();};function draw(){$('dealerPreview').innerHTML=table(['Kode','Dealer','NIK Sales','Sales','Region'],r.rows.slice(page*size,page*size+size).map(d=>[esc(d.id),esc(d.nama),esc(d.nik),esc(d.sales),esc(d.region)]))+`<div class="pager"><label>Tampilkan <select id="dealerPreviewSize">${pageSizeOptions(size)}</select></label><span>Total ${num(r.total)} dealer valid · halaman ${page+1}/${Math.max(1,Math.ceil(r.total/size))}</span><button class="chip" id="dealerPrev" ${page===0?'disabled':''}>Sebelumnya</button><button class="chip" id="dealerNext" ${(page+1)*size>=r.total?'disabled':''}>Selanjutnya</button><button class="chip primary" id="dealerCommit">Simpan ${num(r.total)} dealer</button></div>`;$('dealerPreviewSize').onchange=e=>{size=Number(e.target.value);page=0;draw();};$('dealerPrev').onclick=()=>{page--;draw();};$('dealerNext').onclick=()=>{page++;draw();};$('dealerCommit').onclick=async e=>{e.target.disabled=true;try{await rpc('apiCommitDealers',TOKEN,r.id);await refresh();}catch(err){fail(err);e.target.disabled=false;}};}draw();}catch(err){$('dealerPreview').textContent=err.message;}finally{btn.disabled=false;}};
}

function v6MasterDownloadPanel(v,a){const opts=[['PRODUCT','Master Product'],['TARGET','Target Bulanan per Sales'],['TARGET_KHUSUS','Target Khusus KPI'],['PROMOTOR','Master Promotor'],['GRADE','Master Grade'],['KPI','KPI Config'],['PRODUCT_RULES','Brand & Klasifikasi'],['REGION_MAP','Region Map'],['DOS','DOS Config'],['ORG','Struktur Organisasi / Master Sales']];v.insertAdjacentHTML('beforeend',panel('Download data master',`<p class="hint">Admin boleh download seluruh master sebagai working file berisi data existing. Edit/upload bulk master tetap khusus Super Admin.</p><div class="toolbar"><select class="fi" id="v6mdType">${opts.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</select><button class="chip" id="v6mdGo">Download data master</button></div>`));$('v6mdGo').onclick=async e=>{e.target.disabled=true;try{downloadBase64(await rpc('apiMasterBulkTemplate',TOKEN,$('v6mdType').value));}catch(err){fail(err);}finally{e.target.disabled=false;}};}
let V6PM=null;
function v6ProductPanel(v){v.insertAdjacentHTML('beforeend',panel('Master Product',`<p class="hint">Cari, edit klasifikasi, atau tambah beberapa SKU. KODE BARANG existing dikunci. Semua simpan wajib alasan dan akan checkpoint + publish.</p><div class="toolbar"><input class="fi" id="v6pmQ" placeholder="Cari kode / nama / brand / type"><button class="chip" id="v6pmLoad">Cari / Muat</button><button class="chip primary" id="v6pmAdd">+ Tambah produk</button></div><div id="v6pmBox"><p class="hint">Klik Muat untuk menampilkan produk.</p></div>`));$('v6pmLoad').onclick=()=>v6ProductLoad();$('v6pmQ').onkeydown=e=>{if(e.key==='Enter')v6ProductLoad();};$('v6pmAdd').onclick=()=>v6ProductEdit(null);}
async function v6ProductLoad(){const b=$('v6pmBox');if(!b)return;b.innerHTML='<p class="hint">Memuat…</p>';try{V6PM=await rpc('apiProductMasterGet',TOKEN,$('v6pmQ')?.value||'');b.innerHTML=`<p class="hint">${num(V6PM.total)} produk cocok. Klik Edit untuk melihat warning dampak sebelum save.</p>`+table(['Kode','Nama','Brand','Kategori','Type','Status',''],V6PM.rows.map((r,i)=>[esc(r.code),esc(r.name),esc(r.brand),esc(r.category),esc(r.type),esc(r.status),`<button class="chip" data-v6pmedit="${i}">Edit</button>`]));b.querySelectorAll('[data-v6pmedit]').forEach(x=>x.onclick=()=>v6ProductEdit(V6PM.rows[+x.dataset.v6pmedit]));}catch(err){b.innerHTML='<p class="v6rmErr">'+esc(err.message||err)+'</p>';}}
async function v6ProductEdit(r){if(!V6PM){try{V6PM=await rpc('apiProductMasterGet',TOKEN,'');}catch(e){fail(e);return;}}let impact={transactions:0,qty:0,kpi:[]};if(r){try{impact=await rpc('apiProductImpact',TOKEN,r.code);}catch(e){}}const isNew=!r,rules=(V6PM.rules||[]).filter(x=>x.active||r&&x.name===r.brand),brandOpts=rules.map(x=>`<option value="${esc(x.name)}" ${r&&x.name===r.brand?'selected':''}>${esc(x.name)} → ${esc(x.parent)} · ${esc(x.category)} · ${x.qty?'QTY DEVICE':'NON DEVICE'}</option>`).join(''),catList='<datalist id="v6pmCats">'+(V6PM.categories||[]).map(x=>`<option value="${esc(x)}">`).join('')+'</datalist>',typeList='<datalist id="v6pmTypes">'+(V6PM.types||[]).map(x=>`<option value="${esc(x)}">`).join('')+'</datalist>';modal(isNew?'Tambah produk':'Edit Master Product',`<form id="v6pmForm">${catList}${typeList}<div class="userForm"><label>KODE BARANG<input class="fi" name="code" value="${esc(r?.code||'')}" ${isNew?'':'readonly'} required></label><label>NAMA BARANG<input class="fi" name="name" value="${esc(r?.name||'')}" required></label><label>KLASIFIKASI<select class="fi" name="brand" id="v6pmBrand">${brandOpts}</select><small>Aturan Brand Induk/QTY diatur dari panel Brand & Klasifikasi.</small></label><label>KATEGORI PRODUK<input class="fi" list="v6pmCats" name="category" id="v6pmCategory" value="${esc(r?.category||'')}" required><small>Otomatis mengikuti klasifikasi saat dipilih; tetap bisa dikoreksi untuk pengecualian produk.</small></label><label>TYPE<input class="fi" list="v6pmTypes" name="type" value="${esc(r?.type||'')}" required></label><label>STATUS<select class="fi" name="status"><option ${!r||r.status==='ACTIVE'?'selected':''}>ACTIVE</option><option ${r?.status==='INACTIVE'?'selected':''}>INACTIVE</option></select></label></div>${r?`<div class="v6oldTpl"><b>Dampak histori:</b> ${num(impact.transactions)} baris transaksi · QTY ${num(impact.qty)}.${impact.kpi?.length?' Type ini dipakai KPI: '+impact.kpi.map(esc).join(', ')+'.':''}<br>Ubah KLASIFIKASI/KATEGORI dapat mengubah histori KPI/peringkat; ubah TYPE mengubah grouping Type/DOS.</div>`:''}<label>Alasan perubahan<input class="fi" id="v6pmReason" required placeholder="min. 5 karakter"></label><button class="chip primary">${isNew?'Tambah & publish':'Simpan & publish'}</button></form>`);const syncCat=()=>{const rule=rules.find(x=>x.name===$('v6pmBrand').value);if(rule)$('v6pmCategory').value=rule.category||$('v6pmCategory').value;};$('v6pmBrand').onchange=syncCat;if(isNew)syncCat();$('v6pmForm').onsubmit=async e=>{e.preventDefault();const f=e.target,reason=$('v6pmReason').value.trim();if(reason.length<5){fail(Error('Isi alasan minimal 5 karakter.'));return;}const x=Object.fromEntries(new FormData(f));x.originalCode=r?.code||x.code;if(r&&(x.brand!==r.brand||x.category!==r.category)&&!confirm('Perubahan KLASIFIKASI/KATEGORI dapat mengubah angka historis. Lanjutkan?'))return;const btn=f.querySelector('button');btn.disabled=true;try{await rpc('apiProductMasterSave',TOKEN,[x],reason);closeModal();await v6ProductLoad();}catch(err){fail(err);btn.disabled=false;}};}
let V6DBA=null;
function v6DealerBrandPanel(v,a){v.insertAdjacentHTML('beforeend',panel('PIC Dealer per Brand',`<p class="hint">Lokasi fisik dealer tetap mengikuti Master Customer. PIC dapat berbeda per brand dan lintas region. Pencapaian tetap mengikuti NIK transaksi; assignment ini menentukan tanggung jawab dealer per brand.</p><div id="v6dbaSetting"><span class="v6load">Memuat setting…</span></div><div class="toolbar"><input class="fi" id="v6dbaQ" placeholder="Cari kode / dealer / Sales" style="min-width:260px"><select class="fi" id="v6dbaBrand"><option value="ALL">Semua Brand</option></select><button class="chip primary" id="v6dbaLoad">Muat PIC</button><button class="chip" id="v6dbaSuggest">Review penjual dominan 3 bulan</button></div><div id="v6dbaBox"><p class="hint">Klik Muat PIC untuk melihat assignment. Review 3 bulan hanya saran, bukan warning health check.</p></div>`));
 const loadSetting=async()=>{try{V6DBA=await rpc('apiDealerBrandSettings',TOKEN);$('v6dbaBrand').innerHTML='<option value="ALL">Semua Brand</option>'+V6DBA.brands.map(b=>`<option>${esc(b)}</option>`).join('');$('v6dbaSetting').innerHTML=`<div class="v6oldTpl"><b>Cutover validasi:</b> ${esc(V6DBA.cutover)} · transaksi sebelum tanggal ini dianggap historical accepted dan tidak menjadi warning.${V6DBA.superuser?` <button class="chip" id="v6dbaCut">Ubah cutover</button>`:''}</div>`;if($('v6dbaCut'))$('v6dbaCut').onclick=()=>v6DealerBrandCutover();}catch(e){$('v6dbaSetting').innerHTML='<p class="v6rmErr">'+esc(e.message||e)+'</p>';}};
 $('v6dbaLoad').onclick=()=>v6DealerBrandLoad(a);$('v6dbaSuggest').onclick=()=>v6DealerBrandSuggest(a);$('v6dbaQ').onkeydown=e=>{if(e.key==='Enter')v6DealerBrandLoad(a);};loadSetting();}
async function v6DealerBrandLoad(a){const box=$('v6dbaBox');if(!box)return;box.innerHTML='<p class="v6load">Memuat PIC dealer per brand…</p>';try{const r=await rpc('apiDealerBrandList',TOKEN,$('v6dbaQ')?.value||'',$('v6dbaBrand')?.value||'ALL');box.innerHTML=`<p class="hint">Menampilkan maksimal 500 kombinasi. <b>Fallback Master Customer</b> berarti belum ada override khusus brand dan itu tetap valid.</p>`+table(['Dealer','Lokasi fisik','Brand','PIC Sales','Organisasi PIC','Sumber / efektif',''],r.rows.map((x,i)=>[esc(x.nama)+'<small class="cellsub">'+esc(x.dealer)+'</small>',esc(x.lokasi||'—'),esc(x.brand),esc([x.nik,x.sales].filter(Boolean).join(' — ')||'—'),esc([x.big,x.region].filter(Boolean).join(' · ')||'—'),x.source==='ASSIGNMENT'?'<b>Assignment</b><small class="cellsub">mulai '+esc(x.from||'—')+'</small>':'Fallback Master Customer',`<button class="chip" data-dbaedit="${i}">Set / Transfer PIC</button>`]));box.querySelectorAll('[data-dbaedit]').forEach(b=>b.onclick=()=>v6DealerBrandEdit(a,r.rows[+b.dataset.dbaedit]));}catch(e){box.innerHTML='<p class="v6rmErr">'+esc(e.message||e)+'</p>';}}
function v6DealerBrandEdit(a,r,suggest=null){const sales=(a.users||[]).filter(x=>x.sales),selected=suggest?.suggestNik||r.nik,opts=sales.map(x=>`<option value="${esc(x.nik)}" ${x.nik===selected?'selected':''}>${esc(x.nik)} — ${esc(x.nama)} · ${esc(x.wilayah||x.portfolio||x.region||'')}</option>`).join('');modal('Set / Transfer PIC Brand',`<form id="v6dbaForm"><div class="v6oldTpl"><b>${esc(r.dealer)} · ${esc(r.nama||'')}</b><br>Brand <b>${esc(r.brand)}</b> · lokasi fisik ${esc(r.lokasi||'—')}<br>PIC sekarang: <b>${esc([r.nik,r.sales||r.currentName].filter(Boolean).join(' — '))}</b></div><div class="userForm"><label>PIC Sales baru<select class="fi" name="nik" required>${opts}</select></label><label>Effective Date<input class="fi" name="from" type="date" value="${esc(suggest?.first||v6JktToday())}" required></label></div><label>Alasan<input class="fi" name="reason" placeholder="Contoh: ITEL dealer ini resmi di-handle Gross Nas" required></label><p class="hint">Mengubah PIC tidak memindahkan lokasi dealer dan tidak menulis ulang transaksi lama. Effective Date menentukan riwayat assignment.</p><button class="chip primary">Simpan PIC</button></form>`);$('v6dbaForm').onsubmit=async e=>{e.preventDefault();const f=e.target,x=Object.fromEntries(new FormData(f));if((x.reason||'').trim().length<5){fail(Error('Isi alasan minimal 5 karakter.'));return;}const b=f.querySelector('button');b.disabled=true;try{await rpc('apiDealerBrandSet',TOKEN,r.dealer,r.brand,x.nik,x.from,x.reason);closeModal();await refresh();}catch(err){fail(err);b.disabled=false;}};}
async function v6DealerBrandSuggest(a){const box=$('v6dbaBox');if(!box)return;box.innerHTML='<p class="v6load">Membandingkan PIC dengan penjual dominan 3 bulan terakhir…</p>';try{const r=await rpc('apiDealerBrandSuggestions',TOKEN,3);box.innerHTML=`<div class="v6oldTpl"><b>Review historis — bukan error.</b> Periode ${r.months.map(esc).join(', ')||'—'}. Data sebelum cutover tetap tidak masuk warning Health Check. Daftar ini hanya membantu menemukan case cross-region/brand yang perlu dikonfirmasi.</div>`+table(['Dealer','Brand','PIC sekarang','Penjual dominan','Porsi','Rentang transaksi',''],r.rows.map((x,i)=>[esc(x.nama)+'<small class="cellsub">'+esc(x.dealer)+' · lokasi '+esc(x.lokasi||'—')+'</small>',esc(x.brand),esc([x.currentNik,x.currentName].filter(Boolean).join(' — ')),esc([x.suggestNik,x.suggestName].filter(Boolean).join(' — ')),pct(x.share),esc((x.first||'—')+' s.d. '+(x.last||'—')),`<button class="chip" data-dbasug="${i}">Set PIC ini</button>`]));box.querySelectorAll('[data-dbasug]').forEach(b=>b.onclick=()=>{const x=r.rows[+b.dataset.dbasug];v6DealerBrandEdit(a,{dealer:x.dealer,nama:x.nama,lokasi:x.lokasi,brand:x.brand,nik:x.currentNik,sales:x.currentName},x);});if(!r.rows.length)box.innerHTML+='<div class="empty">Tidak ada perbedaan dominan pada 3 bulan terakhir.</div>';}catch(e){box.innerHTML='<p class="v6rmErr">'+esc(e.message||e)+'</p>';}}
function v6DealerBrandCutover(){const cur=V6DBA?.cutover||'2026-10-01';modal('Ubah Cutover Validasi PIC',`<form id="v6dbaCutForm"><p class="hint">Transaksi sebelum cutover dianggap historical accepted. Mengubah tanggal ini tidak menghapus atau memindahkan transaksi.</p><label>Tanggal cutover<input class="fi" name="date" type="date" value="${esc(cur)}" required></label><label>Alasan<input class="fi" name="reason" placeholder="Alasan perubahan cutover" required></label><button class="chip primary">Simpan cutover</button></form>`);$('v6dbaCutForm').onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if((x.reason||'').trim().length<5){fail(Error('Isi alasan minimal 5 karakter.'));return;}const b=e.target.querySelector('button');b.disabled=true;try{const r=await rpc('apiDealerBrandSetCutover',TOKEN,x.date,x.reason);V6DBA.cutover=r.cutover;closeModal();await refresh();}catch(err){fail(err);b.disabled=false;}};}

function bulkMaintenancePanels(v,a){
