function downloadBase64(file){const bytes=Uint8Array.from(atob(file.base64),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:file.mime})),a=document.createElement('a');a.href=url;a.download=file.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function dealerEditor(a){const fields=['KODE CUSTOMER','NAMA INDUK CUSTOMER','ID_DEALER','KOTA','ALAMAT','No. HP','SUB REGION'];modal('Tambah dealer',`<form id="newDealer"><div class="userForm">${fields.map((h,i)=>`<label>${esc(h)}<input class="fi" name="${esc(h)}" ${i<2?'required':''} maxlength="${i<2?150:500}"></label>`).join('')}<label>Dipantau oleh Sales<select class="fi" name="NIK SALES" required><option value="">Pilih Sales</option>${a.users.filter(u=>u.sales).map(u=>`<option value="${esc(u.nik)}">${esc(u.nama)} · ${esc(u.portfolio||u.region)}${u.role!=='SALES'?' · rangkap':''}</option>`).join('')}</select></label></div><p class="hint">Region mengikuti portofolio Sales. Kode customer adalah identitas dealer fisik, ID_DEALER alias opsional.</p><p id="dealerError" role="alert"></p><button class="chip primary">Simpan dealer</button></form>`);$('newDealer').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{await rpc('apiAddDealer',TOKEN,Object.fromEntries(new FormData(e.target)));closeModal();await refresh();}catch(err){if($('dealerError'))$('dealerError').textContent=err.message;else fail(err);}finally{btn.disabled=false;}};}
let historyFilter={from:'',to:'',brand:'ALL',displayBrands:[],indicators:['ST','SO','OMZET'],query:'',dateMode:'FULL',region:'ALL',subRegion:'ALL',order:'',noOrder:'',basis:'ST',orderBrands:[],noOrderBrands:[],prom:'ALL',grade:'ALL'},historyPage=0,historyPageSize=100,historyRequest=0,historySummaryLevel='BIG',historySummaryRequest=0;
function historyBrandChecks(name,selected){const chosen=new Set(selected||[]);return REPORT.brands.map(b=>b.brand).map(b=>`<label><input type="checkbox" name="${name}" value="${esc(b)}" ${chosen.has(b)?'checked':''}> <span>${esc(b)}</span></label>`).join('');}
function historyIndicatorChecks(selected){const chosen=new Set(selected?.length?selected:['ST','SO','OMZET']),items=[['ST','SELL THRU'],['SO','SELL OUT'],['OMZET','OMZET']];return items.map(x=>`<label><input type="checkbox" name="historyIndicator" value="${x[0]}" ${chosen.has(x[0])?'checked':''}> <span>${x[1]}</span></label>`).join('');}
function historyDisplayBrandsLabel(selected){return selected?.length?`${selected.length} brand dipilih`:'Semua brand';}
function historyIndicatorsLabel(selected){const list=selected?.length?selected:['ST','SO','OMZET'];return list.length===3?'Semua indikator':list.map(x=>x==='ST'?'SELL THRU':x==='SO'?'SELL OUT':'OMZET').join(', ');}
function readHistoryFilters(){const indicators=[...document.querySelectorAll('[name="historyIndicator"]:checked')].map(x=>x.value);return {prom:$('historyProm')?.value||'ALL',grade:$('historyGrade')?.value||'ALL',brand:'ALL',displayBrands:[...document.querySelectorAll('[name="historyDisplayBrand"]:checked')].map(x=>x.value),indicators:indicators.length?indicators:['ST','SO','OMZET'],from:$('historyFrom')?.value||historyFilter.from,to:$('historyTo')?.value||historyFilter.to,query:$('historyQuery')?.value||'',dateMode:$('historyDateMode')?.value||'FULL',region:$('historyRegion')?.value||'ALL',subRegion:$('historySubRegion')?.value||'ALL',order:$('historyOrder')?.value||'',noOrder:$('historyNoOrder')?.value||'',basis:'ST',orderBrands:[...document.querySelectorAll('[name="historyOrderBrand"]:checked')].map(x=>x.value),noOrderBrands:[...document.querySelectorAll('[name="historyNoOrderBrand"]:checked')].map(x=>x.value)};}
function syncHistoryBrandChoices(brands){const current=readHistoryFilters(),draw=(id,name,selected)=>{const el=$(id);if(el)el.innerHTML=brands.map(b=>`<label><input type="checkbox" name="${name}" value="${esc(b)}" ${selected.includes(b)?'checked':''}> <span>${esc(b)}</span></label>`).join('');};draw('historyDisplayBrands','historyDisplayBrand',current.displayBrands||[]);draw('historyOrderBrands','historyOrderBrand',current.orderBrands);draw('historyNoOrderBrands','historyNoOrderBrand',current.noOrderBrands);}

function historyModeLabel(mode){return ({FULL:'Semua tanggal',TODAY:'Today',MTD:'MTD'})[mode]||'Semua tanggal';}
function historyShortMonth(period){return period?new Date(period+'-01T00:00:00Z').toLocaleDateString('id-ID',{month:'short',year:'2-digit',timeZone:'UTC'}):'bulan lalu';}
function historyGrowthHtml(value,growth,kind,previousPeriod){const main=value==null?'—':kind==='OMZET'?rupiah(value):num(value);if(value==null)return main;const g=growth==null?'<small class="historyGrowth neutral">— vs '+esc(historyShortMonth(previousPeriod))+'</small>':`<small class="historyGrowth ${growth>0?'up':growth<0?'dn':'flat'}">${growth>0?'▲':growth<0?'▼':'•'} ${pct(Math.abs(growth))} vs ${esc(historyShortMonth(previousPeriod))}</small>`;return `<span class="historyTotalValue">${main}</span>${g}`;}
function historyRangeText(month,kind,mode){const from=month[kind+'From'],to=month[kind+'Cut'];if(!to)return 'Belum tersedia';if(mode==='TODAY')return 'tgl. '+tgl(to);if(mode==='MTD')return '1–'+Number(to.slice(8))+' '+new Date(to+'T00:00:00').toLocaleDateString('id-ID',{month:'short',year:'numeric'});return 's.d. '+tgl(to);}
function currentHistoryRegionOptions(){return dealerRegions(REPORT?.customers||[]);}
function currentHistorySubRegionOptions(region){return dealerSubRegions(REPORT?.customers||[],region);}
function historySummaryItems(filter){return [['Promotor',({YES:'Ber-promotor',NO:'Non promotor'})[filter.prom]||'ALL'],['Grade',filter.grade||'ALL'],['Mode',historyModeLabel(filter.dateMode)],['Indikator',historyIndicatorsLabel(filter.indicators)],['Brand',filter.displayBrands?.length?filter.displayBrands.join(', '):'ALL'],['Region',filter.region],['Sub Region',filter.subRegion],['Sudah order',filter.orderBrands?.length?filter.orderBrands.join(', '):'ALL'],['Belum order',filter.noOrderBrands?.length?filter.noOrderBrands.join(', '):'ALL'],['Dealer',filter.query]];}
