 const periods=BOOT.periods.slice().sort(),defaultFrom=periods[Math.max(0,periods.length-24)]||REPORT.period;if(!historyFilter.from)historyFilter.from=defaultFrom;if(!historyFilter.to)historyFilter.to=REPORT.period;
