 const brands=REPORT.deviceBrands||REPORT.brands.map(b=>b.brand),regions=currentHistoryRegionOptions(),subRegions=currentHistorySubRegionOptions(historyFilter.region),checked=(name,selected)=>{const chosen=new Set(selected||[]);return brands.map(b=>`<label><input type="checkbox" name="${name}" value="${esc(b)}" ${chosen.has(b)?'checked':''}> <span>${esc(b)}</span></label>`).join('');},shown=historyFilter.displayBrands||[];
