function historyBrandMatrix(r,indicators){
 const brands=r.displayBrands?.length?r.displayBrands:(r.filters.displayBrands?.length?r.filters.displayBrands:r.brands),metricMeta={ST:{label:'SELL THRU',key:'st',total:'totalST',kind:'st',fmt:num,klass:'metricST'},SO:{label:'SELL OUT',key:'so',total:'totalSO',kind:'so',fmt:num,klass:'metricSO'},OMZET:{label:'OMZET',key:'omzet',total:'totalOmzet',kind:'st',fmt:rupiah,klass:'metricOMZET'}},months=r.months;
 const escAttr=v=>esc(v).replace(/"/g,'&quot;');const hc=v6HCols(),hmap=[0,1,2],th=(t,cls)=>`<th rowspan="3" class="${cls}">${t}</th>`;let row1='<tr>'+th('Kode','hxk')+th('Nama Dealer','hxn')+th('Big Region','hxb');V6HOPT.forEach(k=>{if(!hc.includes(k))return;const slot={sub:3,sales:4,asm:5,rgm:6,grade:7,prom:8}[k];hmap.push(slot);const lbl=k==='grade'?(r.promBrand?'Kategori '+esc(r.promBrand):'Kategori'):V6HLBL[k];row1+=th(lbl,'hxo'+(k==='prom'||k==='grade'?' v6hpcol':''));});let row2='<tr>',row3='<tr>';
 brands.forEach((brand,bi)=>{row1+=`<th class="historyBrandBand v6b${bi%8} ${bi?'brandDivider':''}" colspan="${indicators.length*(months.length+1)}">${esc(brand)}</th>`;indicators.forEach((ind,ii)=>{const m=metricMeta[ind];row2+=`<th class="historyMetricBand ${m.klass} ${(bi||ii)?'metricDivider':''}" colspan="${months.length+1}">${m.label}</th>`;months.forEach((month,mi)=>row3+=`<th class="historyMonthHead ${m.klass} ${mi===0?'metricDivider':''}">${esc(new Date(month.period+'-01T00:00:00Z').toLocaleDateString('id-ID',{month:'short',year:'2-digit',timeZone:'UTC'}))}<small class="cellsub">${esc(historyRangeText(month,m.kind,r.filters.dateMode))}</small></th>`);row3+=`<th class="historyBrandTotal ${m.klass}">TOTAL ${ind==='ST'?'ST':ind==='SO'?'SO':'OMZET'}</th>`;});});row1+='</tr>';row2+='</tr>';row3+='</tr>';
 const body=r.rows.map(c=>{let cells=`<td class="hxk">${esc(c.id)}</td><td class="hxn"><button class="textlink" data-customer="${escAttr(c.id)}">${esc(c.nama)}</button>${v6TutupTag(c.id)}</td><td class="hxb">${esc(c.region||'—')}</td>`;hc.forEach(k=>{cells+=k==='sub'?`<td class="hxo">${esc(c.subregion||'—')}</td>`:k==='sales'?`<td class="hxo">${esc(c.sales||'—')}</td>`:k==='asm'?`<td class="hxo">${esc(c.asm||'—')}</td>`:k==='rgm'?`<td class="hxo">${esc(c.rgm||'—')}</td>`:k==='grade'?`<td class="hxo v6hpcell">${v6HistGradeCell(c,r.promBrand)}</td>`:`<td class="hxo v6hpcell">${v6PromCell(c,r.promBrand||'ALL')}</td>`;});brands.forEach((brand,bi)=>indicators.forEach((ind,ii)=>{const m=metricMeta[ind],bm=c.brandMetrics?.[brand]||{},vals=bm[m.key]||months.map(()=>null);vals.forEach((v,mi)=>{const off=v6ClosedAfter(c.id,months[mi]?.period);cells+=`<td class="${mi===0?'metricDivider':''}${off?' v6hoff':''}">${off&&!v?'tutup':v==null?'—':m.fmt(v)}</td>`;});const total=bm[m.total];cells+=`<td class="historyBrandTotal ${m.klass}">${total==null?'—':m.fmt(total)}</td>`;}));return `<tr>${cells}</tr>`;}).join('');
 let totalCells='<td class="hxk">Total</td><td class="hxn"></td><td class="hxb"></td>';hc.forEach(k=>{totalCells+=k==='prom'?'<td class="hxo">'+num(r.promCompare?.yes?.count||0)+' ber-promotor</td>':'<td class="hxo"></td>';});brands.forEach(brand=>indicators.forEach(ind=>{const m=metricMeta[ind],bt=r.totals.byBrand?.[brand]||{},vals=bt[m.key]||months.map(()=>null),growth=bt.growth?.[m.key]||[];vals.forEach((v,i)=>totalCells+=`<td class="${i===0?'metricDivider':''}">${historyGrowthHtml(v,growth[i],ind==='OMZET'?'OMZET':m.label,months[i].previousPeriod)}</td>`);const total=bt[m.total];totalCells+=`<td class="historyBrandTotal ${m.klass}">${total==null?'—':m.fmt(total)}</td>`;}));
 return `<div class="table-scroll"><table class="historyBrandMatrix" data-hid="${hmap.join(',')}"><thead>${row1}${row2}${row3}</thead><tbody>${body}<tr class="totalRow">${totalCells}</tr></tbody></table></div>`;
}
function historySummaryMatrix(r){
 const indicators=r.indicators?.length?r.indicators:['ST','SO','OMZET'],brands=r.displayBrands||[],metricMeta={ST:{label:'SELL THRU',key:'st',total:'totalST',kind:'st',fmt:num,klass:'metricST'},SO:{label:'SELL OUT',key:'so',total:'totalSO',kind:'so',fmt:num,klass:'metricSO'},OMZET:{label:'OMZET',key:'omzet',total:'totalOmzet',kind:'st',fmt:rupiah,klass:'metricOMZET'}},months=r.months||[],hasContext=r.level!=='BIG',levelLabel={BIG:'BIG REGION',REGION:'REGION',ASM:'ASM',SALES:'SALES'}[r.level]||'RINGKASAN',contextLabel={REGION:'BIG REGION',ASM:'BIG REGION',SALES:'ASM / REGION'}[r.level]||'';
 let row1=`<tr><th rowspan="3" class="summaryName">${levelLabel}</th>${hasContext?`<th rowspan="3" class="summaryContext">${contextLabel}</th>`:''}<th rowspan="3" class="summaryDealerCount">JUMLAH DEALER</th>`,row2='<tr>',row3='<tr>';
 brands.forEach((brand,bi)=>{row1+=`<th class="historyBrandBand v6b${bi%8} ${bi?'brandDivider':''}" colspan="${indicators.length*(months.length+1)}">${esc(brand)}</th>`;indicators.forEach((ind,ii)=>{const m=metricMeta[ind];row2+=`<th class="historyMetricBand ${m.klass} ${(bi||ii)?'metricDivider':''}" colspan="${months.length+1}">${m.label}</th>`;months.forEach((month,mi)=>row3+=`<th class="historyMonthHead ${m.klass} ${mi===0?'metricDivider':''}">${esc(new Date(month.period+'-01T00:00:00Z').toLocaleDateString('id-ID',{month:'short',year:'2-digit',timeZone:'UTC'}))}<small class="cellsub">${esc(historyRangeText(month,m.kind,r.filters.dateMode))}</small></th>`);row3+=`<th class="historyBrandTotal ${m.klass}">TOTAL ${ind==='ST'?'ST':ind==='SO'?'SO':'OMZET'}</th>`;});});row1+='</tr>';row2+='</tr>';row3+='</tr>';
 const body=(r.rows||[]).map(x=>{let cells=`<td class="summaryName">${esc(x.label||'—')}</td>${hasContext?`<td class="summaryContext">${esc(x.context||'—')}</td>`:''}<td class="summaryDealerCount">${num(x.dealerCount||0)}</td>`;brands.forEach(brand=>indicators.forEach(ind=>{const m=metricMeta[ind],bt=x.byBrand?.[brand]||{},vals=bt[m.key]||months.map(()=>null);vals.forEach((v,i)=>cells+=`<td class="${i===0?'metricDivider':''}">${v==null?'—':m.fmt(v)}</td>`);const total=bt[m.total];cells+=`<td class="historyBrandTotal ${m.klass}">${total==null?'—':m.fmt(total)}</td>`;}));return `<tr>${cells}</tr>`;}).join('');
 let totalCells=`<td class="summaryName">Total</td>${hasContext?'<td class="summaryContext"></td>':''}<td class="summaryDealerCount">${num(r.total?.dealerCount||0)}</td>`;brands.forEach(brand=>indicators.forEach(ind=>{const m=metricMeta[ind],bt=r.total?.byBrand?.[brand]||{},vals=bt[m.key]||months.map(()=>null),growth=bt.growth?.[m.key]||[];vals.forEach((v,i)=>totalCells+=`<td class="${i===0?'metricDivider':''}">${historyGrowthHtml(v,growth[i],ind==='OMZET'?'OMZET':m.label,months[i].previousPeriod)}</td>`);const total=bt[m.total];totalCells+=`<td class="historyBrandTotal ${m.klass}">${total==null?'—':m.fmt(total)}</td>`;}));
 return `<div class="table-scroll"><table class="historyBrandMatrix historySummaryMatrix ${hasContext?'summaryThreeCols':'summaryTwoCols'}"><thead>${row1}${row2}${row3}</thead><tbody>${body||`<tr><td colspan="${(hasContext?3:2)+brands.length*indicators.length*(months.length+1)}">Tidak ada data summary.</td></tr>`}<tr class="totalRow">${totalCells}</tr></tbody></table></div>`;
}
async function loadHistorySummary(){if(typeof isMobile==='function'&&isMobile())return;
 const panel=$('historySummaryPanel'),target=$('historySummaryRows'),meta=$('historySummaryMeta');if(!panel?.open||!target)return;const request=++historySummaryRequest,seq=SEQUENCE,token=TOKEN,level=$('historySummaryLevel')?.value||historySummaryLevel;historySummaryLevel=level;target.innerHTML='<div class="empty v6load">Memuat summary seluruh hasil filter…</div>';if(meta)meta.textContent='Menghitung seluruh dealer sesuai filter aktif…';
 try{const payload={order:historyFilter.order,noOrder:historyFilter.noOrder,basis:historyFilter.basis,dateMode:historyFilter.dateMode,region:historyFilter.region,subRegion:historyFilter.subRegion,displayBrands:historyFilter.displayBrands||[],indicators:historyFilter.indicators||['ST','SO','OMZET'],orderBrands:historyFilter.orderBrands,noOrderBrands:historyFilter.noOrderBrands,prom:historyFilter.prom,grade:historyFilter.grade},r=await rpc('apiDealerHistorySummary',token,$('scopeSelect').value,'ALL',historyFilter.from,historyFilter.to,historyFilter.query,payload,level);if(request!==historySummaryRequest||seq!==SEQUENCE||token!==TOKEN||!target.isConnected||!panel.open)return;target.innerHTML=historySummaryMatrix(r);if(meta)meta.innerHTML=`<b>${num(r.rows.length)} ${esc(({BIG:'Big Region',REGION:'Region',ASM:'ASM',SALES:'Sales'})[r.level]||'grup')}</b> · ${num(r.totalDealers)} dealer unik · seluruh hasil filter, bukan halaman aktif · klik header untuk mengurutkan`;addTopTableScroll(target);enableTableSorting();}
 catch(e){if(request===historySummaryRequest&&target.isConnected)target.innerHTML='<div class="filterEmpty"><b>Summary tidak dapat dimuat.</b><span>'+esc(e.message)+'</span></div>';}
}
async function loadDealerHistory(){
 const request=++historyRequest,seq=SEQUENCE,token=TOKEN,el=$('dealerHistoryRows');if(!el)return;el.innerHTML='<span class="v6load">Memuat histori…</span>';
 try{
  const payload={order:historyFilter.order,noOrder:historyFilter.noOrder,basis:historyFilter.basis,dateMode:historyFilter.dateMode,region:historyFilter.region,subRegion:historyFilter.subRegion,displayBrands:historyFilter.displayBrands||[],indicators:historyFilter.indicators||['ST','SO','OMZET'],orderBrands:historyFilter.orderBrands,noOrderBrands:historyFilter.noOrderBrands,prom:historyFilter.prom,grade:historyFilter.grade,sort:historySort,pageSize:historyPageSize},r=await rpc('apiDealerHistory',token,$('scopeSelect').value,'ALL',historyFilter.from,historyFilter.to,historyPage,historyFilter.query,payload);
  if(request!==historyRequest||seq!==SEQUENCE||token!==TOKEN||!el.isConnected)return;historyPage=r.page;V6HLAST=r;
  const indicators=r.filters.indicators?.length?r.filters.indicators:['ST','SO','OMZET'];
  const mr=r.missingRegions||{},mrTxt=[['ST',mr.ST],['SO',mr.SO]].filter(x=>x[1]&&x[1].length).map(x=>'<b>'+x[0]+'</b>: '+esc(x[1].join(', '))).join(' · ');el.innerHTML=(mrTxt?'<div class="historyTableNote" style="background:#fff7e0;border-color:#f1d28a;color:#6b4a00">⚠ <b>Sementara</b> — angka belum termasuk region yang datanya belum ada di sebagian bulan. '+mrTxt+'</div>':'')+'<div class="historyTableNote">Setiap brand ditampilkan terpisah. SELL THRU dan OMZET mengikuti cutoff ST; SELL OUT mengikuti cutoff SO. Mode '+esc(historyModeLabel(r.filters.dateMode))+' diterapkan konsisten ke seluruh bulan.</div>'+historyBrandMatrix(r,indicators)+`<div class="pager"><label>Tampilkan <select id="historyPageSize">${pageSizeOptions(r.pageSize)}</select></label><span>${r.total?historyPage*r.pageSize+1:0}–${Math.min((historyPage+1)*r.pageSize,r.total)} dari ${num(r.total)} dealer · total seluruh hasil</span><button class="chip" id="historyPrev" ${historyPage===0?'disabled':''}>Sebelumnya</button><button class="chip" id="historyNext" ${(historyPage+1)*r.pageSize>=r.total?'disabled':''}>Selanjutnya</button></div>`;
  addTopTableScroll(el);el.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>detail(b.dataset.customer));$('historyPrev').onclick=()=>{historyPage--;loadDealerHistory();};$('historyNext').onclick=()=>{historyPage++;loadDealerHistory();};$('historyPageSize').onchange=e=>{historyPageSize=Number(e.target.value);historyPage=0;loadDealerHistory();};
  syncHistoryBrandChoices(r.brands);v6HistGradeSync(r);{let box=$('v6hpcBox');if(!box){box=document.createElement('div');box.id='v6hpcBox';el.after(box);}box.innerHTML=v6HistPromCompare(r);}
  if($('historyFilterSummary'))$('historyFilterSummary').innerHTML=filterSummaryHtml(historySummaryItems({...historyFilter,...r.filters}),r.total,'dealer');
  if($('historyModeInfo')){const last=r.months[r.months.length-1],st=last?historyRangeText(last,'st',r.filters.dateMode):'—',so=last?historyRangeText(last,'so',r.filters.dateMode):'—';$('historyModeInfo').innerHTML=`<b>${esc(historyModeLabel(r.filters.dateMode))}</b><span>ST & Omzet: ${esc(st)} · SO: ${esc(so)}</span>`;}
 }catch(e){if(request===historyRequest&&seq===SEQUENCE&&token===TOKEN&&el.isConnected)el.innerHTML='<div class="filterEmpty"><b>Histori tidak dapat dimuat.</b><span>'+esc(e.message)+'</span></div>';}
}
/* Sort data columns; grouped titles are labels, action-only columns stay buttons. */
let customerSort=null,brandSort=null,historySort=null,trxSort=null,detailSort=null,dosSort=null;
const tableSortPrefs=new Map();
function compareValues(a,b,dir){if(a==null||a==='')return b==null||b===''?0:1;if(b==null||b==='')return -1;return (dir==='desc'?-1:1)*(typeof a==='number'&&typeof b==='number'?a-b:String(a).localeCompare(String(b),'id',{numeric:true,sensitivity:'base'}));}
function sortObjects(rows,sort,getters){if(sort&&getters[sort.column])rows.sort((a,b)=>compareValues(getters[sort.column](a),getters[sort.column](b),sort.dir));return rows;}
function cellValue(cell,heading){const copy=cell.cloneNode(true);copy.querySelectorAll('small,.cellsub').forEach(e=>e.remove());let text=copy.textContent.trim();if(!text||['—','-','Belum lengkap','Tidak dijumlahkan'].includes(text))return null;
 if(/tanggal|terakhir order|lengkap sampai|waktu|dibuat/i.test(heading)){const months={jan:0,feb:1,mar:2,apr:3,mei:4,jun:5,jul:6,agu:7,agt:7,sep:8,okt:9,nov:10,des:11},m=text.toLowerCase().match(/(\d{1,2})\s+(\w+)\s+(\d{4})/);if(m&&months[m[2].slice(0,3)]!=null)return Date.UTC(+m[3],months[m[2].slice(0,3)],+m[1]);if(/^\d{4}-\d\d/.test(text))return text;}
 if(/nama|dealer$|^dealer |^brand$|^type$|region|wilayah|sales|jabatan|posisi|nik|nomor|^kode|status|kondisi|indikator|kelompok kpi|alasan/i.test(heading)&&!/jumlah|total|unik|menipis|aktif|produktif/i.test(heading))return text;
 if(/growth/i.test(heading)){const match=text.match(/(-?[\d.,]+)\s*%/);if(match){const g=Number(match[1].replace(/\./g,'').replace(',','.'));return copy.querySelector('.v7delta .dlt.dn')?-Math.abs(g):g;}}
 if(/target\s*\/\s*aktual/i.test(heading)){const actual=copy.querySelector('b,strong');if(actual)text=actual.textContent.trim();}
 const match=text.replace(/^Rp\s*/i,'').match(/^([+-]?[\d.,]+)(?:\s*(?:%|hari|unit|dealer|user|peserta|baris|aktif|$))/i);if(match){const n=Number(match[1].replace(/\./g,'').replace(',','.'));if(Number.isFinite(n))return n;}return text;
}
function sortDomTable(table,column,dir,heading){const body=table.tBodies[0];if(!body)return;const rows=[...body.rows],fixed=rows.filter(r=>r.classList.contains('totalRow')||r.cells[0]?.textContent.trim()==='Total'),data=rows.filter(r=>!fixed.includes(r));data.sort((a,b)=>compareValues(a.cells[column]?cellValue(a.cells[column],heading):null,b.cells[column]?cellValue(b.cells[column],heading):null,dir));body.append(...data,...fixed);}
function routeTableSort(table,sort){
 if(table.closest('#customerRows,#customerTableRows')){customerSort=sort;customerPage=0;$('customerRows')._redraw?.();return true;}
 if(table.closest('[data-fold="dealers"]')){brandSort=sort;brandDealerPage=0;render();return true;}
 if(table.closest('#dealerHistoryRows')){{const ids=(table.dataset.hid||'').split(',').filter(Boolean).map(Number);if(ids.length)sort={...sort,column:sort.column<ids.length?ids[sort.column]:9+(sort.column-ids.length)};}historySort=sort;historyPage=0;loadDealerHistory();return true;}
 if(!isMobile()&&table.closest('#transactionRows')){trxSort=sort;transactionPage=0;render();return true;}
 if(table.closest('#detailTransactions')){detailSort={...sort,column:sort.column>=2?sort.column+1:sort.column};$('detailTransactions')._reload?.(0);return true;}
 const title=table.closest('.panel')?.querySelector('h3')?.textContent.trim();if(PAGE==='dos'&&['Dealer + TYPE','Dealer + Brand'].includes(title)){dosSort=sort;dosPage=0;render();return true;}
 if(table.closest('#dealerPreview')&&$('dealerPreview')._sort){$('dealerPreview')._sort(sort);return true;}
 return false;
}
function enableTableSorting(){document.querySelectorAll('#app table,#mbody table').forEach(table=>{if(table.dataset.sortReady||!table.tHead||!table.tBodies.length)return;table.dataset.sortReady='1';const grid=[],leaves=[],totalBands=[];[...table.tHead.rows].forEach((row,ri)=>{grid[ri]=grid[ri]||[];let col=0;[...row.cells].forEach(th=>{while(grid[ri][col])col++;const start=col;for(let y=ri;y<ri+th.rowSpan;y++){grid[y]=grid[y]||[];for(let x=start;x<start+th.colSpan;x++)grid[y][x]=true;}if(/total/i.test(th.textContent))totalBands.push({th,column:start,label:th.textContent.trim(),span:th.colSpan});if(th.colSpan===1)leaves.push({th,column:start,label:th.textContent.trim()});col+=th.colSpan;});});
 totalBands.forEach(({th,column,label,span})=>{if(/total/i.test(label)){const tone=/\bSO\b|sell out/i.test(label)?'totalSO':/\bST\b|sell.?thru/i.test(label)?'totalST':'totalGeneric';th.classList.add(tone);[...table.tBodies[0].rows].forEach(r=>Array.from({length:span},(_,i)=>r.cells[column+i]?.classList.add(tone)));}});
 const title=table.closest('.panel,.kgroup')?.querySelector('h3,summary')?.textContent.trim()||'',key=PAGE+'|'+(table.closest('#mbody')?'modal|':'')+title+'|'+leaves.map(x=>x.label).join('|'),stored=tableSortPrefs.get(key);let saved=stored,remote=false;if(table.closest('#customerRows,#customerTableRows')){saved=customerSort;remote=true;}else if(table.closest('[data-fold=dealers]')){saved=brandSort;remote=true;}else if(table.closest('#dealerHistoryRows')){saved=historySort;remote=true;}else if(!isMobile()&&table.closest('#transactionRows')){saved=trxSort;remote=true;}else if(table.closest('#detailTransactions')){saved=detailSort?{...detailSort,column:detailSort.column>=3?detailSort.column-1:detailSort.column}:null;remote=true;}else if(PAGE==='dos'&&['Dealer + TYPE','Dealer + Brand'].includes(title)){saved=dosSort;remote=true;}if(remote){if(saved)tableSortPrefs.set(key,saved);else tableSortPrefs.delete(key);}table._sortKey=key;
 leaves.forEach(({th,column,label})=>{if(/tindakan|aksi/i.test(label))return;th.classList.add('sortableHeader');th.tabIndex=0;th.setAttribute('aria-sort',saved?.column===column?(saved.dir==='asc'?'ascending':'descending'):'none');th.title='Klik untuk mengurutkan '+label;const activate=()=>{const old=tableSortPrefs.get(key),sort={column,dir:old?.column===column&&old.dir==='asc'?'desc':'asc'};tableSortPrefs.set(key,sort);if(routeTableSort(table,sort))return;leaves.forEach(x=>x.th.setAttribute('aria-sort',x.column===column?(sort.dir==='asc'?'ascending':'descending'):'none'));sortDomTable(table,column,sort.dir,label);};th.onclick=activate;th.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate();}};});
