function openMobileMore(){closeMobileMore();const m=document.createElement('section');m.id='mobileMore';m.className='mmDrawer';m.setAttribute('aria-label','Semua menu');m.dataset.previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';const pages=[...$('navigation').querySelectorAll('[data-page]')].map(b=>b.dataset.page).filter(k=>k!=='beranda'&&titles[k]);const has=k=>pages.includes(k);const defs=[['pantau','Pantau','#1F7FC2','#E3EEFA',['customer','brand','tim','dos','tmactivity','tmfu','tmorder']],['analisa','Analisa','#6D3FD8','#EEE8FB',['ai','analisa','kpi','peringkat','transaksi']],['lain','Lainnya','#6B7A8C','#EAEEF3',[]]];const used=new Set();defs.forEach(d=>{d[4]=d[4].filter(k=>{if(!has(k)||used.has(k)||(k==='tmfu'&&has('tmactivity')))return false;used.add(k);return true;});});defs[2][4]=pages.filter(k=>!used.has(k)&&!(k==='tmfu'&&has('tmactivity')));const demo=BOOT?.demo||{},pinDisabled=demo.active?' disabled':'';const demoBtn=demo.active?'<button class="mmBtn" data-more-account="demo">'+menuIcon('demo')+'<span>Kembali Super Admin</span></button>':demo.canStart?'<button class="mmBtn" data-more-account="demo">'+menuIcon('demo')+'<span>Demo</span></button>':'';const nm=String(BOOT.user.nama||'');const ini=(nm.trim()[0]||'D').toUpperCase();m.innerHTML='<div class="mmDim"></div><aside class="mmPanel"><div class="mmMe"><span class="mmAv">'+esc(ini)+'</span><div><b>'+esc(nm)+'</b><small>'+esc(BOOT.user.role||'')+'</small></div></div>'+defs.filter(d=>d[4].length).map(d=>'<div class="mmGrp" style="--a:'+d[2]+';--p:'+d[3]+'"><div class="mmGl">'+d[1].toUpperCase()+'</div><div class="mmGrid">'+d[4].map(k=>'<button class="mmIt'+(PAGE===k||(k==='tmactivity'&&PAGE==='tmfu')?' on':'')+'" data-more-page="'+k+'"><span class="mmIc">'+menuIcon(k)+'</span><span class="mmTx">'+esc(({tmactivity:'Telemarketing',tmfu:'Telemarketing',tmorder:'Form Order',perangkat:'Perangkat'})[k]||titles[k])+'</span></button>').join('')+'</div></div>').join('')+'<div class="mmOut">'+demoBtn+'<button class="mmBtn" data-more-account="pin"'+pinDisabled+'>'+menuIcon('pin')+'<span>Kunci PIN</span></button><button class="mmBtn" data-more-account="logout">'+menuIcon('logout')+'<span>Keluar</span></button></div></aside>';$('app').append(m);requestAnimationFrame(()=>m.classList.add('on'));m.querySelector('.mmDim').onclick=()=>{closeMobileMore();syncMobileNav();};m.onclick=e=>{const b=e.target.closest('[data-more-page]');if(b){navigateTo(b.dataset.morePage);return;}const a=e.target.closest('[data-more-account]');if(!a||a.disabled)return;const act=a.dataset.moreAccount;closeMobileMore();if(act==='demo'){if(BOOT?.demo?.active)stopDemoMode();else openDemoChooser();return;}if(act==='pin'){showPin();return;}if(act==='logout'){logout();return;}};document.querySelectorAll('#mBottom button').forEach(b=>b.classList.toggle('on',b.dataset.mobilePage==='more'));}
