function bulkUserPanel(v,a){v.insertAdjacentHTML('beforeend',panel('Tambah user massal',`<p>XLSX/CSV, maksimal 100 user / 5 MB. NIK yang sudah terdaftar dilewati. Atasan boleh ada dalam file yang sama.</p><button id="userTemplate" class="chip">Download template Excel</button><form id="bulkUsers"><input type="hidden" name="token" value="${esc(TOKEN)}"><input class="fi" type="file" name="file" accept=".xlsx,.csv" required><button class="chip primary" type="submit">Periksa user</button></form><div id="userBulkPreview"></div>`));$('userTemplate').onclick=async()=>{try{downloadBase64(await rpc('apiUserTemplate',TOKEN));}catch(e){fail(e);}};$('bulkUsers').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;$('userBulkPreview').innerHTML='<p class="hint">Memeriksa file… (file .xlsx bisa 10–30 detik)</p>';try{const r=await rpc('apiStageUsers',e.target);$('userBulkPreview').innerHTML=v6UserRejHtml(r)+table(['NIK','Nama','Posisi','Region','Status'],r.rows.map(x=>[esc(x.nik),esc(x.nama),esc(x.role),esc(x.region),esc(x.status)]))+(r.rows.some(x=>/baru/i.test(x.status))?'<button class="chip primary" id="commitUsers">Buat user sesuai pratinjau</button>':'<p class="hint">Tidak ada user baru untuk dibuat.</p>');if($('v6urRej'))$('v6urRej').onclick=async x=>{x.target.disabled=true;try{downloadBase64(await rpc('apiUsersRejected',TOKEN,r.id));}catch(err){fail(err);}finally{x.target.disabled=false;}};$('commitUsers').onclick=async e=>{e.target.disabled=true;try{const result=await rpc('apiCommitUsers',TOKEN,r.id);modal('Hasil pembuatan user',`<p>${result.created} dibuat · ${result.skipped} dilewati.</p><p>PIN sementara tampil pada hasil ini. Sampaikan pribadi; user wajib mengganti saat masuk.</p>`+table(['NIK','Nama','Posisi','Region','PIN sementara'],result.rows.map(x=>[esc(x.nik),esc(x.nama),esc(x.role),esc(x.region),esc(x.pin)]))+(result.download&&result.rows.length?'<button class="chip primary" id="downloadUserPins">Unduh hasil & PIN sementara</button>':''));if($('downloadUserPins'))$('downloadUserPins').onclick=()=>downloadCsv('User-Baru-PIN-Sementara.csv',[['NIK','Nama','Posisi','Region','PIN sementara'],...result.rows.map(x=>[x.nik,x.nama,x.role,x.region,x.pin])]);$('userBulkPreview').textContent='Selesai. Perbarui tampilan untuk melihat akun baru.';}catch(err){fail(err);e.target.disabled=false;}};}catch(err){$('userBulkPreview').innerHTML='<p style="color:#b91c1c;font-weight:700">Gagal: '+esc(err.message||err)+'</p>';fail(err);}finally{b.disabled=false;}};}


async function v12Hist(other,id,selection,period,n,isCur){
 const c=(REPORT.customers||[]).find(x=>x.id===id),ob=((c&&c.brands)||[]).filter(b=>b.qty>0).map(b=>b.brand),brands=ob.length?ob:(REPORT.brands||[]).map(b=>b.brand);
 let brand='ALL',rng=6,cache={};
 const ym=(p,d)=>{const[y,m]=p.split('-').map(Number),t=y*12+m-1+d;return Math.floor(t/12)+'-'+String(t%12+1).padStart(2,'0')};
 other.innerHTML='<div class="v12h"><div class="v12hch" id="v12hb"></div><div class="v12hch" id="v12hr"></div><div id="v12hc"></div></div>';
 const css=document.createElement('style');css.textContent='.v12h{display:grid;gap:10px}.v12hch{display:flex;gap:6px;overflow-x:auto;padding-bottom:2px}.v12hch button{border:1px solid #cfe0f5;background:#fff;border-radius:999px;padding:6px 12px;font-weight:700;font-size:12px;white-space:nowrap;color:#1e4f9c}.v12hch button.on{background:linear-gradient(135deg,#1e6fd9,#2f8ff0);color:#fff;border-color:transparent}.v12hs{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.v12hs div{background:#f4f8fe;border-radius:12px;padding:8px;text-align:center}.v12hs b{display:block;font-size:17px}.v12hs small{color:#667}.v12ht{width:100%;border-collapse:collapse;font-size:13px}.v12ht th,.v12ht td{padding:7px 6px;text-align:right;border-bottom:1px solid #edf1f7}.v12ht th:first-child,.v12ht td:first-child{text-align:left}.v12ht tr.tot td{font-weight:800;background:#f4f8fe}.v12up{color:#16a34a}.v12dn{color:#dc2626}';other.append(css);
 const draw=async()=>{
  const box=$('v12hc');box.innerHTML='<span class="v6load">Memuat…</span>';
  $('v12hb').innerHTML=['ALL'].concat(brands).map(b=>`<button class="${b===brand?'on':''}" data-b="${esc(b)}">${b==='ALL'?'Semua':esc(b)}</button>`).join('');
  $('v12hr').hidden=true;
  try{
   if(!cache[brand])cache[brand]=await rpc('apiDealerHistory',TOKEN,selection,brand,ym(period,-23),period,0,'',{customer:id});
   if(n()||!box.isConnected)return;
   const r=cache[brand],row=r.rows[0],ms=r.months.map((m,j)=>({p:m.period||m.month,st:m.stCut&&row?+row.st[j]||0:null,so:m.soCut&&row?+row.so[j]||0:null})).slice(-rng);
   const sum=k=>ms.reduce((a,m)=>a+(m[k]||0),0),ratio=sum('so')?Math.round(sum('st')/sum('so')*100)+'%':'—';
   const W=330,H=120,mx=Math.max(1,...ms.map(m=>Math.max(m.st||0,m.so||0))),X=i=>12+i*(W-24)/Math.max(1,ms.length-1),Y=v=>H-14-v/mx*(H-30);
   const line=(k,col)=>{const pts=ms.map((m,i)=>m[k]==null?null:X(i)+','+Y(m[k])).filter(Boolean);return pts.length?`<polyline fill="none" stroke="${col}" stroke-width="2.5" points="${pts.join(' ')}"/>`:''};
   const lab=ms.map((m,i)=> `<text x="${X(i)}" y="${H+10}" font-size="9.5" font-weight="700" text-anchor="middle" fill="#889">${esc(['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'][+String(m.p).slice(5,7)-1]||'')} ${esc(String(m.p).slice(2,4))}</text>`).join('');
   const arrow=(m,i)=>{const pv=i?ms[i-1].st:null;if(m.st==null||pv==null||m.st===pv)return'';return m.st>pv?' <span class="v12up">▲</span>':' <span class="v12dn">▼</span>'};
   box.innerHTML=`<div class="v12hs"><div><b style="color:#1e6fd9">${num(sum('st'))}</b><small>ST total</small></div><div><b style="color:#f08a00">${num(sum('so'))}</b><small>SO total</small></div><div><b>${ratio}</b><small>ST ÷ SO</small></div></div><svg viewBox="0 0 ${W} ${H+14}" width="100%">${line('st','#1e6fd9')}${line('so','#f08a00')}${lab}</svg><table class="v12ht"><thead><tr><th>Bulan</th><th style="color:#1e6fd9">ST</th><th style="color:#f08a00">SO</th></tr></thead><tbody>${ms.slice().reverse().map((m,i,a)=>{const idx=ms.length-1-i;return`<tr><td>${esc(m.p)}</td><td>${m.st==null?'—':num(m.st)+arrow(m,idx)}</td><td>${m.so==null?'—':num(m.so)}</td></tr>`}).join('')}<tr class="tot"><td>Total</td><td>${num(sum('st'))}</td><td>${num(sum('so'))}</td></tr></tbody></table><p class="hint">ST dan SO mengikuti cutoff masing-masing. — berarti belum lengkap.</p>`;
  }catch(e){box.textContent=e.message}
 };
 other.onclick=e=>{const b=e.target.closest('[data-b]'),r=e.target.closest('[data-r]');if(b){brand=b.dataset.b;draw()}else if(r){rng=+r.dataset.r;draw()}};
 await draw();
}
function dealerTabs(id,period,selection){const body=$('mbody'),summary=document.createElement('div');summary.id='dealerSummary';while(body.firstChild)summary.append(body.firstChild);const transactions=summary.querySelector('#detailTransactions');body.append(summary);if(transactions)body.append(transactions);const contact=summary.querySelector('#contactPanel');if(contact){body.append(contact);contact.hidden=true;}const other=document.createElement('div');other.id='dealerTabExtra';other.hidden=true;body.append(other);const tabs=document.createElement('div');tabs.className='toolbar dealerTabs';tabs.setAttribute('role','tablist');tabs.innerHTML=['Ringkasan','Histori ST/SO','Stok','Transaksi','Kontak'].map((x,i)=>`<button role="tab" aria-selected="${i===0}" class="chip modalTab ${i===0?'active':''}" data-dtab="${i}">${menuIcon(['beranda','kpi','dos','transaksi','contact'][i])}<span>${x}</span></button>`).join('');body.prepend(tabs);if(transactions)transactions.hidden=true;let request=0;tabs.onclick=async e=>{const selected=e.target.closest('[data-dtab]'),i=selected?.dataset.dtab;if(i==null)return;tabs.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b===selected);b.setAttribute('aria-selected',String(b===selected));});const n=++request;summary.hidden=i!=='0';if(contact)contact.hidden=i!=='4';if(transactions)transactions.hidden=i!=='3';other.hidden=!['1','2'].includes(i);if(other.hidden)return;other.innerHTML='<p class="v6load">Memuat data…</p>';try{if(i==='1'&&isMobile()){await v12Hist(other,id,selection,period,()=>n!==request);return;}if(i==='1'){other.innerHTML=`<div class="toolbar"><label>Dari bulan<input class="fi" id="dHistoryFrom" type="month" value="${period.slice(0,4)}-01"></label><label>Sampai<input class="fi" id="dHistoryTo" type="month" value="${period}"></label><select class="fi" id="dHistoryBrand"><option value="ALL">Semua brand</option>${REPORT.brands.map(b=>`<option>${esc(b.brand)}</option>`).join('')}</select><button class="chip" id="dHistoryLoad">Tampilkan</button></div><div id="dHistoryRows"></div>`;const load=async()=>{const target=$('dHistoryRows');target.innerHTML='<span class="v6load">Memuat…</span>';try{const r=await rpc('apiDealerHistory',TOKEN,selection,$('dHistoryBrand').value,$('dHistoryFrom').value,$('dHistoryTo').value,0,'',{customer:id});if(n!==request||!target.isConnected)return;const row=r.rows[0];target.innerHTML=table(['Bulan','ST','SO'],r.months.map((m,j)=>[esc(m.period||m.month),m.stCut?(row?soNum(row.st[j]):'0'):'—',m.soCut?(row?soNum(row.so[j]):'0'):'—']).concat([['Total',row?soNum(row.totalST):'0',row?soNum(row.totalSO):'0']]))+'<p class="hint">ST dan SO mengikuti cutoff masing-masing. — berarti belum lengkap.</p>';}catch(err){target.textContent=err.message;}};$('dHistoryLoad').onclick=load;await load();}else{const r=await rpc('apiDealerStock',TOKEN,period,selection,id);if(n!==request||!other.isConnected)return;other.innerHTML=r.ready?'<p>ST '+tgl(r.stCut)+' · SO '+tgl(r.soCut)+' · Posisi '+tgl(r.asof)+'</p>'+table(['Brand','TYPE','Est. stok','SO 30 hari','DOS','Status'],r.rows.map(t=>[esc(t.brand),esc(t.type),num(t.stock),num(t.sellout),t.dos==null?'—':decimal(t.dos),esc(t.status)]).concat([['Total','',num(r.rows.reduce((n,t)=>n+t.stock,0)),num(r.rows.reduce((n,t)=>n+t.sellout,0)),'—','']])):esc(r.message||'Data belum tersedia.');}}catch(err){other.innerHTML='<p>'+esc(err.message)+'</p><button class="chip" id="dealerTabRetry">Coba lagi</button>';$('dealerTabRetry').onclick=()=>selected.click();}};}
const mobileViewport=window.matchMedia('(max-width:760px)');
function isMobile(){return mobileViewport.matches;}
async function contactPanel(id){const target=$('contactPanel');if(!target)return;target.innerHTML='<span class="v6load">Memuat kontak…</span>';try{const r=await rpc('apiDealerContact',TOKEN,id);if(!target.isConnected)return;const labels={PENDING:'Menunggu persetujuan',APPROVED:'Disetujui',REJECTED:'Ditolak'};target.innerHTML=(isMobile()?'<h3>Kontak & alamat</h3><p>'+esc(r.values.alamat||'Alamat belum diisi')+'</p>'+contactLinks(r.values.hp):'')+'<p><b>PIC:</b> '+esc(r.values.pic||'—')+'</p>'+(r.canSubmit?'<button class="chip" id="contactEdit">Ajukan perubahan kontak</button>':'')+(r.canEdit?'<button class="chip primary" id="contactAdminEdit">✎ Edit kontak & alamat</button>':'')+r.requests.map(x=>'<details class="contactHistory"><summary>'+esc(labels[x.status])+' · '+esc(x.created.slice(0,10))+'</summary><p>'+esc(x.reason)+'</p>'+contactDiff(x)+(x.reviewReason?'<p>Catatan Admin: '+esc(x.reviewReason)+'</p>':'')+'</details>').join('');if($('contactEdit'))$('contactEdit').onclick=()=>contactForm(id,r);if($('contactAdminEdit'))$('contactAdminEdit').onclick=()=>adminContactForm(id,r);}catch(e){target.textContent=e.message;}}
function contactDiff(r){return '<div class="contactDiff">'+['pic','hp','alamat'].map((k,i)=>'<div class="'+(r.before[k]!==r.after[k]?'changed':'')+'"><b>'+['Nama PIC','Nomor HP','Alamat'][i]+'</b><div><span><small>Sebelum</small>'+esc(r.before[k]||'—')+'</span><span><small>Usulan</small>'+esc(r.after[k]||'—')+'</span></div></div>').join('')+'</div>';}
function contactForm(id,r){if(r.requests.some(x=>x.status==='PENDING')){fail(Error('Masih ada pengajuan menunggu persetujuan.'));return;}modal('Ajukan perubahan kontak',`<form id="contactForm"><label>Nama PIC<input class="fi" name="pic" maxlength="120" required value="${esc(r.values.pic)}"></label><label>Nomor HP<input class="fi" name="hp" type="tel" required value="${esc(r.values.hp)}"></label><label>Alamat<textarea class="fi" name="alamat" maxlength="1000" required>${esc(r.values.alamat)}</textarea></label><label>Alasan (koreksi / pindah lokasi / ganti kontak)<textarea class="fi" name="reason" minlength="5" maxlength="500" required></textarea></label><p>Data lama tetap berlaku sampai disetujui Admin. Perubahan alamat tidak memindahkan region atau Sales.</p><p id="contactError" role="alert"></p><button class="chip primary">Kirim pengajuan</button></form>`);if(tmIsMe()&&$('contactForm')?.elements.pic){$('contactForm').elements.pic.readOnly=true;$('contactForm').elements.pic.required=false;}$('contactForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await rpc('apiSubmitDealerContact',TOKEN,{...Object.fromEntries(new FormData(e.target)),dealer:id,before:r.values});modal('Pengajuan terkirim','<p>Menunggu persetujuan Admin. Status bisa dilihat kembali di detail dealer.</p>');}catch(err){$('contactError').textContent=err.message;b.disabled=false;}};}
function approvalPanel(v){v.insertAdjacentHTML('beforeend',panel('Approval Data Dealer','<div class="toolbar"><select class="fi" id="contactStatus"><option value="PENDING">Menunggu</option><option value="ALL">Semua / Riwayat</option><option value="APPROVED">Disetujui</option><option value="REJECTED">Ditolak</option></select><button class="chip" id="contactReload">Perbarui pengajuan</button></div><div id="contactRequests"></div>'));$('contactStatus').onchange=loadContactRequests;$('contactReload').onclick=loadContactRequests;loadContactRequests();}
async function loadContactRequests(){const target=$('contactRequests');if(!target)return;target.innerHTML='<span class="v6load">Memuat pengajuan…</span>';try{const rows=await rpc('apiContactRequests',TOKEN,$('contactStatus').value);if(!target.isConnected)return;target.innerHTML='<div class="toolbar"><button class="chip" id="contactSelectAll">Pilih semua yang dapat disetujui</button><button class="chip primary" id="contactApproveMany">Setujui terpilih</button><button class="chip" id="contactRejectMany">Tolak terpilih</button></div><p>'+rows.length+' pengajuan sesuai filter</p>'+rows.map(r=>`<article class="contactRequest"><label>${r.status==='PENDING'?`<input type="checkbox" class="contactCheck" data-stale="${r.stale}" value="${esc(r.id)}">`:''}<b>${esc(r.nama)} · ${esc(r.dealer)}</b></label><p>${esc(r.actorName)} · ${esc(r.region)} · ${esc(r.created)} · ${esc(r.status)}</p><p>Alasan: ${esc(r.reason)}</p>${r.stale?'<p class="adminNotice">Perlu dicek ulang: data atau pemegang dealer berubah. Tolak dengan catatan agar Sales mengajukan ulang.</p>':''}${contactDiff(r)}${r.status==='PENDING'?`<div class="toolbar"><button class="chip primary" data-contact-approve="${esc(r.id)}" ${r.stale?'disabled':''}>Setujui</button><button class="chip" data-contact-reject="${esc(r.id)}">Tolak</button></div>`:`<p>Diproses ${esc(r.reviewer)} · ${esc(r.reviewed)} · ${esc(r.reviewReason||'')}</p>`}</article>`).join('');const selected=()=>[...target.querySelectorAll('.contactCheck:checked')].map(x=>x.value);$('contactSelectAll').onclick=()=>target.querySelectorAll('.contactCheck').forEach(c=>c.checked=c.dataset.stale!=='true');$('contactApproveMany').onclick=()=>reviewContacts(selected(),'APPROVED');$('contactRejectMany').onclick=()=>reviewContacts(selected(),'REJECTED');target.querySelectorAll('[data-contact-approve]').forEach(b=>b.onclick=()=>reviewContacts([b.dataset.contactApprove],'APPROVED'));target.querySelectorAll('[data-contact-reject]').forEach(b=>b.onclick=()=>reviewContacts([b.dataset.contactReject],'REJECTED'));}catch(e){target.textContent=e.message;}}
async function reviewContacts(ids,decision){if(!ids.length){fail(Error('Centang pengajuan dahulu.'));return;}let reason='';if(decision==='REJECTED'){reason=prompt('Alasan penolakan (minimal 5 karakter):');if(reason===null)return;}else if(!confirm('Setujui '+ids.length+' pengajuan? Kontak dealer akan diperbarui.'))return;const buttons=[...$('contactRequests').querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await rpc('apiReviewDealerContacts',TOKEN,ids,decision,reason);await refresh();}catch(e){fail(e);await loadContactRequests();}}
async function mobileTransactions(seq){const el=$('transactionRows');try{const r=await rpc('apiTransactionGroups',TOKEN,REPORT.period,$('scopeSelect').value,transactionPage,trxDates.from,trxDates.to,trxGroupSort,transactionPageSize);if(seq!==SEQUENCE)return;transactionPage=r.page;el.innerHTML=r.rows.map((g,i)=>`<button class="mobileTransaction" data-trx-popup="${i}"><b>${tgl(g.date)} · ${esc(g.nama)}</b><span>›</span><small>${esc(g.customer)} · ${num(g.qty)} unit</small></button>`).join('')+table(['Total hasil filter','QTY','Omzet'],[['Total',num(r.totals.qty),rupiah(r.totals.amount)]])+pager(r.page,r.total,r.pageSize);el.querySelectorAll('[data-trx-popup]').forEach(b=>b.onclick=()=>{const g=r.rows[+b.dataset.trxPopup];modal(tgl(g.date)+' · '+g.nama,transactionTable(g.rows,false,{qty:g.qty,amount:g.amount}));});bindPager(()=>{transactionPage--;render();},()=>{transactionPage++;render();},size=>{transactionPageSize=size;transactionPage=0;render();});}catch(e){if(seq===SEQUENCE)el.innerHTML='<p>'+esc(e.message)+'</p><button class="chip" onclick="render()">Coba lagi</button>';}}

function mobileDealerCard(c){return `<article class="mobileCard dealerMobileCard"><div class="toolbar">${customerButton(c)}${(()=>{const x=v6BsSummary(c);return x?`<span class="bsb bs-${x[0]}">${esc(x[1])}</span>`:'';})()}${c.promotor?v6PromCell(c,customerFilter.brand):''}</div><small class="mobileDealerArea">PIC: ${esc(dealerOwnerText(c,customerFilter.brand,'bigRegion'))} · ${esc(dealerOwnerText(c,customerFilter.brand,'subRegion'))}</small><div class="mobilePair"><div>SELL THRU<b>${num(c.current.qty)}</b></div><div>SELL OUT<b>${soNum(c.current.sellout)}</b></div><div>Omzet<b>${moneyCard(c.current.omzet)}</b></div></div>${Object.keys(c.bs||{}).length?`<div class="mobileBs">${(REPORT.brands||[]).filter(b=>c.bs[b.brand]).map(b=>`<div class="bs-box bs-b-${c.bs[b.brand]}"><small>${esc(b.brand)}</small><b>${num(v6Qty(c,b.brand))}</b><span class="bsb bs-${c.bs[b.brand]}">${V6BSL[c.bs[b.brand]]||c.bs[b.brand]}</span></div>`).join('')}</div>`:''}<small>Terakhir order ${tgl(c.last)}</small><button class="chip dealerDetailBtn" data-customer="${esc(c.id)}">Lihat detail →</button></article>`;}
function mobileRankCards(rows){return rows.map(p=>`<article class="mobileCard ${p.top?'rankTop':p.bottom?'rankBottom':''}"><div class="toolbar"><span class="rankNumber ${p.top?'rankGold':p.bottom?'rankRose':''}">${v6Medal(p.rank)}</span>${p.canOpen?`<button class="textlink" data-rank-person="${esc(p.nik)}">${esc(p.nama)} →</button>`:esc(p.nama)}${p.achieved?'<span class="rankTag rankGreen">≥90%</span>':''}</div><small>${esc(p.region)} · ${esc(p.status)}</small><div class="mobilePair">${(p.groupScores||[]).map(g=>`<div>${esc(g.name)}<b>${pct(g.score)}</b></div>`).join('')}<div>KPI Akhir<b>${pct(p.score)}</b></div></div></article>`).join('');}


mobileViewport.addEventListener('change',()=>{closeMobileMore();if(!REPORT)return;/* v7: HP diputar ke landscape saat layar penuh → jangan render ulang (bikin layar penuh tertutup sendiri); tunda sampai keluar layar penuh */if(document.fullscreenElement){window.__v7RenderLater=true;return;}customerPage=0;transactionPage=0;historyPage=0;render();});
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&window.__v7RenderLater){window.__v7RenderLater=false;setTimeout(()=>{if(REPORT){customerPage=0;transactionPage=0;historyPage=0;render();}},250);}});
function adminContactForm(id,r){modal('Edit kontak dealer',`<form id="adminContactForm" class="contactAdminForm"><label>Nama PIC<input class="fi" name="pic" maxlength="120" value="${esc(r.values.pic)}"></label><label>Nomor HP<input class="fi" name="hp" type="tel" value="${esc(r.values.hp)}"></label><label>Alamat<textarea class="fi" name="alamat" maxlength="1000">${esc(r.values.alamat)}</textarea></label><label>Alasan perubahan<textarea class="fi" name="reason" minlength="5" maxlength="500" required></textarea></label><p>Disimpan langsung sesuai kewenangan Admin. Kolom kosong mempertahankan data lama. Pengajuan Sales yang bertabrakan perlu diperiksa ulang.</p><p id="adminContactError" role="alert"></p><button class="chip primary">Simpan perubahan</button></form>`);$('adminContactForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await rpc('apiSaveDealerContact',TOKEN,{...Object.fromEntries(new FormData(e.target)),dealer:id,revision:r.revision});await refresh();modal('Kontak diperbarui','<p>Alamat dan kontak terbaru sudah tersimpan. Riwayat tersedia di detail dealer dan Approval Data Dealer.</p>');}catch(err){$('adminContactError').textContent=err.message;b.disabled=false;}};}
function contactBulkPanel(v){v.insertAdjacentHTML('beforeend',panel('Update kontak dealer massal · Super Admin',`<p>Export data terbaru, edit PIC / nomor HP / alamat, lalu upload kembali. Cocokkan melalui kode dealer; nama dealer, region, dan Sales tidak diubah. Kolom kosong mempertahankan nilai lama. Dealer di luar file tetap utuh.</p>${canExportDealer()?'<button class="chip" id="exportContactMaster">Unduh data kontak Excel</button>':''}<form id="contactBulkForm"><input type="hidden" name="token" value="${esc(TOKEN)}"><p><input class="fi" type="file" name="file" accept=".xlsx,.csv" required></p><p>Maksimal 500 dealer / 5 MB. Jangan ubah kode atau VERSI KONTAK. Pilih maksimal 500 baris dari hasil export.</p><button class="chip primary">Periksa perubahan</button></form><div id="contactBulkResult" role="status"></div>`));if($('exportContactMaster'))$('exportContactMaster').onclick=async e=>{e.target.disabled=true;try{const r=await rpc('apiExportDealerContacts',TOKEN);downloadContactXlsx([r.headers,...r.rows]);}catch(err){fail(err);}finally{e.target.disabled=false;}};$('contactBulkForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button'),target=$('contactBulkResult');b.disabled=true;target.textContent='Memeriksa data…';try{const r=await rpc('apiStageContactBulk',e.target);if(!target.isConnected)return;target.innerHTML='<p><b>'+r.changed+' dealer berubah</b> · '+(r.total-r.changed)+' tanpa perubahan.</p><div class="contactBulkPreview">'+r.rows.filter(x=>x.changed).map(x=>'<details><summary>'+esc(x.nama)+' · '+esc(x.dealer)+' · '+esc(x.region)+'</summary>'+contactDiff(x)+'</details>').join('')+'</div>'+(r.changed?'<label>Alasan update<textarea class="fi" id="contactBulkReason" minlength="5" maxlength="500" placeholder="Contoh: pemutakhiran kontak September"></textarea></label><p><button class="chip primary" id="commitContactBulk">Simpan '+r.changed+' perubahan</button></p>':'<p>Tidak ada kontak yang perlu diperbarui.</p>')+'<p id="contactBulkError" role="alert"></p>';if($('commitContactBulk'))$('commitContactBulk').onclick=async e=>{const reason=$('contactBulkReason').value.trim();if(reason.length<5){$('contactBulkError').textContent='Isi alasan minimal 5 karakter.';return;}if(!confirm('Ganti kontak '+r.changed+' dealer sesuai pratinjau?'))return;e.target.disabled=true;try{const x=await rpc('apiCommitContactBulk',TOKEN,r.id,reason);target.innerHTML='<p><b>Selesai: '+x.updated+' dealer diperbarui.</b> '+x.unchanged+' tanpa perubahan.</p>';await loadContactRequests();}catch(err){$('contactBulkError').textContent=err.message;e.target.disabled=false;}};}catch(err){target.textContent=err.message;}finally{b.disabled=false;}};}
function openDealerExport(){
 const periods=BOOT.periods.filter(p=>p<=REPORT.period).sort(),endIndex=periods.indexOf(REPORT.period),from=periods[Math.max(0,endIndex-2)]||REPORT.period,selected=customerFilter.brand==='ALL'?[]:[customerFilter.brand],brandChecks=(REPORT.deviceBrands||REPORT.brands.map(b=>b.brand)).map(b=>`<label><input type="checkbox" name="dealerExportBrand" value="${esc(b)}" ${selected.includes(b)?'checked':''}> <span>${esc(b)}</span></label>`).join('');
 modal('Export Daftar Dealer',`<form id="dealerExportForm"><div class="userForm"><label>Bulan awal<input class="fi" name="from" type="month" value="${from}" required></label><label>Bulan akhir<input class="fi" name="to" type="month" value="${REPORT.period}" required></label></div><fieldset><legend>Brand yang ditampilkan</legend><div class="regionChecks">${brandChecks}</div><p class="hint">Kosongkan pilihan untuk menampilkan seluruh brand. Total hanya menjumlahkan brand yang tampil.</p></fieldset><p>Filter daftar dealer yang ikut diterapkan: pencarian, Region, Sub Region, status dealer, status order, brand, dan kota. Status dealer dibaca pada bulan akhir; ST, SO, dan omzet dijumlahkan sepanjang rentang.</p><p class="hint">Dealer tetap satu baris. Jika dilayani beberapa Sales, seluruh nama Sales dan ASM terkait akan ditampilkan.</p><p id="dealerExportStatus" role="status"></p><button class="chip primary">Export Excel</button></form>`);
 $('dealerExportForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button'),form=new FormData(e.target),brands=form.getAll('dealerExportBrand');button.disabled=true;$('dealerExportStatus').textContent='Menyiapkan seluruh data dealer…';try{const r=await rpc('apiExportDealerExcel',TOKEN,$('scopeSelect').value,form.get('from'),form.get('to'),{...customerFilter,brands},customerSort);downloadDealerExcelXlsx(r);$('dealerExportStatus').textContent=num(r.rows.length)+' dealer berhasil disiapkan.';}catch(err){$('dealerExportStatus').textContent=err.message;}finally{button.disabled=false;}};
}
function downloadDealerExcelXlsx(data){
 const xml=v=>String(v??'').replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'),col=n=>{let s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26);}return s;},schema='http:&#47;&#47;schemas.openxmlformats.org/'.replace(/&#47;/g,'/'),periodLabel=p=>new Date(p+'-01T00:00:00Z').toLocaleDateString('id-ID',{month:'long',year:'numeric',timeZone:'UTC'}),cells=[],identity=['KODE INDUK CUSTOMER','NAMA INDUK CUSTOMER','KOTA','ASM','SALES','REGION','SUB REGION','STATUS DEALER','TERAKHIR ORDER'];
 const cell=(row,column,value,style,text)=>{const ref=col(column)+row;if(value==null||value==='')cells.push({row,xml:'<c r="'+ref+'" s="'+style+'" t="inlineStr"><is><t>-</t></is></c>'});else if(!text&&typeof value==='number'&&Number.isFinite(value))cells.push({row,xml:'<c r="'+ref+'" s="'+style+'"><v>'+value+'</v></c>'});else cells.push({row,xml:'<c r="'+ref+'" s="'+style+'" t="inlineStr"><is><t xml:space="preserve">'+xml(value)+'</t></is></c>'});},empty=(row,column,style)=>cells.push({row,xml:'<c r="'+col(column)+row+'" s="'+style+'"/>'});
