function foldAdminFeatures(v){const panels=[...v.children].filter(el=>el.classList.contains('panel')),items=[];panels.forEach((panel,i)=>{const head=panel.querySelector(':scope > .ph'),name=head?.querySelector('h3')?.textContent||'Fitur Admin '+(i+1),hint=head?.querySelector('.hint')?.textContent||'',d=document.createElement('details');d.className=panel.className+' adminFeature';d.dataset.feature=name;const summary=document.createElement('summary');summary.innerHTML='<i class="admIc">'+admIcon(name)+'</i>'+'<span>'+esc(name)+(hint?'<small>'+esc(hint)+'</small>':'')+'</span>';d.append(summary);if(head)head.hidden=true;panel.replaceWith(d);d.append(panel);panel.classList.add('adminFeatureContent');items.push(d);});const finder=document.createElement('div');finder.className='adminFinder';finder.innerHTML='<input id="adminFeatureSearch" class="fi" type="search" placeholder="Cari panel atau isinya: reset 2FA, template, ambang…" aria-label="Cari panel Admin"><p class="hint" id="adminFeatureCount"></p>';const TABS=[['u','Pengguna & Akses','#2B7BE0'],['d','Dealer','#0E9F6E'],['m','Master & KPI','#6D3FD8'],['a','Data & Upload','#F07A0C'],['s','Sistem','#6F7B8E']];const tabOf=n=>/akun pengguna|tambah user|hak export|keamanan akun|penugasan telemarketing/i.test(n)?'u':/cari & edit dealer|tambah dealer|upload dealer|bulk edit customer|update kontak|approval data dealer|pic dealer|big region per dealer|dealer tutup/i.test(n)?'d':/master & kebijakan|master product|brand & klasifikasi|brand · ambang|region map|region per brand|atur kpi|edit target|kpi khusus|kpi telemarketing|badan usaha|download data master|hari libur/i.test(n)?'m':/upload regional|peta kelengkapan|kelengkapan data|catatan kualitas|status sync|cek kesehatan/i.test(n)?'a':'s';items.forEach(d=>{d.dataset.tab=tabOf(d.dataset.feature);d.style.setProperty('--c1',(TABS.find(t=>t[0]===d.dataset.tab)||TABS[4])[2]);if(/kunci periode|pemulihan regional|transfer dealer|ganti kode induk/i.test(d.dataset.feature)){d.classList.add('admWarn');const sp=d.querySelector(':scope > summary > span');if(sp){const w=document.createElement('span');w.className='admWl';w.textContent='HATI-HATI';sp.firstChild.after(w);}}d.dataset.hay=(d.dataset.feature+' '+d.textContent).toLowerCase().replace(/\s+/g,' ');});const wrap=document.createElement('div');wrap.className='admWrap';const nav=document.createElement('div');nav.className='admTabs';const list=document.createElement('div');list.className='admList';items.forEach(d=>list.append(d));wrap.append(finder,nav,list);v.prepend(wrap);let cur=(TABS.find(t=>items.some(d=>d.dataset.tab===t[0]))||TABS[0])[0],q='';const hit=d=>!q||d.dataset.hay.includes(q);const cnt=k=>items.filter(d=>d.dataset.tab===k&&hit(d)).length,tot=k=>items.filter(d=>d.dataset.tab===k).length;function paint(){const withHit=TABS.filter(t=>cnt(t[0])>0);if(q&&!cnt(cur)&&withHit.length)cur=withHit[0][0];nav.innerHTML=TABS.filter(t=>tot(t[0])>0).map(t=>'<button type="button" data-k="'+t[0]+'" class="'+(t[0]===cur?'on':'')+(q?(cnt(t[0])?' hit':' dim'):'')+'" style="--c:'+t[2]+'"><span>'+esc(t[1])+'</span><em>'+(q?cnt(t[0]):tot(t[0]))+'</em></button>').join('');items.forEach(d=>{const show=d.dataset.tab===cur&&hit(d);d.hidden=!show;if(q&&show&&q.length>1)d.open=true;});const total=items.filter(hit).length;$('adminFeatureCount').textContent=q?(total+' panel cocok dari '+items.length):items.length+' panel · ketuk untuk membuka';}nav.onclick=e=>{const b=e.target.closest('[data-k]');if(!b)return;cur=b.dataset.k;paint();};$('adminFeatureSearch').oninput=e=>{q=e.target.value.trim().toLowerCase();if(!q)items.forEach(d=>{d.open=false;});paint();};paint();}
/* Desktop V2 progressive enhancement. APIs, kalkulasi dan hak akses tidak diubah. */
(function desktopV2(){
 const app=document.getElementById('app'),nav=document.getElementById('navigation'),main=document.getElementById('main');if(!app||!nav||!main)return;
 const isDesktop=()=>matchMedia('(min-width:761px)').matches;
 const panelStates=new Map();
 function foldDesktopPanels(root){if(!isDesktop())return;[...root.querySelectorAll('section.panel')].forEach((panel,index)=>{if(panel.closest('.modal,.adminFeature')||panel.dataset.v2SkipFold)return;const head=panel.querySelector(':scope > .ph');if(!head)return;const title=head.querySelector('h3')?.textContent.trim()||'Panel '+index,key=(typeof PAGE==='string'?PAGE:'page')+'|'+title+'|'+index,d=document.createElement('details'),summary=document.createElement('summary');[...panel.attributes].forEach(a=>d.setAttribute(a.name,a.value));d.classList.add('v2AutoFold');d.dataset.v2FoldKey=key;summary.className=head.className;while(head.firstChild)summary.append(head.firstChild);d.append(summary);[...panel.children].filter(x=>x!==head).forEach(x=>d.append(x));const isSummary=/^(Ringkasan|Summary)\b/i.test(title),defaultOpen=['tmfu','tmactivity','tmorder'].includes(PAGE)||PAGE==='beranda'||PAGE==='analisa'||PAGE==='peringkat'||PAGE==='transaksi'&&/^(Transaksi harian|Kalender SELL THRU harian|Pola hari penjualan)$/i.test(title)||PAGE==='brand'&&/^(Summary pencapaian per brand$|Tren SELL THRU|Proyeksi SELL THRU|Pertumbuhan per TYPE)/i.test(title)||PAGE==='tim'&&/^(Pencapaian Tim|Early Warning|Perbandingan Tim)/i.test(title)||PAGE==='dos'&&/^DOS per wilayah/i.test(title);/* v7: DOS per wilayah terbuka default */d.open=isSummary?true:(panelStates.has(key)?panelStates.get(key):defaultOpen);d.addEventListener('toggle',()=>{panelStates.set(key,d.open);if(d.open)setTimeout(()=>window.dispatchEvent(new Event('resize')),0)});panel.replaceWith(d);});}
 function enhanceNav(){nav.querySelectorAll('button[data-page]').forEach(b=>{if(b.dataset.v2Ready)return;const page=b.dataset.page,label=b.textContent.trim();b.textContent='';const icon=document.createElement('span'),text=document.createElement('span');icon.className='desktopNavIcon';icon.setAttribute('aria-hidden','true');icon.innerHTML=menuIcon(page);text.className='desktopNavLabel';text.textContent=label;b.append(icon,text);b.dataset.v2Ready='1';});if(isDesktop()&&!document.getElementById('desktopCollapse')){const c=document.createElement('button');c.id='desktopCollapse';c.className='desktopCollapse';c.type='button';c.textContent='‹  Perkecil sidebar';c.setAttribute('aria-label','Buka atau perkecil sidebar');c.onclick=()=>{app.classList.toggle('desktopCollapsed');try{localStorage.setItem('sp-desktop-sidebar',app.classList.contains('desktopCollapsed')?'1':'0');}catch(e){}};nav.before(c);}try{app.classList.toggle('desktopCollapsed',localStorage.getItem('sp-desktop-sidebar')==='1'&&innerWidth>=1100);}catch(e){}}
 function addExpand(root){if(!isDesktop())return;root.querySelectorAll('svg,canvas,.bars,.qtyChartScroll,.brandBars,.teamBars,.trendChart,.periodCompareChart,[class*="Chart"]').forEach(graph=>{const p=graph.closest('.panel')||graph.closest('section');if(!p||p.dataset.v2Graph||p.closest('.chartFullscreen'))return;const h=p.querySelector(':scope > .ph,:scope > summary.ph,:scope > summary');if(!h)return;p.dataset.v2Graph='1';const b=document.createElement('button');b.type='button';b.className='desktopChartExpand';b.title='Buka grafik layar penuh';b.setAttribute('aria-label','Buka grafik layar penuh');b.textContent='⛶';b.onclick=e=>{e.preventDefault();e.stopPropagation();openGraph(p)};h.append(b);});}
 function openGraph(panel){const layer=document.createElement('div'),card=document.createElement('div'),close=document.createElement('button'),clone=panel.cloneNode(true);layer.className='chartFullscreen';layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');card.className='chartFullscreenCard';close.className='chartFullscreenClose';close.type='button';close.textContent='×';close.setAttribute('aria-label','Tutup grafik diperbesar');clone.querySelectorAll('[id]').forEach(x=>x.removeAttribute('id'));clone.querySelectorAll('.desktopChartExpand').forEach(x=>x.remove());const key=e=>{if(e.key==='Escape')done()},done=()=>{layer.remove();document.body.classList.remove('chartFullscreenOpen');document.removeEventListener('keydown',key)};close.onclick=done;layer.onclick=e=>{if(e.target===layer)done()};card.append(close,clone);layer.append(card);document.body.append(layer);document.body.classList.add('chartFullscreenOpen');document.addEventListener('keydown',key);close.focus();}
 const observer=new MutationObserver(()=>{enhanceNav();foldDesktopPanels(main);addExpand(main)});observer.observe(nav,{childList:true,subtree:true});observer.observe(main,{childList:true,subtree:true});enhanceNav();foldDesktopPanels(main);addExpand(main);addEventListener('resize',()=>{if(isDesktop()){enhanceNav();foldDesktopPanels(main)}else app.classList.remove('desktopCollapsed')});
})();
</script>
<script>
/* Tooltip desktop bergaya aplikasi: menggantikan title bawaan browser (hanya perangkat dengan hover). */
(function(){try{if(!matchMedia('(hover:hover) and (pointer:fine)').matches)return;}catch(e){return;}
 const tip=document.createElement('div');tip.id='v6tip';tip.setAttribute('role','tooltip');document.body.appendChild(tip);let cur=null,timer=0;
 const find=t=>t&&t.closest?t.closest('[title],[data-tip]'):null;
 const hide=()=>{clearTimeout(timer);tip.classList.remove('on');cur=null;};
 const place=el=>{const r=el.getBoundingClientRect(),w=tip.offsetWidth,h=tip.offsetHeight;let x=r.left+r.width/2-w/2,y=r.top-h-9;if(y<8)y=r.bottom+9;x=Math.max(8,Math.min(x,innerWidth-w-8));tip.style.left=x+'px';tip.style.top=y+'px';};
 const show=el=>{if(el.hasAttribute('title')){const t=el.getAttribute('title');if(!t.trim())return;el.dataset.tip=t;el.removeAttribute('title');if(!el.textContent.trim()&&!el.getAttribute('aria-label'))el.setAttribute('aria-label',t);}const txt=el.dataset.tip;if(!txt)return;cur=el;clearTimeout(timer);timer=setTimeout(()=>{if(cur!==el)return;tip.textContent=txt;tip.classList.add('on');place(el);},180);};
 document.addEventListener('mouseover',e=>{const el=find(e.target);if(!el){if(cur)hide();return;}if(el!==cur)show(el);},true);
 document.addEventListener('mouseout',e=>{if(cur&&!cur.contains(e.relatedTarget))hide();},true);
 document.addEventListener('focusin',e=>{const el=find(e.target);if(el)show(el);});document.addEventListener('focusout',hide);
 document.addEventListener('mousedown',hide,true);window.addEventListener('scroll',hide,true);document.addEventListener('keydown',e=>{if(e.key==='Escape')hide();});
})();
</script>
<script>
/* Tabel: kolom pertama menempel saat digeser (sticky), lebar kolom bisa ditarik. */
(function(){let queued=false;
 const enhance=()=>{queued=false;document.querySelectorAll('.table-scroll>table:not([data-v6t])').forEach(t=>{t.dataset.v6t='1';const ths=t.tHead?[...t.tHead.rows[t.tHead.rows.length-1].cells]:[];if(ths.length<4)return;t.classList.add('v6wide');ths.forEach((th,i)=>{if(i===ths.length-1&&ths.length>1&&!th.textContent.trim())return;if(getComputedStyle(th).position==='static')th.style.position='relative';const h=document.createElement('i');h.className='v6rz';h.setAttribute('aria-hidden','true');h.title='';th.appendChild(h);h.addEventListener('click',e=>e.stopPropagation());h.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();const x0=e.clientX,w0=th.getBoundingClientRect().width;h.setPointerCapture(e.pointerId);document.body.classList.add('v6resizing');const mv=ev=>{const w=Math.max(44,w0+ev.clientX-x0);th.style.width=w+'px';th.style.minWidth=w+'px';th.style.maxWidth=w+'px';};const up=()=>{h.removeEventListener('pointermove',mv);h.removeEventListener('pointerup',up);document.body.classList.remove('v6resizing');};h.addEventListener('pointermove',mv);h.addEventListener('pointerup',up);});h.addEventListener('dblclick',e=>{e.stopPropagation();th.style.width=th.style.minWidth=th.style.maxWidth='';});});});};
 const q=()=>{if(queued)return;queued=true;requestAnimationFrame(enhance);};
 new MutationObserver(q).observe(document.body,{childList:true,subtree:true});q();
})();
</script>
